    simplifiedGWuClassDiagonal := getSumDecomposition getGWClass beta;
    beta.cache.getDiagonalClass = makeGWuClass(simplifiedGWuClassDiagonal, getScalar beta);
    makeGWuClass(simplifiedGWuClassDiagonal, getScalar beta)
