liftPicToCDiv NormalToricVariety := (X) -> (
    A := fromCDivToPic X;
    IX := intersectionRing X;
    bas := (flatten entries basis(1, IX))/index;
    if not abs det A_bas == 1 then error "I thought this would be invertible over ZZ...";
    B := inverse(A_bas);
    if not B * A_bas == 1 then error "didn't get inverse matrix";
    result := mutableMatrix(ZZ, numColumns A, numRows A);
    for b from 0 to #bas-1 do (
        for i from 0 to numColumns result - 1 do result_(bas#b,i) = B_(b,i);
        );
    matrix result
    )

LRdecomposition(Matrix,Function):=(trmw,pivotfunction)->(
n:=rank source trmw;
prmt:=matrix {deepSplice({0..(n-1)})};
k:=0;
r:=0;
ver:=0;
while k<(n-1) do (
   r=pivot(k,k,trmw,pivotfunction);
   if ver>1 then print k;
   if r!=k then (
        trmw=permute({k,r},trmw);
        kl:=k;
        rl:=r;
        perm1:=join(0..(min({kl,rl})-1),(max {kl,rl})..(max {kl,rl}),(min({kl,rl})+1)..(max({kl,rl})-1),(min {kl,rl})..(min {kl,rl}),(max({kl,rl})+1)..(n-1));
        prmt=prmt_(deepSplice({perm1}))
    );
   trmw=gaussStep(k,trmw);
k=k+1);
prmt=(entries prmt)#0;
(prmt,trmw))

adjointIdeal(Ideal):=(I1)->(
if dim I1 != 2 then error("Not a curve");
