     pInfo (1, "ENTERING DHom ...");
     W := ring M;
     nW := numgens W;
     K := coefficientRing W;

     pInfo (1, "DHom: holonomicity check ...");
     if not (isHolonomic M and isHolonomic N) then
     error "expected holonomic ideals/modules";     

     outputList := {};
     if (ring N =!= W) then error "expected modules over the same Weyl algebra";
     if (W.monoid.Options.WeylAlgebra === {}) then
     error "expected an element of a Weyl algebra";
     createDpairs W;
     n := #W.dpairVars#0;
     naux := #W.dpairVars#2;
     if naux > 0 then error "expected Weyl algebra without parameters";
     if #w != 2*n then error "expected weight vector of length 2n";
     if any(w, i->i<=0) then error "expected strictly positive weight vector";

     pInfo(1, "Beginning computation of Hom_D(M,N) ...");
     pInfo(1, "Computing resolution of M");
     FM := Dres(M, LengthLimit => n+1);
     pInfo(1, "Dualizing (slow for now) ... ");
     tInfo := toString first timing (FM = Dtransposition dual FM);
     pInfo(2, "\t\t\t time = " | tInfo | " seconds");

     pInfo(1, "Computing resolution of N");
     FN := Dres(N, LengthLimit => n+1);

     FMN := ExternalProduct(FM, FN, TwistMap => true);
     WW := ring FMN;
     FMN = FMN[-n]; 
     C := WW.twistMap FMN;

     Ker := zeroize gens kernel C.dd_0;
     Rels := presentation image Ker;
     Im := zeroize C.dd_1;

     if Im%Ker != 0 then error "expected reduction to 0";
     Syz := Im//Ker;
     NewRels := Rels | Syz;
     twistMN := cokernel NewRels;

     outTable := computeRestriction(twistMN, w, -1, n+1, 
	  {GenCycles, VResolution}, hashTable {Strategy => Schreyer});
     F := outTable#VResolution;
     restrictTable := outTable#GenCycles;

     local answer;

     if restrictTable#n == 0 then answer = 0_K
     else (
     	  -- chainMap := new MutableHashTable;
     	  -- chainMap.source = F;
	  -- chainMap.target = C;
	  -- chainMap.degree = 0;
	  -- chainMap#0 = map(C#0, F#0, Ker);
     	  pInfo(1, "computing chain map 1 ... ");
	  tInfo = toString first timing (
	  bottomCompose := (Ker)*F.dd_1;
	  if (zeroize bottomCompose)%(zeroize C.dd_1) != 0 then 
	  error "expected reduction to 0 -- possible lack of gb problem?";
	  nextLiftMap := (zeroize bottomCompose)//(zeroize C.dd_1);
	  -- chainMap#1 = map(C#1, F#1, nextLiftMap);
	  );
          pInfo (2, "\t\t\t time = " | tInfo | " seconds");
	  i := 2;
	  while i <= n do (
	       pInfo(1, "computing chain map " | i | " ..." );
	       tInfo = toString first timing (
	       bottomCompose = nextLiftMap*F.dd_i;
	       if (zeroize bottomCompose)%(zeroize C.dd_i) != 0 then 
	       error "expected reduction to 0 -- possible lack of gb problem?";
	       nextLiftMap = (zeroize bottomCompose)//(zeroize C.dd_i);
	       -- chainMap#i = map(C#i, F#i, nextLiftMap);
     	       i = i+1;
	       );
               pInfo (2, "\t\t\t time = " | tInfo | " seconds");
	       );
	  answer = WW.twistInvMap(nextLiftMap*restrictTable#n);
	  temp := answer;
     	  -- chainMap = new ChainComplexMap from chainMap;
	  );

     if answer == 0 then basisList := matrix{{0_K}}
     else (
	  answer = WW.projMap2 Dtransposition ( (Dtransposition answer)%
	       (directSum (rank target answer:gens Dtransposition WW.diagonal)));
     	  homSize := (rank ambient M)*(rank ambient N);
     	  answerInds := {rank target answer - homSize..rank target answer-1};
     	  answer = answer^answerInds;
     	  basisList = apply(toList(0..rank source answer - 1), i ->
	       map(N, M, transpose matrix pack( 
			 (entries transpose answer_{i})#0, rank ambient N) ) );
     	  );

     basisList
     )

Ddual Module := M -> (
     pInfo(1, "ENTERING Ddual ... ");
     W := ring M;
     if W.monoid.Options.WeylAlgebra === {} then
     error "expected an element of a Weyl algebra";
     pInfo (1, "Ddual: holonomicity check ...");
     if not isHolonomic M then
     error "expected a holonomic module";
     createDpairs W;
     n := #W.dpairVars#0; 
     outputList := {};

     C := Dresolution(M, LengthLimit => n+1);
     m0 := transpose Dtransposition C.dd_n;
     m1 := transpose Dtransposition C.dd_(n+1);  

     F0 := map(C_n, C_(n-1), m0);
     F1 := map(C_(n+1), C_n, m1);

     pres := presentation homology(F1,F0);
     cokernel zeroize Dprune pres)

Dintegration(Module, List) := options -> (M,w) -> (
     W := ring M;
     F := W^(numgens source gens M);
     ensureQuotientModule(M, 
	  "Dintegration currently only handles quotient modules");

     d := #positions(w, i -> (i>0));
     MF := cokernel Fourier relations M; 
     outputRequest := {HomologyModules};
     restrictOut := (computeRestriction(MF, w, -1, d+1, 
	       outputRequest, options))#HomologyModules;

     resW := ring restrictOut#0;
     nrW := numgens resW;
     if nrW == 0 then Mout := restrictOut
     else Mout = hashTable apply(toList(0..d), i -> 
	  (i => FourierInverse restrictOut#i) );     
     Mout
     )

Dintegration(ZZ, Module, List) := options -> (k,M,w)  -> (
     W := ring M;
     ensureQuotientModule(M, 
	  "Dintegration currently only handles quotient modules");

     d := #positions(w, i -> (i>0));
     MF := cokernel Fourier relations M; 
     outputRequest := {HomologyModules, BFunction};
     restriction := computeRestriction (MF, w, k-1, k+1,
	 outputRequest, options);
     restrictOut := restriction#HomologyModules#k;

     resW := ring restrictOut;
     nrW := numgens resW;
     if nrW == 0 then Mout := restrictOut
     else Mout = FourierInverse restrictOut; 
     Mout.cache.BFunction = restriction#BFunction;
     Mout
     )

DintegrationAll(Module, List) := options -> (M,w) -> (
     W := ring M;
     ensureQuotientModule(M, 
	  "Dintegration currently only handles quotient modules");
     d := #positions(w, i -> (i>0));
     n := numgens ring M;
     if n == 2*d then outputRequest := {GenCycles, HomologyModules,
	  VResolution, BFunction, RestrictComplex, Exponents, 
	  Explicit}
     else outputRequest = {Cycles, Boundaries, HomologyModules,
	  VResolution, BFunction, RestrictComplex, Exponents,
	  Explicit};

     MF := cokernel Fourier relations M; 
     outputTable := computeRestriction (MF, w, -1, d+1, 
	  outputRequest, options);
     outputList := {BFunction => outputTable#BFunction};
     if outputTable#VResolution =!= null then 
     outputList = append(outputList, 
	  VResolution => FourierInverse outputTable#VResolution)
     else outputList = append(outputList, VResolution => null);

     if n == 2*d then outputList = outputList | {
	  GenCycles => hashTable apply(toList(0..d), 
		    i -> (i => FourierInverse outputTable#GenCycles#i)),
	       HomologyModules => hashTable apply(toList(0..d), 
		    i -> (i => outputTable#HomologyModules#i)),
	       IntegrateComplex => outputTable#RestrictComplex}
     else (
     	  outputList = outputList | {
	       HomologyModules => hashTable apply(toList(0..d), 
		    i -> (i => FourierInverse outputTable#HomologyModules#i)),
	       Cycles => hashTable apply(toList(0..d), 
		    i -> (i => FourierInverse outputTable#Cycles#i)),
	       Boundaries => hashTable apply(toList(0..d), 
		    i -> (i => FourierInverse outputTable#Boundaries#i)),
	       IntegrateComplex => FourierInverse outputTable#RestrictComplex};
	  );

     hashTable outputList
     )

