IHmodule(Ideal) := options -> I -> (
    R := ring I;
    if class R =!= PolynomialRing
    then error "expected an ideal in a polynomial ring";
    primes := minimalPrimes I;
    if #primes > 1 then error "The variety defined by the ideal must be irreducible";
    P := primes#0;
    c:=codim P;
    if options.LocStrategy == CompleteIntersection then (  -- when complete intersection
	g:=flatten entries (gens I);
    	if #g>c then error "This strategy is for complete intersections only";
        F := product((0..c-1), i->g#i);
	W := makeWA R;
	F = sub(F,W);
	J := RatAnn F;
	for i from 0 to c-1 do J=J+ideal(sub(g#i,W)); -- submodule of H^c_I(R) generated by F^-1
	m := minors (c,jacobian(I));      
	l := (flatten entries (mingens m))#0;
	image map(W^1/J, W^1, matrix{{sub(l,W)}}) -- D-mod generated by fundamental class
	)
    else (
    	S := flatten entries mingens(ideal singularLocus P);
    	f:=1_R;
    	for i from 0 to #S-1 do (
	    if ((S_i % P) != 0) then (
	    	f=S_i; 
	    	break;
	    	);
	    );
    	H := localCohom(c, I, Strategy => options.LocCohomStrategy#0, LocStrategy => options.LocCohomStrategy#1);
    	if (first degree f) == 0 then H   --when smooth
    	else (      	    	    	  --general case
    	    G := Ddual H;
    	    f = sub(f,ring G);
    	    T := DlocalizeAll(G,f, Strategy => options.LocStrategy);
    	    image T#LocMap
       	    )
	)    		 
    );

WeylClosure(Ideal, RingElement) := (I, f) -> (
     W := ring I;
     if W.monoid.Options.WeylAlgebra === {} then
     error "Expected a Weyl algebra" ;

     M := cokernel gens I;
     --<< "Computing localization" << endl;
     locMap := DlocalizeMap(M, f);
     J := I + ideal gens kernel locMap;
     --if (I == J) then << "Ideal is closed with respect to f" << endl
     --else << "Ideal is not closed with respect to f" << endl;
     ideal gens gb J
     )

WeylClosure Ideal := I -> (
     W := ring I;
     outputList :={};
     if W.monoid.Options.WeylAlgebra === {} then
     error "Expected a Weyl algebra" ;

     if holonomicRank I === infinity then
     error "Weyl closure only currently implemented for finite rank ideals.";

     --<< "Computing singular locus" << endl;
     SL := singLocus I;
     f := (gens SL)_(0,0);
     --<< f << endl;

     M := cokernel gens I;
     --<< "Computing localization" << endl;
     locMap := DlocalizeMap(M, f);
     J := I + ideal gens kernel locMap;
     --if (I == J) then << "Ideal is closed " << endl
     --else << "Ideal is not closed " << endl;

     --ideal gens gb J
     J
     )

bFunction(Ideal, List) := RingElement => o -> (I, w) -> (
     result := (
	  if o.Strategy == IntRing then bfIntRing(I, w)
     	  else if o.Strategy == TryGeneric or o.Strategy == NonGeneric 
     	  then bfGenericOrNonGeneric(I, w, o)
     	  else error "wrong Strategy option"
	  );
     result
     );

bFunction(Module, List, List) := RingElement => o -> (M, w, m) -> (
     s := symbol s;
     S := QQ[s];
     bf := 1_S; 
     M' := image presentation M; 
     R := ring M';
     F := super M';
     n := numgens F;

     --sanity check
     if #m != n then 
     error "wrong shift vector length";
     if any(m, u -> class u =!= ZZ) then
     error "shift vector should consist of integers";

     i := 0;
     while i < n do (
	  -- N = i-th component of F
	  N := image map(ambient M', R^1, (toList(i : {0_R})) | {{1}} | (toList((n-i-1):{0_R})) );  
	  NM := intersect(M', N);
	  I := ideal apply(numgens NM, j -> NM_j_i);

	  -- Make sure we don't get the 0 ideal in ZZ
	  if zero I then I = ideal 0_(ring NM);


	  bf' := bFunction(I, w); 
	  bf' = (map(S, ring bf', matrix{{s}})) bf';
	  bf' = substitute(bf', { s => s - m#i });

	  -- bFunctions can't really be zero by definition, but whatever
	  if zero bf' then return 0_S;

	  -- bf = lcm (bf, bf')
	  bf = bf * (bf' // gcd(bf, bf'));
	  i = i + 1;
	  );
     bf 
     );-- end bFunction(Module)

bFunctionRoots RingElement := List => f -> (
     if f==1 then {} else apply(toList factorBFunction f, 
	 u -> - leadCoefficient substitute(u#0, {(ring u#0)_0 => 0_(ring u#0)}) )
     );

