paramBpoly(RingElement, File) := List => o -> (f, file) -> (
     QQflag = (o#"ground field" == 0);
     if not QQflag then (
	  if isPrime o#"ground field" 
     	  then DBIGPRIME = o#"ground field"
     	  else error "need a prime";
	  )
     else error "algorithm is implemented over finite field so far"; 
     R := ring f;
     K := coefficientRing R;
     if coefficientRing K =!= QQ then 
     error "base ring = QQ expected";

     Z := ((ZZ/DBIGPRIME)(monoid [(entries vars K)#0]))(monoid [
	  (entries vars R)#0, WeylAlgebra => R.monoid.Options.WeylAlgebra]);
     f = QtoZmodP(f,Z);  
     V := createVTree(f);
     V = add2VTree(V, ideal 0_(coefficientRing Z), -1);     
     local num;
     while (num = position(V#tempN, u -> u#Itype == NOTCOMPUTED)) =!= null 
     do ( 
     	  V = takeCareOf(V, num);
     	  );
     -- transform into bSet
     bs := VTree2bSet2 V;
     BSet2tex(bs,file);
     ret := apply(bs, u->(
	       s := symbol s;
	       RZ := (ZZ/DBIGPRIME)[s];
	       factorBFunctionZmodP(
		    sum(u#tempBF, v->
			 (if class v#1 === ZZ 
			     -- hashtable was loaded from file
			     then v#1
			     -- original hashtable
			     else substitute(v#1,ZZ)) 
			* RZ_(v#0))) 
	       ));
     ret
     );

polynomialAnnihilator RingElement := f -> (
    W := ring f;
    createDpairs W;
    dpV := W.dpairVars;
    -- error checking
    if W.monoid.Options.WeylAlgebra === {} then
    error "Expected element of a Weyl algebra";
    if substitute(f, (dpV#1 | dpV#2) / (i->(i=>0))) != f then
    error "Expected polynomial element of Weyl algebra";
    if W.monoid.Options.Degrees =!= toList(numgens W:{1}) then
    error "Expect all degrees in a Weyl algebra to be 1";
    tempL := (dpV#1 / (i -> 2*f*i - i*f));  -- (fD_i - df/dx_i)
    suffHigh := (degree f)#0 + 1;
    tempL = join(tempL, (dpV#1 / (i -> i^suffHigh)));  -- D_i^(large m)
    ideal tempL
    )

