     polynomialExt ((ring I)^1/I, options)
     )

polynomialExt Module := options -> (M) -> (
     pInfo (1, "ENTERING polynomialExt ...");
     W := ring M;
     createDpairs W;
     n := #W.dpairVars#0;
     w := toList(n:1);
     outputList := {};
     N := Ddual M;
     integrateTable := Dintegration(zeroize N, w, options);
