             B'SectionString => {(1.49144+.713846*ii)*(x0)+(-.840113+1.1986*ii)*(x1), (.014842+1.23548*ii)*(y0)+(-.214468+.911293*ii)*(y1)+(-.486176+.400577*ii)*(y2)}
             ListB'Sections => {B'Section{...2...}, B'Section{...2...}}
             NameB'Slice => null
