    if not all(netLabels, i -> instance(i, Net)) then (
	error "characterTable: expected labels to be strings (or nets)";	    
	);
    if not all(texLabels, i -> instance(i, Net)) then (
	error "characterTable: expected labels to be strings (or nets)";	    
	);
    new CharacterTable from {
