        cells#s = newCell apply(subsets(s,k-1), s' -> (cells#s',0))
        );
    cellComplex(R,{cells#(toList (0..(n-1)))})
    )

hullComplex MonomialIdeal := CellComplex => I -> (
    n := numgens ring I;
    hullComplex((n+1)!+1,I)
