    r := #gensI;
    if r == 0 then error "scarfComplex expects a non-zero monomialIdeal";
    cells := new MutableHashTable;
    dupLabels := new MutableHashTable;
    for i to r-1 do cells#(gensI#i) = newSimplexCell({},gensI#i);
    for k from 2 to r do (
        hasCells := false;
        for s in subsets(r,k) do (
            --boundary cell via the labels
            bdLabels := for t in subsets(s,k-1) list lcm(gensI_t);
            --compute the label of the cell
            m := lcm(gensI_s);
            --figure out if we have a duplicate label, if we do remove any cells with
            --the same label, otherwise add the cell
            if not dupLabels#?m
            then (if cells#?m
                 then (
                     dupLabels#m = true;
                     remove(cells,m))
                 else (
                     incompleteBoundary := false;
                     bd := for label in bdLabels list (
                         if cells#?label then cells#label else (incompleteBoundary = true; break;));
                     if incompleteBoundary then{
                         dupLabels#m = true;
                         continue
                         };
                     hasCells = true;
                     cells#m = newSimplexCell(bd, m)));
            );
        --if there are no cells at dimension k, there won't be any of higher dimension
        --as well as no new labels
        if not hasCells then break;
        );
    cellComplex(ring I, values cells)
    )

subcomplex(CellComplex,RingElement) := CellComplex => o -> (C,m) -> (
    allCells := flatten values cells C;
    R := ring C;
    S := if o.LabelRing =!= null then o.LabelRing else coefficientRing R;
    withNewLabels := apply(allCells, c -> (c,if (m % ideal toModule(R,cellLabel c))==0 then 1_S else 0));
    nontrivialCells := select(withNewLabels, p -> (p#1) != 0);
    finalCells := new MutableHashTable;
    --it is important here that the cells in allCells are sorted by dimension at this point
    for p in nontrivialCells do (
        c := p#0;
        l := p#1;
        newBoundary := apply(boundary c, p -> (finalCells#(p#0),p#1));
        finalCells#c = newCell(newBoundary,l);
        );
    cellComplex(S,values finalCells)
    )

subcomplex(CellComplex,List) := CellComplex => o -> (C,d) -> (
    allCells := flatten values cells C;
    R := ring C;
    S := if o.LabelRing =!= null then o.LabelRing else coefficientRing R;
    withNewLabels := apply(allCells, c -> (c,source basis(d,toModule(R,cellLabel c),SourceRing=>S)));
    nontrivialCells := select(withNewLabels, p -> (p#1) != 0);
    finalCells := new MutableHashTable;
    --it is important here that the cells in allCells are sorted by dimension at this point
    for p in nontrivialCells do (
        c := p#0;
        l := p#1;
        newBoundary := apply(boundary c, p -> (finalCells#(p#0),p#1));
        finalCells#c = newCell(newBoundary,l);
        );
    cellComplex(R,values finalCells)
    )

taylorComplex MonomialIdeal := CellComplex => I -> (
    gensI := I_*;
    r := #gensI;
    if r == 0 then error "taylorComplex expects a non-zero monomialIdeal";
    cells := new MutableHashTable;
    for i to r-1 do cells#{i} = newSimplexCell({},gensI#i);
    for k from 2 to r do (
        for s in subsets(r,k) do (
            bd := for t in subsets(s,k-1) list cells#t;
            cells#s = newSimplexCell(bd, lcm(gensI_s));
            );
        );
    cellComplex(ring I, {cells#(toList (0..(r-1)))})
    )

AHH(ZZ, MonomialIdeal) := Matrix => (n, I) -> (
    if n == 0 then return gens I;
    R := ring I;
    symbolsList := admissibleSQSymbols I;
    sourceList := symbolsList_(positions(symbolsList, i -> first degree promote(i_0, R) == n));
    targetList := symbolsList_(positions(symbolsList, i -> first degree promote(i_0, R) == n - 1));
    myFn := (i, j) -> (
        tempElt := sourceList_j_0 // targetList_i_0;
        if tempElt != 0_R then (
            if targetList_i_1 == sourceList_j_1 then (
                coe := (-1)^(position(positions(flatten exponents sourceList_j_0, r -> r != 0),
                        s -> s == position(R_*, t -> t == tempElt)));
                coe * tempElt
                ) else (
                deco := canonicalDecomp(tempElt * sourceList_j_1, I_*);
                if targetList_i_1 == deco then (
                    coe2 := (-1)^(1 + position(positions(flatten exponents sourceList_j_0, r -> r != 0),
                            s -> s == position(R_*, t -> t == tempElt)));
                    tempElt2 := (tempElt * sourceList_j_1) // deco;
                    coe2 * tempElt2
                    ) else 0_R
                )
            ) else 0_R
        );
    map(
        R^(- apply(targetList, i -> degree(promote(i_1, R) * promote(i_0, R)))),
        R^(- apply(sourceList, i -> degree(promote(i_1, R) * promote(i_0, R)))),
        myFn)
    )

AHHResolution MonomialIdeal := Complex => I -> (
    R := ring I;
    maxlevel := length(R_*) - max apply(I_*, g -> maxVarMIR g + 1 - first degree g) - 1;
    if maxlevel < 0 then maxlevel = 0;
    diffs := toList apply(0 .. maxlevel, i -> AHH(i, I));
    while #diffs > 1 and (last diffs == 0) do diffs = drop(diffs, -1);
    complex diffs
    )

EK(ZZ, MonomialIdeal) := Matrix => (n, I) -> (
    if n == 0 then return gens I;
    R := ring I;
    symbolsList := admissibleSymbols I;
    sourceList := symbolsList_(positions(symbolsList, i -> first degree promote(i_0, R) == n));
    targetList := symbolsList_(positions(symbolsList, i -> first degree promote(i_0, R) == n - 1));
    myFn := (i, j) -> (
        tempElt := sourceList_j_0 // targetList_i_0;
        if tempElt != 0_R then (
            if targetList_i_1 == sourceList_j_1 then (
                coe := (-1)^(position(positions(flatten exponents sourceList_j_0, r -> r != 0),
                        s -> s == position(R_*, t -> t == tempElt)));
                coe * tempElt
                ) else (
                deco := canonicalDecomp(tempElt * sourceList_j_1, I_*);
                if targetList_i_1 == deco then (
                    coe2 := (-1)^(1 + position(positions(flatten exponents sourceList_j_0, r -> r != 0),
                            s -> s == position(R_*, t -> t == tempElt)));
                    tempElt2 := (tempElt * sourceList_j_1) // deco;
                    coe2 * tempElt2
                    ) else 0_R
                )
            ) else 0_R
        );
    map(
        R^(- apply(targetList, i -> degree(promote(i_1, R) * promote(i_0, R)))),
        R^(- apply(sourceList, i -> degree(promote(i_1, R) * promote(i_0, R)))),
        myFn)
    )

EKResolution MonomialIdeal := Complex => I -> (
    n := numgens ring I;
    -- Build the list of differentials; drop trailing zero maps so the
    -- length matches the actual projective dimension.  toList is essential:
    -- `complex` accepts a List but, on a Sequence, splats the args (no
    -- (Matrix, Matrix, ...) dispatch exists).
    diffs := toList apply(0 ..< n, i -> EK(i, I));
    while #diffs > 1 and (last diffs == 0) do diffs = drop(diffs, -1);
    complex diffs
    )

appendZeroMap ChainComplex := C->(
    L := chainComplexData(C);
    if L_0 == L_1 then 
      return chainComplexFromData {L_0,L_1,{chainComplex map(C_(L_0),(ring C)^0, 0)}};
    minC := L_0;
    newd := map(source last L_2,(ring C)^0, 0);
    chainComplexFromData (minC,append(L_2,newd))
    )

