chromaticIdeal = (kk,G,q) -> (
    V := vertices G;
    n := #vertices G;
    if V!=toList(0..(n-1)) then
        error "vertex set must be 0,1,..,n-1";
    R := nVarsRing(kk,n);
    F := for E in edges G list(
        (i,j):= toSequence elements E;
        sum for d to q-1 list R_i^d*R_j^(q-1-d)
    );
    F = F | for i to n-1 list (R_i)^q-1;
    return ideal F;
)

