cylinder ComplexMap := Complex => f -> (
    if not isComplexMorphism f then 
        error "expected a complex morphism";
    B := source f;
    C := target f;
    (loB,hiB) := B.concentration;
    (loC,hiC) := C.concentration;
    lo := min(loB,loC);
    hi := max(hiB+1,hiC);
    modules := hashTable for i from lo to hi list i => B_(i-1) ++ B_i ++ C_i;
    maps := hashTable for i from lo+1 to hi list i => (
        map(modules#(i-1), modules#i, matrix{
                { - dd^B_(i-1)  , 0      , 0     }, 
                { -id_(B_(i-1)) , dd^B_i , 0     },
                { f_(i-1)       , 0      , dd^C_i}
                }
            )
        );
    result := complex maps;
    result.cache.cylinder = f;
    result
    )

freeResolution Module := Complex => opts -> M -> (
    -- This handles caching, hooks for different methods of computing 
    -- resolutions or over different rings which require different algorithms.
    --
    -- Nonminimal: true if the computation is constructed using the Nonminimal or NonminimalWithGB strategies
    -- LengthLimit prescribes the length of the computed complex.
    -- DegreeLimit is a lower limit on what will be computed degree-wise, but more might be computed.
    R := ring M;
    local C;
    if M === R^0 or opts.LengthLimit < 0
    then (
        C = complex R^0;
        if not M.cache.?Resolution then 
            M.cache.Resolution = C;
        return C;
        );
    if M.cache.?Resolution then (
        C = M.cache.Resolution;
        if not C.cache.?LengthLimit or not C.cache.?DegreeLimit then
            error "internal error: Resolution should have both a LengthLimit and DegreeLimit";
        if C.cache.Nonminimal === (opts.Strategy === Nonminimal or opts.Strategy === NonminimalWithGB) and
           C.cache.LengthLimit >= opts.LengthLimit and 
           C.cache.DegreeLimit >= opts.DegreeLimit then (
               C' := naiveTruncation(C, -infinity, opts.LengthLimit);
               C'.cache.LengthLimit = opts.LengthLimit;
               C'.cache.DegreeLimit = C.cache.DegreeLimit;
               C'.cache.Module = C.cache.Module;
               return C';
               );
        remove(M.cache, symbol Resolution); -- will be replaced below
        );
    if M.cache.?ResolutionObject then (
        RO := M.cache.ResolutionObject;
        if (opts.Strategy === null and (RO.Strategy =!= 4 and RO.Strategy =!= 5)) or --4 is the magic number for Nonminimal.  5 for NonminimalGB. In these cases, we need to recompute the resolution.
            opts.Strategy === RO.Strategy
        then (
            if RO.isComputable(opts.LengthLimit, opts.DegreeLimit) -- this is informational: does not change RO.
            then (
                RO.compute(opts.LengthLimit, opts.DegreeLimit); -- it is possible to interrupt this and then the following lines do not happen.
                C = RO.complex(opts.LengthLimit);
                C.cache.Nonminimal = (RO.Strategy === 4 or  RO.Strategy === 5); -- magic number: this means Nonminimal, or NonminimalWithGB to the engine...
                C.cache.LengthLimit = if max C < opts.LengthLimit then infinity else opts.LengthLimit;
                C.cache.DegreeLimit = opts.DegreeLimit;
                C.cache.Module = M;
                M.cache.Resolution = C;
                return C;
                )
            );
        remove(M.cache, symbol ResolutionObject);
        );

    RO = new ResolutionObject from {
        symbol ring => ring M,
        symbol LengthLimit => opts.LengthLimit,
        symbol DegreeLimit => opts.DegreeLimit,
        symbol Strategy => opts.Strategy,
        symbol Module => M
        };
    M.cache.ResolutionObject = RO;

    -- the following will return a complex (or null), 
    C = runHooks((freeResolution, Module), (opts, M), Strategy => opts.Strategy);

    if C =!= null then (
        assert(instance(C, Complex));
        C.cache.Nonminimal = (RO.Strategy === 4 or RO.Strategy === 5); -- magic number: this means Nonminimal, NonminimalWithGB to the engine...
        C.cache.LengthLimit = if max C < opts.LengthLimit then infinity else opts.LengthLimit;
        C.cache.DegreeLimit = opts.DegreeLimit;
        C.cache.Module = M;
        M.cache.Resolution = C;
        return C;
        );    

    remove(M.cache, symbol ResolutionObject);
    if opts.Strategy === null then     
        error("no method implemented to handle this ring and module");
    error "provided Strategy does not handle this ring and module";        
    );

freeResolution(CpMackeyFunctor,ZZ) := List => opts -> (M,n) -> (
    if n < 0 then return {};

    -- check whether existing resolution exists
    -- k will be the length of the existing resolution
    k := 0;
    if M.cache#?"ProjRes" then (
        k = length M.cache#"ProjRes";
    ) else (
        -- initialize resolution if doesn't exist
        M.cache#"ProjRes" = {makeFreeModuleSurjection M};
        k = 1
    );

    while k <= n do (
        -- add differential d_k to cache
        d := (M.cache#"ProjRes")#(k-1);
        M.cache#"ProjRes" |= {inducedMap(source d, kernel d) * (makeFreeModuleSurjection (kernel d))};
        k += 1
    );

    M.cache#"ProjRes"_(for i to n list i)
)

resolution NCMatrix := opts -> M -> (
   i := 0;
   numSyz := if opts#LengthLimit === infinity then numgens ring M - 1 else opts#LengthLimit;
   currentM := M;
   syzList := {M} | while (i < numSyz and currentM != 0) list (
      newM := rightKernelBergman currentM;
      currentM = newM;
      currentM
   ) do i = i+1;
   new NCChainComplex from apply(#syzList, i -> (i,syzList#i))
)

homotopyMap ComplexMap := ComplexMap => f -> (
    if not f.cache.?homotopyMap then error "expected a complex map created by 'liftMapAlongQuasiIsomorphism'";
    f.cache.homotopyMap
    )

horseshoeResolution Complex := Sequence => opts -> ses -> (
    -- check that ses is a short exact sequence of modules
    -- occurring in homological degrees 0,1,2.
    -- at least check that the length is correct.
    f := yonedaExtension' ses;
    g := yonedaMap(f, LengthLimit => opts.LengthLimit);
    M := ses_0;
    N := ses_2;
    -- the following will have correct length, since 
    -- they have been constructed during yonedaMap.
    FM := freeResolution(M, LengthLimit => opts.LengthLimit);
    FN := freeResolution(N, LengthLimit => opts.LengthLimit);
    HS := complex hashTable for i from 1 to length FM list (
      i => map(FN_(i-1) ++ FM_(i-1), 
             FN_i ++ FM_i, 
             matrix{{dd^FN_i, g_i},{0,dd^FM_i}})
      );
    alpha := map(HS, FN, i -> map(HS_i, FN_i, (HS_i)_[0]));
    beta := map(FM, HS, i -> map(FM_i, HS_i, (HS_i)^[1]));
    (beta, alpha)
    )

horseshoeResolution(Matrix, Matrix) := Sequence => opts -> (g,f) -> (
    horseshoeResolution(complex{g,f}, opts)
    )

isComplexMorphism ComplexMap := (f) -> (
    if debugLevel > 0 and degree f =!= 0 then (
        << "-- the complex map has non-zero degree" << endl;
        return false;
        );
    degree f === 0 and isCommutative f
    )

isFree CellComplex := Boolean => cellComplex -> (
    R := cellComplex.labelRing;
    all(flatten values cells cellComplex,c -> isFreeModule prune toModule(R,cellLabel c))
    )

isFree Complex := Boolean => C -> (
    (lo, hi) := concentration C;
    all(lo..hi, i -> isFreeModule C_i)
    )

isFree ZZdFactorization := Boolean => C -> (
    all(0..period(C)-1, i -> isFreeModule C_i)
    )

isNullHomotopic ComplexMap := Boolean => f -> (
    g := homomorphism' f;
    H := target g; 
    d := degree f;
    g1 := g_0 // dd^H_(d+1); 
    g_0 == dd^H_(d+1) * g1
    )

isNullHomotopic ZZdFactorizationMap := Boolean => f -> (
    g := homomorphism' f;
    H := target g; 
    d := degree f;
    g1 := g_0 // dd^H_(d+1); 
    g_0 == dd^H_(d+1) * g1
    )

isNullHomotopyOf(ComplexMap, ComplexMap) := (h, f) -> (
    -- returns true if h is a null homotopy for f : C --> D.
    -- if debugLevel > 0, then more info as to where it is not, is given
    C := source f;
    D := target f;
    degf := degree f;
    degh := degree h;
    if target f != target h then (
        if debugLevel > 0 then << "expected targets to be the same" << endl;
        return false;
        );
    if source f != source h then (
        if debugLevel > 0 then << "expected sources to be the same" << endl;
        return false;
        );
    if degh - degf =!= 1 then (
        if debugLevel > 0 then << "expected degree of first map to be one more than degree of the second" << endl;
        return false;
        );
    if debugLevel == 0 then h * dd^C + (-1)^degf * dd^D * h == f
    else (
        result := true;
        (lo,hi) := concentration h;
        for i from lo to hi do (
            if h_(i-1) * dd^C_i + (-1)^degf * dd^D_(degh+i) * h_i != f_i then (
                << "fails to be a null homotopy at location " << i << endl;
                result = false;
                );
            );
        result
        )
    )

isNullHomotopyOf(ZZdFactorizationMap, ZZdFactorizationMap) := (h, f) -> (
    -- returns true if h is a null homotopy for f : C --> D.
    -- if debugLevel > 0, then more info as to where it is not, is given
    C := source f;
    D := target f;
    degf := degree f;
    degh := degree h;
    if target f != target h then (
        if debugLevel > 0 then << "expected targets to be the same" << endl;
        return false;
        );
    if source f != source h then (
        if debugLevel > 0 then << "expected sources to be the same" << endl;
        return false;
        );
    if degh - degf =!= 1 then (
        if debugLevel > 0 then << "expected degree of first map to be one more than degree of the second" << endl;
        return false;
        );
    if debugLevel == 0 then h * dd^C + (-1)^degf * dd^D * h == f
    else (
        result := true;
        (lo,hi) := (0,period source h);
        for i from lo to hi do (
            if h_(i-1) * dd^C_i + (-1)^degf * dd^D_(degh+i) * h_i != f_i then (
                << "fails to be a null homotopy at location " << i << endl;
                result = false;
                );
            );
        result
        )
    )

isQuasiIsomorphism(ChainComplexMap) := o -> phi -> (
    (lo, hi) := toSequence o.Concentration;
    isExact(cone phi, LengthLimit => if hi === infinity then infinity else hi)
    )

isQuasiIsomorphism ComplexMap := Boolean => opts -> f -> (
    (loSrc,hiSrc) := concentration source f;
    (loTar,hiTar) := concentration target f;
    (lof,hif) := (min(loTar, loSrc), max(hiTar, hiSrc));
    (loO,hiO) := opts.Concentration;
    all(max(lof,loO)..min(hif,hiO),
        i -> HH_(i+1) cone f == 0
        )
    )

isQuasiIsomorphism ZZdFactorizationMap := Boolean => opts -> f -> (
    p := period source f;
    all(0..p-1,
        i -> HH_(i+1) cone f == 0
        )
    )

isShortExactSequence Complex := Boolean => C -> (
    (lo, hi) := concentration C;
    supp := for i from lo to hi list if C_i != 0 then i else continue;
    lo = first supp;
    hi = last supp;
    if hi - lo > 3 then 
        false
    else
        isShortExactSequence(dd^C_(hi-1), dd^C_hi)
    )

liftMapAlongQuasiIsomorphism(ComplexMap, ComplexMap) := (alpha,beta) -> (
    -- alpha: P --> N, P is semi-free
    -- beta: M --> N, a quasi-isomorphism
    -- result: gamma: P --> M a morphism of chain complexes
    --         h:     P --> N, a homomorphism of degree 1, such that
    -- alpha - beta.gamma = h dd^P + dd^N h.
    P := source alpha;
    N := target alpha;
    M := source beta;
    if N =!= target beta then error "expected targets of two maps to be the same complex";
    (loP, hiP) := concentration P;
    Cbeta := cone beta;
    gamma := new MutableHashTable;
    h := new MutableHashTable;
    -- start with lo-1
    gamma#(loP-1) = map(M_(loP-1), P_(loP-1), 0);
    h#(loP-1) = map(N_loP, P_(loP-1), 0);
    -- once we have defined: gamma_(i-1) : P_(i-1) --> M_(i-1)
    -- and h_(i-1) : P_(i-1) --> N_i
    -- get a map P_i --> M_(i-1) ++ N_i
    for i from loP to hiP do (
        delta := map(Cbeta_i, P_i, matrix{{- gamma#(i-1) * dd^P_i},
                                        {alpha_i - h#(i-1) * dd^P_i}}
                     );
        --if delta % dd^Cbeta_(i+1) != 0 then << "oops, our logic is wrong!" << endl;
        -- note: if Cbeta_(i+1) is 0, then it is not a direct sum module.  We make it one:
        eps := map(M_i ++ N_(i+1), P_i, delta // dd^Cbeta_(i+1));
        gamma#i = map(M_i, P_i, eps^[0]);
        h#i = map(N_(i+1), P_i, eps^[1]);
        );
    gamma = hashTable for i from loP to hiP list i => gamma#i;
    h = hashTable for i from loP to hiP list i => h#i;
    gamma1 := map(M, P, gamma);
    gamma1.cache.homotopyMap = map(N, P, h, Degree => 1);
    gamma1
    )

naiveTruncation(Complex,Sequence) := Complex => (C,loHi) -> (
    if #loHi =!= 2 then error "expected a truncation interval";
    (lo,hi) := loHi;
    if lo === null then lo = -infinity;
    if hi === null then hi = infinity;
    if lo > hi then error "interval of truncation is empty";
    (loC,hiC) := concentration C;
    lo = max(lo,loC);
    hi = min(hi,hiC);
    if lo === loC and hi === hiC then C
    else if lo === hi then complex(C_lo, Base=>lo)
    else if lo > hi then complex (ring C)^0
    else complex(hashTable for i from lo+1 to hi list i => dd^C_i, Base=>lo)
    )

naiveTruncation(ComplexMap,Sequence,Sequence) := ComplexMap => (f, targetLoHi, sourceLoHi) -> (
    D := naiveTruncation(target f, targetLoHi);
    C := naiveTruncation(source f, sourceLoHi);
    map(D, C, i -> f_i, Degree => degree f)
    )

naiveTruncation(Complex, ZZ) := Complex => (C, n) -> (
    (lo, hi) := concentration C;
    if n > 0 then naiveTruncation(C, (lo + n,  infinity)) else
    if n < 0 then naiveTruncation(C, (-infinity, hi + n)) else C)

pruneComplex(Complex, ZZ) := opts -> (C, nsteps) -> (
    m := min C;
    mComplex := toMutableComplex C;
    -- The pruning morphism is computed internally regardless of the PruningMap
    -- option, since it is needed to grade the pruned complex correctly;
    -- PruningMap only controls whether it is exposed in D.cache.pruningMap.
    (D, M) := pruneComplex(mComplex, nsteps,
        Strategy => opts.Strategy, Direction => opts.Direction,
        PruningMap => true, UnitTest => opts.UnitTest);
    F := source map(target C.dd_(m+1), , matrix M#0);
    D = (toChainComplex(D, F))[-m];
    R := ring D;
    if opts.PruningMap == true then
      D.cache.pruningMap = map(C, D, i -> map(C_i, D_i, matrix M#(i-m)));
    D
    )

pruneComplex(List, ZZ) := opts -> (mComplex, nsteps) -> (
    len := length mComplex;
    mComplex = mComplex/mutableMatrix;
    if nsteps == -1 then nsteps = len;
    pruningMorph := new MutableList;
    if opts.PruningMap === true then (
        for i from 0 to #mComplex - 1 do pruningMorph#i = mutableIdentity(ring mComplex#0, numRows mComplex#i);
        pruningMorph#(#mComplex) = mutableIdentity(ring mComplex#0, numColumns mComplex#(#mComplex - 1));
        );
    pruningMorph = new List from pruningMorph;
    if      opts.Strategy === Engine  then                              -- call rawPruneComplex
      return enginePruneComplex(mComplex, nsteps, opts)
    else if opts.Direction == "left"  then                              -- pruning the left one first
      for i from 0 to nsteps-1 do
        pruneDiff(mComplex,       i, pruningMorph, PruningMap => opts.PruningMap, UnitTest => opts.UnitTest)
    else if opts.Direction == "right" then                              -- pruning the right one first
      for i from 0 to nsteps-1 do
        pruneDiff(mComplex, len-i-1, pruningMorph, PruningMap => opts.PruningMap, UnitTest => opts.UnitTest)
    else if opts.Direction == "both"  then                              -- pruning outside-in
      (unique splice for i from 1 to lift((nsteps - nsteps % 2)/2, ZZ) list (i, len-i)) /
      (n -> pruneDiff(mComplex,   n, pruningMorph, PruningMap => opts.PruningMap, UnitTest => opts.UnitTest))
    else if opts.Direction == "best"  then                              -- pruning the sparsest unit
      while (
        units := for i from 0 to nsteps - 1 list (
          M := mComplex#i;
          if debugLevel >= 3 then << "Looking for sparsest unit in differential #" << i << endl;
          findSparseUnit(M, UnitTest => opts.UnitTest)               --TODO only recheck the neighbours
          );
        n := minPosition(units/last);
        unit := units#n;
        last unit != infinity
        ) do pruneUnit(mComplex, n, first unit, pruningMorph, PruningMap => opts.PruningMap, UnitTest => opts.UnitTest);
    (mComplex, pruningMorph)
    )

pruneDiff(Complex, ZZ) := opts -> (C, n) -> (
    m := min C;
    -- The pruning morphism is computed internally regardless of the PruningMap
    -- option, since it is needed to grade the result correctly; PruningMap
    -- only controls whether it is also returned to the caller.
    (D, pruningMorph) := pruneDiff(toMutableComplex C, n,
        PruningMap => true, UnitTest => opts.UnitTest);
    F := source map(target C.dd_(m+1), , matrix pruningMorph#0);
    if opts.PruningMap === true then return (toChainComplex(D, F), pruningMorph);
    toChainComplex(D, F)
    )

pruneDiff(Complex, ZZ, List) := opts -> (C, n, M) -> (
    m := min C;
    -- The leftmost module changes only when the 0-th differential is pruned;
    -- in that case the pruning morphism is needed to recover its grading.
    if opts.PruningMap === true then (
        (D, pruningMorph) := pruneDiff(toMutableComplex C, n, M, opts);
        F := target C.dd_(m+1);
        if n == 0 and pruningMorph#0 =!= null then
          F = source map(F, , matrix pruningMorph#0);
        return (toChainComplex(D, F), pruningMorph);
        );
    (D', M') := pruneDiff(toMutableComplex C, n,
        PruningMap => true, UnitTest => opts.UnitTest);
    F' := target C.dd_(m+1);
    if n == 0 then F' = source map(F', , matrix M'#0);
    toChainComplex(D', F')
    )

pruneDiff(List, ZZ)         := opts -> (mComplex, n) -> (
    pruningMorph := new MutableList;
    if opts.PruningMap === true then (
        for i from 0 to #mComplex - 1 do pruningMorph#i = mutableIdentity(ring mComplex#0, numRows mComplex#i);
        pruningMorph#(#mComplex) = mutableIdentity(ring mComplex#0, numColumns mComplex#(#mComplex - 1));
        );
    pruningMorph = new List from pruningMorph;
    pruneDiff(mComplex, n, pruningMorph, opts)
    )

pruneDiff(List, ZZ, List)         := opts -> (mComplex, n, pruningMorph) -> (
    M := mComplex#n;
    if debugLevel >= 2 then
      << "Pruning differential #" << n << " of size " << (numRows M, numColumns M) << endl;
    while (
        unit := findSparseUnit(M, UnitTest => opts.UnitTest);
        last unit =!= infinity
        ) do pruneUnit(mComplex, n, first unit, pruningMorph, opts);
    if debugLevel >= 2 then
      << "\tDifferential reduced to => " << (numRows M, numColumns M) << endl;
    if opts.PruningMap === true then return (mComplex, pruningMorph);
    mComplex
    )

