baseFractionField PolynomialRing := FractionField => D -> D.baseFractionField ??= (
    -- given frac(QQ[e])[a,b,c][x,y,dx,dy]
    -- extract frac(QQ[x,y,a,b,c,e])
    if not isWeylAlgebra D then return frac D;
    -- find the ultimate coefficient ring (in this case QQ)
    K := ultimate(coefficientRing, D);
    F := frac K flattenBaseMonoid_K D;
    F.dpairVars = D.dpairVars;
    -- TODO: think of a better name
    F#"OriginalWeylAlgebra" = D;
    F)

connectionForm Ideal := Net => I -> (
    P := pfaffianSystem I;
    R := rationalWeylAlgebra ring I;
    net sum(P, gens R, (Px, dx) -> Px * dx)
)

connectionForm List := Net => P -> (
    F := ring P#0;
    D := inferWeylAlgebra F;
    R := rationalWeylAlgebra D;
    -- Check all are over the same ring.
    if not same apply(P, ring) then error "expected matrices over the same ring";
    -- Check that length of list == #differential variables
    if not numgens R == #P     then error "expected the same number of matrices as there are differential variables";
    f := map(R, F);
    net sum(P, gens R, (Px, dx) -> f(Px) * dx)
)

gaugeMatrix(List,  List) := (G, newStdMons) -> (
    -- G a Groebner basis for a D-ideal,
    -- newStdMons a list of new standard monomials
    D := ring G#0;
    n := #newStdMons; -- should be holonomicRank ideal G, checked later
    D1 := ring newStdMons#0;
    if not isWeylAlgebra D     then error "expected a Gröbner basis for a left ideal in a Weyl algebra";
    if not isWeylAlgebra D1    then error "expected a list of standard monomials in a Weyl algebra";
    if not same apply(newStdMons, ring)
    or not same apply(G, ring) then error "expected generators and standard monomials in the same Weyl algebra";
    -- this acts as the associated graded ring of rational Weyl algebra
    R := rationalWeylAlgebra D;
    -- normal forms of the new standard monomials wrt G, in R
    L1 := matrix { apply(newStdMons, mon -> normalForm(mon, G)) };
    -- a basis of R_n/R_nI wrt the current monomial order
    L0 := matrix { apply(standardMonomials G, mon -> sub(mon, R)) };
    -- check that there are enough new standard monomials
    if numcols L0 != numcols L1 then error "expected as many standard monomials as the holonomic rank of the ideal";
    -- rows indexed by new standard monomials in L1
    -- cols indexed by old standard monomials in L0
    g := transpose last coefficients(L1, Monomials => L0);
    -- lift to the coefficient field of R
    lift(g, baseFractionField D)
)

gaugeTransform(Matrix, List, PolynomialRing) := (M, A, D) -> (
    F := ring A#0;
    if not same apply(A, ring) then error "expected matrices over the same ring";
    if F =!= baseFractionField D
    or F =!= baseFractionField ring M
    then error "expected matrices over the fraction field of the rational Weyl algebra";
    M = sub(M, F);
    invM := inverse M;
    createDpairs D;
    apply(D.dpairVars#1, A, (dxi, Ai) -> diffRationalWeyl(dxi, M) * invM + M * Ai * invM)
)

isEpsilonFactorized(List, RingElement) := (P,e) -> (
    e = e_(ring first P);
    if not same apply(P, ring) then error "expected matrices over the same ring";
     lst := new MutableList;
    for p in P do (
        tmp  := lstOfDegrees(p,e);
        lst#(#lst) = tmp;
        if #tmp == 0 then return false;
    );
    lstdeg := flatten toList lst;
    all(lstdeg, x -> x == first lstdeg)
)

isEpsilonFactorized(Matrix, RingElement) := (M,e) -> (
    e = e_(ring M);
    lstdeg := lstOfDegrees(M,e);
    if #lstdeg == 0 then return false;
    all(lstdeg, x -> x == first lstdeg)
)

isIntegrable List := Boolean => A -> (
    -- Infers the WeylAlgebra if stored as option.
    D := inferWeylAlgebra(ring A_0);
    if not numgens D // 2 == #A then error "length doesn't match number of differential variables.";
    isIntegrable(D, A)
)

normalForm(RingElement, RingElement) := (f, g) -> (
    if f == 0 then return f;
    D := ring g;
    w := first weights D;
    n := numgens D // 2;
    F := baseFractionField D;
    R := rationalWeylAlgebra(D);
    if R =!= ring f then f = sub(f, R);
    f0 := leadTerm(f);
    g0 := leadTerm(sub(g,R));
    --fexp := unique exponents f0;
    --gexp := unique apply(exponents g0, e -> last pack_n e);
    fexp := (exponents f0)#0;
    gexp := (last pack_n (exponents g0)#0);
    -- as long as we refine with elimination lexicographic order, we don't need generic weights
    -- if #fexp > 1 or #gexp > 1 then error "expected generic weight order";
    -- RECURSION: if g0 does not divide f0, no reduction is necessary
    if not (gexp << fexp) then return f0 + normalForm(f-f0, g);
    -- compare weights of leading monomials
    -- scalar product of exponent vector with the weight of the d's
    fwt := sum(fexp, last pack_n w, times);
    gwt := sum(gexp, last pack_n w, times);
    if fwt < gwt then return f;
    -- find the coefficient to divide by
    fcoef := lift(f0 // R_(fexp), F);
    gcoef := lift(sub(g0, R) // R_(gexp), F);
    -- this must be in D to perform the derivative
    ddexp := fexp - gexp;
    ddmon := D_(toList(n:0) | ddexp);
    -- exponents on the x's are zeroes and exponents of the d's are ddexp
    -- the remainder is f % sub(ddmon * g, R), but we can get it directly as
    r := f - fcoef / gcoef * sub(ddmon * g, R);
    -- now we recurse to normalize the lower order terms
    normalForm(r, g))

normalForm(RingElement, List)          := (f, G) -> (
    -- f and G are in Weyl algebra D, see SST page 7.
    if f == 0 then return f;
    D := ring(G#0);
    w := first weights D;
    R := rationalWeylAlgebra D;
    G = clearDenominators(G, D);
    f = sub(f, R);
    f0 := 0_R;
    -- iteratively reduce the lead term w.r.t G until it does not change
    while f0 != f do ( f0 = f; scan(G, g -> f = reduceLeadTerm(f, g)) );
    -- now recurse to normalize the lower order terms
    f = leadTerm f + normalForm(f - leadTerm f, G);
    -- Alternatively, we can reduce all of f repeatedly, but this may be slower.
    -- while f0 != f do ( f0 = f; scan(G, g -> f = normalForm(f, g)) );
    f)

pfaffianSystem Ideal := List => I -> I.cache.pfaffianSystem ??= (
    D := ring I;
    if not isWeylAlgebra D then error "expected left ideal in a Weyl algebra";
    -- TODO: Change holonomic Rank, so it only takes ideal and infers the order from it.
    w := (((options(D)).MonomialOrder)#1)#1;
    -- this acts as the associated graded ring of rational Weyl algebra
    R := rationalWeylAlgebra D;
    F := baseFractionField D;
    RtoF := map(F, R);
    -- gb with respect to an elimination order
    G := gens gb I;
    if debugLevel > 0 then printerr("Grobner basis: ", net G);
    r := holonomicRank(w, M := comodule I);
    if r === infinity then error "system is not finite dimensional";
    B := sub(M.cache#"basis", R);
    if debugLevel > 0 then printerr("Standard monomials: ", net B);
    apply(generators R, -- loops over the differentials
	dt -> dehomogenizeMatrix transpose concatCols apply(flatten entries B,
	    s -> RtoF last coefficients(
		-- computes (dt * s) % G
		normalForm(dt * s, first entries G), Monomials => B)))
)

pfaffianSystem(Ideal, List) := (I, B)->(
    g := gaugeMatrix(I,B);
    A := pfaffianSystem I;
    gaugeTransform(g, A)
)

standardMonomials Ideal := I -> (
    D := ring I;
    if not isWeylAlgebra D then error "expected left ideal in a Weyl algebra";
    w := (((options(D)).MonomialOrder)#1)#1;
    M := comodule I;
    r := holonomicRank(w, M);
    B := sub(M.cache#"basis", D);
    return flatten entries B;
)

