	g := flattenMorphism matrix f;
	A := ring g;
	-- TODO: both n and w need to be adjusted for the multigraded case
	n := dim A-1;
	w := A^{-n-1};
	-- using Serre duality for coherent sheaves on schemes with mild
	-- singularities, Cohen–Macaulay schemes, not just smooth schemes.
	-- TODO: check that X is proper (or at least finite type)
	transpose part(0, Ext^(n-p)(g, w)))
    )

Hom(Module, Module) := Module => opts -> (M, N) -> (
    -- TODO: take advantage of cached results with higher e
    e := opts.DegreeLimit;
    if e === {} then e = null;
    if e === 0  then e = degree 0_M;
    opts = opts ++ { DegreeLimit => e };
    -- M.cache is a hashless (hence ageless) CacheTable, but
    -- M.cache.cache is a MutableHashTable, hence has an age.
    Y := youngest(M.cache.cache, N.cache.cache);
    if Y#?(Hom, M, N, e) then return Y#(Hom, M, N, e);
    H := runHooks((Hom, Module, Module), (opts, M, N), Strategy => opts.Strategy);
    if H === null then error "Hom: no strategy found for the given input";
    trim' := if opts.MinimalGenerators then trim else identity;
    -- a hack: we really want to type "Hom(M, N) = ..."
    H = Y#(Hom, M, N, e) = if opts.MinimalGenerators then trim H else H;
    H.cache.homomorphism = f -> map(N, M, adjoint'(f, M, N), Degree => first degrees source f + degree f);
    H.cache.formation = FunctionApplication { Hom, (M, N, DegreeLimit => e) };
    H)

Hom(ChainComplex, ChainComplex) := opts -> (F,G) -> (
   outputCx := new ChainComplex;
   outputCx.ring = ring F;
   topDegree := max G - min F;
   botDegree := min G - max F;
   index1 := topDegree;
   while (index1 > botDegree) do
   {
      sourceList := toList (min F .. max G - index1);
      targetList := toList (min F .. max G - (index1 - 1));
      myFn := i -> (fold((a,b) -> (a || b),
		         apply(targetList,
			       j -> (if (j == i) then 
			               Hom(F_i, G.dd_(i+index1), opts)
				     else if (j == i+1) then
				       (-1)^index1 * Hom(F.dd_j, G_(i+index1), opts)
				     else map(Hom(F_j, G_(j+index1-1), opts), Hom(F_i, G_(i+index1), opts), 0)
				     )
				)
			   )
		     );
      diffl := fold((a,b) -> (a | b), apply(sourceList, myFn));
      outputCx#index1 = source diffl;
      outputCx#(index1 - 1) = target diffl;
      outputCx.dd#index1 = diffl;
      index1 = index1 - 1;
   };
   outputCx.max = topDegree;
   outputCx.min = botDegree;
   outputCx.length = topDegree - botDegree;
   outputCx
)

Hom(Complex, Complex) := Complex => opts -> (C,D) -> (
    -- signs here are based from Christensen and Foxby
    -- which agrees with Conrad (Grothendieck duality book)
    Y := youngest(C,D);
    if Y.cache#?(Hom,C,D) then return Y.cache#(Hom,C,D);
    R := ring C;
    if ring D =!= R then error "expected complexes over the same ring";
    (loC,hiC) := C.concentration;
    (loD,hiD) := D.concentration;
    modules := hashTable for i from loD-hiC to hiD-loC list i => (
        directSum for j from loC to hiC list {j,j+i} => Hom(C_j, D_(j+i), opts)
        );
    if loC === hiC and loD === hiD then (
        result := complex(modules#(loD-hiC), Base => loD-loC);
        result.cache.homomorphism = (C,D); -- source first, then target        
        Y.cache#(Hom,C,D) = result;
        return result;
        );
    maps := hashTable for i from loD-hiC+1 to hiD-loC list i => (
        map(modules#(i-1),
            modules#i,
            matrix table(
                indices modules#(i-1),
                indices modules#i,
                (j,k) -> (
                    tar := component(modules#(i-1), j);
                    src := component(modules#i, k);
                    map(tar, src, 
                        if k-j === {0,1} then (-1)^(k#1-k#0+1) * Hom(C_(k#0), dd^D_(k#1), opts)
                        else if k-j === { -1,0 } then Hom(dd^C_(j#0), D_(k#1), opts)
                        else 0)
                    ))));
    result = complex maps;
    result.cache.homomorphism = (C,D); -- source first, then target
    Y.cache#(Hom,C,D) = result;
    result
    )

Hom(ComplexMap, ComplexMap) := ComplexMap => opts -> (f, g) -> (
    df := degree f;
    dg := degree g;
    src := Hom(target f, source g, opts);
    tar := Hom(source f, target g, opts);
    -- for the i-th matrix src_i --> tar_(i+df+dg)
    -- we make a table of matrices, and create a block matrix from that using "matrix" and "map"
    (lo,hi) := src.concentration;
    (loTar, hiTar) := tar.concentration;
    maps := hashTable for i from lo to hi list (
      if i+df+dg < loTar or i+df+dg > hiTar then continue;
      i => (
        m := for q in indices tar_(i+df+dg) list (
               -- so q == {k,k+i+df+dg}
               for p in indices src_i list (
                   -- so p == {j,j+i}, for various j
                   if p#0 - df == q#0 
                   then (
                       sgn := 1; -- function of df, dg, i
                       sgn = (-1)^(df * (i + dg));
                       sgn * Hom(f_(q#0), g_(p#1), opts)
                       )
                   else map(component(tar_(i+df+dg), q),
                            component(src_i, p),
                            0)
                   ));
        map(tar_(i+df+dg),
            src_i,
            matrix m
            )
      ));
    result := map(tar, src, maps, Degree=>df+dg);
    if isCommutativeCached f and isCommutativeCached g then
        result.cache.isCommutative = true;
    result    
    -- f : C1 --> C2, g : D1 --> D2
    -- Hom(f,g) : Hom(C2,D1)_i --> Hom(C1,D2)_(i+df+dg) (indices?)
    -- Hom(C2,D1)_i = sum_j Hom(C2_j, D1_(j+i))
    -- Hom(C1,D2)_(i+df+dg) = sum_k Hom(C1_k, D2_(k+i+df+dg))
    -- map takes j-th part of k=j-df part, block diagonal, apparently.
    -- need to premultiply by f_(j-df), postmult by g_(j+i)
    -- Hom(f_(j-df), g_(j+i))
    )

Hom(CpMackeyFunctor, CpMackeyFunctor) := Module => opts -> (M,N) -> (
    if not M.PrimeOrder === N.PrimeOrder then error "-- Mackey functors must have the same prime";
    homFixedFixed := Hom(M.Fixed, N.Fixed);
    homUnderlyingUnderlying := Hom(M.Underlying, N.Underlying);
    homFixedUnderlying := Hom(M.Fixed, N.Underlying);
    homUnderlyingFixed := Hom(M.Underlying, N.Fixed);
    lhs := directSum(homUnderlyingUnderlying, homFixedFixed);
    rhs := directSum(homFixedUnderlying, homUnderlyingFixed, homUnderlyingUnderlying);
    result := kernel map(rhs, lhs, matrix(
        {
            {-Hom(M.Res, N.Underlying), Hom(M.Fixed, N.Res)},
            {-Hom(M.Underlying, N.Trans), Hom(M.Trans, N.Fixed)},
            {Hom(M.Conj, N.Underlying) - Hom(M.Underlying, N.Conj), 0}
        }
    ));
    result.cache.homomorphism = f -> (
        map(
            N, M,
            homomorphism (inducedMap(homUnderlyingUnderlying, result, lhs^[0]) * f),
            homomorphism (inducedMap(homFixedFixed, result, lhs^[1]) * f)
        )
    );
    result.cache.formation = FunctionApplication { Hom, (M, N) };
    result
)

Hom(CpMackeyFunctor, MackeyFunctorHomomorphism) := Matrix => opts -> (M,f) -> (
    if not M.PrimeOrder === (source f).PrimeOrder then error "-- Mackey functors must have the same prime";
    T := M.Fixed;
    B := M.Underlying;
    fT := f.FixedMap;
    fB := f.UnderlyingMap;
    phi := Hom(T, fT);
    psi := Hom(B, fB);
    inducedMap(Hom(M,target(f)), Hom(M, source(f)), psi ++ phi)
)

Hom(MackeyFunctorHomomorphism, CpMackeyFunctor) := Matrix => opts -> (f,N) -> (
    if not (source f).PrimeOrder === N.PrimeOrder then error "-- Mackey functors must have the same prime";
    T := N.Fixed;
    B := N.Underlying;
    fT := f.FixedMap;
    fB := f.UnderlyingMap;
    phi := Hom(fT, T);
    psi := Hom(fB, B);
    inducedMap(Hom(source(f),N), Hom(target(f),N), psi ++ phi)
)

Hom(ZZdFactorization,ZZdFactorization) := ZZdFactorization => opts -> (C,D) -> (
    if not(C.period == D.period) then error "Expected factorizations with the same period";
    t := if (ring C).?rootOfUnity then (ring C).rootOfUnity else -1;
    if not((ring C).?rootOfUnity) and not(C.period==2) then error "Must adjoin dth root of unity when input has period d > 2";
    -- signs here are based from Christensen and Foxby
    -- which agrees with Conrad (Grothendieck duality book)
    Y := youngest(C,D);
    if Y.cache#?(Hom,C,D) then return Y.cache#(Hom,C,D);
    R := ring C;
    p := C.period;
    if ring D =!= R then error "expected factorizations over the same ring";
    modules := hashTable for i from 0 to p-1 list i => (
        directSum for j from 0 to p-1 list {j,(j+i)%p} => Hom(C_j, D_(j+i), opts)
        );
    maps := hashTable for i from 1 to p list i => (
        map(modules#((i-1)%p),
            modules#(i%p),
            matrix table(
                indices modules#((i-1)%p),
                indices modules#(i%p),
                (j,k) -> (
                    tar := component(modules#((i-1)%p), j);
                    src := component(modules#(i%p), k);
                    map(tar, src, 
                        if ({(k#0-j#0)%p,(k#1-j#1)%p} == {0,1}) then -(t)^(k#1-k#0) * Hom(C_(k#0), dd^D_(k#1), opts)
                        else if ({(k#0-j#0)%p,(k#1-j#1)%p} == { p-1,0 }) then Hom(dd^C_(j#0), D_(k#1), opts)
                        else 0)
                    ))));
    result := ZZdfactorization maps;
    result.cache.homomorphism = (C,D); -- source first, then target
    Y.cache#(Hom,C,D) = result;
    result
    )

Hom(ZZdFactorization,ZZdFactorization,RingElement) := ZZdFactorization => opts -> (F,G,t) -> (
    if not(F.period==G.period) then error "Expected factorizations with the same period";
    if F.period==2 then error "No need to specify root of unity for ZZ/2-graded factorization";
    dHom(F,G,t,RootOfUnity=>false)
    )

Hom(ZZdFactorization,ZZdFactorization,Symbol) := ZZdFactorization => opts -> (F,G,t) -> (
    if not(F.period==G.period) then error "Expected factorizations with the same period";
    if F.period==2 then error "No need to specify root of unity for ZZ/2-graded factorization";
    dHom(F,G,t)
    )

Hom(ZZdFactorizationMap,ZZdFactorizationMap) := ZZdFactorizationMap => opts -> (f,g) -> (
    if not(period f == period g) then error "Expected factorizations with the same period";
    t := if (ring f).?rootOfUnity then (ring f).rootOfUnity else -1;
    if not((ring f).?rootOfUnity) and not(period f==2) then error "Must adjoin dth root of unity when input has period d > 2";
    df := degree f;
    dg := degree g;
    src := Hom(target f, source g, opts);
    tar := Hom(source f, target g, opts);
    -- for the i-th matrix src_i --> tar_(i+df+dg)
    -- we make a table of matrices, and create a block matrix from that using "matrix" and "map"
    per := period f;
    maps := hashTable for i from 1 to per list (
      i => (
        m := for q in indices tar_(i+df+dg) list (
               -- so q == {k,k+i+df+dg}
               for p in indices src_i list (
                   -- so p == {j,j+i}, for various j
                   if (p#0 - df)%per == q#0 
                   then (
                       sgn := 1; -- function of df, dg, i
                       sgn = -(t)^(df * (i + dg));
                       sgn * Hom(f_(q#0), g_(p#1), opts)
                       )
                   else map(component(tar_(i+df+dg), q),
                            component(src_i, p),
                            0)
                   ));
        map(tar_(i+df+dg),
            src_i,
            matrix m
            )
      ));
    result := map(tar, src, maps, Degree=>df+dg);
    if isCommutativeCached f and isCommutativeCached g then
        result.cache.isCommutative = true;
    result    
    -- f : C1 --> C2, g : D1 --> D2
    -- Hom(f,g) : Hom(C2,D1)_i --> Hom(C1,D2)_(i+df+dg) (indices?)
    -- Hom(C2,D1)_i = sum_j Hom(C2_j, D1_(j+i))
    -- Hom(C1,D2)_(i+df+dg) = sum_k Hom(C1_k, D2_(k+i+df+dg))
    -- map takes j-th part of k=j-df part, block diagonal, apparently.
