    if f!=0 and g==0 then return false;
    if f==0 and g!=0 then return false;
    (lo1,hi1) := (0,(source f).period);
    (lo2,hi2) := (0,(source g).period);
    for i from 0 to max(hi1,hi2) do (
        if f_i != g_i then return false;
