GradedModuleMap == ZZ := (f,i) -> (
     if i === 0 then all(spots f, j -> f_j == 0)
     else source f == target f and f == i id_(source f))

PadicNumber == Number := (x, y) -> (
    if y == 0 then value padicIsZero x.number == 1
    else x^QQ == y)

Permutation == Permutation := Boolean => (w, v) -> (
    (w, v) = extend(w,v);
    toList(w) == toList(v)
)

LeafTree == LeafTree := (S,T) -> (
    if leaves S != leaves T then return false;
    l := first leavesList S;
    ES := set apply(edges S, e->orientEdge(S,e,l));
    ET := set apply(edges T, e->orientEdge(T,e,l));
    ES == ET
    )

Cone == Cone := (C1,C2) -> (
   contains(C1, C2) and contains(C2, C1)
)

Fan == Fan := (F1, F2) -> (
   r1 := rays F1;
   l1 := linealitySpace F1;
   r2 := rays F2;
   if numRows r1 != numRows r2 then return false;
   if numColumns r1 != numColumns r2 then return false;
   m1 := maxCones F1;
   m2 := maxCones F2;
   if #m1 != #m2 then return false;
   rayMap := rayCorrespondenceMap(r1, l1, r2);
   m1Mapped := apply(m1,
      maxCone -> (
         sort apply(maxCone, l -> rayMap#l)
      )
   );
   m2Mapped := apply(m2, maxCone -> sort maxCone);
   (sort m1Mapped) == (sort m2Mapped)
)

Polyhedron == Polyhedron := (P1,P2) -> (
   contains(P1, P2) and contains(P2, P1)
)

RationalMapping == RationalMapping := Boolean => (phi, psi) -> (
    isSameMap(phi, psi)
);

ProjectivePoint == ProjectivePoint := (p1, p2) -> (
    if not #p1 == #p2 then error "wrong number of coordinates";
    p1 = homogCoord toList p1;
    p2 = homogCoord toList p2;
    return p1 == p2;
);

ClassFunction == ClassFunction := (ch1,ch2) ->
(
     equ := true;
     for i in unique(keysCF ch1 | keysCF ch2) do
     	  if not ((not ch1#?i and not ch2#?i) or (ch1#?i and ch2#?i and ch1#i == ch2#i)) then
     	  (
	       equ = false;
	       break;
	       );
     equ
     )

SimplicialModule == SimplicialModule := (C,D) -> (
    --note: we don't check for equality of keys since some operations
    --on simplicial modules may add a key
    if C === D then return true;
    if topDegree C =!= topDegree D then return false;
    if ring C =!= ring D then return false;
    for i from 0 to C.topDegree do (
        if C_i != D_i then return false;
        );
    for i in keys C.dd.map do (
	if not matEq(matrix C.dd.map#i, matrix D.dd.map#i) then return false;
	);
    if C.?ss then for i in keys C.ss.map do (
	if not matEq(matrix C.ss.map#i, matrix D.ss.map#i) then return false;
	);
    true    
    )

SimplicialModule == ZZ := (C,n) -> (
    if n =!= 0 then error "cannot compare simplicial module to non-zero integer";
    for i from 0 to C.topDegree do if C_i != 0 then return false;
    true
    )

SimplicialModuleMap == SimplicialModuleMap := (f,g) -> (
    if f === g then return true;    
    if source f != source g or target f != target g 
      then return false;
    for i from 0 to (source f).topDegree do (
        if not (try (f_i == g_i) else matEq(matrix f_i, matrix g_i)) then return false;
        );
    true
    )

SimplicialModuleMap == ZZ := Boolean => (f,n) -> (
    if n === 0 then
        all(keys f.map, k -> f.map#k == 0)
    else if n === 1 then (
        if source f != target f then return false;
        if degree f =!= 0 then return false;
        (lo,hi) := (0,(source f).topDegree);
        for i from lo to hi do
            if not (try (f_i == id_((source f)_i)) else matIsId(matrix f_i)) then return false;
        f.cache.isCommutative = true;  -- this is the identity, after all!
        true
        )
    else 
        error "cannot compare ComplexMap to integer other than 0 or 1"
    )

MultidimensionalMatrix == MultidimensionalMatrix := (M,N) -> (
    if shape M != shape N then return false;
    if ring M =!= ring N then return false;
    M#"multilinearForm" == N#"multilinearForm"
);

MultidimensionalMatrix == ZZ := (M,n) -> (
    if n != 0 then error "encountered integer other than 0 in comparison with a multidimensional matrix";
    L := entries M;
    for i from 1 to dim M -1 do L = flatten L;
    matrix{L} == 0
);

YoungTableau == YoungTableau := (S,T) -> (

    toList S#partition == toList T#partition and toList S#values == toList T#values
    )

FirstOrderDeformation == FirstOrderDeformation := (f1,f2)->(
if ((f1.bigTorusDegree)!=(f2.bigTorusDegree)) then return(false);
if f1.gens==f2.gens then return(true);
if ((ideal f1.gens) == (ideal f2.gens)) then return(true);
false)

Complex == Complex :=(C1,C2)->(
if not(C1.simplexRing===C2.simplexRing) then return(false);
if C1.grading!=C2.grading then return(false);
if C1.dim!=C2.dim then return(false);
return(compareFaces(C1.facets,C2.facets))
)

SOSPoly == RingElement := (S, f) -> (
    if ring S=!=ring f then
        error "Cannot compare elements of different rings. Try to use 'sub'.";
    value S == f
    )

SOSPoly == Matrix := (S, F) -> (
    if numRows F!=1 or numColumns F!=1 then
        error "matrices have different shapes"
    else S == F_(0,0)
    )

YoungTableau == YoungTableau := (T1,T2) -> (
    (lam1,mu1) := standardize skewShape T1;
    (lam2,mu2) := standardize skewShape T2;

    toList lam1 == toList lam2 and toList mu1 == toList mu2 and entries T1 == entries T2
    )

ToricQuiver == ToricQuiver := Boolean => (TQ1, TQ2) -> (
    (TQ1.Q1 === TQ2.Q1) and (TQ1.flow == TQ2.flow)
)

ToricCycle == ToricCycle := Boolean => (D,E) ->(
    return variety D === variety E and (for orbit in sort support(D) list D#orbit)==(for orbit in sort support(E) list E#orbit);
);

OrderedQQn == OrderedQQn := (N, M) -> (
    N.cache.Ring === M.cache.Ring
)

RWeilDivisor == RWeilDivisor := Boolean => (D, E) ->
(
    if (not (ring D === ring E)) then error "Expected divisors to have the same ring.";
	divDiff := cleanSupport( D - E );
	isZeroDivisor(divDiff)
);

WittRingElement == ZZ := (w1, n) -> (
    w1 == n*witt({1_(unWitt ring w1)} | for i from 0 to wittLength ring w1 - 2 list 0)
)

