Number * CCi := (n, I) -> (
    i1 := I#0;
    i2 := I#1;
    ren := realPart n;
    imn := imaginaryPart n;
    intervalCCi(ren * i1 - imn * i2, ren * i2 + imn * i1)
    )

CCi * Number := (I, n) -> (
    n * I
    )

Number * CCiMatrix := (n, I) -> (
    i1 := I#0;
    i2 := I#1;
    ren := realPart n;
    imn := imaginaryPart n;
    matrixCCi(ren * i1 - imn * i2, ren * i2 + imn * i1)
    )

CCiMatrix * Number := (I, n) -> (
    n * I
    )

CCiMatrix * CCiMatrix := (l, n) -> (
    if length first l =!= length n then error "maps not composable";
    numrow := length l;
    numc := length(l#0);
    numcol := length(n#0);
    mat :=  apply(apply(l, i -> (k := 0; while k < numc list ( j := 0; while j < numcol list ((i#k)*((n#k)#j)) do j = j+1)  do k=k+1)), b -> sum b);
    mat
    )

Matrix * CCiMatrix := (l, n) -> (
    l = entries l;
    if length first l =!= length n then error "maps not composable";
    numrow := length l;
    numc := length(l#0);
    numcol := length(n#0);
    mat :=  apply(apply(l, i -> (k := 0; while k < numc list ( j := 0; while j < numcol list ((i#k)*((n#k)#j)) do j = j+1)  do k=k+1)), b -> sum b);
    matrixCCi mat
    )

RingElement * VectorInWidth := (r, v) -> (
    clsv := class v;
    fmod := clsv.freeOIMod;
    wid := clsv.wid;

    if not class r === getAlgebraInWidth(fmod.polyOIAlg, wid) then error("cannot multiply " | net r | " and " | net v);
    if isZero v then return v;

    K := getBasisKeys(fmod, wid);
    A := for key in K list key => r * v#key;

    makeVectorInWidth(clsv, A)
)

Number * VectorInWidth := (n, v) -> (
    cls := class v;
    n_(getAlgebraInWidth(cls.freeOIMod.polyOIAlg, cls.wid)) * v
)

RingElement * ChainComplexMap := (r,f) -> (
     complete f;
     g := new ChainComplexMap;
     g.cache = new CacheTable;
     g.source = f.source;
     g.target = f.target;
     g.degree = f.degree;
     scan(spots f, i -> g#i = r * f_i);
     g)

ZZ * ChainComplexMap := (n,f) -> (
     complete f;
     g := new ChainComplexMap;
     g.cache = new CacheTable;
     g.source = f.source;
     g.target = f.target;
     g.degree = f.degree;
     scan(spots f, i -> g#i = n * f_i);
     g)

ChainComplexMap * ChainComplexMap := ChainComplexMap => (g,f) -> (
     if target f != source g then error "expected composable maps of chain complexes";
     h := new ChainComplexMap;
     h.cache = new CacheTable;
     h.source = source f;
     h.target = target g;
     h.degree = f.degree + g.degree;
     complete f;
     complete g;
     scan(union(spots f, apply(spots g, i -> i - f.degree)),
	  i -> h#i = g_(i+f.degree) * f_i);
     h)

RingElement * GradedModuleMap := GradedModuleMap => (r,f) -> (
     g := new GradedModuleMap;
     g.ring = ring f;
     g.source = f.source;
     g.target = f.target;
     g.degree = f.degree;
