ToricCycle * ToricCycle := (C,D) ->(
  --assert(variety C === variety D);
  X := variety D;
  E := toricCycle({},{},X); --resulting cycle
  for d in support D do(
    V := C; --auxiliary cycle
    for i in d do(
      V = X_i * V;
    );
    V = (D#d) * V;
    E = E + V;
  );
  return E;
);

