VirtualTally ^** ZZ := VirtualTally => (x,n) -> (
     if n < 0 then error "expected non-negative integer";
     if n == 0 then return new class x from {()};
     if n == 1 then return applyKeys(x,i -> 1:i);
     y := x ** x;
     scan(n-2, i -> y = y ** x);
     y)

Character ^** ZZ := Character => (c,n) -> (
    -- return error for negative exponents
    if n < 0 then (
	error "Character ^** ZZ: not implemented for negative exponents; use dual";
	)
    -- for n=0, return trivial character in hom degree zero
    else if n == 0 then (
	H := hashTable {
	    (0,matrix{toList(c.numActors:1_(c.degreesRing))})
	    };
	new Character from {
	    cache => new CacheTable,
	    (symbol degreesRing) => c.degreesRing,
	    (symbol degreeOrbit) => c.degreeOrbit,
	    (symbol degreeRepresentative) => c.degreeRepresentative,
	    (symbol numActors) => c.numActors,
	    (symbol characters) => H
	    }
	)
    -- for n=1, return original character
    else if n == 1 then (
	c
	)
    -- for n>=2, then reduce to lower power
    else (
	tensor(c, c ^** (n-1) )
	)
    )

LieAlgebraModule ^** ZZ := (M, n) -> M.cache#(symbol ^**, n) ??= (
	if n<0 then "error nonnegative powers only";
    	if n==0 then trivialModule M#"LieAlgebra"
    	else if n==1 then M
    	else M**(M^**(n-1)) -- order matters for speed purposes
    )

MultirationalMap ^** MultiprojectiveVariety := (Phi,Z) -> (
    if ring ambient target Phi =!= ring ambient Z then error "expected a multi-projective variety in the same ambient multi-projective space of the target of the map";
    -- if not isSubset(Z,target Phi) then error "expected a subvariety of the target of the map";
    -- <<"--warning: the code for ^** must be improved, use instead the method ^*"<<endl;
    makeSubvariety multisaturate ((segre Phi)^** ((segre target Phi) ideal Z))
);

NormalToricVariety ^** ZZ := NormalToricVariety => (X, n) ->  (
    if n <= 0 then error "-- expected a positive integer";
    cartesianProduct (n : X)
    )

AbstractSheaf ^** ZZ := AbstractSheaf => (E,n) -> (
     if n == 1 then return E;
     if n < 0 then (
	  if rank E =!= 1 then error "negative tensor power of sheaf of rank not equal to 1 requested";
	  E = dual E;
	  n = - n;
	  );
     abstractSheaf(variety E, ChernCharacter => part(0,dim variety E,(ch E)^n)))

AbstractSheaf ^** QQ := AbstractSheaf ^** RingElement := AbstractSheaf => (E,n) -> (
     if rank E != 1 then error "non-integer tensor power of sheaf of rank not equal to 1 requested";
     abstractSheaf(variety E, Rank => 1, ChernCharacter => geometricSeries(ch E - 1, n, dim variety E)))

