check(List, Package) := opts -> (L, pkg) -> (
    if not pkg.Options.OptionalComponentsPresent then (
	printerr("warning: skipping tests; ", toString pkg, " requires optional components"); return);
    usermode := if opts.UserMode === null then not noinitfile else opts.UserMode;
    --
    use pkg;
    tmp := previousMethodsFound;
    inputs := tests pkg;
    previousMethodsFound = tmp;
    testKeys := if L == {} then toList(0..#inputs-1) else L;
    if #testKeys == 0 then printerr("warning: ", toString pkg,  " has no tests");
    --
    errorList := for k in testKeys list (
	    if not inputs#?k then error(pkg, " has no test #", k);
	    teststring := inputs#k#"code";
	    desc := "check(" | toString k | ", " | format pkg#"pkgname" | ")";
	    ret := elapsedTime captureTestResult(desc, teststring, pkg, usermode);
	    if not ret then (k, temporaryFilenameCounter - 2) else continue);
    outfile := errfile -> temporaryDirectory() | errfile | ".tmp";
    if #errorList > 0 then (
	if opts.Verbose then apply(errorList, (k, errfile) -> (
		stderr << concatenate(printWidth:"=") << endl;
		stderr << locate inputs#k << " error:" << endl;
		printerr getErrors(outfile errfile)));
	stderr << concatenate(printWidth:"=") << endl;
	printerr("Summary: ", toString(#errorList), " test(s) failed in package ", pkg#"pkgname", ":");
	printerr netList(Boxes => false, HorizontalSpace => 2,
	    apply(first \ errorList, i -> { "Test #"|i|".", toString locate tests_i pkg }));
	error("repeat failed tests with:", newline,
	    "  check({", demark(", ", toString \ first \ errorList), "}, ", format pkg#"pkgname", ")")))

check NumericalVariety := o-> V -> (
    if any(keys V, k->(class k =!= ZZ or k<0)) 
    then error "the keys of a NumericalVariety should be nonnegative integers";
    scan(keys V, k->if class k === ZZ then scan(V#k, W->(
		if dim W != k then 
		error "dimension of a witness set does not match the key in NumericalVariety";
		)));
    )

check PolySpace := S -> (
    assert(numrows gens S == 1);
    M := last coefficients gens S;
    assert(numgens numericalImage M == numcols M);
    )

check (ZZ,CongruenceOfCurves) := o -> (n,f) -> (
    X := f#"fourfold";
    try for i to n-1 do f(point ambientFivefold X) else error "the congruence of curves is not valid";
    f
);

check DoublySpecialCubicFourfold := o -> X -> (
    if not (X.cache#?"DataConstruction" and X.cache#?"Construction" and instance(X.cache#"Construction",String) and substring(0,29,X.cache#"Construction") == "X = specialFourfold surface((") then error "expected a cubic fourfold constructed via specialFourfold surface((...),(...))";
    (S,P) := surfaces X;
    (S',C',pr) := X.cache#"DataConstruction";
    C := pr C';
    if not isSubset(C, S * P) then error "projection of curve is not contained in surface-plane intersection";
    D := (S * P) \\ C;
    if dim D != -1 then error("surface-plane intersection contains extra components: " | (? ideal D));
    SingC := support singularLocus C;
    n := S.cache#"FiniteNumberOfNodes";
    if degree SingC == n then (
        if o.Verbose then << "-- verified: surface-plane intersection has correct number of nodes (" << n << ")" << endl;
    ) else (
        error("incorrect number of nodes in surface-plane intersection: expected " | (toString n) | ", obtained " | (toString degree SingC));
    );
    SingS := support singularLocus S;
    if not isSubset(SingC, SingS) then error "singular locus of intersection curve is not contained in the singular locus of the surface";
    resSing := SingS \\ SingC;
    if dim resSing == -1 then (
        if o.Verbose then << "-- verified: surface is smooth outside the curve" << endl;
    ) else (
        errLog := if dim resSing == 0 then (toString degree resSing) | " points" else "singular locus is not 0-dimensional";
        error("surface has singularities outside the curve: " | errLog);
    );
    return X;
);

clean DoublySpecialCubicFourfold := X -> (
    (S,T) := surfaces X;
    K := coefficientRing X;
    x := local x;
    R := K[x_0..x_5];
    S' := Var sub(sub(ideal S,vars R),vars ring ambient X);
    if S.cache#?"euler" then S'.cache#"euler" = S.cache#"euler";
    T' := Var sub(sub(ideal T,vars R),vars ring ambient X);
    if T.cache#?"euler" then T'.cache#"euler" = T.cache#"euler";
    X' := Var sub(sub(ideal X,vars R),vars ring ambient X);
    nS := if S.cache#?"FiniteNumberOfNodes" then S.cache#"FiniteNumberOfNodes" else null;
    nT := if T.cache#?"FiniteNumberOfNodes" then T.cache#"FiniteNumberOfNodes" else null;
    cubicFourfold(S' & T',X',InputCheck=>0,NumNodes=>(nS,nT))
);

clean HodgeSpecialFourfold := X -> (
    K := coefficientRing X;
    x := local x;
    n := dim ambient X;
    R := K[x_0..x_n];
    S := surface X;
    S' := Var sub(sub(ideal S,vars R),vars ring ambient X);
    X' := Var sub(sub(ideal X,vars R),vars ring ambient X);
    V' := Var sub(sub(ideal ambientFivefold X,vars R),vars ring ambient X);
    if S.cache#?"euler" then S'.cache#"euler" = S.cache#"euler";
    if S.cache#?"FiniteNumberOfNodes" then S'.cache#"FiniteNumberOfNodes" = S.cache#"FiniteNumberOfNodes";
    specialFourfold(S',X',V',InputCheck=>0)
);

clean(RR,SOSPoly) := (tol,s) -> (
    if s===null then return (,);
    R := ring s;
    kk := coefficientRing R;
    if kk === QQ then tol=0.;
    g := gens s;
    d := coefficients s;
    I := positions(d, di -> di>tol);
    d = d_I;
    g = g_I;
    if kk =!= QQ then g = clean_tol \ g;
    sosPoly(R,g,d)
    )

clean(RR, Complex) := (epsilon, C) -> (
    (loC, hiC) := concentration C;
    if loC === hiC then return C;
    complex hashTable for i from loC + 1 to hiC list i => clean(epsilon, C.dd_i)
    )

clean(RR, ComplexMap) := (epsilon, f) -> (
    H := hashTable for k in keys f list if instance(k,ZZ) then k => clean(epsilon, f_k) else continue;
    map(clean(epsilon, target f), clean(epsilon, source f), H)
    )

