     )

Manipulator SCSCPConnection := (m, s) -> (
	if m === close then closeConnection s
	else error concatenate("Cannot apply Manipulator ", toString m, " to SCSCPConnection");
)

code FilePosition := x -> (
    filename := x#0; start := x#1; stop := x#3 ?? x#1;
     (
	  wp := set characters " \t\r);";
	  file := (
	       if match("startup\\.m2\\.in$", filename) then startupString
	       else if filename === "currentString" then (
		    if currentString === null
		    then error "code no longer available"
		    else currentString)
	       else if filename === "stdio" then (
		    start = 1;
		    stop += 1 - x#1;
		    toString stack apply(x#1..x#1+stop-1,
			i -> getHistory(i + historyOffset)))
	       else (
		    if not fileExists filename then error ("couldn't find file ", filename);
		    get filename
		    )
	       );
	  file = lines file;
	  if #file < stop then error("line number ",toString stop, " not found in file ", filename);
	  DIV splice { codeAddress(x), codeContent(start, stop, file) }
	  ))

code Sequence   := s -> (
    key := select(s, x -> not instance(x, Option));
    -- handle strategies
    mesg := "-- code for method: ";
    func := if not #key === #s then (
	mesg = "-- code for strategy: ";
	opts := new OptionTable from toList select(s, x -> instance(x, Option));
	if opts.?Strategy then (
	    strategy := opts.Strategy;
	    store := getHookStore(key, false);
	    if store =!= null and store#?key
	    and store#key.HookAlgorithms#?strategy
	    then store#key.HookAlgorithms#strategy));
    -- TODO: say "strategies for method: ..."
    if func =!= null or (func = lookup key) =!= null
    then DIV { DIV { mesg, formatDocumentTag s }, codeFunction(s, func, 0) }
    else "-- no method function found: " | formatDocumentTag key)

codim(ChordalNetChain) := optsC -> (
    -- ignore first argument (options)
    chain:= optsC_1;
    cdim:= sum for Nj in values chain list #Nj.gens;
    return cdim;
)

codim(ChordalNet) := optsN -> (
    -- ignore first argument (options)
    N := optsN_1;
    checkTriangular N;
    initState := Nj -> if Nj=!=null then #Nj.gens else 0;
    initMess := Np -> infinity;
    message := (cdimNj,messg) -> min(cdimNj,messg);
    update := (cdimNp,messg) -> cdimNp+messg;
    Cdims := messagePassing(N,initState,initMess,message,update);
    return Cdims#null;
)

codim(TriaSystem) := optsT -> (
    -- ignore first argument (options)
    T:= optsT_1;
    cdim:= #T.gens;
    return cdim;
)

coefficient(MonoidElement, RingElement) := (m, f) -> (
    R := ring f;
    M := monoid R;
    k := coefficientRing R;
    if instance(m, M)
    then new k from rawCoefficient(raw k, raw f, raw m)
    else error "coefficient: expected a monomial from the corresponding monoid")

coefficient(RingElement, RingElement) := (m, f) -> (
    R := ring f;
    k := coefficientRing R;
    -- TODO: audit this code and how it is used in towers and inexact fields
    if size m === 1 and leadCoefficient m == 1
    then promote(rawCoefficient(raw k, raw f, rawLeadMonomialR m), k)
    else error "coefficient: expected a monomial from the same ring")

coefficient(Ideal, BasicDivisor) := Number => (P, D) ->
(
	n := 0;
	if (instance(D, WeilDivisor)) then ( n = 0; )
	else if (instance(D, QWeilDivisor)) then ( n = 0/1; )
