    facemaps := applyPairs(C.dd.map, (i, v) -> (i, map(modules#(i_0-1), modules#(i_0), matrix v)));
    if C.?ss then (
	degenmaps := applyPairs(C.ss.map, (i, v) -> (i, map(modules#(i_0+1), modules#(i_0), matrix v)));
