degree VectorInWidth := v -> (
    if isZero v then return 0;

    lt := keyedLeadTerm v;
    elt := lt.vec#(lt.key);
    degElt := (degree elt)#0;

    basisIdx := lt.key#1;
    degBasisElt := -(class v).freeOIMod.degShifts#(basisIdx - 1);

    degElt + degBasisElt
)

degree(ClassFunction) := ch ->
(
     ke := keysCF ch;
     if #ke == 0 then -1 else sum(first ke)
     )

degree Divisor := C -> (
    X := C.Surface;
    (matrix{C.Coordinate} * X.IntersectionPairing * 
	transpose matrix{X.HyperplaneClass})_(0,0)
    )

degrees Module := -*(cacheValue symbol degrees) (*-N -> (
    r := degreeLength(R := ring N);
    if r == 0 then toList(numgens N : {}) else (
	degs := pack(r, rawMultiDegree raw cover N);
	if not (M := monoid R).?degreeGroup
	or isFreeModule(G := M.degreeGroup) then degs
	else apply(degs, reduceDegree_G)))

