    A := M.dgAlgebra;
    vEntries := entries v;
    numGens := rank M.natural;
    natGens := apply(numGens, i -> (M.natural)_i);
    sum apply(numGens, i -> (
        fi := vEntries#i;
        if fi == 0 then 0_(M.natural)
        else (
            term1 := polyDifferential(A, fi) * natGens#i;
            signExp := first degree fi;
            sign := if odd signExp then -1 else 1;
            term2 := sign * fi * M.diff#i;
            term1 + term2
