	   lieAlgebra => L};
    if class A===FGLieSubAlgebra then 
       new FGLieSubAlgebra from
         new HashTable from {
	   cache => new CacheTable,
	   subAlgebra => true,
	   gens => skipzz(f\A#gens,L),	   
	   lieAlgebra => L} else
     if instance(A,LieSubAlgebra) then
          new LieSubAlgebra from J else
     new LieSubSpace from J     
    );

image(LieDerivation,LieSubSpace):=(d,S)->(
    L:=target d;
    if not source d===S#lieAlgebra then
        error "the derivation is not defined on the subspace";
    del:=differential L;
    J:=new HashTable from {
	cache => new CacheTable,
	image => {d,S},
	lieAlgebra => L};
    if (source d===L and d#map===id_L
	and all(d\d\L#cache.gens,x->x===0_L) and d del===zeroDerivation(L) and
       instance(S,LieIdeal))  then new LieSubAlgebra from J else	
       new LieSubSpace from J
    );

image (PosetMap, List) := List => (f, L) -> (
    unique apply(select(L, l -> isMember(l, vertices source f)), p -> f(p))
)

image PosetMap := List => (f) -> (
    image(f, vertices source f)
)

image ZZdFactorizationMap := ZZdFactorization => f -> (
    -- f : B --> C
    B := source f;
    C := target f;
    deg := degree f;
    (lo,hi) := (0,C.period);
    modules := hashTable for i from lo to hi list i => image f_(i-deg);
    result :=  if lo === hi then ZZdfactorization(modules#lo, Base => lo)
        else (
            maps := if isCommutativeCached f then (
                hashTable for i from lo+1 to hi list i => (
                    map(modules#(i-1), modules#i, matrix dd^B_(i-deg))
                )) 
                else (
                    inducedMaps := hashTable for i from lo to hi list i => inducedMap(C_i, modules#i);
                    hashTable for i from lo+1 to hi list i => (
                        map(modules#(i-1), modules#i, (dd^C_i * inducedMaps#i) // inducedMaps#(i-1))
                        ));
            ZZdfactorization maps
            );
    if not isCommutativeCached f and not isWellDefined result then
        error "expected differential on the target to induce a well-defined differential on the image";
    result.cache.image = f;
    result
    )

image MultirationalMap := Phi -> (
    if Phi#"image" =!= null then return Phi#"image";
    if Phi#"isDominant" === true then return target Phi;
    Phi#"image" = Phi (source Phi);
    Phi#"isDominant" = Phi#"image" == target Phi;
    if Phi#"isDominant" then Phi#"image" = target Phi;
    return Phi#"image";
);

image (MultirationalMap,String) := (Phi,alg) -> (
    if Phi#"image" =!= null then return Phi#"image";
    if Phi#"isDominant" === true then return target Phi;
    Y := projectiveVariety(image(toRationalMap super Phi,alg),MinimalGenerators=>false,Saturate=>false);
    if Phi#"image" === null then Phi#"image" = Y;
    Phi#"isDominant" = Phi#"image" == target Phi;
    if Phi#"isDominant" then Phi#"image" = target Phi;
    return Phi#"image";
);

image ChainComplexMap := ChainComplex => (f) -> (
     D := target f;
     E := source f;
     deg := f.degree;
     C := new ChainComplex;
     C.ring = ring f;
     complete D;
     scan(spots D, k -> C#k = image f_(k-deg));
     scan(spots C, k -> if C#?(k-1) then C.dd#k = map(C#(k-1),C#k,matrix E.dd_(k-deg)));
     C)

image GradedModuleMap := GradedModule => (f) -> (
     E := new GradedModule;
     E.ring = ring f;
     d := f.degree;
     scan(spots f, i -> E#(i+d) = image f#i);
     E
     )

image SimplicialModuleMap := SimplicialModule => f -> (
    -- f : B --> C
    local result;
    B := source f;
    C := target f;
    deg := degree f;
    modules := hashTable for i from 0 to C.topDegree list i => image f_(i-deg);
    inducedMaps := hashTable for i from 0 to B.topDegree list i => inducedMap(C_i, modules#i);
    facemaps := applyPairs(C.dd.map, (i, v) -> (
	    b1 := v * inducedMaps#(i_0);
	    b2 := map(target b1, source inducedMaps#(i_0-1), inducedMaps#(i_0-1));
	    (i, b1 // b2)
	    ));
    if C.?ss then (
	degenmaps := applyPairs(C.ss.map, (i, v) -> (
		b1 := v * inducedMaps#(i_0);
		b2 := map(target b1, source inducedMaps#(i_0+1), inducedMaps#(i_0+1));
		(i, b1 // b2)
		));
	result =  simplicialModule(modules,facemaps,degenmaps,C.topDegree);
	result.cache.image = f;
	return result;
	);
    result = simplicialModule(modules,facemaps,C.topDegree);
    result.cache.image = f;
    result
    )

image (ToricVectorBundleKlyachko,Matrix) := (T,M) -> (
     k := T#"rank of the vector bundle";
     tRing := T#"ring";
     -- Checking for input errors
     if k != numColumns M then error("The source of the matrix has to be the vector bundle.");
     if tRing =!= ring M then error("The matrix and the bundle have to be over the same ring."); 
     -- Compute a basis of the image
     Mgens := mingens image M;
     ranknew := numColumns Mgens;
     bT := T#"baseTable";
     fT := T#"filtrationTable";
     -- for each ray compute the image of the filtration
     bT = hashTable apply(keys bT, j -> (
	       fTj := drop(sort keys fT#j,1);
	       cols := {};
	       oldImage := map(tRing^ranknew,tRing^0,0);
	       -- for each filtration step compute the image
	       j => apply(fTj, i -> (
			 cols = cols | fT#j#i;
			 -- take the image of the i-th filtration
			 A := M * (bT#j)_cols;
			 -- Represent this in the basis chosen
			 gkMA := (gens ker (Mgens | A))^{0..ranknew-1};
			 -- Select the new basis vectors of the filtration
			 gkMA = mingens (image(oldImage | gkMA) / image oldImage);
			 -- and add them to the matrix
			 oldImage = oldImage |gkMA;
			 -- save the new matrix and filtration step
			 (gkMA,matrix {toList(numColumns gkMA:i)})))));
     -- Generate the new filtration matrices and tables
     fMT := hashTable apply(pairs bT, p -> p#0 => matrix {apply(p#1,last)});
     fT = hashTable apply(pairs fMT, p -> (
	       L := flatten entries p#1;
	       L1 := sort unique L;
	       p#0 => hashTable ({(min L1-1) => {}} | apply(L1, l -> l => positions(L,e -> e == l)))));
     bT = hashTable apply(pairs bT, p -> p#0 => matrix {apply(p#1,first)});
     Tnew := new ToricVectorBundleKlyachko from {
	  "ring" => T#"ring",
	  "rayTable" => T#"rayTable",
	  "baseTable" => bT,
	  "filtrationMatricesTable" => fMT,
	  "filtrationTable" => fT,
	  "ToricVariety" => T#"ToricVariety",
	  "number of affine charts" => T#"number of affine charts",
	  "dimension of the variety" => T#"dimension of the variety",
	  "rank of the vector bundle" => ranknew,
	  "number of rays" => T#"number of rays",
	  symbol cache => new CacheTable};
     if T.cache.?isVB and T.cache.isVB then Tnew.cache.isVB = true;
     Tnew)

imaginaryPart CCi := I -> (
    last I
    )

importFrom(Package, List) := (P, x) -> apply(nonnull x, s ->
    try currentPackage#"private dictionary"#s = P#"private dictionary"#s
    else warning("importFrom: failed to import symbol ", s))

independentSets (Matroid, Set) := List => opts -> (M, S) -> ( 
	H := hashTable transpose({toList(0..<#S)} | {sort keys S});
	apply(bases restriction(M, S), b -> b/(i -> H#i))
)

indices HashTable := X -> (
     if X.cache.?components then if X.cache.?indices then X.cache.indices else toList ( 0 .. #X.cache.components - 1 )
     else error "expected an object with components"
     )

inducedMap(Module, Module)          := Matrix => opts -> (M, N) -> (
    if ambient M =!= ambient N then error "inducedMap: expected modules with same ambient free module";
    -- e.g. avoid a gb computation for inducedMap(M, image basis(d, M))
    if N.cache.?Monomials and M === target N.cache.Monomials
    then map(M, N, N.cache.Monomials, Degree => opts.Degree)
    else inducedMap(M, N, id_(ambient N), opts))

inducedMap(Module, Nothing, Matrix) := Matrix => opts -> (M, N, f) -> (
    B := image f;
    -- e.g. avoid a gb computation for inducedMap(image f, , f)
    if M === target B.cache.Monomials
    then map(M, source B.cache.Monomials, B.cache.Monomials, Degree => opts.Degree)
    else inducedMap(M, source f, f, opts))

inducedMap(Module,Module,Matrix) := Matrix => opts -> (N',M',f) -> (
     N := target f;
     M := source f;
     if ring N' =!= ring M' or ring N' =!= ring f then error "inducedMap: expected modules and map over the same ring";
    if isFreeModule N and isFreeModule M and (
	N =!= ambient N' and rank N === rank ambient N' or
	M =!= ambient M' and rank M === rank ambient M')
     then f = map(N = ambient N', M = ambient M', f)
     else (
	if ambient N' =!= ambient N then error "inducedMap: expected new target and target of map provided to be subquotients of same free module";
	if ambient M' =!= ambient M then error "inducedMap: expected new source and source of map provided to be subquotients of same free module");
     c := runHooks((inducedMap, Module, Module, Matrix), (opts, N', M', f));
     (f', g, gbN', gbM) := if c =!= null then c else error "inducedMap: no method implemented for this type of input";
     if opts.Verify then (
	  if relations M % relations M' != 0 then error "inducedMap: expected new source not to have fewer relations";
	  if relations N % relations N' != 0 then error "inducedMap: expected new target not to have fewer relations";
	  if generators M' % gbM != 0 then error "inducedMap: expected new source not to have more generators";
	  if g % gbN' != 0 then error "inducedMap: expected matrix to induce a map";
	  if not isWellDefined f' then error "inducedMap: expected matrix to induce a well-defined map";
	  );
     f')

inducedMap(Complex, Complex) := ComplexMap => opts -> (D,C) -> (
    -- compute f : C --> D the map induced by the identity matrix.
    deg := if opts.Degree === null then 0 else opts.Degree;
    (loC,hiC) := concentration C;
    (loD,hiD) := concentration D;
    maps := hashTable for i from max(loC,loD-deg) to min(hiC,hiD-deg) list i => inducedMap(D_(i+deg),C_i, Verify => opts.Verify);
    map(D,C,maps,Degree=>deg)
    )

inducedMap(CpMackeyFunctor, CpMackeyFunctor) := MackeyFunctorHomomorphism => opts -> (N,M) -> (
    map(N,M,inducedMap(N.Underlying, M.Underlying), inducedMap(N.Fixed, M.Fixed))
)

inducedMap(CpMackeyFunctor, CpMackeyFunctor, MackeyFunctorHomomorphism) := MackeyFunctorHomomorphism => opts -> (N,M,f) -> (
    map(N,M,inducedMap(N.Underlying, M.Underlying, f.UnderlyingMap), inducedMap(N.Fixed, M.Fixed, f.FixedMap))
)

inducedMap(CpMackeyFunctor, CpMackeyFunctor, Matrix, Matrix) := MackeyFunctorHomomorphism => opts -> (N,M,u,f) -> (
    map(N,M,inducedMap(N.Underlying, M.Underlying, u), inducedMap(N.Fixed, M.Fixed, f))
)

inducedMap(ZZdFactorization, ZZdFactorization) := ZZdFactorizationMap => opts -> (D,C) -> (
    -- compute f : C --> D the map induced by the identity matrix.
    deg := if opts.Degree === null then 0 else opts.Degree;
    (loC,hiC) := (0,period C);
    (loD,hiD) := (0,period D);
    maps := hashTable for i from max(loC,loD-deg) to min(hiC,hiD-deg) list i => inducedMap(D_(i+deg),C_i, Verify => opts.Verify);
    map(D,C,maps,Degree=>deg)
    )

inducedMap(ZZdFactorization, ZZdFactorization,ZZdFactorizationMap) := ZZdFactorizationMap => opts -> (D,C,phi) -> (
    -- compute f : C --> D the map induced by the identity matrix.
    deg := if opts.Degree === null then degree phi else opts.Degree;
    (loC,hiC) := (0,period C);
    (loD,hiD) := (0,period D);
    maps := hashTable for i from max(loC,loD-deg) to min(hiC,hiD-deg) list i => inducedMap(D_(i+deg),C_i, phi_i, Verify => opts.Verify);
    map(D,C,maps,Degree=>deg)
    )

inducedMap ToricMap := RingMap => o -> (cacheValue symbol inducedMap) (f -> (
    	Y := target f;
    	S := ring Y;
    	R := ring source f;
    	m := picardGroup f; -- degree map
    	map(R, S, apply(numgens S, i -> (
		    exps := entries pullback(f, Y_i);
		    product(numgens R, j -> R_j^(exps#j)))),
	    DegreeMap => (deg -> first entries (matrix{deg} * transpose m)))
	)
    )

inducedMap(ChainComplex,ChainComplex) := ChainComplexMap => options -> (C,D) -> (
     h := new ChainComplexMap;
     h.cache = new CacheTable;
     h.source = D;
     h.target = C;
     deg := h.degree = if options.Degree === null then 0 else options.Degree;
     complete D;
     scan(spots D, k -> if C#?(k+deg) then h#k = inducedMap(C#(k+deg),D#k));
     h
     )

inducedMap(SimplicialModule, SimplicialModule) := SimplicialModuleMap => opts -> (D,C) -> (
    -- compute f : C --> D the map induced by the identity matrix.
    deg := if opts.Degree === null then 0 else opts.Degree;
    (loC,hiC) := (0,C.topDegree);
    (loD,hiD) := (0,D.topDegree);
    maps := hashTable for i from max(loC,loD-deg) to min(hiC,hiD-deg) list i => inducedMap(D_(i+deg),C_i, Verify => opts.Verify);
    map(D,C,maps,Degree=>deg)
    )

inducedMap (FilteredComplex, ZZ) := ComplexMap => opts -> (K,p) -> (
  if not K.cache#?inducedMaps then K.cache.inducedMaps = new MutableHashTable;
  if not K.cache.inducedMaps#?p then K.cache.inducedMaps#p = inducedMap(K_infinity, K_p);
  K.cache.inducedMaps#p)

inducesWellDefinedMap(Module,Module,Matrix) := (M,N,f) -> (
     sM := target f;
     sN := source f;
     if ambient M =!= sM
     then error "'inducesWellDefinedMap' expected target of map to be a subquotient of target module provided";
     if ambient N =!= sN
     then error "'inducesWellDefinedMap' expected source of map to be a subquotient of source module provided";
     (f * generators N) % (generators M) == 0
     and
     (f * relations N) % (relations M) == 0)

parser HypertextContainer := x -> (
    -- Apply parser' first
    x = deepSplice parser' x;
    -- Drop the leading and trailing SPs or BKs
    l := position(x, e -> e =!= SP and e =!= BK);
    t := position(x, e -> e =!= SP and e =!= BK, Reverse => true);
    if l =!= null and t =!= null then x = take(x, {l, t});
    -- ??
    x = splice sublists(x, i -> i === BK or i === SP,
	SPBKs -> if isMember(SP,SPBKs) then (BK,"",BK) else BK);
    x = splice sublists(x, i -> i =!= BK,
	x -> if #x===1 and instance(x#0,List) then horizontalJoin x#0 else wrap horizontalJoin x,
	BK -> ());
    -- Stack the pieces vertically
    stack x);

parser INDENT := x -> ( -- INDENT is like DIV but with extra |s on the left. sadly, can't be absorbed into DIV because of non-recursivity of this parser
    n := parser DIV toList x;
    "| "^(height n, depth n) | n )

Hop := (op,filler) -> x -> (
     r := horizontalJoin apply(nooptsnull x,op);
     if width r === 1 then r = horizontalJoin(r," ");
