    A := f.source;
    B := f.target;
    ok := all(gens A.natural, x -> f.natural(A.diff(x)) == B.diff(f.natural(x)));
    if not ok and debugLevel > 0 then
        << "-- DGAlgebraMap: chain-map condition f(d_A x) = d_B(f x) fails on some generator" << endl;
    ok
