            if #added > 0 then << "-- unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- missing key(s): " << toString missing << endl;
            );
        return false;
        );
    -- source and target
    if ring f.source =!= ring f.target then (
        if debugLevel > 0 then (
            << "-- expected source and target to have the same ring" << endl;
            );
        return false;
        );
    if not isWellDefined f.source or not isWellDefined f.target then (
        if debugLevel > 0 then (
            << "-- expected source and target to be well-defined complexes" << endl;
            );
        return false;
        );
    if not instance(f.degree, ZZ) then (
        if debugLevel > 0 then (
            << "-- expected degree of complex homomorphism to be an integer" << endl;
            );
        return false;
        );
    (lo,hi) := f.source.concentration;
    if not all(keys f.map, i -> instance(i,ZZ) and i >= lo and i <= hi) then (
        if debugLevel > 0 then (
            << "-- expected all maps to be indexed by integers in the concentration [lo,hi] of the source" << endl;
            );
        return false;
        );
    for i from lo to hi do (
        g := f_i;
        if not isWellDefined g then (
            if debugLevel > 0 then (
                << "-- expected all differentials to be well-defined morphisms" << endl;
                << "--   differential at index " << i << " fails this condition" << endl;
                );
            return false;
            );
        if source g =!= f.source_i or target g =!= f.target_(i+f.degree)
        then (
            if debugLevel > 0 then (
                << "-- expected source and target of maps in differential to be modules in the complex " << endl;
                << "--   differential at index " << i << " fails this condition" << endl;                
            );    
            return false;
            );
        );
    if f.cache.?isCommutative then (
        deg := degree f;
        C := f.source;
        D := f.target;
        (loC,hiC) := C.concentration;
        (loD,hiD) := D.concentration;
        iscommutative := true;
        for i from loC to hiC do (
            if i+deg-1 >= loD and i+deg-1 <= hiD then (
                if not (dd^D_(i+deg) * f_i == (-1)^deg * (f_(i-1) * dd^C_i))
                then (
                    iscommutative = false;
                    if f.cache.isCommutative then (
                        if debugLevel > 0 then (
                            << "-- the cache table incorrectly asserts that the maps commute with the differentials " << endl;
                            << "--   differential at index " << i << " fails this condition" << endl;                
                            );
                        return false;
                        );
                    )));
        if iscommutative and not f.cache.isCommutative then (
            if debugLevel > 0 then (
                << "-- the cache table incorrectly asserts that the maps do not commute with the differentials " << endl;
                );
            return false;
            );
        );
    true
    )

isWellDefined MackeyFunctorHomomorphism := Boolean => F ->(
    -- Verify the keys are correct
    if not (F#?Domain and F#?Codomain and F#?UnderlyingMap and F#?FixedMap) then return false;

    -- Verify domain and codomain are indeed Mackey functors
    if not (class F.Domain === CpMackeyFunctor and class F.Codomain === CpMackeyFunctor) then return false;

    -- Verify that the primes are the same
    if not (F.Domain.PrimeOrder == F.Codomain.PrimeOrder) then return false;

    -- Verify F.UnderlyingMap and F.FixedMap have the right domain and codomain
    if not (source F.UnderlyingMap == F.Domain.Underlying and target F.UnderlyingMap == F.Codomain.Underlying) then return false;
    if not (source F.FixedMap == F.Domain.Fixed and target F.FixedMap == F.Codomain.Fixed) then return false;

    -- Check commutes with restriction
    if not (F.UnderlyingMap * F.Domain.Res == F.Codomain.Res * F.FixedMap) then (print " -- the given morphism does not commute with restriction"; return false);

    -- Check commutes with transfer
    if not (F.FixedMap * F.Domain.Trans == F.Codomain.Trans * F.UnderlyingMap) then (print " -- the given morphism does not commute with transfer"; return false);

    -- Check commutes with conjugation
    if not (F.UnderlyingMap * F.Domain.Conj == F.Codomain.Conj * F.UnderlyingMap) then (print " -- the given morphism does not commute with conjugation"; return false);

    true
)

isWellDefined CpMackeyFunctor := Boolean => M -> (
    ------------------------
    -- General type-checking
    ------------------------

    -- Ensure all the keys in the hash table defining a Mackey functor are indeed defined
    if not (M#?PrimeOrder and M#?Res and M#?Trans and M#?Conj and M#?Underlying and M#?Fixed) then (print "-- Hashtable does not have correct keys"; return false);

    -- Check that the input p is actually a prime number
    if not (class M.PrimeOrder === ZZ and isPrime(M.PrimeOrder)) then (print "-- p is not prime"; return false);

    -- Check fixed and underlying modules are Z-modules
    if not (isModule M.Fixed and isModule M.Underlying) then return false;
    if not (ring M.Fixed === ZZ and ring M.Underlying === ZZ) then (print "-- objects are not abelian groups"; return false);

    -- Check source and target of restriction are correct
    if not source(M.Res) == M.Fixed then (print " -- the source of res should be the fixed module"; return false);
    if not target(M.Res) == M.Underlying then (print " -- the target of res should be the underlying module"; return false);

    -- Check source and target of transfer are correct
    if not source(M.Trans) == M.Underlying then (print " -- the source of tr should be the underlying module"; return false);
    if not target(M.Trans) == M.Fixed then (print " -- the target of tr should be the fixed module"; return false);

    -- Check source and target of conjugation are correct
    if not source(M.Conj) == M.Underlying then (print " -- the source of conj should be the underlying module"; return false);
    if not target(M.Conj) == M.Underlying then (print " -- the target of conj should be the underlying module"; return false);

    ---------
    -- Axioms
    ---------

    -- Axiom 1: Conj is an automorphism of order dividing p
    if not isIsomorphism(M.Conj) then return false;
    if not (M.Conj)^(M.PrimeOrder) == id_(M.Underlying) then (print "-- Conj is not an automorphism of order dividing p"; return false);

    -- Axiom 2: res and tr are homomorphisms (item 3 in overleaf)
    if not isWellDefined M.Trans then (print "-- tr is not a homomorphism"; return false);
    if not isWellDefined M.Res then (print "-- res is not a homomorphism"; return false);

    -- Axiom 3: c*res = res and tr*c = tr
    if M.Conj * M.Res != M.Res then (print "-- c * res is not equal to res"; return false);
    if M.Trans * M.Conj != M.Trans then (print "-- tr * c is not equal to tr"; return false);

    -- Axiom 4: res * tr = sum of all conjugates (item 5 in overleaf)
    if not (M.Res * M.Trans == sum for i to M.PrimeOrder-1 list M.Conj^i) then (print "-- res * tr is not equal to the sum of all conjugates"; return false);

    true
)

isWellDefined DGAlgebraMap := f -> (
    k := keys f;
    expectedKeys := set {symbol source, symbol target, symbol natural, symbol ringMap, symbol cache};
    -- `cache` is not always present on legacy DGAlgebraMap objects (net
    -- and arithmetic constructors predate the cache slot); tolerate its
    -- absence.
    kExtra := k - expectedKeys;
    kMissing := (expectedKeys - set {symbol cache}) - k;
    if #kExtra > 0 or #kMissing > 0 then (
        if debugLevel > 0 then (
            if #kExtra > 0 then << "-- DGAlgebraMap: unexpected key(s): " << toString(toList kExtra) << endl;
            if #kMissing > 0 then << "-- DGAlgebraMap: missing key(s): " << toString(toList kMissing) << endl;
        );
        return false;
    );
    if not instance(f.source, DGAlgebra) or not instance(f.target, DGAlgebra) then (
        if debugLevel > 0 then << "-- DGAlgebraMap: expected source and target to be DGAlgebras" << endl;
        return false;
    );
    if not isWellDefined f.source then (
        if debugLevel > 0 then << "-- DGAlgebraMap: source is not a well-defined DGAlgebra" << endl;
        return false;
    );
    if not isWellDefined f.target then (
        if debugLevel > 0 then << "-- DGAlgebraMap: target is not a well-defined DGAlgebra" << endl;
        return false;
    );
    if not instance(f.natural, RingMap) then (
        if debugLevel > 0 then << "-- DGAlgebraMap: expected f.natural to be a RingMap" << endl;
        return false;
    );
    if source f.natural =!= (f.source).natural or target f.natural =!= (f.target).natural then (
        if debugLevel > 0 then << "-- DGAlgebraMap: f.natural does not have the expected source/target rings" << endl;
        return false;
    );
    if not instance(f.ringMap, RingMap) then (
        if debugLevel > 0 then << "-- DGAlgebraMap: expected f.ringMap to be a RingMap" << endl;
        return false;
    );
    -- Semantic: chain-map condition on every DG generator.
    A := f.source;
    B := f.target;
    ok := all(gens A.natural, x -> f.natural(A.diff(x)) == B.diff(f.natural(x)));
    if not ok and debugLevel > 0 then
        << "-- DGAlgebraMap: chain-map condition f(d_A x) = d_B(f x) fails on some generator" << endl;
    ok
)

isWellDefined DGAlgebra := A -> (
    -- Structural check (keys + types).
    if not isValidDGAlgebra A then (
        if debugLevel > 0 then (
            missing := select(
                {symbol ring, symbol natural, symbol diff, symbol Degrees},
                s -> not A#?s);
            if #missing > 0 then
                << "-- DGAlgebra: missing required key(s): " << toString missing << endl;
            if A#?(symbol Degrees) and A#?(symbol natural)
                and #A.Degrees != numgens A.natural then
                << "-- DGAlgebra: #A.Degrees (" << #A.Degrees << ") != numgens A.natural ("
                   << numgens A.natural << ")" << endl;
            if A#?(symbol diff) and A.diff =!= {} and not instance(A.diff, RingMap) then
                << "-- DGAlgebra: A.diff is present but not a RingMap or {}" << endl;
        );
        return false;
    );
    -- Ring consistency: A.natural should be a polynomial-like ring over A.ring.
    if coefficientRing A.natural =!= A.ring and not (ambient A.natural === A.ring) then (
        -- Allow the case where A.ring is a quotient or base ring of A.natural's coefficients.
        -- Soft check: just warn in debug mode.
        if debugLevel > 1 then
            << "-- DGAlgebra: coefficientRing A.natural does not equal A.ring (this is usually OK)" << endl;
    );
    -- Differential degree: d must shift homological degree by -1 on every generator.
    if A.diff =!= {} then (
        for g in gens A.natural do (
            dg := diff(A, g);
            if dg != 0 then (
                degG := first degree g;
                degDG := first degree dg;
                if degDG != degG - 1 then (
                    if debugLevel > 0 then
                        << "-- DGAlgebra: d(" << g << ") has homological degree "
                           << degDG << ", expected " << (degG - 1) << endl;
                    return false;
                );
            );
        );
    );
    -- Semantic: d^2 = 0 on every generator (Leibniz extends to all of A.natural).
    if not isWellDefinedDifferential A then (
        if debugLevel > 0 then << "-- DGAlgebra: d^2 fails to vanish on some generator" << endl;
        return false;
    );
    true
)

isWellDefined DGModule := M -> (
    if not isValidDGModule M then (
        if debugLevel > 0 then (
            missing := select(
                {symbol dgAlgebra, symbol ring, symbol natural, symbol Degrees, symbol diff},
                s -> not M#?s);
            if #missing > 0 then
                << "-- DGModule: missing required key(s): " << toString missing << endl;
            if M#?(symbol diff) and M#?(symbol Degrees) and #M.diff != #M.Degrees then
                << "-- DGModule: #M.diff (" << #M.diff << ") != #M.Degrees (" << #M.Degrees << ")" << endl;
        );
        return false;
    );
    if not isWellDefined M.dgAlgebra then (
        if debugLevel > 0 then << "-- DGModule: M.dgAlgebra is not a well-defined DGAlgebra" << endl;
        return false;
    );
    if M.ring =!= M.dgAlgebra.ring then (
        if debugLevel > 0 then << "-- DGModule: M.ring does not equal M.dgAlgebra.ring" << endl;
        return false;
    );
    -- Each entry of M.diff must be an element of M.natural (or coercible).
    for i from 0 to #M.diff - 1 do (
        d := M.diff#i;
        try (
            -- Test coercion: the entry should be in M.natural's module structure.
            if not (instance(d, Vector) or instance(d, Matrix) or d == 0_(M.natural)) then (
                if debugLevel > 0 then
                    << "-- DGModule: M.diff#" << i << " is not a module element of M.natural" << endl;
                return false;
            );
        ) else (
            if debugLevel > 0 then
                << "-- DGModule: M.diff#" << i << " cannot be interpreted in M.natural" << endl;
            return false;
        );
    );
    -- Semantic: d_M^2 = 0 up to a finite bound.
    if not isWellDefinedDifferential M then (
        if debugLevel > 0 then << "-- DGModule: d_M^2 fails to vanish" << endl;
        return false;
    );
    true
)

isWellDefined DGModuleMap := f -> (
    k := keys f;
    expectedKeys := set {symbol source, symbol target, symbol dgAlgebra, symbol natural, symbol cache};
    if set k =!= expectedKeys then (
        if debugLevel > 0 then (
            added := toList(k - expectedKeys);
            missing := toList(expectedKeys - k);
            if #added > 0 then << "-- DGModuleMap: unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- DGModuleMap: missing key(s): " << toString missing << endl;
        );
        return false;
    );
    if not (instance(f.source, DGModule) or instance(f.source, DGQuotientModule)) then (
        if debugLevel > 0 then << "-- DGModuleMap: f.source is not a DGModule or DGQuotientModule" << endl;
        return false;
    );
    if not (instance(f.target, DGModule) or instance(f.target, DGQuotientModule)) then (
        if debugLevel > 0 then << "-- DGModuleMap: f.target is not a DGModule or DGQuotientModule" << endl;
        return false;
    );
    if instance(f.source, DGModule) and not isWellDefined f.source then (
        if debugLevel > 0 then << "-- DGModuleMap: f.source is not a well-defined DGModule" << endl;
        return false;
    );
    if instance(f.source, DGQuotientModule) and not isWellDefined f.source then (
        if debugLevel > 0 then << "-- DGModuleMap: f.source is not a well-defined DGQuotientModule" << endl;
        return false;
    );
    -- DGQuotientModule targets go through a slightly different path; we
    -- still require the ambient to be well-defined.
    if instance(f.target, DGModule) and not isWellDefined f.target then (
        if debugLevel > 0 then << "-- DGModuleMap: f.target is not a well-defined DGModule" << endl;
        return false;
    );
    if instance(f.target, DGQuotientModule) and not isWellDefined f.target then (
        if debugLevel > 0 then << "-- DGModuleMap: f.target is not a well-defined DGQuotientModule" << endl;
        return false;
    );
    if f.source.dgAlgebra =!= f.target.dgAlgebra then (
        if debugLevel > 0 then << "-- DGModuleMap: source and target must share the same DGAlgebra" << endl;
        return false;
    );
    if f.dgAlgebra =!= f.source.dgAlgebra then (
        if debugLevel > 0 then << "-- DGModuleMap: f.dgAlgebra disagrees with f.source.dgAlgebra" << endl;
        return false;
    );
    if not instance(f.natural, Matrix) then (
        if debugLevel > 0 then << "-- DGModuleMap: f.natural is not a Matrix" << endl;
        return false;
    );
    if source f.natural =!= (f.source).natural then (
        if debugLevel > 0 then << "-- DGModuleMap: source of f.natural is not f.source.natural" << endl;
        return false;
    );
    if target f.natural =!= (f.target).natural then (
        if debugLevel > 0 then << "-- DGModuleMap: target of f.natural is not f.target.natural" << endl;
        return false;
    );
    M := source f;
    N := target f;
    -- Hom-degree check: for each M-generator e_i, f(e_i) must sit in
    -- hom-degree (first M.Degrees#i) of N.natural.  Internal-degree shifts
    -- are allowed (only the first component matters).
    homDegOk := all(#M.Degrees, i -> (
        fei := f.natural * (M.natural)_i;
        if fei == 0 then true
        else first degree fei == first M.Degrees#i
    ));
    if not homDegOk then (
        if debugLevel > 0 then << "-- DGModuleMap: f fails to preserve homological degree on some generator" << endl;
        return false;
    );
    -- Chain-map condition, generator by generator.  diff(N, ·) calls
    -- on DGModule or DGQuotientModule (both supply the Leibniz formula).
    ok := all(#M.Degrees, i -> (
        ei    := (M.natural)_i;
        fei   := f.natural * ei;
        dMei  := M.diff#i;
        dNfei := diff(N, fei);
        fdMei := f.natural * dMei;
        dNfei == fdMei
    ));
    if not ok and debugLevel > 0 then
        << "-- DGModuleMap: chain-map condition d_N(f e_i) = f(d_M e_i) fails on some generator" << endl;
    ok
)

isWellDefined DGIdeal := I -> (
    k := keys I;
    expectedKeys := set {symbol dgAlgebra, symbol ring, symbol natural, symbol generators, symbol cache};
    if set k =!= expectedKeys then (
        if debugLevel > 0 then (
            added := toList(k - expectedKeys);
            missing := toList(expectedKeys - k);
            if #added > 0 then << "-- DGIdeal: unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- DGIdeal: missing key(s): " << toString missing << endl;
        );
        return false;
    );
    if not instance(I.dgAlgebra, DGAlgebra) then (
        if debugLevel > 0 then << "-- DGIdeal: I.dgAlgebra is not a DGAlgebra" << endl;
        return false;
    );
    if not isWellDefined I.dgAlgebra then (
        if debugLevel > 0 then << "-- DGIdeal: I.dgAlgebra is not well-defined" << endl;
        return false;
    );
    if not instance(I.natural, Ideal) then (
        if debugLevel > 0 then << "-- DGIdeal: I.natural is not an Ideal" << endl;
        return false;
    );
    if ring I.natural =!= I.dgAlgebra.natural then (
        if debugLevel > 0 then << "-- DGIdeal: I.natural is not an ideal in I.dgAlgebra.natural" << endl;
        return false;
    );
    ok := isDGIdeal(I.dgAlgebra, I.natural);
    if not ok and debugLevel > 0 then
        << "-- DGIdeal: I.natural is not d-closed (some generator has d(g) not in I)" << endl;
    ok
)

isWellDefined DGSubmodule := S -> (
    k := keys S;
    expectedKeys := set {
        symbol dgAlgebra, symbol ring, symbol natural, symbol Degrees,
        symbol diff, symbol cache, symbol ambient, symbol inclusion
    };
    if set k =!= expectedKeys then (
        if debugLevel > 0 then (
            added := toList(k - expectedKeys);
            missing := toList(expectedKeys - k);
            if #added > 0 then << "-- DGSubmodule: unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- DGSubmodule: missing key(s): " << toString missing << endl;
        );
        return false;
    );
    if not instance(S.ambient, DGModule) then (
        if debugLevel > 0 then << "-- DGSubmodule: S.ambient is not a DGModule" << endl;
        return false;
    );
    if not isWellDefined S.ambient then (
        if debugLevel > 0 then << "-- DGSubmodule: S.ambient is not a well-defined DGModule" << endl;
        return false;
    );
    if not instance(S.inclusion, DGModuleMap) then (
        if debugLevel > 0 then << "-- DGSubmodule: S.inclusion is not a DGModuleMap" << endl;
        return false;
    );
    -- Semantic: the column span of S.inclusion.natural must be d-stable
    -- in M = S.ambient.  The free presentation S.natural and its lifted
    -- differential S.diff are derived from that; d-closure fails iff the
    -- lift has nontrivial residual.
    M := S.ambient;
    incMat := S.inclusion.natural;
    if target incMat =!= M.natural then (
        if debugLevel > 0 then << "-- DGSubmodule: target of inclusion matrix is not M.natural" << endl;
        return false;
    );
    if numcols incMat == 0 then return true;
    dMat := applyDiffColumns(M, incMat);
    residual := dMat - incMat * (dMat // incMat);
    ok := residual == 0;
    if not ok and debugLevel > 0 then
        << "-- DGSubmodule: inclusion's column span is not d-closed in the ambient DGModule" << endl;
    ok
)

isWellDefined DGQuotientModule := Q -> (
    k := keys Q;
    expectedKeys := set {
        symbol dgAlgebra, symbol ring, symbol natural, symbol Degrees,
        symbol diff, symbol cache, symbol ambient, symbol subDGModule,
        symbol projection
    };
    if set k =!= expectedKeys then (
        if debugLevel > 0 then (
            added := toList(k - expectedKeys);
            missing := toList(expectedKeys - k);
            if #added > 0 then << "-- DGQuotientModule: unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- DGQuotientModule: missing key(s): " << toString missing << endl;
        );
        return false;
    );
    if not instance(Q.ambient, DGModule) then (
        if debugLevel > 0 then << "-- DGQuotientModule: Q.ambient is not a DGModule" << endl;
        return false;
    );
    if not instance(Q.subDGModule, DGSubmodule) then (
        if debugLevel > 0 then << "-- DGQuotientModule: Q.subDGModule is not a DGSubmodule" << endl;
        return false;
    );
    if Q.subDGModule.ambient =!= Q.ambient then (
        if debugLevel > 0 then << "-- DGQuotientModule: Q.subDGModule.ambient does not match Q.ambient" << endl;
        return false;
    );
    if not instance(Q.projection, DGModuleMap) then (
        if debugLevel > 0 then << "-- DGQuotientModule: Q.projection is not a DGModuleMap" << endl;
        return false;
    );
    if source Q.projection =!= Q.ambient or target Q.projection =!= Q then (
        if debugLevel > 0 then << "-- DGQuotientModule: Q.projection has wrong source/target" << endl;
        return false;
    );
    -- Semantic: delegate to the submodule's well-definedness (which
    -- verifies d-closure of the relations).
    ok := isWellDefined Q.subDGModule;
    if not ok and debugLevel > 0 then
        << "-- DGQuotientModule: Q.subDGModule is not a well-defined DGSubmodule" << endl;
    ok
)

isWellDefined(KClass) := Boolean => C -> (
    X := C.variety;
    if not X.?momentGraph then (
	error "a moment graph needs to be defined for this GKM variety "
	);
    G := X.momentGraph;
    R := X.characterRing;
    x := symbol x;
    S := QQ[x_0..x_(#gens R - 1)];
    badEdges := select(keys G.edges, e -> (
	    pt1 := first e;
	    pt2 := last e;
	    lambda := G.edges#e;
	    ratio := toFraction(C.KPolynomials#pt1 - C.KPolynomials#pt2,  1 - R_lambda, S);
	    #(terms(QQ,denominator first ratio)) != 1
	    )
	);
    if #badEdges != 0 then (
	<< "incompatible edges " | toString(badEdges) <<
	return false
	);
    true
    )

isWellDefined(FlagMatroid) := Boolean => M -> (
    L := M.constituents; k := #L;
    all(k-1, i -> isSubset(flats L_i, flats L_(i+1))) and all(L, isWellDefined)
)

isWellDefined(ZZ,LieAlgebraMap) := (n,f)-> (
  if f#cache.welldef then (print("the map is well defined for all degrees");
      print("the map commutes with the differential for all degrees");true) else (
    M:=f#source;
    L:=f#target;
    F:=M#cache.ambient;
    I:=M#ideal;
    g:=f*lieMap(M,F);
    if class I===List then (
	m:= max(0,max(apply(I,ideglie)));
	reln:=select(I,x->ideglie x<=n);  
        out:=all(g\reln,x->x===0_L);
	if out and m<=n then
	    print("the map is well defined for all degrees");
	) else   
	out=(
	    G:=F#cache.ambient;
	    h:=g*lieMap(F,G);
	    reln=select(F#ideal,x->ideglie x<=n); 
	    all(h\reln,x->x===0_L)
	  ) 
          and   
          skipZZ(dims(1,n,image(g,I)))=={};
     if not out then print("the map is not well defined");      
     computeLie(min(n,genDegMax M),L);
     computeLie(min(n,genDegMax M),M);
     dL:=differential L;
     dM:=differential M;
     gensn:=select(M#cache.gens,x->ideglie x<=n); 
     if not all(gensn,x->dL(f#x)===f(dM#x)) then (
     	      print("the map does not commute with the differential");
	      false) else 
	         (if n>=genDegMax M then (
		     if class I===List and m<=n and out then f#cache.welldef=true;
		     print("the map commutes with the differential for all degrees")); 
		     out)
     ) 
  );

isWellDefined(ZZ,LieDerivation) := (n,d)-> (
    f:=d#map;
    wd:=iswelldefdiff(n,f);
    if not wd then (print("the map defining the 
	    derivation is not well defined");false) else (
    if d#cache.welldef  then 
       (print("the derivation is well defined for all degrees");true) else (
    M:=d#source;
    L:=d#target;
    F:=M#cache.ambient;
    I:=M#ideal;
    g:=d*lieMap(M,F);
    if class I===List then (
	m:= max(0,max(apply(I,ideglie)));
	reln:=select(I,x->ideglie x<=n);  
        out:=all(g\reln,x->x===0_L);
	if out and m<=n then (d#cache.welldef=true;
	    print("the derivation is well defined for all degrees"));
	out
        ) else
          (
	    G:=F#cache.ambient;
	    h:=g*lieMap(F,G);
	    reln=select(F#ideal,x->ideglie x<=n); 
	    all(h\reln,x->x===0_L)
            and   
            skipZZ(dims(1,n+firstDegree d,image(g,I)))=={}
	  ) 
        )
    )     
  );

isWellDefined ZZdFactorization := Boolean => C -> (
    k := keys C;
    expectedKeys := set {
        symbol ring, 
        symbol period, 
        symbol module, 
        symbol dd,
        symbol cache
        };
    if set k =!= expectedKeys
    then (
        if debugLevel > 0 then (
            added := toList(k - expectedKeys);
            missing := toList(expectedKeys - k);
            if #added > 0 then << "-- unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- missing key(s): " << toString missing << endl;
            );
        return false;
        );
    -- check keys, check their types
    if not instance(C.ring, Ring) then (
        if debugLevel > 0 then (
            << "-- expected 'ring C' to be a ring" << endl;
            );
        return false;
        );
    (lo,hi) := (0,C.period);
    if not instance(lo,ZZ) or not instance(hi,ZZ) or lo > hi then (
        if debugLevel > 0 then (
            << "-- expected period to be nonnegative integer" << endl;
            );
        return false;
        );
    if not instance(C.module, HashTable) then (
        if debugLevel > 0 then (
            << "-- expected C.module to be a HashTable" << endl;
            );
        return false;
        );    
    if not instance(C.dd, ZZdFactorizationMap) then (
        if debugLevel > 0 then (
            << "-- expected dd^C to be a ZZdFactorizationMap" << endl;
            );
        return false;
        );
    if not instance(C.cache, CacheTable) then (
        if debugLevel > 0 then (
            << "-- expected 'C.cache' to be a CacheTable" << endl;
            );
        return false;
        );
    -- check ring matches modules
    if not all(keys C.module, i -> instance(i,ZZ) and i >= lo and i <= hi) then (
        if debugLevel > 0 then (
            << "-- expected all keys of C.module to be integers in concentration range " << [lo,hi] << endl;
            );
        return false;
        );
    if not all(values C.module, m -> ring m === ring C) then (
        if debugLevel > 0 then (
            << "-- expected all modules in C.module to be over 'ring C'" << endl;
            );
        return false;
        );
    -- check differential
    if ring C.dd =!= ring C then (
        if debugLevel > 0 then (
            << "-- expected ring of the differential to be the ring of the factorization" << endl;
            );
        return false;
        );
    if degree C.dd =!= -1 then (
        if debugLevel > 0 then (
            << "-- expected degree of the differential to be -1" << endl;
            );
        return false;
        );
    if not all(keys (dd^C).map, i -> instance(i,ZZ) and i >= lo+1 and i <= hi) then (
        if debugLevel > 0 then (
            << "-- expected all maps in the differential to be indexed by integers in the concentration [lo+1,hi]" << endl;
            );
        return false;
        );
    for i from lo+1 to hi do (
        f := dd^C_i;
        if source f =!= C_i or target f =!= C_(i-1)
        then (
            if debugLevel > 0 then (
                << "-- expected source and target of maps in differential to be modules in the factorization " << endl;
                << "--   differential at index " << i << " fails this condition" << endl;                
            );    
            return false;
            );
        );
    -*for i from lo+2 to hi do (
        f := dd^C_i;
        g := dd^C_(i-1);
        if g*f != 0 then (
            if debugLevel > 0 then (
                << "-- expected maps in the differential to compose to zero " << endl;
                << "--   differentials at indices " << (i,i-1) << " fail this condition" << endl;                
            );    
            return false;
            );
        );*-
    true
    )

isWellDefined ZZdFactorizationMap := f -> (
    k := keys f;
    expectedKeys := set {
        symbol source, 
        symbol target, 
        symbol degree, 
        symbol map,
        symbol cache
        };
    if set k =!= expectedKeys
    then (
        if debugLevel > 0 then (
            added := toList(k - expectedKeys);
            missing := toList(expectedKeys - k);
            if #added > 0 then << "-- unexpected key(s): " << toString added << endl;
            if #missing > 0 then << "-- missing key(s): " << toString missing << endl;
            );
        return false;
        );
    -- source and target
    if ring f.source =!= ring f.target then (
        if debugLevel > 0 then (
            << "-- expected source and target to have the same ring" << endl;
            );
        return false;
        );
    if not isWellDefined f.source or not isWellDefined f.target then (
        if debugLevel > 0 then (
            << "-- expected source and target to be well-defined ZZdFactorizations" << endl;
            );
        return false;
        );
    if not instance(f.degree, ZZ) then (
        if debugLevel > 0 then (
            << "-- expected degree of factorization homomorphism to be an integer" << endl;
            );
        return false;
        );
    (lo,hi) := (0,f.source.period);
    if not all(keys f.map, i -> instance(i,ZZ) and i >= lo and i <= hi) then (
        if debugLevel > 0 then (
            << "-- expected all maps to be indexed by integers in the period of the source" << endl;
            );
        return false;
        );
    for i from lo to hi do (
        g := f_i;
        if source g =!= f.source_i or target g =!= f.target_(i+f.degree)
        then (
            if debugLevel > 0 then (
                << "-- expected source and target of maps in differential to be modules in the factorization " << endl;
                << "--   differential at index " << i << " fails this condition" << endl;                
            );    
            return false;
            );
        );
    if f.cache.?isCommutative then (
        deg := degree f;
        C := f.source;
        D := f.target;
        (loC,hiC) := (0,C.period);
        (loD,hiD) := (0,D.period);
	if not(hiC==hiD) then (
	    << "--expected source and target to have the same period" << endl;
	    return false;
	    );
        iscommutative := true;
        for i from loC to hiC do (
            if i+deg-1 >= loD and i+deg-1 <= hiD then (
                if not (dd^D_(i+deg) * f_i == (-1)^deg * (f_(i-1) * dd^C_i))
                then (
                    iscommutative = false;
                    if f.cache.isCommutative then (
                        if debugLevel > 0 then (
                            << "-- the cache table incorrectly asserts that the maps commute with the differentials " << endl;
                            << "--   differential at index " << i << " fails this condition" << endl;                
                            );
                        return false;
                        );
                    )));
        if iscommutative and not f.cache.isCommutative then (
            if debugLevel > 0 then (
                << "-- the cache table incorrectly asserts that the maps do not commute with the differentials " << endl;
                );
            return false;
            );
        );
    true
    )

isWellDefined Matroid := Boolean => M -> (
	K := keys M;
	expectedKeys := set {
		symbol groundSet, 
		symbol bases, 
		symbol rank, 
		symbol cache
	};
	if set K =!= expectedKeys then (
		if debugLevel > 0 then (
			added := toList(K - expectedKeys);
			missing := toList(expectedKeys - K);
			if #added > 0 then printerr("isWellDefined: unexpected key(s): " | toString added);
			if #missing > 0 then printerr("isWellDefined: missing keys(s): " | toString missing);
		);
		return false
	);
	if not M.groundSet === set(0..<#M.groundSet) then (
		if debugLevel > 0 then printerr("isWellDefined: expected groundSet to be " | toString set(0..<#M.groundSet));
		return false
	);
	if not (instance(M.bases, List) and all(bases M, b -> instance(b, Set) and isSubset(b, M.groundSet))) then (
		if debugLevel > 0 then printerr("isWellDefined: expected bases to be a list of subsets of groundSet");
		return false
	);
	if not all(M.bases, b -> #b === M.rank) then (
		if debugLevel > 0 then printerr("isWellDefined: expected rank to be the size of all bases");
		return false
	);
	if M.cache.?storedRepresentation then (
		A := M.cache.storedRepresentation;
		if numcols A =!= #M.groundSet or rank A =!= rank M then (
			if debugLevel > 0 then printerr("isWellDefined: storedRepresentation is invalid");
			return false
		);
	);
	 -- circuit elimination
	I := ideal dual M;
	if numgens ideal M < numgens I then I = ideal M;
	R := ring I;
	J := ideal flatten apply(subsets(I_*, 2), p -> (indices gcd(p#0,p#1))/(i -> p#0*p#1//(R_i^2)));
	numgens J == 0 or isSubset(J, I)
)

isWellDefined NCRingMap := f -> (
--- check whether the source or target is an NCRing
   defIdeal := ideal source f;
   liftf := ambient f;
   all(gens defIdeal, x -> liftf x == 0)
)

isWellDefined NCFreeAlgebra := Boolean => R -> (
    -- an internal check that R is defined properly.
    isbad := str -> (if debugLevel > 0 then << str; false);
    if # R.generators =!= numgens R then 
        return isbad "# R.generators =!= numgens R";
    if # R.generatorExpressions =!= numgens R then 
        return isbad "# R.generatorExpressions =!= numgens R";
    if # R.generatorSymbols =!= numgens R then 
        return isbad "# R.generatorSymbols =!= numgens R";
    if not all(R.generators, x -> class x === R) then 
        return isbad "generators are not all in the ring";
    if not all(R.generatorExpressions, x -> instance(x,Expression) or instance(x,Symbol)) then
        return isbad "generatorExpressions are not all expressions";
    if not all(R.generatorSymbols, x -> instance(x, Symbol) or instance(x, IndexedVariable)) then
        return isbad "generatorSymbols are not all symbols or indexed variables";
    if not instance(expression R, Expression) then
        return isbad "expression R should be an expression";
    if not instance(describe R, Net) then
        return isbad "'describe R' should be a Net";
    if not instance(net R, Net) then
        return isbad "'net R' should be a Net";
    if not instance(toString R, String) then
        return isbad "'toString R' should be a string";
    if not instance(toExternalString R, String) then
        return isbad "'toExternalString R' should be a string";
    true
    )

