    if not instance(W.imageSlice, Matrix) then (
        if debugLevel > 0 then << "-- expected `imageSlice' to be a matrix" << endl;
	return false
    );
    if not instance(W.witnessPointPairs, List) then (
        if debugLevel > 0 then << "-- expected `witnessPointPairs' to be a list" << endl;
	return false
    );
    if not all(W.witnessPointPairs, pair -> instance(pair, Sequence)) then (
        if debugLevel > 0 then << "-- expected `witnessPointPairs' to be a list of sequences" << endl;
        return false
    );
    if not all(W.witnessPointPairs, pair -> all(pair, p -> instance(p, Point))) then (
        if debugLevel > 0 then << "-- expected `witnessPointPairs' to be a list of sequences of points" << endl;
        return false
    );
    if not instance(W.trace, RR) then (
        if debugLevel > 0 then << "-- expected `trace' to be a real number" << endl;
	return false
    );
    -- CHECK MATHEMATICAL STRUCTURE
    R := ring W.sourceEquations;
    if not R === ring W.map then (
        if debugLevel > 0 then << "-- expected `map' and `sourceEquations' to have the same ring" << endl;
        return false
    );
    if not instance(class 1_(coefficientRing R), InexactFieldFamily) then (
        if debugLevel > 0 then << "-- expected ground field to have floating point arithmetic" << endl;
        return false
    );
    if not all(W.witnessPointPairs, pair -> #(pair#0#Coordinates) === #gens R and #(pair#1#Coordinates) === numcols W.map) then (
        if debugLevel > 0 then << "-- number of coordinates in `witnessPointPairs' do not match" << endl;
        return false
    );
    if not all(W.witnessPointPairs/first, p -> clean(1e-5, sub(gens W.sourceEquations, matrix p)) == 0) then (
	if debugLevel > 0 then << " -- expected first components of `witnessPointPairs' to satisfy `sourceEquations'" << endl;
	return false
    );
    if not all(W.witnessPointPairs, pair -> clean(1e-5, matrix last pair - sub(W.map, matrix first pair)) == 0) then (
	if debugLevel > 0 then << " -- expected components `witnessPointPairs' to correspond under `map'" << endl;
	return false
    );
    if not all(W.witnessPointPairs/first/matrix, p -> clean(1e-5, sub(W.imageSlice, p)) == 0) then (
	if debugLevel > 0 then << " -- expected second components of `witnessPointPairs' to lie on `imageSlice'" << endl;
	return false
    );
    true
)

isWellDefined Permutation := Boolean => w -> (
    wList := toList w;
    ((sort wList) == toList(1..#wList)) and not (#wList == 0)
)

isWellDefined SimplicialComplex := Boolean => D -> (
    -- CHECK DATA STRUCTURE
    -- check keys
    K := keys D;
    expectedKeys := set {symbol ring, symbol monomialIdeal, symbol facets, symbol cache};
    if set K =!= expectedKeys then (
	if debugLevel > 0 then (
	    added := toList (K - expectedKeys);
	    missing := toList (expectedKeys - K);
	    if # added > 0 then 
	        << "-- unexpected key(s): " << toString added << endl;
	    if # missing > 0 then 
	        << "-- missing key(s): " << toString missing << endl;
	    );
	return false
	);
    -- check types
    if not instance (D.ring, PolynomialRing) then (
	if debugLevel > 0 then 
	    << "-- expected `.ring' to be a PolynomialRing" << endl;
	return false
	);
    if not instance (D.monomialIdeal, MonomialIdeal) then (
	if debugLevel > 0 then 
	    << "-- expected `.monomialIdeal' to be a MonomialIdeal" << endl;
	return false
	);
    if ring D.monomialIdeal =!= D.ring then (
	if debugLevel > 0 then 
	    << "-- expected the ring of `.monomialIdeal' to be `.ring'" << endl;
	return false
	);     
    if not instance (D.facets, List) then (
	if debugLevel > 0 then 
	    << "-- expected `.facets' to be a List" << endl;
	return false
	);        
    if any(D.facets, F -> ring F =!= D.ring) then (
	if debugLevel > 0 then 
	    << "-- expected the entries in `.facets' to be elements of `.ring'" << endl;
	return false
	); 
    if not instance (D.cache, CacheTable) then (
    	if debugLevel > 0 then 
	    << "-- expected `.cache' to be a CacheTable" << endl;
    	return false
	);     
    -- CHECK MATHEMATICAL STRUCTURE
    -- check whether the monomialIdeal is square free
    if not isSquareFree D.monomialIdeal then (
	if debugLevel > 0 then 
	    << "-- expected `.monomialIdeal' to be square free" << endl;
	return false
	);   
    -- check whether the facets correspond to the monomialIdeal
    S := ring D;
    G := matrix {{product gens S}};
    if D.facets =!= first entries sort contract (gens dual monomialIdeal D, G) then (
	if debugLevel > 0 then
	    << "-- expected '.facets' to list the facets corresponding to `.monomialIdeal' << "endl;
    	return false
	);	    
    true
    )

isWellDefined SimplicialMap := Boolean => f -> (
    -- CHECK DATA STRUCTURE
    -- check keys
    K := keys f;
    expectedKeys := set{symbol source, symbol target, symbol map, symbol cache};
    if set K =!= expectedKeys then (
	if debugLevel > 0 then (
	    added := toList(K - expectedKeys);
	    missing := toList(expectedKeys - K);
	    if #added > 0 then 
	        << "-- unexpected key(s): " << toString added << endl;
	    if #missing > 0 then 
	        << "-- missing keys(s): " << toString missing << endl);
    	return false
	);
    --Check types
    if not instance(f.source, SimplicialComplex) then (
	if debugLevel > 0 then (
	    << "-- expected the source to be a SimplicialComplex" << endl);
	return false	);
    if not instance(f.target, SimplicialComplex) then (
	if debugLevel > 0 then (
	    << "-- expected the target to be a SimplicialComplex" << endl);
	return false
	);
    if not instance(f.map, RingMap) then (
	if debugLevel > 0 then (
	    << "-- expected the map to be a RingMap" << endl);
	return false
	);
    if not instance(f.cache, CacheTable) then (
    	if debugLevel > 0 then (
	    << "-- expected cache to be a CacheTable" << endl);
    	return false
	);    
    --Check mathematical structure
    D := source f;
    E := target f;
    g := map f;
    -- check ring map
    if source g =!= ring D then (
    	if debugLevel > 0 then (
	    << "-- expected source of the underlying ring map to be the ring of the source");
	return false	
	);
    if target g =!= ring E then (
    	if debugLevel > 0 then (
	    << "-- expected target of the underlying ring map to be the ring of the target");
	return false	
	);
    -- check that coefficient rings agree
    if coefficientRing ring D =!= coefficientRing ring E then (
	if debugLevel > 0 then (
	    << "-- expected the coefficient rings of the Stanley-Reisner rings to be equal");
	return false
	);
    -- check that vertices map to vertices
    if not all(vertices D, m -> member (g m, vertices E)) then (
    	if debugLevel > 0 then (
	    << "-- expected image of a vertex to be a vertex");
	return false	
	);
    -- check that the image of a face is a face
    if not all(facets D, m -> any(facets E, e -> e % (product support g m) == 0))
    then (
    	if debugLevel > 0 then (
	    << "-- expected image of a face to be a face");
	return false
	);
    true    
    )

isWellDefined SimplicialModule := Boolean => C -> (
    k := keys C;
    -- check keys, check their types
    if not instance(C.ring, Ring) then (
        if debugLevel > 0 then printerr "expected 'ring C' to be a ring";
        return false;
        );
    (lo,hi) := (0, C.topDegree);
    if not instance(hi,ZZ) or lo > hi then (
        if debugLevel > 0 then printerr "expected topDegree to be a nonnegative integer";
        return false;
        );
    if not instance(C.module, HashTable) then (
        if debugLevel > 0 then printerr "expected C.module to be a HashTable";
        return false;
        );
    if not instance(C.dd, SimplicialModuleMap) then (
        if debugLevel > 0 then printerr "expected dd^C to be a SimplicialModuleMap";
        return false;
        );
    if not instance(C.cache, CacheTable) then (
        if debugLevel > 0 then printerr "expected 'C.cache' to be a CacheTable";
        return false;
        );
    -- check ring matches modules
    if not all(keys C.module, i -> instance(i,Sequence) and i_0 >= lo and i_0 <= hi)
       and not all(keys C.module, i -> instance(i,ZZ) and i >= lo and i <= hi) then (
        if debugLevel > 0 then printerr("expected all keys of C.module to be sequences or integers with nonnegative first entry, bounded by the top degree", toString [lo,hi]);
        return false;
        );
    if not all(values C.module, m -> ring m === ring C) then (
        if debugLevel > 0 then printerr "expected all modules in C.module to be over 'ring C'";
        return false;
        );
    -- check face maps
    if ring C.dd =!= ring C then (
        if debugLevel > 0 then printerr "expected ring of the face maps to be the ring of the simplicial module";
        return false;
        );
    if degree C.dd =!= -1 then (
        if debugLevel > 0 then printerr "expected degree of the face maps to be -1";
        return false;
        );
    if not all(keys (dd^C).map, i -> instance(i,Sequence) and i_0 >= lo+1 and i_0 <= hi) then (
        if debugLevel > 0 then printerr "expected all maps of the face maps to be indexed by integers in the concentration [lo+1,hi]";
        return false;
        );
    for i from lo+1 to hi do (
        f := dd^C_i;
        if source f != C_i or target f != C_(i-1)
        then (
            if debugLevel > 0 then (
                printerr "expected source and target of the face maps to be modules in the simplicial module";
                printerr("  face map at index ", toString i, " fails this condition");
            );
            return false;
            );
        );
    if not(C.?ss) then (
    D := naiveNorm C;
    if not isWellDefined D then (
            if debugLevel > 0 then printerr "expected naive normalization to be a well-defined complex";
            return false;
            );
	);
    if C.?ss then (
	if not isSimplicialModule C then (
	    if debugLevel > 0 then printerr "object fails to satisfy simplicial identities; run isSimplicialModule to see where it fails";
	    return false;
	    );
	);
    true
    )

isWellDefined SimplicialModuleMap := f -> (
    k := keys f;
    -- source and target
    if ring f.source =!= ring f.target then (
        if debugLevel > 0 then printerr "expected source and target to have the same ring";
        return false;
        );
    if not isWellDefined f.source or not isWellDefined f.target then (
        if debugLevel > 0 then printerr "expected source and target to be well-defined simplicial modules";
        return false;
        );
    if not instance(f.degree, ZZ) then (
        if debugLevel > 0 then printerr "expected degree of homomorphism to be an integer";
        return false;
        );
    (lo,hi) := (0,f.source.topDegree);
    if not all(keys f.map, i -> instance(i,ZZ) or instance(i, Sequence)) then (
        if debugLevel > 0 then printerr "expected all maps to be indexed by integers or sequences of two integers";
        return false;
        );
    if all(keys f.map, i -> instance(i,ZZ)) then for i from lo to hi do (
        g := f_i;
        if source g != f.source_i or target g != f.target_(i+f.degree)
        then (
            if debugLevel > 0 then (
                printerr "expected source and target of maps to agree with those of simplicial module";
                printerr("  the map at index ", toString i, " fails this condition");
            );
            return false;
            );
        );
    --print "here we are";
    if all(keys f.map, i -> instance(i,ZZ)) and f.cache.?isCommutative then (
        deg := degree f;
        C := f.source;
        D := f.target;
        (loC,hiC) := (0, C.topDegree);
        (loD,hiD) := (0, D.topDegree);
        iscommutative := true;
        for i from loC to hiC do (
            if i+deg-1 >= loD and i+deg-1 <= hiD then (
		for l from 0 to i do (
                if not (try (dd^D_(i+deg,l) * f_i == (-1)^deg * (f_(i-1) * dd^C_(i,l))) else matEq(matrix(dd^D_(i+deg,l)) * matrix(f_i), (-1)^deg * (matrix(f_(i-1)) * matrix(dd^C_(i,l)))))
                then (
                    iscommutative = false;
                    if f.cache.isCommutative then (
                        if debugLevel > 0 then (
                            printerr "the cache table incorrectly asserts that the maps commute with the differentials";
                            printerr("  differential at index ", toString i, " fails this condition");
                            );
                        return false;
                        );
                    )
	    );));
        if iscommutative and not f.cache.isCommutative then (
            if debugLevel > 0 then printerr "the cache table incorrectly asserts that the maps do not commute with the differentials";
            return false;
            );
        );
    true
    )

isWellDefined(ToricQuiver) := Boolean => Q -> (
    -- check that the vertices are consecutive
    vertexRange := toList(0..#Q.Q0 - 1),
    if any(Q.Q0, x -> not isIn(x, vertexRange)) then (
        print("error: Toric Quiver is missing vertices");
        return false;
    );
    -- check that each edge is defined in terms of two vertices
    if any(Q.Q1, e -> (#e < 2) or (not (isIn(e#0, vertexRange) and isIn(e#1, vertexRange)))) then (
        print("error: edge is has invalid endpoint");
        return false;
    );
    -- check that the flow has the same dimension as the number of edges
    if #Q.flow != #Q.Q1 then (
        print("error: the flow of the Toric Quiver has incorrect dimension.");
        return false;
    );
    if #Q.flow != numgens source Q.IncidenceMatrix then (
        print("error: the flow of the Toric Quiver has incorrect dimension.");
        return false;
    );
    -- check that the weights have the same dimension as the number of vertices
    if #Q.weights != #Q.Q0 then (
        print("error: the weights of the Toric Quiver have incorrect dimension.");
        return false;
    );
    if #Q.weights != #entries Q.IncidenceMatrix then (
        print("error: the weights of the Toric Quiver have incorrect dimension.");
        return false;
    );
    -- check that the weights match the flow and incidence matrix
    computedWeights := sumList(entries(Q.IncidenceMatrix*diagonalMatrix(Q.flow)), Axis => "Row");
    if any(0..#Q.weights - 1, x -> computedWeights#x != Q.weights#x) then (
        print("error: Toric Quiver weights do not match its flow and incidence matrix");
        return false;
    );
    -- check that the incidence matrix is an actual incidence matrix
    Qp := matrix(for e in entries(Q.IncidenceMatrix) list(for x in e list abs x));
    if any(sum entries Qp, x -> x != 2) then (
        print("error: Matrix is not a graph incidence matrix");
        return false;
    );
    if any(sum entries Q.IncidenceMatrix, x -> x != 0) then (
        print("error: Matrix is not a graph incidence matrix");
        return false;
    );
    return true;
)

