jacobian (List, GateSystem) := (inds, GS) -> (
    if not GS.cache#?Jacobian then (
    	F := gateMatrix GS;
    	I := (vars GS)_inds;
    	J := diff(I,F);
    	GS.cache.Jacobian = makeSLProgram(parameters GS | vars GS, J);
	);
    GS.cache.Jacobian
    )

kernel Matrix := Module => opts -> g -> g.cache.kernel ??= if g == 0 then source g else tryHooks(
    (kernel, Matrix), (opts, g), (opts, g) -> (
	-- this is the default algorithm
	-- compare with homology below
	N := source g;
	P := target g;
	g = matrix g;
	if P.?generators then g = P.generators * g;
	h := modulo(g, if P.?relations then P.relations);
	if N.?generators then h = N.generators * h;
	subquotient(h, if N.?relations then N.relations)))

kernel RingMap := Ideal => opts -> (cacheValue (symbol kernel => opts)) (f -> (
    (F, R) := (target f, source f);
    if 0_F == 1_F then return ideal 1_R;
    -- the actual computation occurs here
    I := runHooks((kernel, RingMap), (opts, f));
    if I =!= null then I else error "kernel: no method implemented for this type of ring map"))

kernel ComplexMap := Complex => opts -> f -> (
    -- f : B --> C
    B := source f;
    (lo,hi) := B.concentration;
    modules := hashTable for i from lo to hi list i => kernel f_i;
    result := if lo === hi then complex(modules#lo, Base => lo)
        else (
            inducedMaps := hashTable for i from lo to hi list i => inducedMap(B_i, modules#i);
            maps := hashTable for i from lo+1 to hi list i => (
                (dd^B_i * inducedMaps#i) // inducedMaps#(i-1)
                );
            complex maps
            );
    if not isCommutativeCached f and not isWellDefined result then
        error "expected differential on the source to induce a well-defined differential on the kernel";
    result.cache.kernel = f;
    result
    )

ker MackeyFunctorHomomorphism := CpMackeyFunctor => options -> F -> (
    T := ker F.FixedMap;
    B := ker F.UnderlyingMap;

    C' := inducedMap(B,B,(source F).Conj);
    T' := inducedMap(T,B,(source F).Trans);
    R' := inducedMap(B,T,(source F).Res);
    p' := (source F).PrimeOrder;

    makeCpMackeyFunctor(p',R',T',C')
)

kernel DGModuleMap := opts -> F -> (
    M := source F;
    kerMat := gens kernel F.natural;
    dgSubmodule(M, kerMat)
)

kernel ZZdFactorizationMap := ZZdFactorization => opts -> f -> (
    -- f : B --> C
    B := source f;
    (lo,hi) := (0,B.period);
    modules := hashTable for i from lo to hi list i => kernel f_i;
    result := if lo === hi then ZZdfactorization(modules#lo, Base => lo)
        else (
            inducedMaps := hashTable for i from lo to hi list i => inducedMap(B_i, modules#i);
            maps := hashTable for i from lo+1 to hi list i => (
                (dd^B_i * inducedMaps#i) // inducedMaps#(i-1)
                );
            ZZdfactorization maps
            );
    if not isCommutativeCached f and not isWellDefined result then
        error "expected differential on the source to induce a well-defined differential on the kernel";
    result.cache.kernel = f;
    result
    )

kernel ChainComplexMap := ChainComplex => options -> (f) -> (
     D := source f;
     C := new ChainComplex;
     C.ring = ring f;
     complete D;
     scan(spots D, k -> C#k = kernel f_k);
     scan(spots C, k -> if C#?(k-1) then C.dd#k = (D.dd_k * inducedMap(D_k,C_k)) // inducedMap(D_(k-1),C_(k-1)));
     C)

kernel GradedModuleMap := GradedModule => options -> (f) -> (
     E := new GradedModule;
     E.ring = ring f;
     scan(spots source f, i -> E#i = kernel f_i);
     E
     )

kernel SimplicialModuleMap := SimplicialModule => opts -> f -> (
    -- f : B --> C
    local result;
    B := source f;
    modules := hashTable for i from 0 to B.topDegree list i => kernel f_i;
    inducedMaps := hashTable for i from 0 to B.topDegree list i => inducedMap(B_i, modules#i);
    facemaps := applyPairs(B.dd.map, (i, v) -> (
	    b1 := v * inducedMaps#(i_0);
	    b2 := map(target b1, source inducedMaps#(i_0-1), inducedMaps#(i_0-1));
	    (i, b1 // b2)
	    ));
    if B.?ss then (
	degenmaps := applyPairs(B.ss.map, (i, v) -> (
		b1 := v * inducedMaps#(i_0);
		b2 := map(target b1, source inducedMaps#(i_0+1), inducedMaps#(i_0+1));
		(i, b1 // b2)
		));
	result =  simplicialModule(modules,facemaps,degenmaps,B.topDegree);
	result.cache.kernel = f;
	return result;
	);
    result = simplicialModule(modules,facemaps,B.topDegree);
    result.cache.kernel = f;
    result
    )

ker (ToricVectorBundleKlyachko,Matrix) := opts -> (T,M) -> (
     k := T#"rank of the vector bundle";
     tRing := T#"ring";
     -- Checking for input errors
     if k != numColumns M then error("The source of the matrix has to be the vector bundle.");
     if tRing =!= ring M then error("Matrix and bundle have to be over the same ring.");
     -- Compute a basis of the kernel
     M = mingens ker M;
     ranknew := numColumns M;
     bT := T#"baseTable";
     fT := T#"filtrationTable";
     -- Compute the new filtration for each ray
     bT = hashTable apply(keys bT, j -> (
	       fTj := drop(sort keys fT#j,1);
	       cols := {};
	       oldKer := map(tRing^ranknew,tRing^0,0);
	       -- compute each filtration step
	       j => apply(fTj, i -> (
			 cols = cols | fT#j#i;
			 A := (bT#j)_cols;
			 -- Represent the kernel intersected with the actual filtration step in the basis chosen
			 gkMA := (gens ker (M | A))^{0..ranknew-1};
			 -- Select the "new" vectors
			 gkMA = mingens (image(oldKer | gkMA) / image oldKer);
			 oldKer = oldKer |gkMA;
			 -- Save the new vectors and the filtration step
			 (gkMA,matrix {toList(numColumns gkMA:i)})))));
     -- Compute the filtration matrices and tables
     fMT := hashTable apply(pairs bT, p -> p#0 => matrix {apply(p#1,last)});
     fT = hashTable apply(pairs fMT, p -> (
	       L := flatten entries p#1;
	       L1 := sort unique L;
	       p#0 => hashTable ({min L1 - 1 => {}} | apply(L1, l -> l => positions(L,e -> e == l)))));
