map(Ring, Ring, List)    := RingMap => opts -> (R, S, m) -> (
    if m#?0 and instance(m#0, Option) then sub2(R, S, m) -- TODO: deprecate this?
    else map(R, S, matrix(R, {m}), opts))

map(Ring, Ring, Matrix)  := RingMap => opts -> (R, S, m) -> (
     if not isFreeModule target m or not isFreeModule source m
     then error "expected a homomorphism between free modules";
     if ring m === (try coefficientRing R) and ring m === (try coefficientRing S)
     then (
	  if numgens R != rank target m
	  then error ("expected a matrix with ", toString numgens R, " rows");
	  m = vars R * (m ** R);   -- handle a change of coordinates
	  )
     else (
	  try m = promote(m,R) else error "map: expected a matrix over the target ring, or promotable to it";
	  );
     if rank target m != 1
     then error "expected a matrix with 1 row";
     degmap := (
	  if opts.DegreeMap =!= null then (
	       if degreeLength R =!= # (opts.DegreeMap apply(degreeLength S, i -> 0))
	       then error ("expected DegreeMap function to transform a degree of length ", 
		    toString degreeLength S,
		    " into a degree of length ", toString degreeLength R);
	       opts.DegreeMap
	       )
	  else if (pr:=lookup(promote,List,S,R)) =!= null then (d -> first pr({d},S,R))
	  else if degreeLength R === degreeLength S then identity
	  else if degreeLength S === 0 or degreeLength R === 0 then degmap0 degreeLength R
	  else (
	       -- error "map(Ring,Ring,Matrix): nonzero degree monoids differ, promotion not available, DegreeMap needed";
	       degmap0 degreeLength R));
     dR := ZZ^(degreeLength R);
     dS := ZZ^(degreeLength S);
     degmapmatrix := map(dR,dS,transpose apply(entries id_dS,degmap));
     deglift := (
	  if opts.DegreeLift =!= null then opts.DegreeLift
	  else if degmap === identity then identity
	  else if degreeLength S === 0 and degreeLength R === 0 then identity
	  else (d -> (
		    (q,r) := quotientRemainder(transpose matrix {d}, degmapmatrix);
		    if r != 0 then error "degreeLift: degree not liftable";
		    flatten entries q)));
     mdegs := {};
     n := 0;
     A := S;
     record := new MutableHashTable; -- we should look for variables with the same symbol
     justonce := s -> (
	  if record#?s then error "map: multiple variables would map to the same variable, by name";
	  record#s = true;
	  R.indexSymbols#s);
     mE := m;
     while true do (
	  mdegs = join(mdegs, promote(degrees A,A,S) / degmap);
	  r := numgens source m;
	  if r > n then (
	       if instance(A,GaloisField) and A.rawGaloisField then (
		    -- the engine wants to know where the primitive element will go
		    p := map(R,ambient A,m_(toList(n .. r-1)));
		    m' := new MutableMatrix from m;
		    m'_(0,n) = p A.PrimitiveElement;
		    m = matrix m';
		    ))
	  else if r < n then error ("encountered values for ", toString r, " variables, but expected ", toString n)
	  else if r == n then (
	       if numgens A > 0 then (
		    if A === R or isPromotable(A, R) then (
			 -- we can promote
			 mE = mE | promote(vars A, R);
			 if instance(A,GaloisField) and A.rawGaloisField then (
		    	      -- the engine wants to know where the primitive element will go
		    	      m = m | promote(A.PrimitiveElement, R)
			      )
			 else m = m | promote(vars A, R);
			 )
		    else (
			 mm := matrix(R, {apply(A.generatorSymbols, s -> if R.?indexSymbols and R.indexSymbols#?s then justonce s else 0_R)});
			 mE = mE | mm;
			 if instance(A,GaloisField) and A.rawGaloisField then (
			      -- the engine wants to know where the primitive element will go
			      m = m | matrix {{(map(R,ambient A,mm)) A.PrimitiveElement}}
			      )
			 else m = m | mm;
			 )));
	  n = n + numgens A;
	  try A = coefficientRing A else break
	  );
     if n != numgens source m then error ("encountered values for ", toString numgens source m," variables");
     zdeg  := toList ( degreeLength R : 0 );
     mE = map(R^{zdeg}, R^-mdegs, mE, Degree => zdeg);
     new RingMap from {
	  symbol target => R,
	  symbol source => S,
	  symbol matrix => mE,
	  symbol RawRingMap => rawRingMap m.RawMatrix,
	  symbol Matrix => degmapmatrix,
	  symbol cache => new CacheTable from {
	       symbol DegreeMap => degmap,
	       symbol DegreeLift => deglift
	       }
	  }
     )

map(Module,Module,RingMap,RawMatrix) := opts -> (M,N,p,f) -> (
     (R,S) := (ring M,ring N);
     (M',N') := (cover M,p cover N);
     if R =!= target p or S =!= source p then error "expected rings to match";
     if target f =!= raw M' then error "expected target of matrix to match (cover of) target module";
     ---- we relax this check so "basis" can return something for basis(QQ[x]/x^2,SourceRing=>QQ):
     -- if source f =!= raw N' then error "expected source of matrix to match (cover of) source module";
     deg := if opts.Degree === null then rawMultiDegree f else degreeCheck(opts.Degree,R);
     new Matrix from {
	  symbol RingMap => p,
	  symbol target => M,
	  symbol source => N,
	  symbol RawMatrix => reduce(M,rawMatrixRemake2(raw M',raw N',deg,f,0)),
	  symbol cache => new CacheTable
	  })

map(Module,Nothing,RingMap,RawMatrix) := Matrix => o -> (M,N,p,f) -> (
    d := degreeLength ring M;
     degs := pack(d,degrees source f);
     deg := o.Degree;
     if deg =!= null then degs = apply(degs, dg -> dg - deg);
     srcdegs := apply(degs,p.cache.DegreeLift);
     map(M,(source p)^-srcdegs,p,f,o))

map(Complex, Complex, HashTable) := ComplexMap => opts -> (tar, src, maps) -> (
    R := ring tar;
    if ring src =!= R or any(values maps, f -> ring f =!= R) then
        error "expected source, target and maps to be over the same ring";
    deg := if opts.Degree === null 
           then 0 
           else if instance(opts.Degree, ZZ) then 
             opts.Degree
           else
             error "expected integer degree";
    (lo,hi) := src.concentration;
    maps' := hashTable for k in keys maps list (
        if not instance(k, ZZ) then error "expected integer keys";
        f := maps#k;
        -- note: we use != instead of =!= in the next 2 tests,
        -- since we want to ignore any term order differences
        if source f != src_k then
            error ("map with index "|k|" has inconsistent source");
        if target f != tar_(k+deg) then
            error ("map with index "|k|" has inconsistent target");
        if k < lo or k > hi then continue else (k,f)
        );
    new ComplexMap from {
        symbol source => src,
        symbol target => tar,
        symbol degree => deg,
        symbol map => maps',
        symbol cache => new CacheTable
        }
    )

map(Complex, Complex, List) := ComplexMap => opts -> (tar, src, maps) -> (
    -- case 1: maps is a (single) list of matrices (maps between components of the complex)
    -- case 2: maps is a double list of ComplexMap's
    --    in this case, if the maps all commute with differentials, and are diagonal, then
    --    we could declare the result to be commutative as well. Should we do this?
    --  Can tell, depending on the class of maps#0.
    (lo,hi) := src.concentration;
    if not instance(maps#0, List) then (
        mapHash := hashTable for i from lo to hi list i => (
            h := maps#(i-lo);
            if h == 0 then continue else h
            );
        return map(tar,src,mapHash,opts)
        );
    -- At this point, the first entry of 'maps' is a List.
    -- Check: it is a table of ComplexMap
    R := ring tar;
    if R =!= ring src then error "expected complexes over the same ring";
    if not isTable maps then error "expected a table of ComplexMaps";
    -- check: all entries which are ComplexMaps have the same homological degree
    deg := if opts.Degree === null 
           then null
           else if instance(opts.Degree, ZZ) then 
             opts.Degree
           else
             error "expected integer degree";
    degs := unique for f in flatten maps list 
        if instance(f,ComplexMap) 
            then degree f 
            else continue;
    if #degs > 1 then error "expected all ComplexMaps to have the same degree";
    if deg =!= null and #degs == 1 and degs#0 =!= deg then error "Supplied degree is incompatible with the ComplexMaps";
    if deg === null then deg = (if #degs == 1 then degs#0 else 0);
    -- At this point, we need to create (block) matrices for each component of the complex.
    mapHash = hashTable for i from lo to hi list i => (
        newmaps := applyTable(maps, f -> if instance(f,ComplexMap) then f_i else f);
        h := map(tar_(i+deg), src_i, matrix newmaps);
        if h == 0 then continue else h
        );
    map(tar,src,mapHash,opts, Degree=>deg)
    )

map(Complex, Complex, Function) := ComplexMap => opts -> (D,C,f) -> (
    deg := if opts.Degree === null then 0 else opts.Degree;
    (loC,hiC) := concentration C;
    (loD,hiD) := concentration D;
    maps := hashTable for i from max(loC,loD-deg) to min(hiC,hiD-deg) list (
        if C_i == 0 or D_(i+deg) == 0 then continue;
        g := f(i);
        if g === null or g == 0 then continue;
        i => g
        );
    map(D,C,maps,Degree=>deg)
    )

map(Complex, Complex, ZZ) := ComplexMap => opts -> (D, C, j) -> (
    if j === 0 then (
        result := map(D,C,hashTable{},opts);
        result.cache.isCommutative = true;
        return result
        );
    if C == D and (opts.Degree === null or opts.Degree === 0) then
        return j * id_C;
    error "expected 0 or source and target to be the same")

map(Complex, Complex, ComplexMap) := ComplexMap => opts -> (tar, src, f) -> (
    deg := if opts.Degree === null then degree f else opts.Degree;
    H := hashTable for k in keys f.map list k => map(tar_(deg+k), src_k, f.map#k);
    map(tar,src,H, Degree=>deg)
    )

map(GaloisField,GaloisField) := RingMap => o -> (K,F) -> (
     p := char F;
     n := K.degree;
     m := F.degree;
     if char K =!= p 
     or n % m != 0
     then error "no map of fields exists";
     if F === K then return map(K,F,vars K);
     if not (isConway F and isConway K) then error "not implemented: maps between non-Conway Galois fields";
     map(K,F,{K_0^((p^n-1)//(p^m-1))}))

map(CpMackeyFunctor, CpMackeyFunctor, Matrix, Matrix) := MackeyFunctorHomomorphism => opts -> (N,M,u,f) -> (
    F := new MackeyFunctorHomomorphism from {
        symbol Codomain => N,
        symbol Domain => M,
