mathML BinaryOperation := m -> (
    x := mathML m#1;
    y := mathML m#2;
    if rightPrecedence m#1 < lprec m#0 then x = mathMLparen x;
    if precedence m#2 <= rprec m#0 then y = mathMLparen y;
    mrow(x | mo m#0 | y))

mathML Sum := v -> (
     n := # v;
     if n === 0 then "<mn>0</mn>"
     else if n === 1 then mathML v#0
     else (
	  p := precedence v;
	  seps := newClass(MutableList, apply(n+1, i->"<mo>+</mo>"));
	  seps#0 = "";
	  seps#n = "";
	  v = apply(n, i -> (
		    if class v#i === Minus 
		    then (
			 seps#i = "<mo>-</mo>"; 
			 v#i#0)
		    else v#i));
	  concatenate (
	       "<mrow>", 
	       mingle(seps, 
	       	    apply(n, i -> 
		    	 if precedence v#i <= p 
		    	 then ("<mrow><mo>(</mo>", mathML v#i, "<mo>)</mo></mrow>")
		    	 else mathML v#i),
		    n:newline),
	       "</mrow>",newline)))

mathML Product := v -> (
    n := # v;
    if n === 0 then mathML 1
    else (
	v = apply(v, x -> if class x === Power and (x#1 === 1 or x#1 === ONE) then x#0 else x);
	p := precedence v;
	nums := apply(v, x -> isNumber x or (class x === Power and isNumber x#0));
	precs := apply(v, x -> precedence x <= p);
	seps := apply (n-1, i->
	    if nums#(i+1) then mo "&times;"
	    else if (
		class v#i =!= Power and
		class v#i =!= Subscript and
		not precs#i and
		not precs#(i+1) and
		(nums#i or class v#i === Symbol))
	    then "<mspace width=\"0.1667em\"></mspace>"
	    else "");
	boxes := apply(n, i -> (
		if precs#i and class v#i =!= Divide
		then mathMLparen mathML v#i
		else mathML v#i));
	mrow concatenate splice mingle (boxes,seps)))

