mathML Complex := C -> (
    if C == 0 then mathML "0"
    else (
	(lo, hi) := concentration C;
	mtable transpose between({leftarrow, "", ""},
	    toList apply(lo..hi, i -> {mathML short C_i, "", mathML i}))))

mathML ChainComplex := C -> (
    complete C;
    s := sort spots C;
    if #s === 0 then mathML "0"
    else mtable transpose between({leftarrow,"",""}, toList apply(s#0 .. s#-1,i -> {mathML C_i,"",mathML i})))

matrix(Ring,List) := Matrix => opts -> (R,m) -> (
     m = apply(splice m,splice);
