norm(Number, Matrix) := (p, M) -> (
    R := ring M;
    if p == infinity then (
	-- l^infty norm for RR and CC is implemented in the engine
	if instance(R, RealField) or instance(R, ComplexField)
	then (
	    if precision p > precision R
	    then p = numeric(precision R, infinity);
	    new RR from norm(p, raw M))
	else max apply(flatten entries M, norm))
    else if isReal p and p >= 1
    then (sum(flatten entries M, x -> (norm(p, x))^p))^(1/p)
    else error "expected p >= 1")

norm(Number, Matrix) := (p, M) -> (
    R := ring M;
    if p == infinity then (
	-- l^infty norm for RR and CC is implemented in the engine
	if instance(R, RealField) or instance(R, ComplexField)
	then (
	    if precision p > precision R
	    then p = numeric(precision R, infinity);
	    new RR from norm(p, raw M))
	else max apply(flatten entries M, norm))
    else if isReal p and p >= 1
    then (sum(flatten entries M, x -> (norm(p, x))^p))^(1/p)
    else error "expected p >= 1")

norm (Thing, List) := (no,p) -> (
     if instance(no,InfiniteNumber) and no === infinity then return max(p/abs);
     assert((instance(no, ZZ) or instance(no, QQ) or instance(no, RR)) and no>0);
     (sum(p, c->abs(c)^no))^(1/no)
     )

norm CCi := I -> (
    reI := realPart I;
    imI := imaginaryPart I;
    reN := max {left reI, right reI};
    imN := max {left imI, right imI};
    norm(reN + ii*imN)
    )

norm CCiMatrix := M -> (
    nr := length M;
    nc := length first M;
    max apply(nr, i -> sum apply(nc, j -> norm M#i#j))
    )

