    C := source f;
    if not C.cache.?pruningMap then f = f * (minimalPresentation C).cache.pruningMap;
    D := target f;
    if not D.cache.?pruningMap then f = (minimalPresentation D).cache.pruningMap^-1 * f;
    f
    )

prune MackeyFunctorHomomorphism := MackeyFunctorHomomorphism => opts -> f -> (
    src := prune source f;
    tgt := prune target f;
    srcPrune := src.cache.pruningMap;
    tgtPrune := tgt.cache.pruningMap;
    (inverse tgtPrune) * f * srcPrune
    )

prune CpMackeyFunctor := CpMackeyFunctor => opts -> M -> (
    T := prune M.Fixed;
    B := prune M.Underlying;
    fT := (T.cache.pruningMap);
    fB := (B.cache.pruningMap);
    r := map(B, T, (matrix inverse fB) * (matrix M.Res) * (matrix fT));
    t := map(T, B, (matrix inverse fT) * (matrix M.Trans) * (matrix fB));
    c := map(B, B, (matrix inverse fB) * (matrix M.Conj) * (matrix fB));
    M' := makeCpMackeyFunctor(M.PrimeOrder, r, t, c);
    M'.cache.pruningMap = map(M,M',fB,fT);
    M'
    )

