    -- No redundancy to trim if there are no generators or mingens is
    -- already the same width: cache an identity pruningMap and return.
    minIm := if numcols incMat == 0 then incMat else mingens image incMat;
    if numcols minIm == numcols incMat then (
        S.cache#(symbol pruningMap) = identityDGModuleMap S;
        return S;
    );
    -- Build pruned Sp with fewer generators.
    Sp := dgSubmodule(M, minIm);
    -- Build pruningMap: Sp --> S as a DGModuleMap.  Factor minIm = incMat * T
    -- via `minIm // incMat` (solves the A.natural-linear system), then
    -- coerce T to a map with the correct degree labels.
    T := minIm // incMat;
    Tcoerced := map(S.natural, Sp.natural, T);
    pm := dgModuleMap(S, Sp, Tcoerced);
    Sp.cache#(symbol pruningMap) = pm;
    Sp
)

prune DGQuotientModule := o -> Q -> (
    -- Step 1: minimize the submodule presentation (A.natural-level prune).
    prunedS := prune Q.subDGModule;
    Qp := if prunedS === Q.subDGModule then Q else Q.ambient / prunedS;
    -- Step 2: build pruningMap: Qp --> Q as a raw DGModuleMap.  Both are
    -- cokernels of inclusions of the same image(S) in M (equal sets), so
    -- the identity on M.natural descends to a canonical map
    -- Qp.natural --> Q.natural.  Construct it directly (dgModuleMap does
    -- not accept DGQuotientModule source/target because the type doesn't
    -- inherit from DGModule).
    idAmb := id_(Q.ambient.natural);
    pmNat := try inducedMap(Q.natural, Qp.natural, idAmb) else
             map(Q.natural, Qp.natural, idAmb);
    pm := new DGModuleMap from {
        symbol source    => Qp,
        symbol target    => Q,
        symbol dgAlgebra => Q.dgAlgebra,
        symbol natural   => pmNat,
        symbol cache     => new CacheTable
    };
    Qp.cache#(symbol pruningMap) = pm;
    -- Step 3: compute the complex-level prune and cache it.  This mirrors
    -- `prune Complex` and closes the commutation gap: after this, calling
    -- toComplex on Qp returns the minimally-presented complex.
    cxQ := toComplex Qp;
    prunedCxQ := prune cxQ;
    Qp.cache#(symbol prunedComplex) = prunedCxQ;
    Qp
)

prune DGIdeal := o -> I -> (
    A := I.dgAlgebra;
    minI := trim I.natural;
    if numgens minI == numgens I.natural then (
        -- DGIdeals don't support maps directly (no DGIdealMap type); we
        -- cache the identity as the pruningMap so downstream code can
        -- share a uniform calling convention.  The pruningMap for a DGIdeal is
        -- recorded as the identity DGAlgebraMap on the ambient, which is
        -- well-defined and trivially an iso.
        I.cache#(symbol pruningMap) = identityDGAlgebraMap A;
        return I;
    );
    Ip := dgIdeal(A, (generators minI)_*);
    -- For a pruned DGIdeal, the ambient DGAlgebra is unchanged and the
    -- underlying ideal is equal (as a set) -- mingens just chooses a
    -- smaller generating set.  So the canonical comparison Ip --> I is
    -- the identity on the ambient DG algebra.
    Ip.cache#(symbol pruningMap) = identityDGAlgebraMap A;
    Ip
)

prune Arrangement := Arrangement => options -> A -> (
     R := ring A;
     if not instance(R, PolynomialRing) then (
	  S := prune R;
	  f := R.minimalPresentationMap;
	  arrangement(f \ hyperplanes A, S)) 
     else A
     )

prune ZZdFactorization := ZZdFactorization => opts -> (cacheValue symbol minimalPresentation)(C -> (
    -- opts is ignored here
    -- to be cached: in the input C: cache the result D
    --               in the result: cache pruningMap: D --> C
    (lo,hi) := (0,C.period-1);
    --if C == 0 then return ZZdfactorization((ring C)^0, period C);
    nonzeros := select(lo..hi, i -> minimalPresentation C_i != 0);
    D := if #nonzeros === 0 
         then (
             ZZdfactorization((ring C)^0, period C)
             )
         else (
             lo = min nonzeros;
             hi = max nonzeros;
             if lo === hi 
             then ZZdfactorization(minimalPresentation C_lo, period C, Base=>lo)
             else (
                 maps := hashTable for i from lo+1 to hi+1 list i => minimalPresentation dd^C_i;
                 ZZdfactorization maps
                 )
             );
    -- create the isomorphism D --> C
    (lo,hi) = (0,D.period);
    pruning := hashTable for i from lo to hi list i => (minimalPresentation C_i).cache.pruningMap;
    D.cache.pruningMap = map(C,D,pruning);
    D.cache.pruningMap.cache.isCommutative = true;
    D
    ))

prune ZZdFactorizationMap := ZZdFactorizationMap => opts -> f -> (
    C := source f;
    if not C.cache.?pruningMap then f = f * (minimalPresentation C).cache.pruningMap;
    D := target f;
    if not D.cache.?pruningMap then f = (minimalPresentation D).cache.pruningMap^-1 * f;
    f
    )

minimalPresentation ChainComplex := prune ChainComplex := ChainComplex => opts -> (C) -> (
     D := new ChainComplex;
     complete C;
     complete C.dd;
     D.ring = ring C;
     scan(spots C, i -> D#i = minimalPresentation C#i);
     scan(spots C.dd, i -> D.dd#i = minimalPresentation C.dd#i);
     D)

minimalPresentation ChainComplexMap := prune ChainComplexMap := ChainComplexMap => opts -> (f) -> (
     complete f;
     map(minimalPresentation target f, minimalPresentation source f, k -> minimalPresentation f#k)
     )

minimalPresentation GradedModule := prune GradedModule := GradedModule => opts -> (M) -> (
     E := new GradedModule;
     E.ring = M.ring;
     scan(spots M, i -> E#i = minimalPresentation M#i);
     E)

prune SimplicialComplex := SimplicialComplex => opts -> D -> (
    V := vertices D;
    if gens ring D === V then return D;
    R := (coefficientRing D)(monoid[V]);
    if dim D < -1 then return simplicialComplex monomialIdeal(1_R);
    if dim D === 1 then return simplicialComplex {1_R};
    simplicialComplex for x in facets D list (
	if sum first exponents x =!= 1 then substitute(x, R) else continue)
    )

prune SimplicialModule := SimplicialModule => opts -> (cacheValue symbol minimalPresentation)(C -> (
	if C.?complex then C = forgetComplex C;
	R := ring C;
    -- opts is ignored here
    -- to be cached: in the input C: cache the result D
    --               in the result: cache pruningMap: D --> C
    faceKeys := keys C.dd.map;
    if C.?ss then degenKeys := keys C.ss.map; 
    prunedMods := new MutableHashTable from for i to C.topDegree list i => prune C_i;
    prunedFaceMaps := new MutableHashTable from for i in faceKeys list i => map(prune C_(i_0-1),prune C_(i_0),0);
    if C.?ss then prunedDegenMaps := new MutableHashTable from for i in degenKeys list i=>map(prune C_(i_0+1),prune C_(i_0),0); 
    nonzeros := select(0..C.topDegree, i -> minimalPresentation C_i != 0);
    D := if #nonzeros === 0 
         then (
             simplicialModule((ring C)^0,C.topDegree)
             )
         else (
             lo := min nonzeros;
             hi := max nonzeros;
	     for i from lo to hi do prunedMods#i = minimalPresentation(C_i);
             for i in select(faceKeys,i->(i_0>=lo and i_0<=hi)) do prunedFaceMaps#i = minimalPresentation C.dd_i;
	     if C.?ss then (
		 for i in select(degenKeys,i->(i_0>=lo and i_0<hi)) do prunedDegenMaps#i = minimalPresentation C.ss_i;
		 );
             nmMods := new HashTable from prunedMods;
	     nmFaces := new HashTable from prunedFaceMaps;
	     if C.?ss then (
		 nmDegens := new HashTable from prunedDegenMaps;
		 );
	     if C.?ss then simplicialModule(nmMods,nmFaces,nmDegens,C.topDegree) else simplicialModule(nmMods,nmFaces,C.topDegree)
                 );
    -- create the isomorphism D --> C
    pruning := hashTable for i from 0 to C.topDegree list i => (minimalPresentation C_i).cache.pruningMap;
    D.cache.pruningMap = map(C,D,pruning);
    D.cache.pruningMap.cache.isCommutative = true;
    D
    ))

prune SimplicialModuleMap := SimplicialModuleMap => opts -> f -> (
    if all(keys f.map, i -> instance(i, Sequence)) then return (if degree f == -1 then (prune source f).dd else (prune source f).ss);
    C := source f;
    if not C.cache.?pruningMap then f = f * (minimalPresentation C).cache.pruningMap;
    D := target f;
    if not D.cache.?pruningMap then f = (minimalPresentation D).cache.pruningMap^-1 * f;
    f
    )

minimalPresentation SpectralSequence := prune SpectralSequence := SpectralSequence  => opts -> (E) -> (
	  spectralSequence(E.filteredComplex, Prune => true)
	  )

minimalPresentation SpectralSequencePage := prune SpectralSequencePage := SpectralSequencePage  => opts -> (E) -> (
     spectralSequencePage(E.filteredComplex, E.number, Prune => true)
     )

prune SheafMap := minimalPresentation SheafMap := SheafMap => opts -> (cacheValue symbol minimalPresentation) (f -> (
    (G, F) := (target f, source f);
    if f == 0 then return map(prune G, prune F, 0);
    prune G; prune F; -- these are pruned just to populate cached data
    -- F.cache.TorsionFree = M/H^0_B(M)
    g := inducedMap(G.cache.TorsionFree, truncate(f.degree, F.cache.TorsionFree, MinimalGenerators => false), matrix f);
    -- TODO: verify that f.degree is always sufficient here
    p := max(G.cache.GlobalSectionLimit, F.cache.GlobalSectionLimit) + max(0, f.degree);
    -- TODO: substitute with appropriate irrelevant ideal
    Bp := module (ideal vars ring variety F)^[p];
    lift sheaf(f.variety, prune Hom(Bp, g)))
    )

