pushForward(RingMap, Module) := Module => opts -> (f, M) -> (
    R := ring M;
    strategy := opts.Strategy;

    -- error checking
    if target f =!= R then error "expected module over the target of the ring map";

    -- this logic runs the strategies in order, or the specified strategy
    computation := (opts, container) -> (
	runHooks((pushForward, RingMap, Module), (opts, f, M), Strategy => strategy));

    -- this is the logic for caching partial pushforward computations. M.cache contains an option:
    --   PushforwardContext{} => PushforwardComputation{ Result, ... }
    container := fetchComputation(PushforwardComputation, M, (f, M), new PushforwardContext from f);

    -- the actual computation of the pushforward occurs here
    C := (cacheComputation(opts, container)) computation;

    if C =!= null then C else if strategy === null
    then error("no applicable strategy for computing pushforward")
    else error("assumptions for pushForward strategy ", toString strategy, " are not met"))

pushForward(RingMap,Matrix) := opts -> (f,M) -> (
   -- converts a map of free S-modules (a finite R-algebra) to a map over R
   R := source f;
   S := target f;
   assert (ring M === S);
   J := graphIdeal(f,VariableBaseName=>(local XX));
   T := ring J;
   Tbar := T/J;
   I := ideal 0_Tbar;
   -- have to be a little careful if graphIdeal is zero.
   if (Tbar =!= S) then I = image matrix {drop(gens Tbar,numgens S)};
   Tbarbar := Tbar/I;
   phi := map(Tbar,Tbarbar);
   h := map(Tbar,S,matrix {take(gens Tbar,numgens R)});
   sVars := (flatten entries basis Tbarbar) / (z -> phi(z));
   -- sVars is so that the coefficients are in the same order as the generators
   -- chosen in pushForward (is this true?)
   h2 := map(R,Tbar,matrix map(R^1,R^(numgens S),0_R) | matrix {gens R});
   MEntriesOverR := apply(entries M, row -> apply(row, p -> h2(last coefficients(matrix{h(p)*sVars}, Variables=>take(gens Tbar, numgens R),Monomials=>sVars))));
   targetM := pushForward(f,target M,opts);
   sourceM := pushForward(f,source M,opts);
   sRank := #sVars;
   map(targetM, sourceM, (i,j) -> (entries MEntriesOverR#(i//sRank)#(j//sRank))#(i%sRank)#(j%sRank))
)

pushForward(RingMap, SheafOfRings)  := opts -> (f, O) -> (
    X := variety O;
    X.cache.Pushforwards   ??= new MutableHashTable;
    X.cache.Pushforwards#f ??= pushForward(f, O^1, opts))

pushForward(RingMap, CoherentSheaf) := opts -> (f, G) -> (
    G.cache.Pushforwards   ??= new MutableHashTable )#f ??= (
    d := degree f(first gens source f); -- FIXME: this should be the degree of the map
    if #d == 1 then d = d#0 else error "not implemented for multigraded maps";
    S := source f;
    m0 := presentation pushForward'(f, module G, opts);
    m1 := first decomposePushforwardPresentation(d, m0);
    m2 := sub(m1, S); -- TODO: do better than sub?
    (tardegs, srcdegs) := toSequence(-degrees m2 // d);
    -- TODO: how long does this take? is it worth caching?
    sheaf prune coker map(S^tardegs, S^srcdegs, m2))

applyUniformMethod = (symb, name) -> args -> (
    if #args === 0 then error("expected at least one argument for ", name);
    type := if uniform args then class args#0 else error("expected uniform objects for ", name);
    meth := lookup(symb, type) ?? error("no method for ", name, " of ", pluralsynonym type);
    if (Y := youngest args) =!= null and Y.?cache
    then Y.cache#(symb, args) ??= meth args else meth args)

