quotientRemainder(RingElement,RingElement) := (f,g) -> (
     R := ring f;
     S := ring g;
     m := quotientRemainder(R,S) := (
	  if R === S then divmod R
	  else if isPromotable(R,S) then (
	       (x,y) -> divmod(promote(x,S), y)
	       )
	  else if isPromotable(S,R) then (
	       (x,y) -> divmod(x, promote(y,R))
	       )
	  else error "expected pair to have a method for quotientRemainder"
	  );
     m(f,g))

quotientRemainder(Matrix, GroebnerBasis) := Matrix => (n, G) -> (
    -- this gb might not be one with change of basis matrix attached...
    -- so it is best for the user not to use it
    R := ring G;
    (rem, quot, cplt) := rawGBMatrixLift(raw G, raw n);
    (map(R, quot), map(R, rem)))

quotientRemainder(Matrix,Matrix) := Matrix => (f,g) -> (
     L := source f;					    -- result may not be well defined if L is not free
     M := target f;
     N := source g;
     if M =!= target g then error "expected maps with the same target";
     if M.?generators then (
	  M = cokernel presentation M;	    -- this doesn't change the cover
	  );
     f = matrix f;
     g = matrix g;
     G := (
	  if M.?relations 
	  then gb(g | presentation M, ChangeMatrix => true, SyzygyRows => rank source g)
	  else gb(g,                  ChangeMatrix => true)
	  );
     (rem,quo,cplt) := rawGBMatrixLift(raw G, raw f);
     (
	  map(N, L, quo, Degree => degree f - degree g),
	  map(M, L, rem)
     ))

