    cmd = cmd | program#"path" | addPrefix(name, program#"prefix") | " " | args;
    if opts.Verbose then printerr("running: ", cmd);
    if match("\\|", cmd) then cmd = "{ " | cmd | ";}";
    returnValue := (
	if opts.Verbose
	then run ("(((((" | cmd | "; echo $? >&4) | tee " | outFile |
	    ") 3>&1 1>&2 2>&3 | tee " | errFile |
	    " >&5) 4>&1) | (read r; exit $r)) 5>&1")
