tensor(LieAlgebraRepresentation,LieAlgebraRepresentation) := (rhoV,rhoW) -> (
    V:=rhoV#"Module";
    W:=rhoW#"Module";
    LABV:=rhoV#"Basis";
    LABW:=rhoW#"Basis";
    LV:=rhoV#"RepresentationMatrices";
    LW:=rhoW#"RepresentationMatrices";
    U:=V**W;
    if LABV#"BasisElements" != LABW#"BasisElements" then error "The representations do not have the same basis";
    R1:=ring(LV_0);
    R2:=ring(LW_0);
    if R1 =!= R2 then error "The representations do not have the same base ring";
    lieAlgebraRepresentation(U,LABV,apply(#(LABV#"BasisElements"), i -> XactionOnTensorProduct(LV_i,LW_i)))
);

tensorAssociativity(Complex, Complex, Complex) := ComplexMap => (A,B,C) -> (
    -- implements the isomorphism A ** (B ** C) --> (A ** B) ** C
    AB := A ** B;
    BC := B ** C;
    E := A ** BC; -- source
    F := AB ** C; -- target
    (lo,hi) := concentration E;
    maps := new HashTable from for i from lo to hi list i => (
        -- want the map E_i --> F_i
        matrix for ab'c in indices F_i list
                for a'bc in indices E_i list (
                    a := a'bc#0;
                    b := a'bc#1 - ab'c#1;
                    c := ab'c#1;
                    bc := a'bc#1;
                    ab := ab'c#0;
                    if A_a != 0 and B_b != 0 and C_c != 0 then (
                        ((AB_ab)_[{a,b}] ** C_c)
                        * tensorAssociativity(A_a, B_b, C_c)
                        * (A_a ** (BC_bc)^[{b,c}])
                        )
                    else (
                        map(F_i.cache.components#(F_i.cache.indexComponents#{ab,c}),
                            E_i.cache.components#(E_i.cache.indexComponents#{a,bc}),
                            0)
                        )
                    )
        );
    map(F,E,maps)
    )

tensorAssociativity(ZZdFactorization, ZZdFactorization, ZZdFactorization) := ZZdFactorizationMap => (A,B,C) -> (
    -- implements the isomorphism A ** (B ** C) --> (A ** B) ** C
    AB := A ** B;
    BC := B ** C;
    E := A ** BC; -- source
    F := AB ** C; -- target
    p := period A;
    maps := new HashTable from for i from 1 to p list i => (
        map(F_i, E_i, 
        -- want the map E_i --> F_i
        matrix for ab'c in indices F_i list
                for a'bc in indices E_i list (
                    a := a'bc#0;
                    b := (a'bc#1 - ab'c#1);
                    c := ab'c#1;
                    bc := a'bc#1;
                    ab := ab'c#0;
                    if A_a != 0 and B_b != 0 and C_c != 0 then (
                        ((AB_ab)_[{a,b%p}] ** C_c)
                        * tensorAssociativity(A_a, B_b, C_c)
                        * (A_a ** (BC_bc)^[{b%p,c}])
                        )
                    else (
                         map(F_i.cache.components#(F_i.cache.indexComponents#{ab,c}),
                            E_i.cache.components#(E_i.cache.indexComponents#{a,bc}),
                            0)
                        )
                    )
		)
        );
    map(F,E,maps)
    )

