texMath Character := c -> (
    pc := prepCharacter c;
    -- make table headers, one column per actor
    s := concatenate("\\begin{array}{c|",c.numActors:"r","}\n");
    -- character entries
    rows := apply(sort pairs pc, (k,v) -> concatenate(texMath k,"&",
	    between("&",apply(flatten entries v,texMath)))
	);
    -- assemble and close array
    s | concatenate(between("\\\\ \n",rows),"\n\\end{array}")
    )

texMath CharacterTable := T -> (
    -- make table headers, one column per actor
    s := concatenate("\\begin{array}{c|",T.numActors:"r","}\n");
    -- print size of "conjugacy" classes
    s = s | concatenate("&",between("&",apply(T.size,texMath)),"\\\\ \\hline\n");
    -- get matrix of table entries and convert to strings
    M := for row in entries(T.table) list (
	concatenate(between("&",apply(row,texMath)))
	);
    -- put character label in front of its row
    M = apply(last T.Labels,M,(l,r)->l|"&"|r);
    -- close the array
    s | concatenate(between("\\\\ \n",M),"\n\\end{array}")
    )

texMath CharacterDecomposition := D -> (
    pd := prepDecomposition D;
    -- find non zero columns of table for printing
    M := matrix apply(values D.decompose, m -> flatten entries m);
    p := positions(toList(0..numColumns M - 1), i -> M_i != 0*M_0);
    -- make table headers, one column per nonzero irrrep
    s := concatenate("\\begin{array}{c|",#p:"r","}\n");
    -- top row with labels of characters appearing in decomposition
    s = s | concatenate("&",between("&",(last D.Labels)_p),"\\\\ \\hline\n");
    -- decomposition table entries
    rows := apply(sort pairs pd, (k,v) -> concatenate(texMath k,"&",
	    between("&",apply((flatten entries v)_p,texMath)) )
	);
    -- assemble and close array
    s | concatenate(between("\\\\ \n",rows),"\n\\end{array}")
    )

texMath Cell := String => cell -> (
    "\\textrm{Cell of dimension }" | (texMath dim cell) | "\\textrm{ with label }" | (texMath cellLabel cell)
    )

texMath CellComplex := String => cellComplex -> (
    if hasAttribute (cellComplex, ReverseDictionary) then return texMath getAttribute (cellComplex, ReverseDictionary);
    d := dim cellComplex;
    nTotalCells := #(flatten values cells cellComplex);
    if nTotalCells == 0
    then "\\textrm{empty cell complex}"
    else (
        ("\\textrm{Cell complex over }" | (texMath cellComplex.labelRing) | "\\textrm{ of dimension }" | d | "\\textrm{ with }" | nTotalCells | "\\textrm{ total cells }\n")
    ))

texMath Complex := String => C -> (
    (lo, hi) := concentration C;
    if C == 0 then 
        "0" 
    else (
        concatenate for i from lo to hi list (
            if i === lo then 
                texUnder(texMath short C_i, i) 
            else (
                "\\,\\xleftarrow{\\scriptsize " 
                | texMatrixShort dd^C_i 
                | "}\\," 
                | texUnder(texMath short C_i, i)
                )
            )
        )
    )

texMath DiagonalAction := D -> (
    torus := "";
    cyclicGroups := "";
    r := D.rank;
    g := D.numgens;
    local weightMatrix;
    if r > 0 then (
        torus = (texMath coefficientRing D.ring) | "^*";
	    if r > 1 then (
            torus = ("\\left("| torus |"\\right)") | "^" | (texMath r);
        );
    );
    if g > 0 then (
	cyclicGroups = demark(" \\times ",
	    apply(D.cyclicFactors, i -> texMath(ZZ) | "/" | toString(i))
	    );
        if r > 0 then (
            torus = torus|" \\times ";
            weightMatrix = D.weights
        )
        else weightMatrix = last D.weights;
	)
    else weightMatrix = first D.weights;
    (texMath D.ring) | "\\curvearrowleft" | torus | cyclicGroups | "\\text{ via }" | (texMath weightMatrix)
)

texMath RingOfInvariants := S -> (
    G := gens S;
    texString := (texMath coefficientRing ambient S);
    if #G != 0 then (
	texString |= "\\left[" |
	concatenate mingle(apply(G, g -> texMath g),toList(#G-1:", ")) | "\\right]";
	);
    if not zero ideal ambient S then (
	L := (ideal ambient S)_*;
	texString |= " / \\left(" |
	concatenate mingle(apply(L, l -> texMath l),toList(#L-1:", ")) | "\\right)";
	);
    texString
    )

texMath LinearlyReductiveAction := V -> (
    I := V.groupIdeal;
    l := apply(I_*,texMath);
    -- recreate action matrix to avoid printing degrees
    m := matrix entries V.actionMatrix;
    texMath(V.ring) | " \\curvearrowleft " | (texMath ring I) | "/" | "\\left(" |
    concatenate mingle(l,toList(#l-1:", ")) | "\\right)" | " \\text{ via } " |
    (texMath m)
    )

texMath GateSystem := S -> (
    out := "\\text{gate system}: " | toString numVariables S | " \\to " | toString numFunctions S;
    if numParameters S =!= 0 then out = out ||  "\\text{ (with $" | toString numParameters S | "$ parameters)}";
    out
    )

texMath ChainComplex := C -> (
     complete C;
     s := sort spots C;
     if # s === 0 then "0" else
     concatenate apply(s,i->(
	     if i>s#0 then "\\,\\xleftarrow{" | texMath short C.dd_i | "}\\,",
	     texUnder(texMath short C_i, i)
	     ))
      )

texMath GradedModule := C -> (
     s := sort spots C;
     if # s === 0 then "0"
     else demark("\\quad ",apply(s,i->texUnder(texMath C_i,i)))
      )

texMath GradedModuleMap := f -> (
     d := f.degree;
