trim Partition := Partition => o -> lam -> (
    numTrailingZeros := # for i from 1 to #lam list (if lam#-i == 0 then 1 else break);

    lamShortened := (toList lam)_(toList(0..(#lam-1-numTrailingZeros)));

    new Partition from lamShortened
    )

