methods.source:
multiHilbertPolynomial Module := o-> M ->(
s := getSymbol o.VariableName;
R := ring M;
u := unique ((gens R)/degree);
n := #u;
nums := apply(u, i-> #select(gens R, x -> degree x == i));
--form the Hilbert polynomials of the factor rings
a := local a;
polys1 := apply(n, j-> (
  hilbertPolynomial(ZZ/2[a_0 .. a_(nums_j-1)], 
      Projective => false)));
--move them to the Cox ring
cox := QQ(monoid [s_0..s_(n-1)]);
polys := apply(n, j->
	  (map(cox, ring polys1_j, {cox_j})) polys1_j);
M1 := coker leadTerm gb presentation M;
F := res M1;
pd := length F;
Fdeglists := apply(1+pd, i->degrees F_i);
Fpolys := apply (1+pd, i -> 
    sum(Fdeglists_i, L-> 
	product(n, j -> 
	    sub(polys_j,{cox_j=>cox_j-L_j}))));
sum(1+pd, i-> (-1)^i*Fpolys_i)
)

productOfProjectiveSpaces(List) := o -> L -> (
    kkk := o.CoefficientField;
    x := getSymbol o.VariableName;
    degs := flatten apply(#L, i -> toList (1+L_i:apply(#L, j-> if j==i then 1 else 0)));
    varlist := flatten apply(#L, i->apply(1+L_i, j->x_(i,j)));
    kkk[varlist, Degrees =>degs])

schemeInProduct(Ideal, List, Ring) := o->(I,Maps,PP) ->(
    --I defines a projective scheme in a polynomial ring S
    --Maps is a sequence of 1 x (1+m_i) matrices each consisting of forms of the 
    --same degree inside S/I, interpreted as rational maps from proj(S/I) to 
    --P^(m_i). PP is a multigraded ring corresponding to the product of the P^(m_i),
    --defined over the same field as S.
    --The routine forms the corresponding product of projective spaces, and
    --returns the multi-homogeneous ideal of the image.
    --
    --We should also have a version
    --inputting the product of projective spaces.
    S := ring I;
    dims := apply(Maps, f -> numcols f-1);
    degs := apply(Maps, f -> degree f_0);
    degslist := apply(#degs, i->toList(i:0)|degs_i|toList(1-i+dims_i:0));
    PPS := PP**(S/I);
    p := map(PPS,S);
    q := apply(#Maps,i-> select(gens PPS, u -> (degree u)_i == 1));
    lastdegs := toList (#Maps:0)|{1};
    Mats := apply(#Maps, i->
             map(PPS^{degslist_i,lastdegs}, PPS^(1+dims_i), 
	    (u,v) ->if u == 0 then p (Maps_i_v)_0 else q_i_v)
	);
    J := sum(Mats, m->minors(2,m));
    Jsat := saturate(J, irrelevantIdeal PPS);
    eliminate( (gens S)/p, Jsat)
    )

schemeInProduct(Ideal, List) := o-> (I,Maps) ->(
    --This version forms the corresponding product of projective spaces, and
    --returns the multi-homogeneous ideal of the image.
    S := ring I;
    kkk := coefficientRing S;
    dims := apply(Maps, f -> numcols f-1);
    PP := productOfProjectiveSpaces (dims, 
	         CoefficientField => kkk, 
	         VariableName => o.VariableName);
    schemeInProduct(I,Maps,PP)
)

smallDiagonal Ring  := S ->(
    --given an appropriate ring, as returned by 
    --productOfProjectiveSpaces n
    --returns the ideal of the small diagonal
    n := numgens S//2;
    v := genericMatrix(S,S_0,2,n);
    minors(2,v)
    )

inversion LabelList := o -> p -> (
    if member("_",p) then (
	if o.Separation===null then error "need to specify Separation";
	sep:=toString(o.Separation+if instance(o.Separation,QQ) then 0 else if any(p,a->a!="_" and first ascii a-48<o.Separation) then 1/2 else -1/2);
	p=apply(p,a->if a=="_" then sep else a);
	);
    sum(#p-1,i->sum(i+1..#p-1,j->if ord p_i>ord p_j then 1 else 0))
    )

ExtCoh(ZZ,CpMackeyFunctor,CpMackeyFunctor) := CpMackeyFunctor => (i,M,N) -> (
    if not isCohomological(N) then error "second Mackey functor not cohomological";
    d := resolutionCohomological(M,i+1);
    if i == 0 then (
        -- it's a cochain complex, so ker instead of coker
        ker internalHom(d_1, N)
    ) else (
        computeHomology(internalHom(d_(i+1), N),internalHom(d_i, N))
    )
)

TorCoh(ZZ,CpMackeyFunctor,CpMackeyFunctor) := CpMackeyFunctor => (i,M,N) -> (
    if not isCohomological(N) then error "second Mackey functor not cohomological";
    d := resolutionCohomological(M,i+1);
    if i == 0 then (
        coker ((d_1)**N)
    ) else (
        computeHomology((d_i)**N,((d_(i+1))**N))
    )
)

boxProduct (CpMackeyFunctor,CpMackeyFunctor) := CpMackeyFunctor => (M,N) -> (
    if M.PrimeOrder != N.PrimeOrder then error("-- Primes not the same (incompatible)");
    result := makeCpMackeyFunctor(M.PrimeOrder,boxProductRestriction(M,N), boxProductTransfer(M,N),boxProductConjugation(M,N));
    result.cache.formation = FunctionApplication{boxProduct, (M, N)};
    result
)

boxProduct (CpMackeyFunctor, MackeyFunctorHomomorphism) := MackeyFunctorHomomorphism => (M,f) -> (
    underlyingReturn := M.Underlying ** f.UnderlyingMap;
    fixedSource := coker(totalBoxProductRelation(M, source f));
    fixedTarget := coker(totalBoxProductRelation(M, target f));
    fixedReturn := inducedMap(fixedTarget, fixedSource, M.Fixed ** f.FixedMap ++ M.Underlying ** f.UnderlyingMap);
    map(boxProduct(M, f.Codomain),boxProduct(M, f.Domain), underlyingReturn, fixedReturn)
)

boxProduct (MackeyFunctorHomomorphism, CpMackeyFunctor) := MackeyFunctorHomomorphism => (f,M) -> (
    underlyingReturn := f.UnderlyingMap ** M.Underlying;
    fixedSource := coker(totalBoxProductRelation(source f, M));
    fixedTarget := coker(totalBoxProductRelation(target f, M));
    fixedReturn := inducedMap(fixedTarget, fixedSource, f.FixedMap ** M.Fixed ++ f.UnderlyingMap ** M.Underlying);
    map(boxProduct(f.Codomain, M),boxProduct(f.Domain, M), underlyingReturn, fixedReturn)
)

complexLinearizationMap(ZZ) := MackeyFunctorHomomorphism => p -> (
    map(makeComplexRepresentationMackeyFunctor p, makeBurnsideMackeyFunctor p, matrix {{1}}, matrix {{1,1}} || matrix (for i to p-2 list {0,1}))
)

drawVerticalCpMackeyFunctor(CpMackeyFunctor) := Net => M -> (
    hMid := 1 + max {length net M.Res, length net M.Trans};
    hTop := length net M.Fixed + 1;
	firstCol := vertSpace(hTop) || " Res" || (net M.Res);
    w1 := width net M.Fixed;
    w2 := width net M.Underlying;
    w3 := width net M.Conj;
    wm := max{w1, w2, w3};
    w := round(wm / 2)-1;
    w1 = if w1 == wm then 0 else round((wm-w1)/2);
    w2 = if w2 == wm then 0 else round((wm-w2)/2);
    w3 = if w3 == wm then 0 else round((wm-w3)/2);
    secondCol := horizontalJoin(horSpace(w1),net M.Fixed) || horizontalJoin(horSpace(w),vertArrows(hMid)) || horizontalJoin(horSpace(w2),net M.Underlying) || horizontalJoin(horSpace(w), "  ^") || horizontalJoin(horSpace(w), "└-┘") || horizontalJoin(horSpace(w), " c") || horizontalJoin(horSpace(w3),net M.Conj);
    thirdCol := vertSpace(hTop) || " Tr" || (net M.Trans);
    return horizontalJoin(firstCol, " ", secondCol, " ", thirdCol)
)

internalHom (CpMackeyFunctor,CpMackeyFunctor) := CpMackeyFunctor => (M,N) -> (
    if not M.PrimeOrder === N.PrimeOrder then error "internalHom: CpMackeyFunctors must have the same prime";
    p := M.PrimeOrder;
    A := makeBurnsideMackeyFunctor p;
    B := makeUnderlyingFreeMackeyFunctor p;
    underlying := Hom(B ** M, N);
    fixed := Hom(A ** M, N);
    tau := makeUniversalMapUnderlying(A, vector(A.Underlying,{1}));
    restriction := Hom(tau ** M, N);
    rho := makeUniversalMapFixed(B, vector(B.Fixed,{1}));
    transfer := Hom(rho ** M, N);
    gen := {0,1} | for i to p-3 list 0;
    conj := Hom(makeUniversalMapUnderlying(B, vector(B.Underlying, gen)) ** M, N);
    makeCpMackeyFunctor(
        p,
        restriction,
        transfer,
        conj
    )
)

internalHom (CpMackeyFunctor, MackeyFunctorHomomorphism) := MackeyFunctorHomomorphism => (M,f) -> (
    if not M.PrimeOrder === (source f).PrimeOrder then error "internalHom: Mackey functors are over different primes";
    p := M.PrimeOrder;
    A := makeBurnsideMackeyFunctor p;
    B := makeUnderlyingFreeMackeyFunctor p;
    src := internalHom(M, source f);
    tgt := internalHom(M, target f);
    underlyingMap := Hom(B ** M, f);
    fixedMap := Hom(A ** M, f);
    map(tgt, src, underlyingMap, fixedMap)
)

internalHom (MackeyFunctorHomomorphism, CpMackeyFunctor) := (f,N) -> (
    if not N.PrimeOrder === (source f).PrimeOrder then error "internalHom: Mackey functors are over different primes";
    p := N.PrimeOrder;
    A := makeBurnsideMackeyFunctor p;
    B := makeUnderlyingFreeMackeyFunctor p;
    src := internalHom(target f, N);
    tgt := internalHom(source f, N);
    underlyingMap := Hom(B ** f, N);
    fixedMap := Hom(A ** f, N);
    map(tgt, src, underlyingMap, fixedMap)
)

isCohomological CpMackeyFunctor := Boolean => M -> (
    if not M.cache#?"isCohomological" then (
        M.cache#"isCohomological" = (M.Trans * M.Res == map(M.Fixed, M.Fixed, M.PrimeOrder));
    );
    M.cache#"isCohomological"
)

isTrivialMackeyFunctor(CpMackeyFunctor) := Boolean => F -> (
    F.Fixed == 0 and F.Underlying == 0
)

makeBurnsideMackeyFunctor(ZZ) := CpMackeyFunctor => (p) -> (
    C := matrix{{1}};
    T := matrix{{0},{1}};
    R := matrix{{1,p}};

    return makeCpMackeyFunctor(p,R,T,C);
)

makeComplexRepresentationMackeyFunctor(ZZ) := CpMackeyFunctor => (p) -> (
    C := matrix {{1}};
    T := matrix (for i to p-1 list {1});
    R := matrix {for i to p-1 list 1};

    return makeCpMackeyFunctor(p,R,T,C);
)

makeCpMackeyFunctor(ZZ,Matrix,Matrix,Matrix) := CpMackeyFunctor => (p,R,T,C) ->(
    M := new CpMackeyFunctor from {
        symbol PrimeOrder => p,
        symbol Underlying => source T,          -- extract the underlying module from the transfer homomorphism
        symbol Fixed => target T,               -- extract the fixed module from the transfer homomorphism
        symbol Res => R,
        symbol Trans => T,
        symbol Conj => C,
        symbol cache => new CacheTable
        };
    if assertLevel > 0 and not isWellDefined M then error "Mackey Functor is not well-defined";
    M
)

makeFixedPointMackeyFunctor (ZZ,Matrix) := CpMackeyFunctor => (p,C) -> (
    m := C^0 - C; --declare the matrix 1-C
    R := inducedMap(source m, kernel m);
    T := inducedMap(kernel m, source m, sum (for i to p-1 list C^i));
    return makeCpMackeyFunctor(p,R,T,C)
)

makeFixedSignMackeyFunctor Sequence := x -> (
    makeFixedPointMackeyFunctor(2, -id_(ZZ^1))
)

makeFixedTrivMackeyFunctor(ZZ) := CpMackeyFunctor => (p) -> (
    U := coker matrix {{p}};
    makeFixedPointMackeyFunctor(p, id_U)
)

makeKGroupMackeyFunctor(ZZ,ZZ,ZZ) := CpMackeyFunctor => (p,q,n) -> (
    if not isPrime p then
        error "p must be prime";
    if not isPrimePower q then
        error "q must be a prime power";
    if n < 1 then
        error "n must be a positive integer";
    und := coker matrix {{q^(n*p) - 1}};
    fix := coker matrix {{q^n - 1}};
    tr := inducedMap(fix, und, matrix {{1}});
    re := inducedMap(und, fix, matrix {{sum (for i to p-1 list q^(n*i))}});
    conj := inducedMap(und, und, matrix {{q^n}});
    makeCpMackeyFunctor(p, re, tr, conj)
)

makeOrbitMackeyFunctor (ZZ,Matrix) := CpMackeyFunctor => (p,C) -> (
    m := C^0 - C; --declare the matrix 1-C
    R := inducedMap(source m, cokernel m, sum (for i to p-1 list C^i));
    T := inducedMap(cokernel m, source m);
    return makeCpMackeyFunctor(p,R,T,C)
)

