genIm (DiffAlgElement,DiffAlgElement) := List => (expr,var) ->	(
	x := getSymbol VAR;
	dx := getSymbol (if class expr === DiffAlgForm then VARD|VAR else VARA|VAR);

	C := coefficientRing coefficientRing ring expr;
	B := coefficientRing coefficientRing ring var;
	otherVars := reverse sort toList (set(gens C) - set(apply(gens B,s->sub(s,C))));
	cT := (if #otherVars > 0 then LL[otherVars] else LL);

	n := numgens ring expr;
	R := cT[x_0..x_(n-1)][dx_0..dx_(n-1),SkewCommutative => class expr === DiffAlgForm];
	T := R[gens B];
	wAux := expr#"f";
	for i in gens B do wAux = sub(wAux,{sub(i,C) => 0});
	if (wAux != 0) or (expr#"f" == 0) or ((degree sub(expr,T))_0 != 1) then (
		print "ERROR: genIm, expression must be non-zero and homogeneous";
		return {};
	);

	J := ideal apply(gens B, s -> coefficient(sub(s,T),sub(expr,T)));
	d := degree expr;
	if #d == 2 then d = {d_0,1,d_1};
	A := apply(flatten entries super basis({d_1,d_2},J), s->new class expr from {"f" => s});
	if #A == 0 then {expr-expr} else A
)

genKer (DiffAlgElement,DiffAlgElement) := List => (expr,var) -> (
	x := getSymbol VAR;
	dx := getSymbol (if class var === DiffAlgForm then VARD|VAR else VARA|VAR);

	C := coefficientRing coefficientRing ring expr;
	B := coefficientRing coefficientRing ring var;
	otherVars := reverse sort toList (set(gens C) - set(apply(gens B,s->sub(s,C))));
	cT := (if #otherVars > 0 then LL[otherVars] else LL);

	n := numgens ring expr;
	R := cT[x_0..x_(n-1)][dx_0..dx_(n-1),SkewCommutative => class var === DiffAlgForm];
	T := R[gens B];
	TAux := LL[gens ring expr|gens coefficientRing ring expr][gens coefficientRing coefficientRing ring expr];
	if (expr#"f" == 0) or ((degree sub(expr,TAux))_0 != 1) then ( 
		print "ERROR: genKer, expression must be linear and non-zero";
		return {};
	);

	I := sub(moduliIdeal expr,T);
	if ideal gens gb I == 1 then (
		print "ERROR: genKer, the system has no solutions";
		return {};
	);
	Bt := apply(gens B,s->sub(s,T));
	L := apply(Bt,s -> s => sub(s % I,T));
	L0 := apply(Bt,s -> s => sub(s % I,T) % (ideal Bt)); 
	vAux := sub(sub(var,T),L);
	vP := sub(vAux,L0);
	v := vAux - vP;

	J := ideal apply(Bt, s -> coefficient(s,v));
	d := degree var;
	if #d == 2 then d = {d_0,1,d_1};
	A := apply(flatten entries super basis({d_1,d_2},J), s->new class var from {"f" => s});
	A = {(if #A == 0 then {var-var} else A), new class var from {"f" => sub(vP,R)}};
	if vP == 0 then first A else A
)

isInvolutive DiffAlgDistribution := Boolean => L -> (
	T := extendRing L;
	I := ideal apply(L, s->sub(s,T));
	all(L,L, (i,j) -> (sub(i|j,T)%I) == 0)
)

linearComb(List,String) := DiffAlgElement => (L,varName) -> (
	if not all(L,s->instance(s,DiffAlgElement)) or not uniform L then (print "ERROR: linearComb";return 0;);

	x := getSymbol VAR;
	dx := getSymbol (if class L_0 === DiffAlgForm then VARD|VAR else VARA|VAR);
	a := getSymbol varName;
	n := max apply(L,s->(degree s)_0);

	eAux := newField(#L-1,0,varName);
	T := extendRing(L|{eAux});
	C := coefficientRing coefficientRing ring eAux;

	new class L_0 from {"f" => sum apply(gens C,L,(i,j)->sub(i,T)*sub(j,T))}
)

logarithmicForm(ZZ,List,String) := DiffAlgForm => o -> (n,l,varName) -> (
	F := for i in 0..#l-1 list newForm(n,0,l_i, varName | (i+1));
	x := getSymbol VAR;
	dx := getSymbol (VARD|VAR);
	a := getSymbol (varName | 0);
	C := LL[a_0..a_(#l-1)];
	R := C[x_0..x_(n-1)][dx_0..dx_(n-1),SkewCommutative => true];

	term := new DiffAlgForm from {"f"=>(a_0)_R};
	for j in drop(0..#l-1,{0,0}) do term = term ^ (F_j);
	out := term ^ (diff(F_0));
	for i in 1..#l-1 do (
		term := new DiffAlgForm from {"f"=>(a_i)_R};
		for j in drop(0..#l-1,{i,i}) do term = term ^ (F_j);
		out = out + term ^ (diff(F_i));
	);

	if o#Projective then (
		proj := 0_C;
		for i in 1..#l-1 do proj = proj + (a_i)_C*l_i/l_0;
		ccr := coefficientRing coefficientRing ring out;
		newForm toString (sub(out#"f",{(a_0)_ccr => sub(-proj,ccr)}))
	) else out
)

moduliIdeal DiffAlgElement := Ideal => elem -> (
	w := elem#"f";
	l := for i in (flatten entries monomials w) list
		for j in (flatten entries monomials(coefficient(i,w))) list
			coefficient(j,coefficient(i,w));
	sub(ideal flatten l,coefficientRing coefficientRing ring w)
)

projectivize DiffAlgElement := DiffAlgElement => e -> ( 
	n := (degree e)_0;
	x := getSymbol VAR;
	dx := getSymbol (if class e === DiffAlgForm then VARD|VAR else VARA|VAR);
	R := (coefficientRing coefficientRing ring e)[dx_0..dx_(n+1),x_0..x_(n+1)];
	c := max apply(terms sub(e,R),s->(degree s)_0);

	s := concatenate (for i in terms(sub(e,R)) list "+("| toString i | ")*"|VAR|"_"|n+1|"^"|c-((degree i)_0));

        if class e === DiffAlgForm then (
		r := radial (n+1);
		aux := (newForm s)_r;
		if aux#"f" == 0 then newForm s else
			newForm(VAR|"_"|n+1|"*("|s|")-"|VARD|VAR|"_"|n+1|"*"|aux)
	) else newField(s)
)

radial ZZ := DiffAlgField => n -> (
	x := getSymbol VAR;
	ax := getSymbol (VARA|VAR);
	W := LL[x_0 .. x_n][ax_0 .. ax_n];
	new DiffAlgField from {"f" => (basis(1,coefficientRing W)*transpose(basis(1,W)))_(0,0)}
)

singularIdeal DiffAlgElement := Ideal => elem -> (
	w := elem#"f";
	l := for i in (flatten entries monomials w) list coefficient(i,w);
	sub(ideal flatten l,coefficientRing ring w)
)

changeBaseField(GaloisField, Module) := (L, M) -> M.cache#(symbol changeBaseField, L) ??= (
    S := first flattenRing(ring M,
	CoefficientRing => null);
    K := coefficientRing S;
    if class K =!= GaloisField then return (
        R0 := quotient sub(ideal S, L monoid S);
	M' := directSum apply(cachedSummands M,
	    N -> coker sub(presentation N, R0));
        M.cache#(symbol changeBaseField, L) = M');
    -- don't needlessly create new rings:
    if K.order === L.order then return M;
    i0 := map(L, K);
    LS := L(monoid S);
    i1 := map(LS, ring ideal S, gens LS | { i0 K_0 });
    R := quotient i1 ideal S;
    i := map(R, S, i1);
    directSum apply(cachedSummands M, N -> i ** N))

changeBaseField(Ring, Module) := (L, M) -> M.cache#(symbol changeBaseField, L) ??= (
    S := first flattenRing(ring M,
	CoefficientRing => null);
    psi := changeBaseMap(L, S);
    directSum apply(cachedSummands M,
	N -> coker(psi ** presentation N)))

changeBaseField(Ring, Matrix) := (L, f) -> f.cache#(symbol changeBaseField, L) ??= (
    S := first flattenRing(ring f,
	CoefficientRing => null);
    psi := changeBaseMap(L, S);
    psi ** f)

directSummands Module := List => opts -> M -> M.cache.summands ??= (
    checkRecursionDepth();
    strategy := opts.Strategy;
    R := ring M;
    if prune' M == 0 then return { M };
    -- Note: End does not work for WeylAlgebras or AssociativeAlgebras yet, nor does basis
    if not isCommutative R and not isWeylAlgebra R then error "expected a commutative base ring";
    -- Note: rank does weird stuff if R is not a domain
    if opts.Verbose then printerr("splitting module of rank: ", toString rank M);
    if rank cover M <= 1 then return M.cache.summands = { M.cache.isIndecomposable = true; M };
    if isDirectSum  M    then return M.cache.summands = splitComponents(M, components M, directSummands_opts);
    if isDegreeSplit M   then return M.cache.summands = splitComponents(M, splitByDegrees M, directSummands_opts);
    if isFreeModule M    then return M.cache.summands = splitFreeModule(M, opts);
    if degrees R == {}   then return M.cache.summands = splitComponents(M, splitPIDModule M, N -> {N});
    if strategy & 1 == 1 then return M.cache.summands = (
	splitComponents(M, splitFreeSummands(M, opts),
	    directSummands_(opts, Strategy => strategy - 1)));
    -- TODO: where should indecomposability check happen?
    -- for now it's here, but once we figure out random endomorphisms
    -- without computing Hom, this would need to move.
    -- Note: this may return null if it is inconclusive
    if strategy & 2  == 2  and isIndecomposable M === true then { M } else
    if strategy & 16 != 16 and isHomogeneous M
    then summandsFromProjectors(M, opts)   -- see DirectSummands/homogeneous.m2
    else summandsFromIdempotents(M, opts)) -- see DirectSummands/idempotents.m2

directSummands(Module, Module) := List => opts -> (L, M) -> (
    checkRecursionDepth();
    if ring L =!= ring M then error "expected objects over the same ring";
    if rank L  >  rank M
    or rank L  == rank M and isFreeModule M then return {M};
    limit := opts.Limit ?? numgens M;
    tries := opts.Tries ?? defaultNumTries char ring M;
    if 1 < #cachedSummands M then return flatten apply(cachedSummands M, N -> directSummands(L, N, opts));
    if 1 < limit then (
	N := M;
	M.cache#(symbol ^, [0]) = id_M;
	if opts.Verbose then stderr << " -- splitting summands of degree " << degrees L << ": " << flush;
	comps := new MutableList from {M};
	for i to limit - 1 do (
	    pr := M.cache#(symbol ^, [#comps-1]);
	    LL := directSummands(L, N, opts, Limit => 1);
	    if #LL == 1 then break;
	    M.cache#(symbol ^, [#comps])   = N^[1] * pr;
	    M.cache#(symbol ^, [#comps-1]) = N^[0] * pr;
	    comps#(#comps-1) = L; -- === LL#0
	    comps##comps = N = LL#1);
	if opts.Verbose then stderr << endl << flush;
	return toList comps
    );
    zdeg := degree 0_M;
    -- TODO: can we detect multiple summands of L at once?
    -- perhaps find a projector onto a summand with several copies?
    gensHom0 := (N, M) -> (
	H := Hom(N, M,
	    DegreeLimit => zdeg,
	    MinimalGenerators => false);
	smartBasis(zdeg, H));
    h := catch if isFreeModule L then (
	-- TODO: for the case of line bundle summands,
	-- is it faster if we compute all of Hom and check
	-- for line bundles of any degree all at once?
	C := gensHom0(M, L); if numcols C == 0 then return {M};
	-- Previous alternative:
	-- h := for i from 0 to numcols C - 1 do (
	--     isSurjective(c := homomorphism C_{i}) ...)
	for i to tries - 1 do (
	    c := homomorphism(C * random source C);
	    if isSurjective c then throw (c, rightInverse c)))
    else (
        -- we look for a composition L -> M -> L which is the identity
	B := gensHom0(L, M); if numcols B == 0 then return {M};
	C  = gensHom0(M, L); if numcols C == 0 then return {M};
        -- attempt to find a random isomorphism
        for i to tries - 1 do (
	    b := homomorphism(B * random source B);
	    c := homomorphism(C * random source C);
            --TODO: change isIsomorphism to isSurjective?
	    if isIsomorphism(c * b) then throw (c, b));
	-- TODO: find an example where the following lines get used
	if opts.Strategy & 8 == 8 then (
	    -- precomputing the Homs can sometimes be a good strategy
	    -- TODO: confirm that this injectivity check is worthwhile and not slow
	    Bhoms := select(apply(numcols B, i -> homomorphism B_{i}), isInjective);
	    Choms := select(apply(numcols C, i -> homomorphism C_{i}), isSurjective);
	    scan'(Choms, Bhoms, (c, b) -> if isIsomorphism(c * b) then throw (c, b)))
	-- but sometimes too memory intensive
