      assert(lift(m1,R) == m); -- NOT YET
      m1 = promote(m,R);
      assert(promote(m1,R) == m);
      m1 = promote(m,S);
      assert(promote(m1,R) == m);
      m1 = promote(m,T);
      assert(lift(m1,R) == m); -- NOT YET
      m1 = promote(m,R1);
