(
    rCt := numRows M1;
    cCt := numColumns M1;
    if (n1 < 0) or (n1 > min(rCt, cCt)) then error "chooseRandomSubmatrix: not a valid submatrix size";
    rowL := randomSubset(numRows M1, n1);
    colL := shuffle(toList(0..<numColumns M1), n1);
    return {rowL, colL};
    )

