    	R := makeCharacterRing n;
    	K := M.constituents/rank;
    	FM := fourierMukai(K,n,R);
    	FlK := first first FM;
    	f := first last FM; g := last last FM;
    	yM := makeKClass(FlK,M);
    	YM := (pushforward g)( (pullback f)(yM * (ampleKClass FlK)) );
    	toPolynomial YM
    );
    M.cache.flagGeomTuttePolynomial
)

