o2 = GKMVariety{cache => CacheTable{...2...}                                          }
                characterRing => ZZ[T ..T ]
                                     0   1
                charts => HashTable{{set {0, 1*}} => {{0, 2}, {-1, 1}, {-2, 0}} }
                                    {set {0, 1}} => {{0, -2}, {-2, 0}, {-1, -1}}
                                    {set {1*, 0*}} => {{1, 1}, {2, 0}, {0, 2}}
