digraph(ChordalNet) := Digraph => opts -> N -> (
    tree := N.elimTree;
    nods := {};
    edges := {};
    alias := Ni -> Ni.label;
    for ip in nodePairs(tree) do(
        (i,p):= ip;
        NRi := nodes(N,i);
        nods = nods | (NRi/alias);
        if p===null then continue;
        Er := for Ni in NRi list(
            {alias(Ni),(Ni.parents)/alias} );
        edges = edges | Er;
    );
    G := digraph (nods,edges);
    return G;
)
```

