diffOps (Ideal, ZZ) := (I, k) -> (
     R := ring I;
     W := makeWeylAlgebra( R, SetVariables=>false);
     createDpairs W;

     -- make coeffs of derivations
     F := gens I;

     -- make Dk
     Dbasis := matrix {flatten apply( toList(0..k-1), i -> (
	       (entries symmetricPower(k-i, matrix{W.dpairVars#1}))#0 ) )};
     xbasis := matrix {flatten apply( toList(0..k-1), i -> (
	       (entries symmetricPower(k-i, vars R))#0 ) )};
     smallxbasis := matrix {flatten apply( toList(0..k-2), i -> (
	       (entries symmetricPower(k-1-i, vars R))#0 ) )};

     pInfo(1, "Making the matrix of partial derivatives of elements in I...");
     temp := transpose diff(transpose xbasis, F | 
	       flatten ((transpose smallxbasis)*F) );

     addon := directSum toList(rank target temp:matrix{{F}});

     full := temp | addon;
     pInfo(1, "Computing syzygies on an " | rank source full | " by " |
	  rank target full | " matrix...");
     syzy := (syz full)^{0..rank source temp - 1}; 
     pInfo(1, "Reducing matrix of " | rank source syzy | " by " |
	  rank target syzy | " syzygies with respect to I...");
     syzy = gens gb (syzy % I);

     hashTable {PolyGens => syzy, BasisElts => Dbasis}
     )

distraction(RingElement, Ring) := List => (f, ThetaRing) -> (
    if (n := numgens ring f // 2) != numgens ThetaRing then error "mismatched numbers of variables";
    sum(apbFactor f, q -> ( 
	    b := drop(q#0, n);
	    phi := map(ThetaRing, ThetaRing, ThetaRing_* - b);
	    pTheta := phi sum(q#1, v -> sub(v#0, ThetaRing) * product(#v#1, k -> product(v#1#k, i -> ThetaRing_k-i )));
	    thetaBracketSub(b, ThetaRing) * pTheta))
    )

eulerOperators (Matrix, List, PolynomialRing) := (A, b, W) -> (
    gkzInputValidation(A, b, W);
    apply(numRows A, i -> sum(numColumns A, j -> A_(i,j) * W.dpairVars#0#j * W.dpairVars#1#j) - b#i)
    )

gkz(Matrix, List, PolynomialRing) := (A, b, W) -> (
    gkzInputValidation(A, b, W);

    d := numRows A;
    n := numColumns A;

    -- Make the toric ideal
    toricIdeal := toricIdealPartials(A, W);

    -- Make the Euler operators
    eulerOpsWithBeta := eulerOperators(A, b, W);

    -- Make the gkz ideal
    ideal eulerOpsWithBeta + (map(W, ring toricIdeal)) toricIdeal
    )

