    boolean:=true;
    (A,b):=halfspaces(P);
    V:=vertices(P);
    E:=facesAsPolyhedra((dim P)-1,P);
    minLen:=infinity;
    for e in E do(
	len:=gcd(flatten entries((vertices(e))_0-(vertices(e))_1));
	minLen=min(len,minLen);
	);
    P0:=0;
