adams (ZZ,LieAlgebraModule) := (k,M) -> (
    g:=M#"LieAlgebra";
    if k==0 then new LieAlgebraModule from (g,{})
    else if k==1 then M
    else if k==-1 then starInvolution M
    else LieAlgebraModuleFromWeights(applyKeys(weightDiagram M, w -> k*w),g) -- primitive but works
)

adjointModule LieAlgebra := g -> (
    type:=g#"RootSystemType";
    m:=g#"LieAlgebraRank";
    if isSimple g then irreducibleLieAlgebraModule(g,adjointWeight(type,m))
    else new LieAlgebraModule from (g, tally apply(#m, i -> unsplit(adjointWeight(type#i,m#i),m,i)))
    )

adjointRepresentation(String,ZZ) := (type,m) -> (
    LAB:=lieAlgebraBasis(type,m);
    adjointRepresentation(LAB)
);

adjointRepresentation(LieAlgebra) := (g) -> (
    LAB:=lieAlgebraBasis(g);
    adjointRepresentation(LAB)
);

adjointRepresentation(LieAlgebraBasis) := LAB -> (
    br := LAB#"Bracket";
    writeInBasis := LAB#"WriteInBasis";
    B := LAB#"BasisElements";
    ad := X -> transpose matrix apply(B, Y -> writeInBasis br(X,Y));
    L := apply(B, X -> ad X);
    V := adjointModule(LAB#"LieAlgebra");
    lieAlgebraRepresentation(V,LAB,L)
);

