    true
);

isomorphismOfRepresentations(LieAlgebraRepresentation,LieAlgebraRepresentation) := (rho1, rho2) -> (
    V:=rho1#"Module";
    if rho2#"Module"!=V then error "The representations are not isomorphic";
    if not isIrreducible(V) then error "Not implemented yet for reducible representations";
    LAB1:=rho1#"Basis";
    LAB2:=rho2#"Basis";
    if LAB1#"BasisElements"!=LAB2#"BasisElements" then error "Not implemented yet when the representations have different Lie algebra bases";
    lambda:=first keys(V#"DecompositionIntoIrreducibles");
    vlambda:=weightMuHighestWeightVectorsInW(lambda,rho1);
    LOMaps:=apply(LAB1#"LoweringOperatorIndices", i -> (rho1#"RepresentationMatrices")_i);
    basisWords:=basisWordsFromMatrixGenerators(rho2);
    act:=(X,f) -> X*f;
    P:=matrixFromColumns(apply(basisWords, w -> applyWord(w,vlambda,act,LOMaps)));
    -- Check this before returning it
    Pinv := inverse P;
    L1:=rho1#"RepresentationMatrices";
    L2:=rho2#"RepresentationMatrices";
    g:=LAB1#"LieAlgebra";
    if not all(dim g, i -> L2_i == Pinv*(L1_i)*P) then error "Isomorphism not found";
    P
);

lieAlgebraBasis(String,ZZ) := o -> (type,m) -> (
    LAB:={};
    if o#"Method"=="Lusztig" then LAB=lusztigBasis(simpleLieAlgebra(type,m));    
    if type=="A" then LAB=slnBasisFH(m+1);
    if type=="B" then LAB=so2n1BasisFH(m);
    if type=="C" then LAB=sp2nBasisFH(m);
    if type=="D" then LAB=so2nBasisFH(m);
    if type=="G" and m==2 then LAB=g2BasisFH();
    if o#"Check" then (
	(b,errorString):=checkLieAlgebraBasis(LAB);
	if not b then error errorString;
    );
    LAB
);

lieAlgebraBasis(LieAlgebra) := o -> (g) -> (
    if not isSimple(g) then error "Lie algebra bases are only implemented for simple Lie algebras so far" << endl;
    LAB:={};
    if o#"Method"=="Lusztig" and isSimple(g) then LAB = lusztigBasis(g);
    if o#"Method"=="FH" and isSimple(g) and g#"RootSystemType"=="A" then LAB = slnBasisFH(g#"LieAlgebraRank"+1);
    if o#"Method"=="FH" and isSimple(g) and g#"RootSystemType"=="B" then LAB = so2n1BasisFH(g#"LieAlgebraRank");
    if o#"Method"=="FH" and isSimple(g) and g#"RootSystemType"=="C" then LAB = sp2nBasisFH(g#"LieAlgebraRank");
    if o#"Method"=="FH" and isSimple(g) and g#"RootSystemType"=="D" then LAB = so2nBasisFH(g#"LieAlgebraRank");
    if o#"Method"=="FH" and g==simpleLieAlgebra("G",2) then LAB = g2BasisFH();
    if o#"Check" then (
	(b,errorString):=checkLieAlgebraBasis(LAB);
	if not b then error errorString << endl;
    );
    LAB    
);

lieAlgebraRepresentation(LieAlgebraModule,LieAlgebraBasis,List):=(V,LAB,L) -> (
    new LieAlgebraRepresentation from {
        "Module"=>V,
        "Basis"=>LAB,
	"RepresentationMatrices"=>L
    }
);

positiveRoots(String,ZZ):= (type,m) -> (
    M:=matrix apply(simpleRoots(type,m), a -> 1/1*a);
    Mtinv:=inverse transpose M;
    PhiPlus := sort apply(unorderedPositiveRoots(type,m), a -> {level(a,type,m),reverse flatten entries (Mtinv*(transpose matrix {a})),a});
    apply(PhiPlus, p -> p_2)
)

qdim (LieAlgebraModule,ZZ) := (M,l) -> (
    g:=M#"LieAlgebra";
    if not isSimple g then error "Lie algebra not simple";
    (map(qring(l+dualCoxeterNumber g,2*fac(g#"RootSystemType",g#"LieAlgebraRank")),R)) qdim M
    )

reynoldsOperator(LieAlgebraRepresentation) := (rho) -> (
    casimirProjection(rho,0)
);

simpleLieAlgebra(String,ZZ) := (type,m) -> (
    if not isSimple(type,m) then (
    	if not member(type,{"A","B","C","D","E","F","G"}) then error "The simple Lie algebras over the complex numbers have types A, B, C, D, E, F, or G";
    	if type=="A" and m<= 0 then error "The rank for type A must be >= 1.";
    	if type=="B" and m<= 1 then error "The rank for type B must be >= 2.";
    	if type=="C" and m<= 1 then error "The rank for type C must be >= 2.";
    	if type=="D" and m<= 2 then error "The rank for type D must be >= 3.";
    	if type=="E" and not member(m,{6,7,8}) then error "The rank for type E must be 6, 7, or 8.";
    	if type=="F" and m!=4 then error "The rank for type F must be 4.";
    	if type=="G" and m!=2 then error "The rank for type G must be 2.";
	);
    new LieAlgebra from (type,m)
    )

spinRepresentationMatrices(ZZ) := o -> (n) -> (
    B:={};
    R:=o#CoefficientRing;
    I:=identityMatrix(2^n,R);
    WedgeBasis:=wedgeBasis(n);
    -- First create the Hs in the first basis I used
    Hs := apply(n, i ->  wedgeByek(i+1,WedgeBasis,R)*contractByemk(i+1,WedgeBasis,R) - (1/2)*I);
    -- Now make the basis Ha1..Han
    Hbasis := apply(n-1, i -> Hs_i-Hs_(i+1));
    Hbasis = append(Hbasis, Hs_(n-2)+Hs_(n-1));
    Xbasis := flatten apply(n, i -> delete(null,apply(n, j -> if j!=i then wedgeByek(i+1,WedgeBasis,R)*contractByemk(j+1,WedgeBasis,R))));   
    Ybasis := flatten apply(n, i -> delete(null,apply(n, j -> if i<j then wedgeByek(i+1,WedgeBasis,R)*wedgeByek(j+1,WedgeBasis,R)))); 
    Zbasis := flatten apply(n, i -> delete(null,apply(n, j -> if i<j then contractByemk(j+1,WedgeBasis,R)*contractByemk(i+1,WedgeBasis,R)))); 
    L:=flatten {Hbasis, Xbasis, Ybasis, Zbasis};
    sigma := so2nPermutation(n);
    apply(sigma, i -> L_i)
);

standardModule LieAlgebra := g -> (
    type:=g#"RootSystemType";
    m:=g#"LieAlgebraRank";
    if isSimple g then irreducibleLieAlgebraModule(g,standardWeight(m))
    else new LieAlgebraModule from (g, tally apply(#m, i -> unsplit(standardWeight(m#i),m,i)))
    )

standardRepresentation(String,ZZ) := (type,m) -> (
    if not member(type,{"A","B","C","D"}) then error "Only implemented for types A,B,C,D";    
    LAB:=lieAlgebraBasis(type,m);
    V := standardModule(LAB#"LieAlgebra");
    lieAlgebraRepresentation(V,LAB,LAB#"BasisElements")

);

standardRepresentation(LieAlgebra) := g -> (
    if not member(g#"RootSystemType",{"A","B","C","D"}) then error "Only implemented for types A,B,C,D";
    LAB:=lieAlgebraBasis(g);
    V := standardModule(LAB#"LieAlgebra");
    lieAlgebraRepresentation(V,LAB,LAB#"BasisElements")
);

starInvolution LieAlgebraModule := M -> (
    g:=M#"LieAlgebra";
    new LieAlgebraModule from (
    	g,
    	applyKeys(M#"DecompositionIntoIrreducibles", v -> starInvolution(g,v))
	)
    )

starInvolution(String,ZZ,List) := (type, m, w) ->  ( N:=#w;
    if type == "A" then return reverse w;
    if type == "B" or type == "C" or type == "F" or type == "G" then return w;
    if type == "E" and m!= 6 then return w;
    if type == "D" and even(m) then return w;
    if type == "D" and odd(m) then (x:=w;
        return append(drop(x,{#x-2,#x-2}),w_(#w-2)));
    if type == "E" and m== 6 then return {w_5,w_1,w_4,w_3,w_2,w_0};
    )

starInvolution(Sequence,Sequence,List) := (type,m,w) -> (
    w = split(w,m);
    flatten apply(#w, i -> starInvolution(type#i,m#i,w#i))
)

subLieAlgebra (LieAlgebra, List) := (g,S) -> subLieAlgebra(g,if #S==0 then map(ZZ^(rank g),0,0) else matrix transpose apply(splice S,s ->
	if class s === ZZ and s>0 and s<=rank g then apply(rank g, j -> if j+1 == s then 1 else 0)
	else if class s === ZZ and s==0 then entries lift(-inverse cartanMatrixQQ g*vector highestRoot g,ZZ)
	else if instance(s,Vector) and rank class s == rank g then entries s
	else if class s === List and #s == rank g then s
	else error "wrong argument"))

subLieAlgebra (LieAlgebra,Matrix) := (g,M) -> ( -- matrix of coroots
    if ring M =!= ZZ then try M=lift(M,ZZ) else error "matrix must be integer";
    -- in the simply laced case it'd be simply transpose M * cartanMatrix g * M. in general have to work harder
    if numRows M != rank g then error "wrong size of coroots";
    G := transpose M * inverse quadraticFormMatrix g * M; -- new inverse quadratic form <coroot_i|coroot_j>
    D := diagonalMatrix apply(numColumns M,i->2/G_(i,i)); -- inverse square norm of new simple coroots
    C := lift(D * G,ZZ);
    (type,m,L):=lieTypeFromCartan C;
    M=M_L; -- permuted matrix of coroots
    if M == id_(ZZ^(rank g)) then return g; -- better this way, no weirdness of defining a new g subalgebra of g
    new LieAlgebra from (
	unsequence type,
	unsequence m,
	applyValues(supalgebras g, A -> A*M)
	)
    )

subLieAlgebra(LieAlgebra,String) := (g,s) -> (
    if s =!= "principal" then error "only principal subalgebra predefined";
    if g#"RootSystemType"==="A" and g#"LieAlgebraRank"===1 then return g; -- better this way, no weirdness of defining a new g subalgebra of g
    M := lift(2*inverse promote(cartanMatrix g,QQ)*matrix apply(rank g,i->{1}),ZZ); -- 2 rho^v = 2 sum of fundamental coweights
    new LieAlgebra from (
	"A",
	1,
	applyValues(supalgebras g, A -> A*M)
	)
    )

trivialRepresentation(String,ZZ) := (type,m) -> (
    LAB:=lieAlgebraBasis(type,m);
    trivialRepresentation(LAB)
);

trivialRepresentation(LieAlgebra) := (g) -> (
    LAB:=lieAlgebraBasis(g);
    trivialRepresentation(LAB)
);

trivialRepresentation(LieAlgebraBasis) := LAB -> (   
    L := apply(#(LAB#"BasisElements"), i -> matrix {{0/1}});
    V := trivialModule(LAB#"LieAlgebra");
    lieAlgebraRepresentation(V,LAB,L)
);

uNminus(LieAlgebraBasis) := (LAB) -> (
    -- Set up the Lie algebra basis
    g := LAB#"LieAlgebra";
    B := LAB#"BasisElements";
    br := LAB#"Bracket";
    writeInBasis := LAB#"WriteInBasis";
    Bweights:=LAB#"Weights";
    -- Get the bracket relations with respect to the original basis
    BB:=getSymbol "BB";
    R1 := QQ<|apply(#B, i -> BB_i)|>;
    LOI:=LAB#"LoweringOperatorIndices";
    v:={};
    r:=0;
    uNminusbracketRelations := flatten for i from 0 to #B-1 list (
        for j from 0 to #B-1 list (
	    if not(member(i,LOI) and member(j,LOI)) then continue;
            v = writeInBasis(br(B_i,B_j));
            r = R1_i*R1_j-R1_j*R1_i - (sum apply(#B, k -> v_k*R1_k));
            r
        )
    );
    -- Now set up the free algebra
    PhiPlus := positiveRoots(g);
    Y:=getSymbol "Y";
    varListy := reverse apply(#PhiPlus, i -> Y_(i+1));
    R2 := QQ<|varListy|>;
    -- Get the map
    WtToZZ:=new HashTable from apply(#B, i -> (Bweights_i,i));
    posRootMap:=reverse apply(PhiPlus, w -> WtToZZ#w);
    cartanMap:=reverse apply(g#"LieAlgebraRank", i -> i);
    negRootMap:=reverse apply(PhiPlus, w -> WtToZZ#(-w));
    sigma:=join(posRootMap,cartanMap,negRootMap);
    sigmainverse := apply(sort apply(#sigma, i -> {sigma_i,i}), p -> p_1);
    n:=#PhiPlus+g#"LieAlgebraRank";
    f12:=map(R2,R1,apply(#sigma, i -> if sigmainverse_i <n then 0 else R2_(sigmainverse_i-n)));
    R2/f12(ideal uNminusbracketRelations)
);

uNminus(LieAlgebra) := (g) -> (
    uNminus(lieAlgebraBasis(g))
);

universalEnvelopingAlgebra(LieAlgebraBasis) := (LAB) -> (
    -- Set up the Lie algebra basis
    g := LAB#"LieAlgebra";
    B := LAB#"BasisElements";
    br := LAB#"Bracket";
    writeInBasis := LAB#"WriteInBasis";
    Bweights:=LAB#"Weights";
    -- Create U(g) in the original basis
    BB:=getSymbol "BB";
    R1 := QQ<|apply(#B, i -> BB_i)|>;
    v:={};
    r:=0;
    bracketRelations:=flatten for i from 0 to #B-1 list (
        for j from 0 to #B-1 list (
            v = writeInBasis(br(B_i,B_j));
            r = R1_i*R1_j-R1_j*R1_i - (sum apply(#B, k -> v_k*R1_k));
            r
        )
    );
    -- Now set up the free algebra
    PhiPlus := positiveRoots(g);
    x:=getSymbol "x";
    h:=getSymbol "h";
    y:=getSymbol "y";
    varListx := reverse apply(#PhiPlus, i -> x_(i+1));
    varListh := reverse apply(g#"LieAlgebraRank", i -> h_(i+1));
    varListy := reverse apply(#PhiPlus, i -> y_(i+1));
    R2 := QQ<|flatten {varListx,varListh,varListy}|>;
    -- Get the map
    WtToZZ:=new HashTable from apply(#B, i -> (Bweights_i,i));
    posRootMap:=reverse apply(PhiPlus, w -> WtToZZ#w);
    cartanMap:=reverse apply(g#"LieAlgebraRank", i -> i);
    negRootMap:=reverse apply(PhiPlus, w -> WtToZZ#(-w));
    sigma:=join(posRootMap,cartanMap,negRootMap);
    sigmainverse := apply(sort apply(#sigma, i -> {sigma_i,i}), p -> p_1);
    f12:=map(R2,R1,apply(#sigma, i -> R2_(sigmainverse_i)));
    (R2/f12(ideal bracketRelations),sigma,sigmainverse)
);

universalEnvelopingAlgebra(LieAlgebra) := (g) -> (
    universalEnvelopingAlgebra(lieAlgebraBasis(g))
);

