	    RP, frac R);
	liftFromFractionFieldMap := map(RP, frac R);
	setupLift(f -> (
		if isMember(denominator f, RP.maxIdeal)
		then error "expected a denominator outside the maximal ideal"
		else liftFromFractionFieldMap f),
	    frac R, RP);
        RP
        )

localsyz(Matrix) := (m) -> (
     localMingens syz m
