profondeur(Ideal, Module) := (I,M) ->(
    --requires R to be an affine ring (eg NOT ZZ[x])
    R := ring M;
    d := max(1,dim M); -- d=0 causes a crash
    if not isCommutative R then error"profondeur undefined for noncommutative rings";
    F := M**dual freeResolution (R^1/I, LengthLimit => d);
    i := 0;    
    while HH_i F == 0 do i=i-1;
    -i)

profondeur Module := M  ->(
    --profondeur of a module with respect to the max ideal, via finite proj dim
    --gives error if the ultimate coefficient ring of R = ring M is not a field.
    R := ring M;
    if not isCommutative R then error"profondeur undefined for noncommutative rings";
    (S,F) := flattenRing R;
    if not isField coefficientRing S then error"input must be a module over an affine ring";
    S0 := ring presentation S;
    r := F*map(S,S0); 
    MM := pushForward(r,M);
    numgens S0 - pdim MM)

setupModules(List,Module) := (R,M)->(
    --R_i is a ci of codim i in a ring S
    --returns (MM,kk,p) where
    --MM,kk are lists whose i-components are the module M and residue field k, but over R_i
    --p_i_j is the projection from R_j to R_i (c >= i >= j >= 0)
    --M is a a module over R_c.
    c := length R-1;
    kk :=apply(c+1, i-> coker vars R_i);
    p := apply(c+1, i->apply(i+1, j->map(R_i,R_j)));
    MM := apply(c+1, j->prune pushForward(p_c_j, M));
    (MM,kk,p))

setupRings(ZZ,ZZ) := opts -> (c,d)->(
    x := local x;
    p := opts.Characteristic;
    S := ZZ/p[x_0..x_(c-1)];
    ff := matrix{apply(c, i->S_i^d)};
    if opts.Randomize===true then ff = ff*random(source ff, source ff);
    {S}|apply(c, j->(S/ideal(ff_{0..j})))
    )

setupRings(Matrix) := opts -> (ff)->(
     S := ring ff;
     c := numcols ff;
     if opts.Randomize===true then ff = ff*random(source ff, source ff);
     {S}|apply(c, j->(S/ideal(ff_{0..j})))
     )

socleDegrees Module := M ->(
    R := ring M;
    k := coefficientRing R;
    if not isField k then error"coefficient ring not a field";
     flatten degrees target basis Hom(coker vars R,M)    
    )

syzygyModule(ZZ,Module) := opts -> (k,M) -> (
    if k === 0 then return M;
    F := null;

    if k>0 then (
	F = freeResolution(M, LengthLimit => k+1);
	return coker F.dd_(k+1));

    if k<0 then (
	n := numgens ring M;
	if opts.CoDepth == 0 then
	n = 1 else
	if opts.CoDepth >0 then
	n = opts.CoDepth;
	F  = freeResolution(M, LengthLimit => n);
	M1 := image dual F.dd_(n);
	G := freeResolution(M1, LengthLimit => -k+n);
    return image dual G.dd_(-k+n));
    )

addLoadMethod(String, Function) := o -> (type, f) -> (
    if not loadMethods#?(o.Namespace)
    then error("unknown namespace: ", o.Namespace);
    loadMethods#(o.Namespace)#type = f)

addNamespace(String, String, String) := (ns, url, v) -> (
    namespaces#ns = {url, v};
    loadMethods#ns = new MutableHashTable;
    Thing#{ns, UseID} = false;)

addSaveMethod(Type, Function, Function) := o -> (T, paramsf, dataf) -> (
    T#{o.Namespace, saveMRDI} = (x, refs) -> (
	if o.UseID then thingToUuid x; -- save uuid
	params := processMRDI(o.Namespace, paramsf x, refs);
	data := processMRDI(o.Namespace, dataf x, refs);
	hashTable {
	    "_type" => (
		if params =!= null then hashTable {
		    "name" => getType(o.Name, x),
		    "params" => params}
		else getType(o.Name, x)),
	    if data =!= null then "data" => data});
    T#{o.Namespace, UseID} = o.UseID;)

loadMRDI HashTable := r -> (
    ns := first keys r#"_ns";
    if not loadMethods#?ns then error("unknown namespace: ", ns);
    -- save info about refs we haven't created yet
    if r#?"_refs" then scanPairs(r#"_refs",
	(i, s) -> if not thingsByUuid#?i then uuidsToCreate#i = s);
    if r#?"id" then uuidToThing(r#"id", () -> fromMRDI(ns, r))
    else fromMRDI(ns, r))

saveMRDI Thing := o -> x -> (
    if not namespaces#?(o.Namespace)
    then error("unknown namespace: ", o.Namespace);
    refs := new MutableHashTable;
    mrdi := toMRDI(o.Namespace, x, refs);
    r := (if o.ToString then toJSON else identity) merge(
	hashTable {
	    "_ns" => hashTable {
		o.Namespace => namespaces#(o.Namespace)},
	    if useID(o.Namespace, x) then "id" => thingToUuid x,
	    if #refs > 0 then "_refs" => new HashTable from refs},
	mrdi,
	(x, y) -> error "unexpected key collision");
    if o.FileName =!= null then o.FileName << r << endl << close;
    r)

validateMRDI HashTable := x -> (
    validateObject x;
    if not x#?"_type" then error "expected a '_type' key";
    if instance(x#"_type", String) then null
    else if instance(x#"_type", HashTable) then (
	validateObject x#"_type";
	if x#"_type"#?"name" then (
	    if not instance(x#"_type"#"name", String)
	    then error("expected value of 'name' to be a string"));
	if x#"_type"#?"params" then validateData x#"_type"#"params")
    else error("expected value of '_type' to be a string or object");
    scan({"_ns", "_refs"}, k -> (
	    if x#?k then (
		if not instance(x#k, HashTable)
		then error("expected value of '", k, "' to be an object");
		validateObject x#k)));
    if x#?"_refs" then scanPairs(x#"_refs", (k, v) -> (
	    if not isUuid k
	    then error("expected all keys of '_refs' to be UUID's, but got ", k);
	    validateMRDI v));
    )

