        \draw (3) -- (6);
        \draw (4) -- (7);
        \draw (4) -- (6);
        \draw (2) -- (4);
        \draw (2) -- (5);
        \draw (5) -- (7);
\end{tikzpicture}
        \draw (0) -- (2);
        \draw (0) -- (1);
        \draw (2) -- (4);
        \draw (2) -- (5);
        \draw (5) -- (7);
        \draw (4) -- (6);
        \draw (4) -- (7);
        \draw (1) -- (4);
        \draw (1) -- (3);
        \draw (3) -- (6);
\end{tikzpicture}
                 2        2   2      2              2        2     2   2
```

```
o3 = {{1, x, y, x , x*y, y , x y, x*y }, {1, y, x, y , x*y, x , x*y , x y}}
o3 : List
```

