            if grMF.tupleMaxSize >= 2 and grMF.tupleMaxValue - grMF.tupleMaxSize >= 2 then (
                flatten for I in subsets(1 .. grMF.tupleMaxValue, grMF.tupleMaxSize - 1) list (
                    for J in subsets(1 .. grMF.tupleMaxValue, grMF.tupleMaxSize + 1) list (
                        newGenerator := sum for jPosition from 0 to #J - 1 list (
                            j := J_jPosition;
                            if not member(j, I) then (
                                IIndex := sort(I | {j});
                                JIndex := delete(j, J);
                                swapsToSortI := # for i in I list if i > j then i else continue;
                                pI := variableFromSubset#IIndex;
                                pJ := variableFromSubset#JIndex;
                                (-1)^(jPosition + swapsToSortI)*pI*pJ
                                ) else continue
                            );
                        if not zero(newGenerator) then (
                            newGenerator
                            ) else continue
                        )
                    )
                ) else continue
            );
        ---------------------
        -- Incident Relations
        --
        generatorList = generatorList | flatten for grMFs in subsets(getGrMatchingFields MF, 2) list (
            grMF0 := grMFs_0;
            grMF1 := grMFs_1;
            flatten for I in subsets(1 .. grMF0.tupleMaxValue, grMF0.tupleMaxSize - 1) list (
                for J in subsets(1 .. grMF1.tupleMaxValue, grMF1.tupleMaxSize + 1) list (
                    sum for jPosition from 0 to #J - 1 list (
                        j := J_jPosition;
                        if not member(j, I) then (
                            IIndex := sort(I | {j});
                            JIndex := delete(j, J);
                            swapsToSortI := # for i in I list if i > j then i else continue;
                            pI := variableFromSubset#IIndex;
                            pJ := variableFromSubset#JIndex;
                            (-1)^(jPosition + swapsToSortI)*pI*pJ
                            ) else continue
                        )
                    )
                )
            );
        MF.cache.mfPlueckerIdeal = ideal(generatorList);
        );
    MF.cache.mfPlueckerIdeal
    )

plueckerMap MatchingField := opts -> MF -> (
    setupMatchingFieldRings(opts, MF);
    if not MF.cache.?plueckerRingMap then (
        R := MF.cache.ringP;
        S := MF.cache.ringX;
        matX := MF.cache.XVarMatrix;
        MF.cache.plueckerRingMap = map(S, R, for tuple in MF.tuples list det(matX_(apply(sort tuple, i -> i - 1))^(toList(0 .. #tuple - 1))));
        );
    MF.cache.plueckerRingMap
    )

topeField GrMatchingField := MF -> (
    new TopeField from {
        "type" => toList(MF.tupleMaxSize : 1),
        "matchingField" => MF
        }
    )

topeField(GrMatchingField, List) := (MF, type) -> (
    assert(sum type == MF.tupleMaxSize);
    new TopeField from {
        "type" => type,
        "matchingField" => MF
        }
    )

weightMatrixCone GrMatchingField := opts -> MF -> (
    if opts.ExtraZeroRows == 0 and MF.cache.?computedWeightMatrixCone then (
        MF.cache.computedWeightMatrixCone
        ) else (
        -- form the matrix of inequalities A: such that the cone is Ax >= 0
        local inequalities;
        if MF.tupleMaxSize > 1 then (
            inequalities = matrix (
                subsetList := subsets(1 .. MF.tupleMaxValue, MF.tupleMaxSize);
                flatten for i from 0 to binomial(MF.tupleMaxValue, MF.tupleMaxSize) - 1 list (
                    columnIndices := subsetList_i;
                    minimalTuple := MF.tuples_i;
                    for p in delete(minimalTuple, permutations columnIndices) list (
                        -- the row vector the encodes: minimalTuple <= p
                        -- E.g. if the minimal tuple is {1,2,3} then
                        --      one of the inequalities is given by {1,2,3} <= {1,3,2}
                        --      which cancels down further since 1 is in the same place
                        for coord in (0,1) .. (MF.tupleMaxSize - 1 + opts.ExtraZeroRows, MF.tupleMaxValue) list (
                            sum {if coord_0 < MF.tupleMaxSize and p_(coord_0) == coord_1 then 1 else 0,
                                if coord_0 < MF.tupleMaxSize and minimalTuple_(coord_0) == coord_1 then -1 else 0}
                            )
                        )
                    )
                );
            ) else (
            inequalities = matrix {toList((MF.tupleMaxSize + opts.ExtraZeroRows) * MF.tupleMaxValue : 0)};
            );
        C := coneFromHData(inequalities);
        if opts.ExtraZeroRows == 0 then MF.cache.computedWeightMatrixCone = C;
        C
        )
    )

weightMatrixCone FlMatchingField := opts -> MF -> (
    if opts.ExtraZeroRows == 0 and MF.cache.?computedWeightMatrixCone then (
        MF.cache.computedWeightMatrixCone
        ) else (
        weightMatrixConeList := for grMF in getGrMatchingFields MF list (
            weightMatrixCone(grMF, ExtraZeroRows => (MF.tupleMaxSize - grMF.tupleMaxSize + opts.ExtraZeroRows))
            );
        inequalityMatrix := facets (weightMatrixConeList_0);
        hyperplanesMatrix := hyperplanes (weightMatrixConeList_0);
        for i from 1 to #weightMatrixConeList - 1 do (
            inequalityMatrix = inequalityMatrix || facets (weightMatrixConeList_i);
            hyperplanesMatrix = hyperplanesMatrix || hyperplanes (weightMatrixConeList_i);
            );
        C := coneFromHData(inequalityMatrix, hyperplanesMatrix);
        if opts.ExtraZeroRows == 0 then MF.cache. computedWeightMatrixCone = C;
        C
        )
    )

Fold(Complex,ZZ) := (C,d) -> (
    (lo,hi) := concentration C;
    L := for i to d-1 list select(lo..hi+1,j->j%d==i);
    ZZdfactorization (apply(L_{1..d-1,0},i->if #i > 0 then directSum apply(i,j->C.dd_j) else id_((ring C)^0)))
    )

Fold(ComplexMap,ZZ) := (phi,d) -> (
    (lo,hi) := concentration phi;
    L := (for i to d-1 list select(lo-1..hi+1,j->j%d==i));
    Lk := for i from 1 to d list i=> if #(L_(i%d))>0 then directSum apply(L_(i%d),j->phi_j) else id_((ring phi)^0);
    map(Fold(target phi,d),Fold(source phi,d),P:=new HashTable from Lk,Degree => degree phi)
    )

ZZdfactorization HashTable := ZZdFactorization => opts -> maps -> (
    spots := sort keys maps;
    if #spots === 0 then
      error "expected at least one matrix";
    if not all(spots, k -> instance(k,ZZ)) then
      error "expected matrices to be labelled by integers";
    if not all(spots, k -> instance(maps#k,Matrix)) then
      error "expected hash table or list of matrices";
    R := ring maps#(spots#0);
    if not all(values maps, f -> ring f === R) then
      error "expected all matrices to be over the same ring";
    moduleList := new MutableHashTable;
    for k in spots do (
        if not moduleList#?(k-1) 
          then moduleList#(k-1) = target maps#k;
        moduleList#k = source maps#k;
        );
    C := new ZZdFactorization from {
           symbol ring => R,
           symbol module => new HashTable from moduleList,
           symbol period => #spots,
           symbol cache => new CacheTable
           };
    C.dd = map(C,C,maps,Degree=>-1);
    if R.?rootOfUnity then C.cache.rootOfUnity = R.rootOfUnity;
    C
    )

ZZdfactorization List := ZZdFactorization => opts -> L -> (
    d:=length L;
    -- L is a list of matrices,  a list of modules, or a list of ring elements
    if not instance(opts.Base, ZZ) then
      error "expected Base to be an integer"; 
    if all(L, ell -> instance(ell,Matrix)) then (
        --trg := target L#0;
	mapHash := hashTable for i from 0 to #L-1 list
	         (if (opts.Base+i+1)%(#L) == 0 then #L else (opts.Base+i+1)%(#L)) => map(source(L#((i-1)%d)),source(L#(i%d)) , L#i);
        return ZZdfactorization(mapHash, opts)
        );
    --
    if all(L, ell -> instance(ell,RingElement)) then (
        trg2 := (ring(L#0))^1;
	mapHash2 := hashTable for i from 0 to #L-1 list
	            (if (opts.Base+i+1)%(#L) == 0 then #L else (opts.Base+i+1)%(#L))  => map(trg2, trg2, matrix{{L#i}});
        return ZZdfactorization(mapHash2, opts)
        );
    --
    if all(L, ell -> instance(ell,Module)) then (
        R := ring L#0;
        if any(L, ell -> ring ell =!= R) then
            error "expected modules all over the same ring";
        moduleHash := hashTable for i from 0 to #L-1 list (opts.Base + i)%(#L) => L#i;
        C := new ZZdFactorization from {
            symbol ring => R,
            symbol period => #L,
            symbol module => moduleHash,
            symbol cache => new CacheTable
            };
        C.dd = map(C,C,0,Degree=>-1);
        return C;
        );
    error "expected a list of matrices, a list of modules, or a list of ring elements";
    )

ZZdfactorization(Module, ZZ) := ZZdFactorization => opts -> (M,d) -> (
    if not instance(opts.Base, ZZ) then
      error "ZZ/d factorization: expected base to be an integer";
    if M.cache.?ZZdFactorization and opts.Base === 0 and period M.cache.ZZdFactorization == d then return M.cache.ZZdFactorization;
    C := new ZZdFactorization from {
           symbol ring => ring M,
           symbol period => d,
           symbol module => hashTable {opts.Base => M},
           symbol cache => new CacheTable
           };
    if opts.Base === 0 then M.cache.ZZdFactorization = C;
    C.dd = map(C,C,0,Degree=>-1);
    C
    )

ZZdfactorization ZZdFactorization := ZZdFactorization => opts -> C -> (
    -- all this does is change the homological degrees 
    -- so the factorization starts at a new base
    p := period C;
    if 0 === opts.Base then
        C
    else (
        L := for i from 1 to p list dd^C_i;
        ZZdfactorization(L, Base=>opts.Base)
        )
    )

adjoinRoot(ZZ,Ring,Symbol) := (d,Q,t) -> (S1 := Q[t,Degrees => {0}];
    var := (S1_*)_0;
    cyclo := cycloPoly(d, var);
    S := S1/(cyclo);
    S.rootOfUnity = (S_*)_0;
    S
    )

adjoinRoot(ZZdFactorization,RingElement) := (F,t) -> (
    adjoinRoot(F,getSymbol "t")
    )

adjoinRoot(ZZdFactorization,Symbol) := (F,t) -> (
        d := period F;
	S := adjoinRoot(d,ring F,t);
	P := F**S;
	P.cache.rootOfUnity = (S_*)_0;
	P
	)

adjoinRoot(ZZdFactorizationMap,RingElement) := (F,t) -> (
adjoinRoot(F,getSymbol "t")
)

adjoinRoot(ZZdFactorizationMap,Symbol) := (F,t) -> (
        d := period F;
	S := adjoinRoot(d,ring F,t);
	P := F**S;
	P.cache.rootOfUnity = (S_*)_0;
	P
	)

