randomTailMF(RingElement, ZZ, ZZ, ZZ) := ZZdFactorization => opts -> (f, m, n, b) -> (
    S:= ring(f)/ideal(f);
    Lm := for i to m-1 list random(1,b);
--    Ln := for i to n-1 list random(-b,b);    
    M := prune trim cokernel random(S^Lm, S^n);
    F := tailMF(M);
    if not(opts.WellDefined) then return F;
    rk := rank F_0;
    if not all(values F.module, i -> rank i == rk) then randomTailMF(f, m, n, b) else F
)

rk1MCM2gen(List, ZZ) := ZZdFactorization =>  (L,d) -> (a := local a;
    b := local b;
    x := local x;
    Q := if d==0 then QQ[x_1..x_4,a,b] else ZZ/d[x_1..x_4,a,b]; 
    an := (Q_*)_4;
    bn := (Q_*)_5;
    S := Q/(an^2-an+1,bn^2-bn+1);
    use S;
    (i,j,s) := toSequence L;
    M1 := matrix{{x_1-an*x_s,-(x_i^2+bn*x_i*x_j+bn^2*x_j^2)},{x_i-bn*x_j,x_1^2+an*x_1*x_s+an^2*x_s^2}};
    M2 := matrix{{x_1^2+an*x_1*x_s+an^2*x_s^2,x_i^2+bn*x_i*x_j+bn^2*x_j^2},{-(x_i-bn*x_j),x_1-an*x_s}};
    ZZdfactorization {M1,M2}
    )

suspension(ZZdFactorization) := ZZdFactorization =>  F -> (
    prune coker injectiveCover F
