ASMFullList ZZ := List => (n) -> (
    if (n < 1 or n > 7) then error("expected an integer between 1 and 7");
    filename := concatenate(
	MatrixSchubert#"source directory",
	"MatrixSchubert/ASMData/full/", toString n, ".txt");
