ASMRandomList (ZZ,ZZ) := List => (n,m) -> (
    if (n < 1 or n > 7) then error("expected an integer between 1 and 7");
    fullList := ASMFullList(n);
    randNums := for i to m-1 list random (#fullList-1);
    listOfMatrices := apply(randNums, i -> fullList#i);
