	else flatten apply(possibleTopRows(w), ro->(
	    wp := permAfterTopRow(w,ro);
	    wp = apply(#wp-1, i->(wp_(i+1)-1));
	    apply(pipeDreams(wp), D->
		prepend(ro, apply(D, Dro -> append(Dro, "/"))))
