    I := schubertDeterminantalIdeal A';
    schubertDecompose I
    )

schubertDeterminantalIdeal Matrix := o -> A -> (
    if not(isPartialASM A) then error("The input must be a partial alternating sign matrix or a permutation.");
 --   A = partialASMToASM(A);
    zMatrix := genMat(numrows A, numcols A, CoefficientRing=> o.CoefficientRing, Variable => o.Variable); --generic matrix
    rankMat := rankTable A; --rank matrix for A
    essBoxes := essentialSet A;
    R := ring zMatrix;
    I := ideal(0_R);
    if essBoxes == {} then (
	I.cache.ASM = A;
	return I;
	);
    zBoxes := apply(essBoxes, i -> flatten table(i_0, i_1, (j, k) -> (j+1, k+1))); --smaller matrix indices for each essential box
    ranks := apply(essBoxes, i -> rankMat_(i_0-1, i_1-1)); --ranks for each essential box
    fultonGens := new MutableList;
    for box in essBoxes do (
    	pos := position(essBoxes, i -> i == box);
        fultonGens#(#fultonGens) = (minors(ranks_pos+1, zMatrix^{0..(box_0-1)}_{0..(box_1-1)}))_*;
    );
    I = ideal (unique flatten toList fultonGens);
    I.cache.ASM = A;
    I
)

schubertDeterminantalIdeal List := o -> w -> (
    if not(isPerm w) then error("The input must be a partial alternating sign matrix or a permutation.");    
    A := permToMatrix w;
    schubertDeterminantalIdeal(A,CoefficientRing=>o.CoefficientRing, Variable => o.Variable)
)

schubertIntersect List := Ideal => (L) -> (
    if (#L == 0) then error("Please enter a nonempty list.");
    ll := L / schubertDeterminantalIdeal;
    numVars := apply(ll, i-> #((ring i)_*));
    Q := ring ll_(position(numVars, i-> i == max numVars));
    intersect apply(ll, J -> sub(J, Q))
);

schubertPolynomial(List) := opts-> (w) -> (

    n := #w;
    x := local x;
    Q := QQ[x_1..x_n];
    if opts.Algorithm == "Transition" then 
        schubertPolyHelper(w, Q, Double=>false)
    else if opts.Algorithm == "DividedDifference" then
        polyByDividedDifference(w,Q)
    else error("Invalid option for Algorithm.")

)

schubertRegularity List := ZZ => w -> (
     if not (isPerm w) then error ("The input must be a partial alternating sign matrix or a permutation.");
     rajIndex(w) - permLength(w)
)

schubertRegularity Matrix := ZZ => A -> (
    if not(isPartialASM A) then error("The input must be a partial alternating sign matrix or a permutation.");
    --Check if Matrix is a partial permutation matrix, and if it is, use rajindex formula.
    w := toOneLineNotation partialASMToASM A;
    if (w != {}) then return rajIndex(w) - permLength(w);
    --Otherwise compute regularity of its antidiagonal initial ideal
    I := antiDiagInit A;
    if I == 0 then return 0;
    regularity(I) -1
);

subwordComplex List := SimplicialComplex => w -> (
    if not(isPerm w) then error("The input must be a permutation.");
    simplicialComplex antiDiagInit w
);

toOneLineNotation (List, ZZ) := List => (perm, maxIdx) -> (
    if maxIdx == 1 then return {1};
    switch(perm_0-1, perm_1-1, toList(1..maxIdx))
)

toOneLineNotation (Matrix) := List => (P) -> (
     if (isASM P == false) then return {};
     nonzeroIndices := flatten for j from 0 to (numColumns P - 1) list positions(flatten entries P^{j}, i -> i != 0);
     w := nonzeroIndices / (i -> i+1);
     if isPerm w then return w;
     if not (isPerm w) then return {};
)

allMatroids (ZZ, ZZ) := List => (n, r) -> (
	if r > n then (n, r) = (r, n);
	if r > n//2 then return allMatroids(n, n-r)/dual;
	E := toList(0..<n);
	if r == 0 then return {uniformMatroid(0, n)};
	if r == 1 then return {uniformMatroid(1, n)} | apply(n-1, i -> matroid(E, take(subsets(n, 1), i+1), EntryMode => "nonbases"));
	if n > 9 then error "allMatroids: Can only return all matroids on <= 9 elements";
	PE := reverse sort subsets(set E, r);
	dir := first select(path, p -> fileExists(p | "Matroids/SmallMatroids.txt"));
	db := if (n, r) =!= (9, 4) then (
		numMatroids := {7,13,23,38,37,108,58,325,940,87,1275}; -- cf. Table 1 in https://arxiv.org/pdf/math/0702316.pdf
		K := {(4,2),(5,2),(6,2),(6,3),(7,2),(7,3),(8,2),(8,3),(8,4),(9,2),(9,3)};
		H := hashTable apply(#K, i -> K#i => {2*i+1+sum take(numMatroids,i), 2*i+sum take(numMatroids,i+1)});
		take(lines get(dir | "Matroids/SmallMatroids.txt"), H#(n,r))
	) else lines get(dir | "Matroids/r4n9.txt");
	apply(db, l -> matroid(E, PE_(positions(characters l, c -> c === "*"))))
)

allMinors (Matroid, Matroid) := List => (M, N) -> (
	flatten apply(independentSets(M, rank M - rank N), X -> (
		C := M/X; 
		apply(select(independentSets(dual C, #C.groundSet - #N.groundSet), Y -> areIsomorphic(N, C\Y)), Y -> {X, Y/(y -> (sort toList(M.groundSet - X))#y)})
)))

bases(FlagMatroid) := List => M -> (
    if not M.cache.?bases then M.cache.bases = (
	ML := M.constituents; k := #ML;
	BL := flatten apply(k, i -> (bases ML_i)/(b -> (i,b)) );
	rel := (a,b) -> first a < first b and isSubset(last a, last b);
	P := poset(BL, rel , AntisymmetryStrategy => "none");
	(maximalChains P)/(c -> c/last)
    );
    M.cache.bases
)

basisIndicatorMatrix Matroid := Matrix => M -> (
	initVector := toList M.groundSet;
	transpose matrix(bases M/(b -> initVector/(i -> if member(i, b) then 1 else 0)))
)

chromaticPolynomial Graph := RingElement => G -> (
	P := characteristicPolynomial matroid G;
	(ring P)_0^(#connectedComponents G)*P
)

circuits Matroid := List => M -> (
	if M.cache.?circuits then M.cache.circuits else M.cache.circuits = (ideal M)_*/indices/set
)

closure(Arrangement, Ideal) := Flat => (A,I) -> (
     flat(A, positions(A.hyperplanes, h -> h % gb I == 0), Validate => false)
     )

closure(Arrangement, List) := Flat => (A, S) -> (
     closure(A,ideal (A.hyperplanes_S | {0_(ring A)}))  -- ugly hack for empty list
     )

closure (Matroid, Set) := Set => (M, S) -> (
	r := rank(M, S);
	if r == rank M then return M.groundSet;
	S + set select(toList(M.groundSet - S), s -> r == rank(M, S + set{s}))
)

cogeneratorChowRing Matroid := RingElement => M -> ( -- sorted flats makes this 3x faster
	t := getSymbol "t";
	I := trim idealChowRing M;
	R := ring I;
	W := R[apply(gens R, v -> t_(last baseName v))];
	sub(value (factor((sum(#gens R, i -> W_i*R_i))^(rank M - 1) % sub(I, W)))#1, QQ[gens W])
)

