methods.source:
radical Ideal := Ideal => opts -> I -> (
    -- TODO: what does the Unmixed boolean add to strategy?
    strategy := if opts.Unmixed then Unmixed else opts.Strategy;
    key := (radical, Ideal);

    computation := (cacheValue symbol radical) (I -> runHooks(key, (opts, I), Strategy => strategy));
    C := computation I;

    if C =!= null then C else if strategy === null
    then error("no applicable method for ", toString key)
    else error("assumptions for radical strategy ", toString strategy, " are not met"))

radicalContainment(RingElement, Ideal) := Boolean => opts -> (g, I) -> (
     R := ring I;
     if ring g =!= R then error "Expected same ring";
     if isHomogeneous I and opts.Strategy == "Kollar" then (
	  -- Radical membership test for homogeneous ideals
	  -- Based on Theorem 1.5 in https://www.jstor.org/stable/pdf/1990996.pdf
	  -- should assume degrees are > 2
	  degs := reverse sort((flatten entries mingens I)/degree/sum);
	  n := min(#support I, #degs);
	  degs = drop(degs_{0..<n}, -1) | {last degs};
	  if debugLevel > 0 then print("Upper bound of " | toString(product degs) | " for radical");
	  for i to floor(log_2 product degs) do (
	       if debugLevel > 0 then print("Testing power " | toString(2^(i+1)));
	       g = g^2 % I;
	       if g == 0 then return true;
	  );
	  false
     ) else (
	  n = numgens R;
	  S := (coefficientRing R) (monoid[Variables=>n+1,MonomialSize=>16]);
	  mapto := map(S,R,submatrix(vars S,{0..n-1}));
	  I = mapto I;
	  g = mapto g;
	  J := I + ideal(g*S_n-1);
	  1_S % J == 0_S
     )
)

add(Ideal, Ideal) := (J, K)->(
if ring(J) =!=ring(K) then error "-- expected the same ring" ;
reduced (J*K)
)

scalarMultiplication(Ideal, ZZ) := (J, m)->(
if m<0 then error "--expected a positive integer";
if m==0 then return ideal 1_(ring J);
if even m then return double scalarMultiplication(J, m//2);
return add(double scalarMultiplication(J, (m-1)//2), J)
)

setPolynomialRing(GaloisField, List, List):=(kk, v, w)->(
if gcd w !=1 then error "-- the weights have gcd>1" ;
if min w <1 then error "-- some weights are not positive" ;
if #v != #w then error "-- the numbers of variables and weights are different" ;
PR=kk[v,MonomialOrder=>{Weights => w, Weights=>toList(1 ..#w) }]
)

setPolynomialRing(List, List):=(v, w)->(
if gcd w !=1 then error "-- the weights have gcd>1" ;
if min w <1 then error "-- some weights are not positive" ;
if #v != #w then error "-- the numbers of variables and weights are different" ;
PR=QQ[v,MonomialOrder=>{Weights=>w, Weights=>toList(1 ..#w) }]
)

homIdealPolytope List := Ideal => o -> W -> (
    n := #W_0;
    r := #W;

    -- to check if the vertices entered are in the same dimension
    for i from 0 to r-1 do (
	if #W_i != n then error "Incorrect list of vertices entered";
	); 

    --to translate points    
    shiftList := splice new MutableList from {n:0}; 
    for i from 0 to r-1 do (
	apply(0..n-1, j -> if W#i#j < shiftList#j then shiftList#j = W#i#j);
	); 
    WNew := toList apply(0..r-1, j -> toSequence (toList W#j - toList shiftList));

    X := o.VariableBaseName; 
    if instance(X, String) then X = getSymbol X; 
    k := o.CoefficientRing;
    R := k[X_1..X_(n+1)];
    g := sum for p from 0 to r-1 list ( product(0..(n-1), i -> R_i^(((WNew#p)_i))) );
    g1 := homogenize(g,R_n); 
    I := ideal(terms g1)
