bettiTablesWithHilbertFunction (List, PolynomialRing) := o -> (D, R) -> (
    M := monomialIdealsWithHilbertFunction(D, R, 
	BoundGenerators => o.BoundGenerators, 
	FirstBetti => o.FirstBetti, 
	GradedBettis => o.GradedBettis,
	SquareFree => o.SquareFree);
    if o.Count then(
	tally apply(M, m -> betti res m)
	)
    else(
	unique apply(M, m -> betti res m)
	)
    )

codimensionIP (MonomialIdeal) := I -> (
    if I.cache#?(symbol codim) then return I.cache#(symbol codim);
    (dir, zimplFile, solFile, errorFile, detailsFile) := tempDirectoryAndFiles("codim");
    zimplFile << codimensionIPFormulation(I) << close;
    run(concatenate("(",ScipPath, 
	    " -c 'read ", zimplFile,
	    "' -c 'optimize'",
	    " -c 'display solution ",
	    "' -c quit;) 1>",
	    solFile,
	    " 2>",
	    errorFile));
    printStatement({zimplFile, solFile, errorFile, "Codim", dir});
    readScipSolution(solFile)
    )

degreeIP (MonomialIdeal) := o -> I -> (
    if I.cache#?(symbol degree) then return I.cache#(symbol degree);
    if (cokernel generators I).cache#?(symbol poincare) then return oldDegree I;
    objValue := if o.KnownDim >= 0 then o.KnownDim else dimensionIP(I);
    (dir, zimplFile, solFile, errorFile, detailsFile) := tempDirectoryAndFiles("deg");        
    if not isSquareFree I then (
    	J := polarize(I);
    	newDim := numgens ring J - numgens ring I + objValue;
    	zimplFile << degreeIPFormulation(J, newDim) << close;
  	) else (
    	zimplFile << degreeIPFormulation(I, objValue) << close;
  	);
    run(concatenate("(",ScipPath, 
	    " -c 'set emphasis counter'",
	    " -c 'set constraints countsols collect FALSE'",     	    
	    " -c 'read ", zimplFile, "'",
	    " -c 'count'",
	    " -c quit;)",
	    " 1>",
	    solFile,
	    " 2>",
	    errorFile
	    ));
    printStatement({zimplFile, solFile, errorFile, "Degree", dir});
    readScipCount(solFile)
    )

dimensionIP (MonomialIdeal) := I -> (
    n := numgens ring I;
    n - codimensionIP(I)
    )

installMethod(loadBuiltinCodimAndDegree, () -> (
  codim MonomialIdeal := oldCodim;
  degree MonomialIdeal := oldDegree;
));

installMethod(loadSCIPCodimAndDegree,() -> (
  codim MonomialIdeal := options oldCodim >> opts -> m -> ((cacheValue symbol codim) codimensionIP) m;
  degree MonomialIdeal := m -> ((cacheValue symbol degree) degreeIP) m;
));

minimalPrimesIP (MonomialIdeal, ZZ) := (I, iterations) -> (
  collectedPrimes := {};
  i := 0;
  while i < iterations or iterations < 0 do (
    newPrimes := topMinimalPrimesIP(I, IgnorePrimes => collectedPrimes);
    if #newPrimes === 0 then break;
    collectedPrimes = collectedPrimes | newPrimes;
    i = i + 1;
  );
  collectedPrimes
)

monomialIdealsWithHilbertFunction (List, PolynomialRing) := o -> (D, R) -> (
    if not isHF D then(if ScipPrintLevel >= 1 then print("Impossible Hilbert function values."); {})
    else(
	if o.FirstBetti =!= null and o.GradedBettis =!= null then error("cannot specify FirstBetti and GradedBettis options simultaneously");
	n := numgens R;
    	Dlist := apply(#D, i -> binomial(n+i-1,i)-D#i);
    	if all(Dlist, d -> d==0) then return {monomialIdeal(0_R)};
    	(dir, zimplFile, solFile, errorFile, detailsFile) := tempDirectoryAndFiles("hilbert");            
    	zimplFile << hilbertIPFormulation(Dlist, n, o) << close;
    	run(concatenate("(",ScipPath, 
	    " -c 'set emphasis counter'",
	    " -c 'set constraints countsols collect TRUE'",     
	    " -c 'read ", zimplFile,
	    "' -c 'count'",
	    " -c 'write allsolutions ",
	    solFile,
	    "' -c quit;)",
	    " 1>",
	    detailsFile,
	    " 2>",
	    errorFile));
        printStatement({zimplFile, solFile, errorFile, "Hilbert", dir});
    	readAllMonomialIdeals(solFile, R)
	)
    )

topMinimalPrimesIP (MonomialIdeal) := o -> I -> (
    if I == monomialIdeal(1_(ring I)) then return I;
    R := null;
    squarefree := isSquareFree I;
    ignorePrimes := o.IgnorePrimes;
    if not squarefree then (
      R = ring I;
      I = polarize I;
      polarizedRing := ring I;
      ignorePrimes = apply(ignorePrimes, p ->(
        sub(polarize monomialIdeal p, polarizedRing)
      ));
    );
    ignorecontraints := ignorePrimesConstraints(ignorePrimes, squarefree);

    k := if o.KnownDim >= 0 then o.KnownDim else dimensionIPWithConstraints(I, ignorecontraints);
    if k === null then return {};
    (dir, zimplFile, solFile, errorFile, detailsFile) := tempDirectoryAndFiles("comps");
    zimplFile << degreeIPFormulation(I, k) << ignorecontraints << close;
    run(concatenate("(",ScipPath,
	    " -c 'set emphasis counter'",
	    " -c 'set constraints countsols collect TRUE'",
	    " -c 'read ", zimplFile,
	    "' -c 'count'",
	    " -c 'write allsolutions ",
	    solFile,
	    "' -c quit;)",
	    " 1>",
	    detailsFile,
	    " 2>",
	    errorFile));
    printStatement({zimplFile, solFile, errorFile, "Minimal primes of codim " | (numgens ring I - k), dir});
    L := readAllPrimes(solFile, ring I);
    if squarefree then L else unPolarizeSome(L, R)
)

hilbertRepresentatives(Ring, VisibleList) := List => o -> (R, h) -> (
    --orbit representatives of all monomial ideals I, if any, such that
    --hilbertFunction(i,R/I) = h_(i-1) for all i = 1,..,#h.
    G := permutations R;

    if h_0 > numgens R then error "not enough variables";
    if min h < numgens R and o.MonomialType == "SquareFree" then return {};

    result := if h_0 == numgens R then 
                  {monomialIdeal 0_R} 
              else
                  {monomialIdeal((gens R)_{0..numgens R - h_0 -1})};
    rawMonsMat := matrix{{}};
    mons := {};
    for i from 2 to #h do (
        rawMonsMat = monomialsInDegree(i, R, o.MonomialType);
        mons = flatten entries sort(rawMonsMat,
                     DegreeOrder => Ascending, MonomialOrder => Descending);
        result = flatten for I in result list (
            mons = flatten entries sort(compress(rawMonsMat % truncate(i, I)),
                DegreeOrder => Ascending, MonomialOrder => Descending);
            defect := hilbertFunction(i, R^1/I) -  h_(i-1);
            if defect < 0 then continue;
            if h_(i-1) == 0  then (
                if mons == {} then result1 := {I}
                else result1 = {monomialIdeal trim (I+ideal mons)}
                )
            else (
                result1 = {I};
                scan(defect, j->(
                        result1 = normalForms(sumMonomials(result1, mons), G);
                        ))
                );
     	    result1);
        );
    result
    )

normalForms(List, List) := (Fs, G) -> (
    <<"---"<< #Fs<<endl;
    -- Fs is a list of MonomialIdeals, G a list of ring maps
    -- returns a minimal subset F of Fs such that G F = Fs.
    if #Fs == 0 then return {};
    S := ring Fs_0;
    G1 := select(G, s -> s vars S != vars S); -- remove the identity element if present.
    L := new MutableList from Fs;
    LH := hashTable for i from 0 to #Fs-1 list Fs#i => i;
    count := #L;
    if debugLevel > 0 then << "-- " << #L << " ideals" << endl;

    ans := for i from 0 to #L-1 list (
        if L#i === null then continue;
        F := L#i;
        for f in G1 do (
            H := monomialIdeal(f F);
            if LH#?H then (
                j := LH#H;
                if j > i and L#j =!= null then (
                    L#j = null;
                    count = count - 1;
                    if count % 1000 == 0 and debugLevel > 0 then
                        << "--  remaining count: " << count << endl;
                    );
                );
            );
        F
        )
    )

orbitRepresentatives(Ring, Ideal, VisibleList) := List => o -> (R, I, degs) -> (
    if not isMonomialIdeal I then error"orbitRepresentatives:arg 1 is not a monomial ideal";
    if #degs >1 then  degs = sort toList(degs); -- more efficient to add the small degree gens first.

    n := numgens R;
    G := permutations n;

    result := {toLis monomialIdeal I}; --if I = 0, this gives {{}} ; has to be treated specially
    for d in degs do( 
        mons := monomialsInDegreeLis(d, R, o.MonomialType);
	sumList := sumMonomialsLis(result, mons);
	result = normalFormsLis(sumList, G);
    	);
     result/(L -> fromLis(R,L))
    )

orbitRepresentatives(Ring, VisibleList) := List => o -> (R, degs) -> (
    ze := monomialIdeal 0_R;
    orbitRepresentatives(R, ze, degs, o)
    )

orbitRepresentatives(Ring, Ideal, Ideal, ZZ) := List => o -> (R, I, startmons, numelts) -> (
     --take or subtract numelts elements from startmons mod I, plus I.
    if not isMonomialIdeal I then error"orbitRepresentatives:arg 1 is not a monomial ideal";
    I = monomialIdeal I;
    if not isMonomialIdeal startmons then error"orbitRepresentatives:arg 2 is not a monomial ideal";
    startmons = monomialIdeal startmons;

    n := numgens R;
    G := permutations n;

    num := abs(numelts);

    Ilis := if I == 0 then {} else toLis monomialIdeal I;
    startLis := toLis monomialIdeal startmons;
    start := if Ilis ==={} then startLis else
             for m in startLis list if notIn(m,Ilis) then m else continue;

   result := {Ilis}; --if I = 0, this gives {{}} ; has to be treated specially   
   mons := start;

   apply(num, i-> (
	sums := sumMonomialsLis(result, mons);
	result = normalFormsLis(sums, G)
        ));
   result = apply(result, L -> fromLis(R,L));

   --case of subtraction:
   if numelts < 0 then(
       bigideal := fromLis(R, Ilis|start);
       result = for K in result list(I + (bigideal - K))
    );
result)

msolveEliminate(Ideal,        List) := Ideal => opts -> (I0, elimvars) -> (
    -- turns generators into indices, but also allows indices
    elimIndices := monoidIndices(S0 := ring I0, elimvars);
    keepvars := S0_* - set S0_*_elimIndices;
    -- gives ring maps to and from a ring with elimvars first, keepvars last
    (toS0', toS0) := eliminationRing(elimIndices, S0);
    (S, K, I) := toMsolveRing(I' := toS0' I0);
    mOut := msolve(S, K, I_*, "-g 2 -e " | length elimIndices, opts);
    S' := if char K === 0
    then K(monoid [keepvars]) -- msolve does not return the remaining generators over QQ
    else newRing(ring I', MonomialOrder => {#elimvars, #keepvars}); -- but over ZZ/p it does
    ideal readMsolveOutputFile(S', mOut))

msolveGB Ideal := opts -> I0 -> (
    (S, K, I) := toMsolveRing I0;
    mOut := msolve(S, K, I_*, "-g 2", opts);
    gens forceGB readMsolveOutputFile(ring I0, mOut))

msolveLeadMonomials Ideal := opts -> I0 -> (
    -- TODO: premute the coefficient variables to make this work for tower rings
    S0 := ring I0;
    if numgens S0 =!= S0.numallvars then error "msolveLeadMonomials: unsupported tower ring";
    (S, K, I) := toMsolveRing I0;
    mOut := msolve(S, K, I_*, "-g 1", opts);
    gens forceGB readMsolveOutputFile(ring I0, mOut))

msolveRUR Ideal := opt -> I0 ->(
    S0 := ring I0;
    (S, K, I) := toMsolveRing I0;
    mOut := msolve(S, K, I_*, "-P 2", opt);
    -- format: [dim, [char, nvars, deg, vars, form, [1, [lw, lwp, param]]]]:
    solsp := value readMsolveList get mOut;
    if first solsp != 0 then error "msolveRUR: expected zero dimensional input ideal";
    lc:=(solsp_1)_4;
    l:=sum(numgens S0,i->lc_i*S0_i);
    RUR:= new MutableHashTable;
    T:= getSymbol("T");
    S2 := K(monoid[T]);
    T=first gens S2;
    RUR#"T"=l;
    RUR#"var"=T;
    RUR#"degree"=(solsp_1)_2;
    para:= ((solsp_1)_5)_1;
    sVarsMsolve:=(solsp_1)_3;
    W:=sum((para_0)_0+1,i->(T)^i*(((para_0)_1)_i));
    RUR#"findRootsUniPoly"=W;
    RUR#"denominator"=diff(T,W);
    vs:=last para;
    msolveVarOrder:=for sg in gens(S) list position(sVarsMsolve,i->i==toString(sg));
    tempNumerator:=(append(for f in vs list sum((f_0)_0+1,i->T^i*((f_0)_1)_i),-T*diff(T,W)));
    if (numgens(S)==#(tempNumerator)) then(
	RUR#"numerator"=tempNumerator_msolveVarOrder;
	)
    else(
	RUR#"numerator"=tempNumerator_(append(msolveVarOrder, numgens(S)));
	);
    return new HashTable from RUR;
    );

msolveRealSolutions(Ideal, Ring)       := opt -> (I0, F) -> (
    if not any({QQ, QQi, RR_*, RRi_*}, F' -> ancestor(F', F))
    then error "msolveRealSolutions: expected target field to be rationals, reals, or a rational or real interval field";
    (S, K, I) := toMsolveRing I0;
    -- if precision is not specified, we want to use msolve's default precision
    prec := if precision F === infinity then msolveDefaultPrecision else precision F;
    mOut := msolve(S, K, I_*, "-p " | prec, opt);
    -- format: [dim, [numlists, [ solution boxes ]]] when zero-dimensional, otherwise [1?, numgens, -1, []]
    mSeq := toSequence value readMsolveList get mOut;
    d := mSeq#0;
    if d =!= 0 then error "msolveRealSolutions: expected zero dimensional system of equations";
    solsp := mSeq#1;
    if solsp_0 > 1 then (
	printerr "msolveRealSolutions: unexpected msolve output, returning full output"; return {d, solsp});
    prec  = max(defaultPrecision, prec); -- we want the output precision to be at least defaultPrecision
    sols := apply(last solsp, sol -> apply(sol, QQinterval));
    if ancestor(QQi,   F) then sols else
    if ancestor(QQ,    F) then apply(sols, sol -> apply(sol, midpoint'))                    else
    if ancestor(RR_*,  F) then apply(sols, sol -> apply(sol, midpoint') * numeric(prec, 1)) else
    if ancestor(RRi_*, F) then apply(sols, sol -> apply(sol, range -> interval(range, Precision => prec))))

msolveSaturate(Ideal, RingElement) := opts -> (I0, f0) -> (
    (S, K, I) := toMsolveRing I0;
    f := substitute(f0, vars S);
    -- see https://github.com/algebraic-solving/msolve/issues/165
    if char K < 2^16 or 2^31 < char K then error "msolveSaturate: expected characteristic between 2^16 and 2^31 for F4SAT";
    -- msolve expects a list of the generators of the ideal followed by f
    mOut := msolve(S, K, I_* | {f}, "-S -g 2", opts);
    gens forceGB readMsolveOutputFile(ring I0, mOut))

Hm1Rees0(Ideal) := (I) -> (
    checkSingleGraded(I);

    localHm1Rees0 RgradRees I 
)

degreeOfMapIter(Ideal, ZZ) := (I, nsteps) -> (
    grading := checkMultiGraded(I);
    r := (sum grading) - (length grading);
    S := specialFiber I;

    -- if the map is not genericaly finite, then return 0   
    if (dim S) - 1 < r then return 0;

    satFib := satSpecialFiber(I, nsteps);
    N := numerator reduceHilbert hilbertSeries satFib;
    mult := sub(N, { (vars ring N)_(0,0) => 1 });
    degIm := degree S;

    mult // degIm
)

gensSatSpecialFib(Ideal, ZZ) := (I, nsteps) -> (    
    checkMultiGraded(I);
    d := degree (gens I)_(0,0);
    NN := getIrrelevantIdeal ring I;
    satIpow := saturate(I, NN);
    tot := flatten entries super basis(d, satIpow);
    L := { ideal tot };

    for i from 2 to nsteps do (
        satIpow = saturate(I * satIpow, NN);
   	curr := ideal image super basis(i*d, satIpow);

	-- delete those that can be also obtained by multiplication of lower graded parts
	toDel := ideal();
	for j from 1 to i - 1 do toDel = toDel + (L_(j-1) * L_(i-j-1));
	toAdd := flatten entries mingens (curr / toDel);

        tot = join(tot, toAdd);
        L = append(L, curr);
    );

    tot
)

gensSatSpecialFib(Ideal) := (I) -> (
    checkSingleGraded(I);
    nsteps := max flatten degrees Hm1Rees0 I;-- degree of the generators of Hm1Rees0
    nsteps = max(nsteps, 1);  -- degree of the generators of S

    gensSatSpecialFib(I, nsteps)
)

isBiratMap(Ideal) := (I) -> (    
    grading := checkMultiGraded(I);

    r := (sum grading) - (length grading);
    JDR := jacobianDualRank I;

    (JDR == r)
)

jacobianDualRank(Ideal) := (I) -> (
    checkMultiGraded(I);
    ReesEq := RgradRees(I); -- equations of Rees(I)
    AA := ring ReesEq;
    m := length (getGrading ring I)_0;

    -- computes the total Jacobian dual matrix
    L := select(flatten entries gens ReesEq, f -> sum(m, j -> (degree f)_j) == 1);
    if L == {} then return 0;
    M := jacobian matrix{L};    

    --coordinate ring of the image
    mm := ideal vars AA;
    S := AA / (mm + ReesEq);

    -- computes the total Jacobian dual rank  
    rank (M ** S)	   
)

partialJDRs(Ideal) := (I) -> (
    grading := checkMultiGraded(I);
    R := ring I;
    m := length grading;
    ReesEq := RgradRees(I);
    AA := ring ReesEq;
    gensRees := flatten entries gens ReesEq;

    -- coordinate ring of the image   
    mm := ideal vars AA;
    S := AA / (mm + ReesEq);

    JDRs := { };	

    -- compute the JDRs	 
    for i from 1 to m do (
    	deg := toList((i-1):0) | {1} | toList((m-i):0);
        L := select(gensRees, f -> apply(m, j -> (degree f)_j) == deg);
     	if L == {} then JDRs = append(JDRs, 0) 
	else (
	    M := jacobian matrix{L};
	    JDRs = append(JDRs, rank(M ** S));     
     	);    
    );

    JDRs
)

satSpecialFiber(Ideal, ZZ) := (I, nsteps) -> (
    checkMultiGraded(I);
    satFibEq := satSpecialFiberIdeal(I, nsteps);

    (ring satFibEq) / satFibEq
)

satSpecialFiber(Ideal) := (I) -> (
    checkSingleGraded(I);
    nsteps := max flatten degrees Hm1Rees0(I);-- degree of the generators of Hm1Rees0
    nsteps = max(nsteps, 1);  -- degree of the generators of S

    satSpecialFiber(I, nsteps)
)

satSpecialFiberIdeal(Ideal, ZZ) := (I, nsteps) -> (
    checkMultiGraded(I);
    R := ring I;
    d := degree (gens I)_(0,0);

    lGens := gensSatSpecialFib(I, nsteps);
    lDegs := apply(lGens, G -> (degree G)_0 // d_0);

    K := coefficientRing R;	    	
    Z := symbol Z;		
    B := K[Z_1 .. Z_(length lGens), Degrees => lDegs]; 
    F := map(R, B, lGens);

    ker F
)

satSpecialFiberIdeal(Ideal) := (I) -> (
    checkSingleGraded(I);
    nsteps := max flatten degrees Hm1Rees0 I;-- degree of the generators of Hm1Rees0
    nsteps = max(nsteps, 1);  -- degree of the generators of S

    satSpecialFiberIdeal(I, nsteps)
)

upperBoundDegreeSingleGraded(Ideal) := (I) -> (
    checkSingleGraded(I);
    if dim I > 1 then 
           error "The base locus should have dimension zero.";
    d := (degree I_0)_0;
    n := numgens ring I;
    J := saturate(I);
    B := 1 + binomial(d-1,n-1) + hilbertFunction(d,I) - hilbertFunction(d,J);
    for i from 2 to n-2 do B = B + hilbertFunction((n-i)*d-n,I);

    B
)

differentialModule Complex := C -> (
    if C != naiveTruncation(C, -1, 1) then error "--complex needs to be concentrated in homological degrees -1, 0, and 1";
    if C.dd_0 != C.dd_1 then error "--the two differentials of the complex need to be identical";
    if C.dd_0^2 != 0 then error "--differential must square to zero";
    new DifferentialModule from C
    );

differentialModule Matrix := phi -> (
    if phi^2 != 0 then error "The differential does not square to zero.";
    R := ring phi;
    if target phi != source phi then error "source and target of map are not the same"; 
    new DifferentialModule from (complex({-phi,-phi})[1])--the maps are negated to cancel out the sign introduced by the shift.
    );

dualRingToric PolynomialRing := opts -> S ->(
    kk := coefficientRing S;
    degs := null;
    if isSkewCommutative S == false then(
    	degs = apply(degrees S,d-> (-d)|{-1});
	e := opts.SkewVariable;
    	ee := apply(#gens S, i-> e_i);
    	return kk[ee,Degrees=>degs,SkewCommutative=>true, MonomialOrder => Lex]
	); 
    if isSkewCommutative S == true then(
    	degs = apply(degrees S, d-> drop(-d,-1));
	y := opts.Variable;
    	yy := apply(#gens S, i-> y_i);
    	return kk[yy,Degrees=>degs,SkewCommutative=>false]
	);       
    )

foldComplex(Complex,ZZ) := DifferentialModule => (F,d)->(
    R := ring F;
    FDiff := directSum apply(min F .. max F + 1, i -> F.dd_i);
    FMod := directSum apply(min F .. max F, i -> F_i ** R^{i*d});
    degFDiff := map(FMod,FMod,FDiff, Degree=>d); 
    differentialModule(complex({-degFDiff,-degFDiff})[1]) 
    )

minimizeDM(DifferentialModule) := r ->(
    R := ring r;
    d := degree r;
    A := minimizeDiff(r.dd_1);
    degA := map(target A, source A, A, Degree=>d);
    differentialModule (complex({-degA,-degA})[1])
    )

resDM(DifferentialModule,ZZ) := (D,k)->(
    d := degree D;
    R := ring D;
    s := numgens D_0;
    scan(k,i-> D = killingCyclesOneStep(D));
    t := numgens D_0;
    newDiff := submatrix(D.dd_1, toList(s..t-1),toList(s..t-1));
    differentialModule (complex({-newDiff**R^{-d},-newDiff**R^{-d}})[1])
    )

resDM(DifferentialModule) := (D)->(
    k := dim ring D + 1;
    d := degree D;
    R := ring D;
    s := numgens D_0;
    scan(k,i-> D = killingCyclesOneStep(D));
    t := numgens D_0;
    newDiff := submatrix(D.dd_1, toList(s..t-1),toList(s..t-1));
    differentialModule (complex({-newDiff**R^{-d},-newDiff**R^{-d}})[1])
    )

resMinFlag(DifferentialModule, ZZ) := (D, k) -> (
    d := degree D;
    assert(first d == 0);
    R := ring D;
    s := numgens D_0;
    scan(k,i-> D = minFlagOneStep(D));
    t := numgens D_0;
    newDiff := submatrix(D.dd_1, toList(s..t-1),toList(s..t-1));
    differentialModule (complex({-newDiff**R^{-d},-newDiff**R^{-d}})[1])
)

stronglyLinearStrand Module := M -> (
    S := ring M;
    h := heft S;
    if h === null then error("--ring M does not have heft vector");
    if not same degrees M then error("--M needs to be generated in a single degree");
    degM := first degrees M;
    canonical := sum flatten degrees vars S;
    degrange := unique prepend(degM, apply(degrees S, d -> d + degM));
    RM := toricRR(M,degrange);
    mat := RM.dd_0;
    cols := positions(degrees source mat, x -> drop(x,-1) == degM + canonical);
    N := ker mat_cols;
    toricLL N
)

toricLL Module := N -> (
    E := ring N;
    if not isSkewCommutative E then error "ring N is not skew commutative";
    S := dualRingToric E;
    N = coker presentation N;
    bb := basis N;
    b := degrees source bb;
    homDegs := sort unique apply(b, i-> last i);
    inds := new HashTable from apply(homDegs, i-> i=> select(#b, j-> last(b#j) == i));
    sBasis := new HashTable from apply(homDegs, i-> i => bb_(inds#i));
    FF := new HashTable from apply(homDegs, i ->(
	    i => S^(apply((degrees sBasis#i)_1, j-> -drop(j,-1)))
	    )
	);
    EtoS := map(S,E,toList (numgens S:0));
    differential := sum for i to numgens E-1 list (
        S_i* EtoS matrix basis(-infinity, infinity, map(N,N,E_i))
	);
    if #homDegs == 1 then (complex {map(S^0,FF#0,0)})[1] else (
	complex apply(drop(homDegs,-1), i-> map(FF#i,FF#(i+1), (-1)^(homDegs#0)*differential_(inds#(i+1))^(inds#(i))))[-homDegs#0]
	)
    )

toricRR(Module,List) := (N,L) ->(
    M := coker presentation N;
    S := ring M;
    grade := #(degrees S)_0;
    if L === {} then error "--expected non-empty list of degrees";
    if any(L, l -> #l != grade) then error("--expected each multidegree to be of length " | grade); 
    if not isCommutative S then error "--base ring is not commutative";
    if heft S === null then error "--need a heft vector for polynomial ring";
    -- we need to modify L so that the "quotient" differential is well-defined
    L = pickOutMonomials(S,L);
    E := dualRingToric S;
    -- pick out the generators in the selected degree range.
    f0 := matrix {for d in unique L list gens image basis(d,M)};
    -- this is the degree of the anti-canonical bundle, which
    -- we need to twist by when we take the koszul dual.
    wEtwist := append(-sum degrees S, -numgens S);
    -- here are the degrees of the generators we will have in the dual.
    f0degs := apply(degrees source f0, d -> (-d | {0}) + wEtwist);
    if #f0degs == 0 then complex map(E^0, E^0, 0) else (	
    	relationsM := presentation M;
    	SE := S**E;
    	tr := sum(dim S, i-> SE_(dim S+i)*SE_i);
    	newf0 := sub(f0,SE)*tr;
    	relationsMinSE := sub(relationsM,SE);
    	newf0 = newf0 % relationsMinSE;
    	newg := matrixContract(transpose sub(f0,SE), newf0);
	-- null input is to make the map have the correct degrees to be homogeneous.
	newg = transpose map(source newg, , transpose newg);
    	g' := sub(newg,E);
	del := map(E^f0degs,E^f0degs, -g', Degree => degree 1_S | {-1});
	differentialModule(complex({del, del})[1])
    	)
    )

toricRR Module := M -> (
    L := if length M < infinity then unique flatten degrees basis M
    else join(degrees M, apply(degrees ring M, d -> (degrees M)_0 + d));
    toricRR(M,L)
    )

unfold(DifferentialModule,ZZ,ZZ) := Complex => (D,low,high)->(
    L := toList(low..high);
    d := degree D;
    R := ring D;
    phi := differential D;
    (complex apply(L,l-> phi))[-low]
    )

