    d := dim ring I;
    P := NP(I);
    M := halfspaces P;
    Mm := M_0;
    Mv := M_1;
    r := rank target Mm;  --- # of rows
    monj := 0;
    for p from 0 to r-1 do (
    if isBddFacet(p, Mm) then (
