    );
    NumDivIntersect := 0;
    for j from 0 to NumDiv - 1 list( 
       if FracPart_(0,j) == 0 then(
          for k from 0 to NumDiv - 1 list( 
              if IntersectionMatrix_(k,j) == 1 then(
                   if FracPart_(0,k) == 0 then(
                       NumDivIntersect = NumDivIntersect + 1;
                   )else(
                       MultJN = MultJN + FracPart_(0,k);
