methods.source:
differencePointSet (PointSet,PointSet) := o -> (A,B) -> (
    D := new MutableHashTable;
    i := 0; 
    j := 0;
    c := 0;
    while i<#A and j<#B do (
	a := isGEQ(A#i,B#j,Tolerance=>o.Tolerance);
	if not a then (D#c = A#i; i=i+1; c=c+1)
	else (
	    if areEqual(A#i,B#j,Tolerance=>o.Tolerance) then i=i+1;
	    j=j+1;
	    ) 
	);
    if j==#B then for i' from i to #A-1 do (D#c = A#i'; c=c+1);
    new PointSet from D
    )

dualSpace (PolySpace, AbstractPoint) := (S,p)-> (
    assert(numgens ring S.Gens == #coordinates p);
    new DualSpace from {Space=>S,BasePoint=>p}
    )

dualSpace (List, AbstractPoint) := (L, p) -> (
    if #L == 0 then error"expected nonempty list";
    S := ring first L;
    R := coefficientRing S;
    L' := select(L, op -> op != 0);
    gens := matrix{ L' / (op -> matrix op)};
    if #L' == 0 then gens = sub(gens, S);
    dualSpace((map(R,S, vars R)) gens, p)
)

evaluate (Matrix,Matrix) := (M,X) ->  (
    C := coefficientRing ring M;
    RX := ring X;
    commonField := commonRing{1_C, 1_RX};--try promote(1_C, RX) then RX else try promote(1_RX, C) then C else error "common field not found";
    -- work around a sub(CC,QQ) bug!!!
    if instance(ring X, InexactField) then 
	M = toCCpolynomials(M,C=commonField);   
    if numColumns X == 1 then X = transpose X;
    if numRows X == 1 then sub(M,sub(X,C))
    else error "expected a row or a column vector"
    )

evaluate(DiffOp, Matrix) := (D, pt) -> (
    S := ring D;
    R := coefficientRing S;
    (mon, coe) := coefficients D;
    diffOp (mon * evaluate(sub(coe, R) , pt))
)

evaluate (GateSystem,Matrix,Matrix) := (F,p,x) -> (
    if numrows x =!= 1 or numrows p != 1 then "expected a 1-row matrix of values";
    if numVariables F =!= numcols x then error "wrong number of variables values";
    if numParameters F =!= numcols p then error "wrong number of parameter values";
    evaluate(F#"SLP", matrix p | matrix x)
    )

evaluate(SLProgram, Matrix) := (slp, inp) -> (
		I := mutableMatrix inp;
		O := mutableMatrix(ring I, 1, numberOfOutputs slp);
		evaluate(slp,I,O);
		matrix O
		)

evaluate(InterpretedSLProgram, MutableMatrix, MutableMatrix) := (slp,I,O) -> (
		--if numrows I =!= 1 or numrows O =!= 1 then error "expected matrices with 1 row";
		if numrows I * numcols I =!= slp#"number of inputs" then error "wrong number of inputs";
		if numrows O * numcols O =!= slp#"number of outputs" then error "wrong number of outputs";
		K := ring I; 
    if ring O =!= K then error "expected same Ring for input and output";
    rawSLEvaluatorEvaluate(rawSLEvaluatorK(slp,K), raw I, raw O);
    )

evaluate(CompiledSLProgram, MutableMatrix, MutableMatrix) := (slp,I,O) -> (
		--if numrows I =!= 1 or numrows O =!= 1 then error "expected matrices with 1 row";
		if numrows I * numcols I =!= #(slp#"input") then error "wrong number of inputs";
		if numrows O * numcols O =!= #(slp#"output") then error "wrong number of outputs";
		K := ring I; 
    if ring O =!= K then error "expected same Ring for input and output";
