     )

generalEquations WitnessSet := (W) -> (
     R := ring W;
     n := numgens R;
     d := dim W;
     ngens := numgens ideal W;
     if ngens === n-d then W
     else (
	  -- take random combinations of the equations
	  neweqns := (generators ideal W) * random(R^ngens, R^(n-d));
	  witnessSet(ideal neweqns, slice W, points W))
     )

isGEQ(List,List) := o->(t,s)-> (
     n := #t;
     for i from 0 to n-1 do ( 
	  if not areEqual(t#i,s#i, Tolerance=>o.Tolerance) 
	  then 
	  if abs(realPart t#i - realPart s#i) < o.Tolerance then 
	  return imaginaryPart t#i > imaginaryPart s#i
	  else return realPart t#i > realPart s#i
	  ); 
     true -- if approx. equal 
     )

numParameters PolySystem := P -> (
    C := coefficientRing ring P;
    if instance(C,PolynomialRing) then numgens C else 0
    )

numericalAffineSpace PolynomialRing := R -> (
    n := numgens R;
    C := coefficientRing R; 
    A := random(C^n,C^n);
    b := random(C^n,C^1);
    W := witnessSet(ideal R, A|(-b), {point entries transpose solve(A,b)});
    declareIrreducible W;
    numericalVariety {W}
    )

numericalVariety List := Ws -> if #Ws==0 then new NumericalVariety else (
     T := class first Ws;
     if not ancestor(WitnessSet,T) then error "a list of WitnessSet-s expected";
     V := new NumericalVariety;
     scan(Ws, W->(
	     if class W =!= T then error "a list of witness sets of same type expected";
	     d := dim W;
	     if V#?d then V#d = V#d | {W} else V#d = {W};
	     ));     
     check V;
     V
     )

parameters PolySystem := P -> (
    C := coefficientRing ring P;
    if instance(C,PolynomialRing) then gens C else {}
    )

point (List,CacheTable) := (c,h) -> new Point from {
    Coordinates=>prepareCoordinates c,
    cache => copy h
    }

pointSet Thing := L -> (
    if not instance(L,List) and not instance(L,Set) then error "a list/set is expected"; 
    LL := toList L;
    if not all(LL, x->instance(x,AbstractPoint)) then error "a list/set of Points is expected"; 
    S := solutionsWithMultiplicity LL;
    new PointSet from apply(#S, i->((S#i).cache.Multiplicity=1; i=>S#i))	 
    )

polySpace Matrix := o -> M -> (
    assert(numrows M == 1);
    new PolySpace from {Gens=>M,Reduced=>o.Reduced}
    )

polySystem List := L -> (
    if not instance(commonRing L,PolynomialRing) then error "expected a list of polynomials";
    polySystem transpose matrix {L} 
    )

polySystem Matrix := M -> (
    if not instance(ring M,PolynomialRing) then error "expected a matrix of polynomials";    
    if numcols M != 1 then error "expected a matrix with 1 column";
    new PolySystem from {PolyMap=>M, NumberOfVariables=>numgens ring M, NumberOfPolys=>numrows M}
    )

polySystem(GateSystem, PolynomialRing) := (G,R) -> (
    -- check that the ring is of form K[x] or K[y][x] !!!
    C := coefficientRing R;
    if numgens R != numVariables G then error "numbers of variables don't match";
    if numgens C != numParameters G then error "numbers of parameters don't match";
    polySystem transpose evaluate(G, vars C, vars R)
    )

polySystem WitnessSet := W->if W.cache.?SolutionSystem then W.cache.SolutionSystem else 
    W.cache.SolutionSystem = polySystem(
    	n := #equations W;
    	R := ring W;
    	m := codim W;
	if m == n then W.Equations else (
    	    M := sub(randomOrthonormalRows(m,n),coefficientRing R);
    	    sub(M,ring W) * transpose matrix{equations W}
	    )
    	)

project (Point,ZZ) := (p,n) -> (
    p' := point { take(coordinates p, n) };
    if p.cache.?ErrorBoundEstimate then p'.cache.ErrorBoundEstimate = p.cache.ErrorBoundEstimate;
    p'
    )

reduceSpace PolySpace := o -> S -> (
    if dim S == 0 then return polySpace(gens S,Reduced=>true);
    (mons,coefs) := coefficients(gens S, Monomials => o.Monomials);
    M := mons*(colReduce(coefs,Reverse=>true,Tolerance=>o.Tolerance));
    polySpace(M,Reduced=>true)
    )

slice WitnessSet := (W) -> ( 
    --if class W.Slice === List then W.Slice
    --else 
    if class W.Slice === Matrix then (
	if class W === ProjectiveWitnessSet 
	then projectiveSliceEquations(W.Slice, ring W)
	else sliceEquations(W.Slice, ring W)
	)
    else error "ill-formed slice in WitnessSet" )

sortSolutions List := o -> sols -> (
-- sorts numerical solutions     
     if #sols == 0 then (
	 sorted := {};
	 sols
	 )
     else (
     	 if o.Weights =!= null then return sortSolutionsWithWeights(sols,o.Weights);
	 sorted = {0};
	 get'coordinates := sol -> if class sol === Point then coordinates sol else 
	     if ancestor(BasicList, class sol) then toList sol
	     else error "expected Points or BasicLists";
	 scan(#sols-1, s->(
		    -- find the first element that is "larger";
		    -- "larger" means the first coord that is not (approx.) equal 
		    -- has (significantly) larger realPart, if tie then larger imaginaryPart
		    --l := position(sorted, t->isGEQ(first t, first s));
     	       	    s = s + 1;
		    t := get'coordinates sols#s;
		    l := 0; r := #sorted-1;
		    if isGEQ(t, get'coordinates sols#(sorted#r)) then  sorted = sorted | {s}
		    else if isGEQ(get'coordinates sols#(sorted#l),t) then  sorted = {s} | sorted 
		    else (
		    	 while r-l>0 do (
			      m := (l+r)//2;
			      if isGEQ(get'coordinates sols#(sorted#m), t) then r=m
			      else l=m+1; 
			      );
		    	 sorted = take(sorted,r) | {s} | drop(sorted,r);
		    	 )
		    ));      
	  );
     apply(sorted, i->sols#i)
     )

toAffineChart (ZZ,List) := List => (k,x) -> (
     if k<0 or k>#x then error "chart number is out of range ";
     if x#k == 0 then return infinity;
     y := apply(x, c->c/x#k);
     take(y,k) | drop(y,k+1)
     )

unionPointSet (PointSet,PointSet) := o -> (A,B) -> (
    S := solutionsWithMultiplicity(values A | values B, Tolerance=>o.Tolerance); 
    new PointSet from apply(#S, i->((S#i).cache.Multiplicity=1; i=>S#i))	 
    )

witnessSet (Ideal,ZZ) := (I,d) -> ( -- assume: dim I == d
     R := ring I;
     n := numgens R;
     F := if numgens I == n-d then I_* else (
     	 RM := (randomUnitaryMatrix numgens I)^(toList(0..n-d-1));
     	 RM = promote(RM,ring I);
     	 flatten entries (RM * transpose gens I) 
	 );
     SM := (randomUnitaryMatrix n)^(toList(0..d-1))|random(CC^d,CC^1);
     S := ideal(promote(SM,R) * ((transpose vars R)||matrix{{1_R}}));
     P := solveSystem(F | S_*);
     w'points := if numgens I == n-d then P else select(P, p->isOn(p,I));
     witnessSet(ideal F, SM, w'points)
     )

assignDegrees NCMatrix := M -> (
   rowsM := #(M.matrix);
   colsM := #(first M.matrix);
   if rowsM == 0 or colsM == 0 then error "Use assignDegrees(NCMatrix, List, List) to change degrees of maps to/from the zero module.";
   sourceDeg := toList (colsM:0);
   targetDeg := toList (rowsM:0);
   entriesM := select(flatten entries M, f -> f != 0);
   -- if the zero matrix or entries not homogeneous, then just assign zero degrees.
   if entriesM == {} or any(entriesM, f -> not isHomogeneous f) then
      return assignDegrees(M,targetDeg,sourceDeg);
   colDegs := apply(transpose M.matrix, col -> unique apply(select(col, f -> f != 0), f -> degree f));
   if not all(colDegs, coldeg -> #coldeg == 1) then
      return assignDegrees(M,targetDeg,sourceDeg);
   sourceDeg = apply(colDegs, coldeg -> if coldeg == {} then 0 else first coldeg);
   -- assign the degrees
   assignDegrees(M,targetDeg,sourceDeg);
   -- set the isHomogeneous flag
   setIsHomogeneous M;
   -- for matrices that are not homogeneous with these degrees, the user may use assignDegrees
   -- below.  An attempt to find a (nontrivial) set of degrees for which the map is homogeneous requires
   -- integer programming.  I may implement this in the future.
   M
)

assignDegrees (NCMatrix, List, List) := (M,targetDeg,sourceDeg) -> (
   -- this function is for manual assignment of degrees
   -- it's also called by the method trying to assign degrees automatically
   -- this means an input matrix may not have "source" and "target" keys
   -- but it will if it's a map to the zero module
   if (#(targetDeg) != #(entries M)) then error "Target degree list does not match number of rows of matrix";
   if #(entries M) !=0 and (#(sourceDeg) != #(first entries M)) then error "Source degree list does not match number of columns of matrix";   
   if #(entries M) == 0 and (#(sourceDeg) != #(M.source)) then error "Source degree list does not match number of columns of matrix";
   M#(symbol source) = sourceDeg;
   M#(symbol target) = targetDeg;
   -- set the isHomogeneous flag.
   setIsHomogeneous M;
   M
)

centralElements(NCRing,ZZ) := (B,n) -> (
   idB := ncMap(B,B,gens B);
   normalElements(idB,n)
)

coordinates List := opts -> L -> (
   if opts#Basis === null then
      sparseCoeffs L
   else
      bas := opts#Basis;
      R := ring bas#0;
      firstNonzero := select(1,bas,b -> b != 0);
      d := if firstNonzero == {} then 0 else degree first firstNonzero;
      if not all(L, m-> (isHomogeneous(m) and ((degree m) == d or m == 0))) then
	error "Expected homogeneous elements of the same degree.";
      mons := flatten entries basis(d,R);
      M := sparseCoeffs(bas, Monomials=>mons);
      N := sparseCoeffs(L, Monomials=>mons);
      if rank (M|N) != rank M then error "Expected elements in the span of given basis.";
      I := id_(target M);
      T := I // M;
      T*N
)

endomorphismRing (Module,Symbol) := (M,X) -> (
   R := ring M;
   endM := End M;
   N := numgens endM;
   gensEndMaps := apply(N, i -> homomorphism endM_{i});
   W := coker relations endM;
   gensEndM := map(W,source gens endM,gens endM);
   endMVars := apply(N, i -> X_i);
   A := R endMVars;
   gensA := basis(1,A);
   -- build the squarefree relations
   twoSubsets := subsets(N,2);
   mons := twoSubsets | (twoSubsets / reverse) | apply(N, i -> {i,i});
   relsHomM := getHomRelations(gensA,gensEndM,mons,gensEndMaps);
   -- should now make some attempt at finding a minimal set of algebra generators
   I := ncIdeal relsHomM;
   Igb := ncGroebnerBasis(I,InstallGB=>true);
   B := A/I;
   B.cache#(symbol endomorphismRingGens) = gensEndMaps;
   B
)

envelopingAlgebra (NCRing, Symbol) := (A,x) -> (
   --  want to add an option to index op variables by number rather than a ring element?
   R := coefficientRing A;
   Aop := oppositeRing A;
   B := R apply(#gens A, g-> x_g);  -- remove # once indexing works without printing ( ) 
   if class A === NCPolynomialRing then (A ** B) 
   else (
      A' := ambient Aop;   
      f := ncMap(B,A',gens B);
      J := ncIdeal (gens ideal Aop / f);
      A ** (B/J)
   )
)

fourDimSklyanin (Ring, List, List) := opts -> (R, params, varList) -> (
   if #params != 3 or #varList != 4 then error "Expected three parameters and four variables.";
   if instance(varList#0, R) or instance(varList#0,ZZ) or instance(varList#0,QQ) then
      error "Expected list of variables in third argument.";
   A := R varList;
   gensA := gens A;
   varList = gens A;
   f1 := (varList#0*varList#1 - varList#1*varList#0) - params#0*(varList#2*varList#3 + varList#3*varList#2);
   f2 := (varList#0*varList#2 - varList#2*varList#0) - params#1*(varList#3*varList#1 + varList#1*varList#3);
   f3 := (varList#0*varList#3 - varList#3*varList#0) - params#2*(varList#1*varList#2 + varList#2*varList#1);
   g1 := (varList#0*varList#1 + varList#1*varList#0) - (varList#2*varList#3 - varList#3*varList#2);
   g2 := (varList#0*varList#2 + varList#2*varList#0) - (varList#3*varList#1 - varList#1*varList#3);
   g3 := (varList#0*varList#3 + varList#3*varList#0) - (varList#1*varList#2 - varList#2*varList#1);

   I := ncIdeal {f1,f2,f3,g1,g2,g3};
   installGB := not (A#BergmanRing or bergmanCoefficientRing gens I =!= null);
   Igb := ncGroebnerBasis(I, InstallGB=>installGB, DegreeLimit=>opts#DegreeLimit);
   B := A/I;
   B
)

fourDimSklyanin (Ring, List) := opts -> (R, varList) -> (
   if char R != 0 and char R < 100 then error "For random Sklyanin, QQ coefficients or characteristic larger than 100 are required.";
   --- generate a generic four dimensional Sklyanin that is AS regular
   alpha := random(QQ);
   while (alpha == 0) do alpha = random(QQ);
   beta := random(QQ);
   while (beta == 0 or (1 + alpha*beta) == 0) do beta = random(QQ);
   gamma := (-alpha-beta)/(1 + alpha*beta);
   fourDimSklyanin(R,{alpha,beta,gamma}, varList)
)

freeProduct (NCRing,NCRing) := (A,B) -> (
   R := coefficientRing A;
   if R =!= (coefficientRing B) then error "Input rings must have same coefficient ring.";
   gensA := gens A;
   gensB := gens B;
   newgens := gensA | gensB;     
   if #unique(newgens) != (#gensA + #gensB) then error "Input rings have a common generator.";

   I := gens ideal A;
   J := gens ideal B;

   A' := if class A === NCPolynomialRing then A else ambient A;
   B' := if class B === NCPolynomialRing then B else ambient B;

   C := R newgens;
   gensAinC := take(gens C, #gensA);
   gensBinC := drop(gens C, #gensA);
   incA := ncMap(C,A',gensAinC);
   incB := ncMap(C,B',gensBinC);
   IinC := I / incA;
   JinC := J / incB;
   newIdealGens := select( (IinC | JinC), x -> x!=0);       
   if newIdealGens == {} then C 
   else C/(ncIdeal newIdealGens)
)

