torsionOrder(ZZ, Ideal) := (ZZ, Ideal) => opts -> (n1, I1) -> (
    i := 1;
    local curIdeal;
    while (i < n1) do (
        curIdeal = reflexivePower(i, I1);
        if isInvertibleIdeal(curIdeal) then return (i, curIdeal);        
        i = i+1;
    );
