rmNmzFiles = () -> (
    suffixes := {"in","gen","out","sup","egn","esp","inv","tri","typ","ht1","ext","cst","tgn","lat","mod","dec"};
    checkNmzFile("rmNmzFiles");
    for s in suffixes do if fileExists(nmzFile | "." | s) then removeFile(nmzFile | "." | s);
    nmzFilename = "");

