		ResidualTolerance=>DEFAULT.ResidualTolerance*LARGE,
		Software=>o.Software);
	    regPoints := select(refinedPoints, p->p.cache.SolutionStatus===Regular);
	    singPoints := select(refinedPoints, p->p.cache.SolutionStatus===Singular);
	    targetPoints = if o.Output == Regular then regPoints else regPoints | solutionsWithMultiplicity singPoints;
	    if DBG>2 then << "( regeneration: " << net cOut << " meets V(f) at " 
	    << #targetPoints << " points for" << endl 
	    << "  f = " << f << " )" << endl;
	    f' := ideal (equations comp | {f});
	    nonJunkPoints := select(targetPoints, p-> not isPointOnAnyComponent(p,c2)); -- this is very slow		    
	    scan(partitionViaDeflationSequence(nonJunkPoints,T),
		pts -> (
		    newW := witnessSet(f',slice',selectUnique(pts, Tolerance=>1e-4));--!!!
		    if DBG>2 then << "   new component " << peek newW << endl;
		    check newW;    
		    insertComponent(newW,c2);
		    )
		)
	    ) 
	);
    	numericalVariety flatten apply(keys c2, i->apply(keys c2#i, j->c2#i#j))
    )

isOn (AbstractPoint,NumericalVariety) := o -> (p, V) -> (
    o = fillInDefaultOptions o;
    if o.Software === BERTINI then #bertiniComponentMemberTest({p},V)>0
    else any(keys V, d->any(V#d, C->isOn(p,C,o)))  
    )

isOn (AbstractPoint,WitnessSet) := o -> (p, W) -> (
    o = fillInDefaultOptions o;
    if # coordinates p != numgens ring W 
    then if W.cache.?ProjectionDimension then isOn(p,W,W.ProjectionDimension,o) 
    else error "numbers of coordinates mismatch";
    --if o.Software === BERTINI then bertiniComponentMemberTest(numericalWariety {W},{p})
    --else 
    (
	R := ring W.Equations;
	C := coefficientRing R;
	W' := moveSlice(W, randomSlice(dim W, numgens R, C, p));
	any(W'.Points, p'->areEqual(p',p))
	)
    )

isOn (AbstractPoint,WitnessSet,ZZ) := o -> (p, W, m) -> (
    o = fillInDefaultOptions o;
    if # coordinates p != m then error "wrong number of coordinates",
    R := ring W.Equations;                    
    C := coefficientRing R;
    n := numgens R;
    rows := toList (0..dim W - 1);
    M := ((map C^n)^m || random(C^(n-m),C^n))^rows;
    mp := transpose (matrix p | random(C^1,C^(n-m)));
    W' := moveSlice(W, M | -M*mp);
    any(W'.Points, p'->areEqual(project(p',m),p))
    )

isSolution(AbstractPoint,PolySystem) := o -> (P,F) -> (
    o = fillInDefaultOptions o;
    -- P = newton(F,P); -- !!! change for non regular
    -- P.ErrorBoundEstimate < o.Tolerance
    residual(F,P) < o.Tolerance
    )

liftPointToDeflation (AbstractPoint,PolySystem,ZZ) := (P,F,r) -> (
    if F.NumberOfVariables == (F.Deflation#r).NumberOfVariables then P
    else (
    	A := evaluate(jacobian F, P)*(F.DeflationRandomMatrix#r);
    	last'column := numColumns A-1; 
    	point {
	    coordinates P | 
	    flatten entries solve(submatrix'(A,{last'column}),-submatrix(A,{last'column}),ClosestFit=>true)
	    }
	) 
    )

newton (System, AbstractPoint) := (F,P) -> (
    X := transpose matrix P;
    valueJ := evaluateJacobian(F,P);
    dX := if isSquare F then solve(valueJ, evaluate(F,P))
    else if numVariables F < numFunctions F then solve(valueJ, evaluate(F,X), ClosestFit=>true)
    else ( -- underdetermined
	M := valueJ;
	(S,U,Vt) := SVD M;
	invJ := conjugate transpose Vt *
	        diagonalMatrix(numColumns M, numRows M, apply(S, s->if s==0 then 0 else 1/s)) * 
		conjugate transpose U; -- pseudo-inverse
	invJ*evaluate(F,X) 
	); 
    X':=X-dX;
    P' := point X';
    P'.cache.ErrorBoundEstimate = norm(X'-X);
    P'
    )

numericalIntersection (NumericalVariety, Ideal) := (V,I) -> (
    W := new NumericalVariety from V;
    for f in I_* do W = hypersurfaceSection(W,f);
    W
    )

numericalIntersection (WitnessSet,WitnessSet) := (W1,W2) -> (
    R := ring W1;
    if R =!= ring W2
    then error "expected witness sets in the same ambient space";
    y := symbol y;
    n := numgens R;
    S := (coefficientRing R) monoid([gens R, y_1..y_n]);
    x := take(gens S,n);
    y = take(gens S,-n);
    toSx := map(S,R,x);
    toSy := map(S,R,y);
    W12 := witnessSet(toSx ideal equations W1 + toSy ideal equations W2, 
	toSx ideal slice W1 + toSy ideal slice W2,
	flatten apply(W1.Points, P1->apply(W2.Points, P2-> 
		point {coordinates P1 | coordinates P2}
		))
	);
    numericalIntersection(
	numericalVariety {moveSlice(W12,randomSlice(dim W12, numgens ring W12, coefficientRing ring W12))}, 
	ideal apply(n, i->x#i-y#i)
	)
    )

numericalIntersection (NumericalVariety,NumericalVariety) := (V1,V2) -> (
    V := numericalVariety {};
    for W1 in components V1 do
    for W2 in components V2 do V = V | numericalIntersection(W1,W2);
    V 
    )

numericalIrreducibleDecomposition Ideal := o -> I -> (
    o = fillInDefaultOptions o;   
    ( 
	if o.Software === BERTINI 
    	then numericalIrreducibleDecompositionBertini 
    	else if o.Software === PHCPACK 
    	then numericalIrreducibleDecompositionPHCpack 
    	else if member(o.Software,{M2,M2engine})  
	then numericalIrreducibleDecompositionM2
    	else error "allowed values for Software: M2engine, M2, BERTINI, PHCPACK"
    	) (I,o)
    )

parameterHomotopy (List, List, List) := o -> (F, P, T) -> (
    o = fillInDefaultOptions o;
    if o.Software === BERTINI then bertiniParameterHomotopy(F,P,T)
    else error "not implemented"
    )

parametricSegmentHomotopy GateSystem := F -> (
    V := flatten entries vars F;
    W := flatten entries parameters F;
    A := matrix{apply(W, w->inputGate symbol A_w)};
    B := matrix{apply(W, w->inputGate symbol B_w)};
    t := inputGate symbol t;
    H := sub(gateMatrix F,matrix{W},(1-t)*A+t*B);
    gateHomotopy(H,matrix{V},t,Parameters=>A|B)
    )

randomInitialPair List := T -> (
-- for a homogeneous system constructs a start system and one root 
-- IN:  T = list of polynomials 
-- OUT: (S,solsS}, where 
--      S     = list of polynomials, 
--      solsS = list of sequences
     R := commonRing T;
     n := numgens R - 1; 
     Ml := flatten entries randomInComplexUnitBall dimHd(T/first@@degree);
     M := map(CC^n, n+1, (i,j)->Ml#((n+1)*i+j)); -- n by n+1 matrix formed from n^2+n (first) entries of Ml    
     coord'transform := last SVD M;
     --oMl := flatten entries randomInComplexUnitBall (dimHd(T/first@@degree)-n);
     --M := map(CC^n,CC^1,0) | map(CC^n, n, (i,j)->oMl#(n*i+j)); -- 0-column | n by n matrix formed from n^2 (first) entries of Ml    
     --O := flatten entries randomInComplexUnitSphere((n+1)^2);
     --coord'transform := last SVD map(CC^(n+1), n+1, (i,j)->O#((n+1)*i+j));
     inv'coord'transform := solve(coord'transform, map CC^(n+1));
     coord'change := map(R,R,(vars R) * transpose coord'transform);
     --(good'sys, good'sol) := goodInitialPair(R,T/first@@degree);
     good'sol := transpose matrix{toList (n:0_CC)|{1}};
     sol := inv'coord'transform * good'sol; -- root
     good'sys := transpose matrix{randomHd'NoHighXn(T/first@@degree)};  
     h := coord'change ((map(R,ring good'sys, vars R)) good'sys); 
     ret := sqrt(1-(normF M)^2)*h + diagonalMatrix apply(T,f->(
	       d := sum degree f;
	       (sum(numgens R, i->R_i*conjugate sol_(i,0)))^(d-1) * sqrt d 
	       )) * M * transpose vars R;     
     assert (norm2 sub(ret,transpose sol)<0.0001); -- just a check
     (flatten entries ret, {flatten entries sol})
     )

randomSd List := ds -> (
     n := #ds;
     x := symbol x;
     R := CC_53(monoid [vars(53..n+53)]); 
     sqrt'n := 1/sqrt n;
     u := randomInComplexUnitSphere dimHd ds;     
     i := -1; --counter
     ret := apply(ds,d->sum( 
	       ((ideal gens R)^d)_*, 
	       m->(
	       	    a := first first listForm m; -- exponent vector
	       	    i = i + 1;
     	       	    u_(i,0) * sqrt((sum a)! / product(a, d->d!))*m -- ... * sqrt of multinomial coeff
	       	    )
	       ));
     assert(i+1 == dimHd ds);
     ret          
     );

