	    if DBG > 3 then << "x=" << toString x1 << " res=" <<  Fx << " dx=" << dx << endl;
	    if norm'dx < error'bound then (
	    	x1 = x1 + dx;
	    	--if isProjective then x1 = normalize x1;
	    	nCorrSteps = nCorrSteps + 1;
	    	)
	    else (
	    	if DBG>2 then print "warning: Newton's method correction exceeded the error bound obtained in the previous step"; 
	    	refinement'success = false;
	    	);
	    error'bound = norm'dx; 
	    ) else (
	    refinement'success = false;
	    )
	);
    if refinement'success then (
    	if norm'Fx > o.ResidualTolerance then (
	    if DBG>2 then print "warning: Newton's method did not converge within given residual bound in the given number of steps";
	    refinement'success = false;
	    );
    	if norm'dx > errorTolerance * norm x1 then (
	    if DBG>2 then print "warning: Newton's method did not converge within given error bound in the given number of steps";
	    refinement'success = false;
	    );
	);  
    s' := point { flatten entries x1, 
	SolutionSystem => F, 
	ConditionNumber => conditionNumber evaluate(jacobian F, x1)
	};
    s'.cache.ErrorBoundEstimate = error'bound;
    s'.cache.SolutionStatus = if refinement'success then (
	if s'.cache.ConditionNumber > o.SingularConditionNumber 
	then Singular 
	else Regular
	)
    else (
	if DBG>2 then print "warning: refinement failed";
	RefinementFailure
	);
    s'
    )

refine (PolySystem,List) := List => o -> (F,solsT) -> (
-- refines solutions to solsT of the system F
     o = fillInDefaultOptions o;
     n := F.NumberOfVariables; 
     if n > 0 then (
	 R := ring F;
	 C := coefficientRing R; 
	 )
     else error "expected nonempty target system";
     isProjective := false;
     if n != numgens R then (
	  if numgens R == n+1 and isHomogeneous F 
	  then ( 
	       isProjective = true; 
	       n = n+1;
	       )  
	  else error "expected a square system";
     	  );
     if #solsT == 0 then return solsT;

     if isProjective then (
     	  if o.Software === M2engine then (
	      error "refine is not implemented in the engine yet";
	      ) 
	  else error "refining projective solutions is not implemented yet";
    	  );  
    if o.Software === PHCPACK then return refinePHCpack(equations F,solsT,o)/point 
    else apply(solsT, s->refine(F,    		  
	    if instance(s,AbstractPoint) then s else point {s/toCC},
	    o 
	    ))
    )

refine(SDP,Sequence) := o -> (P,X0y0) -> (
    (X0,y0) := X0y0;
    (J,X,y,Z) := rawCriticalIdeal(P,,true);
    pt := smat2vec entries X0 | flatten entries y0;
    pt' := first refine (polySystem J, {pt}, o);
    if status pt'==RefinementFailure then(
        print "refinement failed";
        return (X0,y0) );
    L := coordinates pt';
    m := numColumns y0;
    X1 := matrix vec2smat drop(L,-m);
    y1 := matrix transpose {take(L,-m)};
    (X1,y1))

regeneration List := List => o -> F -> (
-- solves a system of polynomial Equations via regeneration     
-- IN:  F = list of polynomials
--      Software => {PHCPACK, BERTINI, hom4ps2}
-- OUT: a NumericalVariety
     o = fillInDefaultOptions o;

     checkCCpolynomials F;
     F = toCCpolynomials(F,53);

     R := ring F#0;
     V := numericalAffineSpace R; -- current solution components
     for f in F do V = hypersurfaceSection(V,f,o); -- intersect with hypersurface	 
     V
     )

removeRedundantComponents NumericalVariety := o -> V -> (
    o = fillInDefaultOptions o;
    scan(rsort keys V, d->(
	Vd := V#d;
	ind := select(#Vd, i->
	    all(components(V,d+1,infinity), W->not isSubset(Vd#i,W))
	    and 
	    all(drop(Vd,i+1), W->not isSubset(Vd#i,W))
	    );
	V#d = Vd_ind;
	))
    )

sample WitnessSet := o -> W -> (
    W' := moveSlice(W, randomSlice(dim W, numgens ring W, coefficientRing ring W));
    p := W'.Points # (random(#W'.Points));
    if not p.?ErrorBoundEstimate or p.ErrorBoundEstimate > o.Tolerance then p = refine(p,ErrorTolerance=>o.Tolerance); 
    if W.cache.?ProjectionDimension then project(p, W.cache.ProjectionDimension)
    else p 
    )

segmentHomotopy (GateSystem, GateSystem) := o -> (S,T) -> (
    if T.Variables =!= S.Variables 
    then error "expected systems with the same inputs";  
    if numFunctions T =!= numFunctions S
    then error "expected systems with the same dimension of codomain";
    t := local t;
    tt := inputGate [t];
    gateHomotopy((1-tt)*gateMatrix S+ o.gamma*tt*gateMatrix T, 
	S.Variables, tt, Strategy=>compress)
    )

segmentHomotopy (PolySystem, PolySystem) := o -> (S,T) -> (
    R := ring T;
    if R =!= ring S then error "systems in the same ring expected";  
    if numFunctions T =!= numFunctions S
    then error "expected systems with the same dimension of codomain";
    t := local t;
    tt := inputGate [t];
    gateHomotopy((1-tt)*gateMatrix S + o.gamma*tt*gateMatrix T, 
	gateMatrix{getVarGates R}, tt, Strategy=>compress)
    )

solveGenericSystemInTorus List := F -> (
    (vol,S,solsS) := mixedVolume(toRingXphc F, StartSystem=>true);
    assert(vol==#solsS);
    (fromRingXphc(S,ring ideal F), solsS)
    )

