specialize (ParameterHomotopy,Matrix) := (PH, M) -> (
    if numcols M != 1 then M = transpose M;
    if numcols M != 1 then error "1-row or 1-column matrix expected"; 
    if numcols PH.Parameters != numrows M then error "wrong number of parameters";  
    SPH := new SpecializedParameterHomotopy;
    SPH.ParameterHomotopy = PH;
    SPH.Parameters = M;
    SPH
    )

specialize (GateSystem, AbstractPoint) := GateSystem => (GS,p) -> (
    if numParameters GS != #coordinates p then error "wrong number of parameter values"; 
    gateSystem(vars GS, sub(gateMatrix GS, gateMatrix matrix p, vars GS))
    )

squareUp (System, ZZ) := o -> (P, n) -> (
    m := numFunctions P;
    if m<=n then "expect more equations than second argument";
    C := if instance(o.Field, Nothing) then (
	if instance(P, PolySystem) then coefficientRing ring P
	else default CC
	) else o.Field;
    if instance(o.Strategy, Nothing) or o.Strategy == "random matrix" then (
    	M := if class C === ComplexField then sub(randomOrthonormalRows(n,m), C) else random(C^n,C^m);
    	squareUp(P,M,o)
	) 
    else if o.Strategy == "slack variables" then error "strategy not implemented"
    else error "strategy not implemented"
    )

squareUp(System, Matrix) := o -> (P, M) -> (
    P.SquareUpMatrix = M;
    P.SquaredUpSystem = if instance(P, PolySystem) then polySystem (M*P.PolyMap) else gateSystem(parameters P, vars P, M * gateMatrix P)
    )

squareUp (AbstractPoint, AbstractPoint, GateSystem) := o -> (p0, x0, F) -> (
    keptRows := rowSelector(p0, x0, F, "block size" => o#"block size", Verbose=>o.Verbose);
    F.SquaredUpSystem = F^keptRows
    )

totalDegreeStartSystem List := Sequence => T -> (
-- constructs a total degree start system and its solutions 
-- for the given target system T
-- IN:  T = list of polynomials 
-- OUT: (S,solsS}, where 
--      S     = list of polynomials, 
--      solsS = list of sequences
     R := commonRing T;
     if any(gens R, x->sum degree x != 1) then error "expected degrees of ring generators to be 1";
     n := #T;
     if n != numgens R then (
	  if numgens R == n+1 and all(T, isHomogeneous) 
	  then isH := true
	  else error "wrong number of polynomials";
	  )
     else isH = false;
     S := apply(n, i->R_i^(sum degree T_i) - (if isH then R_n^(sum degree T_i) else 1) );
     s := apply(n, i->( 
	  d := sum degree T_i; 
	  set apply(d, j->sequence exp(ii*2*pi*j/d))
	  ));
     solsS := first s;
     scan(drop(s,1), t->solsS=solsS**t);
     if numgens R === 1 
     then solsS = toList solsS/(a -> 1:a)
     else solsS = toList solsS/deepSplice; 
     if isH then solsS = solsS / (s->s|sequence 1);
     (S, apply(solsS,s->point{toList s}))
     )

