    c := coordinates p;
    if any(c, i -> imaginaryPart i =!= 0) then (
	matrixCCi{apply(c, i -> 
		intervalCCi(interval((realPart i) - r, (realPart i) + r),
		    interval((imaginaryPart i) - r, (imaginaryPart i) + r)))}
	)
