   if opt.Verbose then stdio << "the number of flags : " << nbr << endl; 
   fixedFlags := extractFixedFlags(dim, nbr, linesf);
   movedFlag := extractMovedFlag(dim, linesf);
   solutionPlanes := extractSolutionPlanes(dim, linesf);
