lyndonShuffle(NCRingElement) := (f) -> ( -- rewrites a tensor as a shuffle polynomial in lyndon words
    d := #(gens ring f);
    k := degree f;
    ly := getSymbol("ly");
    var := new Array from apply(lyndonWords(d,k), i-> ly_i);
    cR := coefficientRing (ring f);
