    -- Output: an Ulrich module of rank r*2^(g-2)

    -- By Riemann-Roch, we need a rank r vector bundle E of degree r(g-2)/2, or a twist by a line bundle
    -- so we are tempting to find a rank r, degree rg/2 vector bundle by extensions of r line bundles.

    Mor := vectorBundleOnE M.evenCenter;
    Mor1:= vectorBundleOnE M.oddCenter;
    f := M.hyperellipticBranchEquation;
    assert(dim ideal jacobian ideal f ==0);

    g:=degree ideal f//2-1;
    if (numgens S != 2*g+4) then error "S should be a polynomial ring in (2g+4) variables";
    if (rank source M.evenCenter != 2^(g+1)) then error "M should be a Clifford module associated to a maximal isotropic subspace";

    if (r <= 1) then error "r should be at least 2";
    if ((r*g)%2 != 0) then error "either r or g should be even";

    m1:=null; m2:= null; m12 := null; 
    Ul:= null; Ul1:= null; V:= null;
    d1 := null; d0:= null;

    d:=g%2;

    -- build up a nondecreasing sequence begin with d, end with d+g, and their sum is an expected degree, and is balanced as possible as it can
    targetSum := (r*g)//2 + d*r;
    degSeq := apply(r, i-> d + floor(g*i/(r-1)));
    delta := targetSum - sum degSeq;
    mutSeq := new MutableList from degSeq;

    -- adjust the sequence
    searchIndex:=1; -- start from the second element
    while (delta > 0) do (
	if (searchIndex >= r-1) then searchIndex=1;
    	if (mutSeq#searchIndex < mutSeq#(searchIndex+1)) then (mutSeq#searchIndex = mutSeq#searchIndex+1; delta=delta-1; searchIndex=1;) else searchIndex=searchIndex+1;
	);

    degSeq=toList mutSeq;
    assert( degSeq#0 == d and degSeq#(r-1) == d+g and (sum degSeq == targetSum));

    while (
	-- build a vector bundle V as extensions of line bundles of degrees in degSeq
	V=randomLineBundle(degSeq#0,f);
	for i from 1 to r-1 do(
	    m1=randomLineBundle(degSeq#i,f); 
	    m12=randomExtension(m1.yAction,V.yAction);
	    V=vectorBundleOnE m12;
	    ); 
	Ul=tensorProduct(Mor,V);
	Ul1=tensorProduct(Mor1,V);
	d0=unique degrees target Ul.yAction;
	d1=unique degrees target Ul1.yAction;

	#d1 >=3 or #d0 >=3) do ();

    Ul = tensorProduct(M,V); -- the heaviest part computing the actions of generators
    M1Ul:=sum(#Ul.oddOperators,i->S_i*sub(Ul.oddOperators_i,S));
    Ulrich := M1Ul^{r*2^g..(2*r)*2^g-1};
    coker map(S^(r*2^g),,Ulrich)
)

tensorProduct(Matrix,Matrix) := (phi,psi) -> (
    --tensor product of sheaves on the hyperell curve y^2 \pm f
    --with f in R
    --represented by giving sheaves on proj R (usually P^1)
    --plus the action phi or psi of the element y
    R := ring phi;
    g := degree ideal ((phi^2)_(0,0))//2 - 1;
    inclusion:=syz(phi**id_(target psi)-(id_(target phi)**psi)); 	
    F:=complex inclusion;
    F1:=F**R^{g+1}; 
    (extend(F1,F,map(F1_0,F_0,(phi**id_(target psi)))))_1
)

tensorProduct(CliffordModule, VectorBundleOnE) := (M,L) -> (
    phi0 := M.evenCenter;
    phi1 := M.oddCenter;
    psi := L.yAction;
    assert((phi0^2)_(0,0)==(psi^2)_(0,0));
    R := ring psi;
    g := degree ideal ((psi^2)_(0,0))//2 - 1;

    inclusion0 := syz(phi0**id_(target psi)-(id_(target phi0)**psi)); 	
    inclusion1 := syz(R^{1}**(phi1**id_(target psi)+(id_(target phi1)**psi))); 	    

    FEven := complex inclusion0;
    FOdd := complex inclusion1;
    Odd' := null;
    Even' := null;
    eOdd := apply(M.oddOperators, Odd->(
	Odd' = map(FEven_0, R^{-g-1}**FOdd_0, R^{-g-1}**Odd**id_(target psi));
	(extend(FEven,R^{-g-1}**FOdd, Odd'))_1));

    eEv := apply(M.evenOperators, Even->(
	Even' = map(FOdd_0, R^{-g-1}**FEven_0, R^{-g-1}**Even**id_(target psi));
	(extend(FOdd,R^{-g-1} ** FEven, Even'))_1));

    assert(symMatrix(eOdd,eEv) == symMatrix(M.oddOperators, M.evenOperators));
    c0 := tensorProduct(phi0, psi);
    c1 := tensorProduct(phi1, psi);
    eOdd = apply(eOdd, e->map(target c0, target c1, e));
    eEv = apply(eEv, e->map(target c1, R^{-1}**target c0, e));
    cliffordModule(eOdd,eEv)
)

translateIsotropicSubspace(CliffordModule, VectorBundleOnE, PolynomialRing) := (M, L, S) -> (
    -- Input:
    -- M, a Clifford Module, corresponding to a maximal isotropic subspace u
    -- L, a degree 0 line bundle on the associated hyperelliptic curve E
    -- S, a polynomial ring kk[x_0..y_(g-1),z_0,z_1,s,t] in (2g+4) variables

    -- Output:
    -- uL, a matrix, presenting a maximal isotropic subspace of the translation of u by L.

    f:=M.hyperellipticBranchEquation;
    g:=(first degree f)//2 - 1;

    if (numgens S != 2*g+4) then error "S should be a polynomial ring in (2g+4) variables";
    if (rank source M.evenCenter != 2^(g+1)) then error "M should be a Clifford module associated to a maximal isotropic subspace";
    if (degOnE L != 0) or (rank source L.yAction != 2) then error "L should be a degree 0 line bundle";
    if (((L.yAction)^2)_(0,0) + (-1)^g*f != 0) then error "L should be a line bundle on E";

    kk:=coefficientRing ring f;
    u:=(vars S)_{0..g-1} | (vars S)_{2*g, 2*g+1};

    M':=tensorProduct(M,L);
    (Mqq1,Mqq2):=cliffordModuleToMatrixFactorization(M',S); -- MF of qq
    qq:=(Mqq1*Mqq2)_(0,0);
    q1:=diff(S_(numgens S-2),qq);
    q2:=diff(S_(numgens S-1),qq);
    S':=(coefficientRing S)[drop (gens S,-2)]; -- ring without s,t
    CI:=S'/ideal (sub(q1,S'), sub(q2,S')); -- complete intersection ring
    resCI:=cliffordModuleToCIResolution (M', S, CI);
    BCI:=betti resCI;

    d:=first last (select (keys BCI, k->BCI_k==1));
    uL:=sub(mingens ideal (resCI.dd_d)_{0}, S);

    assert((dim ideal uL, degree ideal uL) ==(dim ideal u, degree ideal u));
    uL
    )

glynn Matrix := (M) -> (

      n := numgens target M;
      R :=ring(M);

      if char R==2 then error "Glynn's formula requires the coefficient ring to have characteristic other than 2";

      E :=entries M;
      --these are the sums of the rows
      s := new MutableList from {};
      for i from 0 to n-1 do(
	  s=append(s,sum(E#i));
	  );

      perm := 0;

      --Recall that we can list the binary strings of length n in a Gray code order by
      --defining defining a vector delta to be all 0's and counting as usual in binary.
      --Then the ith entry of the current word in the Gray code is delta_i+delta_{i+1},
      --so at the point increment delta below we are searching for the unique index
      --in which the current word in the Gray code changed.

      --initialize delta vector to all 1's
      del := new MutableList from {0};
      --Is there any better way to create a MutableList of length n or is this the only way??
      for i from 1 to n-2 do(del = append(del,0););--delta is of length n-1 because first position is always positive, so we don't consider it in the gray code

      --take the initial product corresponding to delta all +1's
      sgn:=1;
      prod:=1;
      for i from 0 to n-1 do(
	  prod=prod*s#i;
	  );
      perm=prod;

      curIndex:=0;--which position in the gray code changed
      curVal:=0;--what is the new value in the changed position of the gray code
      for count from 2 to 2^(n-1) do(--start at 2 because we already took the initial product corresponding to delta consisting of all 1's
	  sgn=(-1)*sgn;
	  --increment delta
	  flag:=1;
	  for k from 0 to n-2 when flag==1 do(
	      if del#k==0 then (del#k=1; flag=0; curIndex=k;) else (del#k=0);
	      if curIndex==n-2 then curVal=del#(n-2) else curVal=(del#curIndex)+(del#(curIndex+1));
	      if curVal==2 then curVal=0;
	      );

	  prod = 1;
	  --for every row update the values of s
	  for i from 0 to n-1 do (
	      if curVal==0 then s#i=s#i+2*(E#i#curIndex) else s#i=s#i-2*(E#i#curIndex); 
	  );
          --take the product of all of the row sums
          for i from 0 to n-1 do(
	  	  prod=prod*s#i;
	      );

	  perm = perm+sgn*prod;
	  );

      --need to divide in Glynn's formula
      --so can't be characteristic 2
      perm=perm//2^(n-1);
      perm
)

grenet Matrix := (M) -> ( 

     --get size of the matrix
     --n = length M_rows; --this is really the length of the list consisting of all of the rows of M
     n := numgens target M;
     R := ring(M);

     E:=entries M;

     m := 2^n-1; -- Size of the new matrix
     N := mutableMatrix(R,m,m); 
     --The last row and column will correspond to the merged source/sink vertex t in Grenet's construction.
     --Entry N_{i,j} will correspond to the weight on the edge from vertex i to vertex j.
     --The rows and columns are ordered by the binary order on the power set of [n] with the combined source/sink vertex being the last position.

     --Make the discrete cube and its powerset
     cube := set splice {0..n-1};
     powerSet := subsets(cube);

     emptySet:=set{};

     powerSet = subsets(cube); --This is a list given in binary ordering
     powerSet = delete(emptySet,powerSet);

     --Start filling the matrix

     --the diagonal entries are -1 when n is even and +1 when n is odd
     diag:=1;
     if n%2==0 then diag=-1 else diag=1; 
     --fill the diagonal entries (last diagonal entry is 0 corresponding to source/sink)
     for i from 0 to m-2 do N_(i,i)=diag;

     --fill the row labelled by t, i.e. vertices the vertex t points to in the construction
     --get all subsets of the cube of size 1
     currentSets := subsets(cube,1);

     for el in currentSets do(
	 place:=((elements(el))#0);
	 --the indices of the columns and rows of N correspond to the binary order of the powerset
	 N_(m-1,2^place-1)=E#0#place;
         );

     --fill the column labelled by t, i.e. the vertices that point to t in the construction
     --get all subsets of the cube of size n-1
     currentSets = subsets(cube,n-1);

     for el in currentSets do(
	 place:=((elements(cube-el))#0);
	 N_((2^n)-(2^place)-2,m-1)=E#(n-1)#place;
	 );

     --i is the row index  
     for i from 0 to m-2 do(
	  current := powerSet#i;
	  index1 := #current;

	  --technically, we could just call subsets(cube,index1+1), 
	  --but then we would have to work out the value of index2 from a given subset in this list
	  --j is the row index
	  for j from i+1 to m-2 do(
	       superSet:=powerSet#j;
	       if isSubset(current,superSet)and#(superSet-current)==1 then (
		    index2:=((elements (superSet-current))#0);
		    N_(i,j)=E#index1#index2;
		    );
	       );
	  );

     --fills in 0's in all of the other spaces that were not explicitly defined
     N = matrix N;

     --we want to return the matrix resulting from this construction
     N
)

pminors (ZZ,Matrix) := opts -> (i,M) -> (

    -- M is nxm
    n := numgens target M;
    m := numgens source M;
    R := ring M;
    E := entries M;

    if (i>m or i>n) then (I:=ideal(1_R);) else(

    rows := subsets(n,i);
    cols := subsets(m,i);

    --List from which the ideal will be created
    L:= {};

    for a in rows do(
	for b in cols do(
	    N := submatrix(M,a,b);
	    if (opts.Strategy === glynn or opts.Strategy === null) then (L=append(L,glynn(N));) else (L=append(L,ryser(N));); 
	    );
	);

    I=ideal(L);
    );
    I
)

ryser Matrix := (M) -> (

      n := numgens target M;
      R := ring(M);

      E := entries M;

       --these are the sums of the rows
      s := new MutableList from {};
      for i from 0 to n-1 do(
	  s=append(s,sum(E#i));
	  );

      cube := set splice {0..n-1};

      permanent := 0;

      --Recall that we can list the binary strings of length n in a Gray code order by
      --defining defining a vector delta to be all 0's and counting as usual in binary.
      --Then the ith entry of the current word in the Gray code is delta_i+delta_{i+1},
      --so at the point increment delta below we are searching for the unique index
      --in which the current word in the Gray code changed.    

      --initialize del vector to all 0's
      del := new MutableList from {0};
      --Is there any better way to create a MutableList of length n or is this the only way??
      for i from 1 to n-1 do(del = append(del,0););--delta is of length n

      --take the initial product corresponding to delta all +1's
      sgn:=1;
      prod:=1;
      for i from 0 to n-1 do(
	  prod=prod*s#i;
	  );
      permanent=prod;

      curIndex:=0;--which position in the gray code changed
      curVal:=0;--what is the new value in the changed position of the gray code
      for count from 2 to 2^n do(--start at 2 because we already took the initial product corresponding to delta consisting of all 1's
	  sgn=(-1)*sgn;
	  --increment delta
	  flag:=1;
	  for k from 0 to n-1 when flag==1 do(
	      if del#k==0 then (del#k=1; flag=0; curIndex=k;) else (del#k=0);
	      if curIndex==n-1 then curVal=del#(n-1) else curVal=(del#curIndex)+(del#(curIndex+1));
	      if curVal==2 then curVal=0;
	      );

	  prod = 1;
	  --for every row update the values of s
	  for i from 0 to n-1 do (
	      if curVal==0 then s#i=s#i+(E#i#curIndex) else s#i=s#i-(E#i#curIndex); 
	  );
          --take the product of all of the row sums
          for i from 0 to n-1 do(
	  	  prod=prod*s#i;
	      );

	  permanent = permanent+sgn*prod;
	  );

      permanent
)

ascendingRuns Permutation := List => w -> (
    -- inspired from the SageMath implementation
    -- https://github.com/sagemath/sage/blob/develop/src/sage/combinat/permutation.py
    if #w == 1 then allRuns := {toSequence w}
    else (
        allRuns = {};
        currentRun := {w#0};
        for wi in w_(toList(1 ..< #w)) do (
            if wi > last currentRun then currentRun = append(currentRun, wi)
            else (
                allRuns = append(allRuns, toSequence currentRun);
                currentRun = {wi};
            );
        );
        allRuns = append(allRuns, toSequence currentRun);
    );
    allRuns
)

ascents Permutation := List => w -> (
    for i in 1 ..< #w list if w_i < w_(i+1) then i else continue
)

avoidsPattern (Permutation,List) := (w, pattern) -> (
    --assume permutation is pattern-avoiding, break if not true
    for idx in subsets(0 .. #w-1, #pattern) do {
        vals := w_(idx);
        sortedVals := sort(vals);
        relPositions := hashTable toList apply(0..#vals-1, i -> {sortedVals#i, i});
        p := toList apply(vals, i -> (relPositions#i) + 1); 
        if p == pattern then return false;
    };
    true
)

avoidsPatterns (Permutation, List) := (w, patterns) -> (
    all(patterns, pattern -> avoidsPattern(w, pattern))
)

