    if #w == 1 then allRuns := {toSequence w}
    else (
        allRuns = {};
        currentRun := {w#0};
        for wi in w_(toList(1 ..< #w)) do (
            if wi < last currentRun then currentRun = append(currentRun, wi)
            else (
                allRuns = append(allRuns, toSequence currentRun);
                currentRun = {wi};
            );
        );
        allRuns = append(allRuns, toSequence currentRun);
