     stdsMu := pmStdTabsByConv(n, mu, opts.Convention);
     srcLabels := flatten for tLam in stdsLam list for alpha in monBasis list (tLam, alpha);
     attachBasisLabels(N, srcLabels, stdsMu)
     );

