	       if toList LHS =!= RHS then (
		    ok = false;
		    if opts.Verbose then
			 stdio << "  [verifyEquivariant LR] FAIL at E_{" << i << "," << j
			       << "}, T = " << toString stdsLam#tIdx << endl;
		    );
	       );
