	  for trip in imgD do imgDmap#(toList trip#1, toList trip#2) = trip#0;
	  allKeys := unique (keys imgDmap | keys imgM);
	  caseOk := true;
	  for k in allKeys do (
	       a := imgDmap#k ?? 0;
