randomPointsMat(Ring, ZZ) := opts -> (R,n) -> (
	d := numgens R;
	if opts.AllRandom == true then return random(R^d, R^n);

	m1 := id_(R^d)|transpose matrix(R,{toList(d:1)});
	if n<=d+1 then return m1_(toList(0..n-1));

	m3 := random(R^d,R^(n-d-1));
	m1 | m3
	)

addCone(Fan, Cone) := (F, C) -> (
   if ambDim F != ambDim C then error("Fan and Cone must live in same ambient space.");
   linF := linealitySpace F;
   linC := linealitySpace C;
   if image linF != image linC then error("Cannot add cone with different lineality space.");
   joinedRays := makeRaysUniqueAndPrimitive(rays F | rays C, linF);
   mc := maxCones F;
   map := rayCorrespondenceMap(rays F, linF, joinedRays);
   mc = apply(mc, c-> apply(c, e->map#e));
   map = rayCorrespondenceMap(rays C, linF, joinedRays);
   newCone := toList apply(numColumns rays C, i -> map#i);
   mc = append(mc, newCone);
   result := new HashTable from {
      ambientDimension => ambDim F,
      rays => joinedRays,
      computedLinealityBasis => linF,
      inputCones => mc
   };
   internalFanConstructor result
)

addCone(List, Fan) := (L, F) -> (
   if not all(L, l->instance(l, Cone)) then error("List does not contain cones");
   result := F;
   for cone in L do (
      result = addCone(result, cone)
   );
   result
)

addPolyhedron(Polyhedron,PolyhedralComplex) := (P, PC) -> (
   F := getProperty(PC, underlyingFan);
   C := getProperty(P, underlyingCone);
   result := new HashTable from {
      underlyingFan => addCone(F, C)
   };
   internalPolyhedralComplexConstructor result
)

addPolyhedron(List,PolyhedralComplex) := (L, PC) -> (
   if not all(L, p -> instance(p, Polyhedron)) then error("Expected list of polyhedra.");
   result := PC;
   for p in L do (
      result = addPolyhedron(p, result)
   );
   result
)

affineHull Polyhedron := P -> (
     M := vertices P;
     R := promote(rays P,QQ);
     -- subtracting the first vertex from all other vertices
     N := (M+M_{0}*(matrix {toList(numColumns M:-1)}))_{1..(numColumns M)-1};
     convexHull(M_{0},N | -N | R | -R));

affineImage(Matrix,Polyhedron,Matrix) := (A,P,v) -> (
   -- Checking for input errors
   A = chkZZQQ(A,"linear map");
   v = chkZZQQ(v,"translation vector");
   if ambDim(P) =!= numColumns A then error("Matrix source must be ambient space");
   if numRows A =!= numRows v then error("Vector must lie in target space of matrix");
   if numColumns v =!= 1 then error("Second argument must be a vector");
   -- Generating nr of vertices many copies of v
   v = v * (matrix {toList((numColumns vertices P):1_QQ)});
   Mv := A*(vertices P) + v;
   Mr := A*(rays P);
   Ml := A*(linealitySpace P);
   convexHull(Mv, Mr, Ml)
)

affineImage(Matrix,Polyhedron) := (A,P) -> (
     -- Generating the zero translation vector
     A = chkZZQQ(A,"map");
     v := map(target A,QQ^1,0);
     affineImage(A,P,v))

affinePreimage(Matrix,Polyhedron,Matrix) := (A,P,b) -> (
     -- Checking for input errors
     A = chkZZQQ(A,"linear map");
     b = chkZZQQ(b,"translation vector");
     if ambDim(P) =!= numRows A then error("Matrix source must be ambient space");
     if numRows A =!= numRows b then error("Vector must lie in target space of matrix");
     if numColumns b =!= 1 then error("Second argument must be a vector");
     -- Constructing the new half-spaces and hyperplanes
     (M,v) := halfspaces P;
     (N,w) := hyperplanes P;
     v = v - (M * b);
     w = w - (N * b);
     M = M * A;
     N = N * A;
     polyhedronFromHData(M,v,N,w))

