barycentricTriangulation Polyhedron := P -> (
     -- Defining the recursive face triangulation
     -- This takes a polytope and computes all facets. For each facet that is not a simplex, it calls itself
     -- again to replace this facet by a triangulation of it. then it has a list of simplices triangulating 
     -- the facets. Then it computes for each of these simplices the convex hull with the weighted centre of 
     -- the input polytope. The weighted centre is the sum of the vertices divided by the number of vertices.
     -- It returns the resulting list of simplices in a list, where each simplex is given by a list of its 
     -- vertices.
     -- The function also needs the dimension of the Polyhedron 'd', the list of facets of the original 
     -- polytope, the list 'L' of triangulations computed so far and the dimension of the original Polytope.
     -- 'L' contains a hash table for each dimension of faces of the original Polytope (i.e. from 0 to 'n').
     -- If a face has been triangulated than the list of simplices is saved in the hash table of the 
     -- corresponding dimension with the weighted centre of the original face as key.
     recursiveFaceTriangulation := (P,d,originalFacets,L,n) -> (
	  -- Computing the facets of P, given as lists of their vertices
	  F := intersectionWithFacets({(set P,set{})},originalFacets);
	  F = apply(F, f -> toList(f#0));
	  d = d-1;
	  -- if the facets are at least 2 dimensional, then check if they are simplices, if not call this 
	  -- function again
	  if d > 1 then (
	       F = flatten apply(F, f -> (
			 -- Check if the face is a simplex
			 if #f != d+1 then (
			      -- Computing the weighted centre
			      p := (sum f)*(1/#f);
			      -- Taking the hash table of the corresponding dimension
			      -- Checking if the triangulation has been computed already
			      if L#d#?p then L#d#p
			      else (
				   -- if not, call this function again for 'f' and then save this in 'L'
				   (f,L) = recursiveFaceTriangulation(f,d,originalFacets,L,n);
				   L = merge(L,hashTable {d => hashTable{p => f}},(x,y) -> merge(x,y,));
				   f))
			 else {f})));
	  -- Adding the weighted centre to each face simplex
	  q := (sum P)*(1/#P);
	  P = apply(F, f -> f | {q});
	  (P,L));
     -- Checking for input errors
     if not isCompact P then error("The polytope must be compact!");
     n := dim P;
     -- Computing the facets of P as lists of their vertices
     (HS,v) := halfspaces P;
     (hyperplanesTmp,w) := hyperplanes P;
     originalFacets := apply(numRows HS, i -> polyhedronFromHData(HS,v, hyperplanesTmp || HS^{i}, w || v^{i}));
     originalFacets = apply(originalFacets, f -> (
	       V := vertices f;
	       (set apply(numColumns V, i -> V_{i}),set {})));
     -- Making a list of the vertices of P
     P = vertices P;
     P = apply(numColumns P, i -> P_{i});
     if #P == n+1 then {P} else (
	  d := n;
	  -- Initiating the list of already computed triangulations
	  L := hashTable apply(n+1, i -> i => hashTable {});
	  (P,L) = recursiveFaceTriangulation(P,d,originalFacets,L,n);
	  P))

bipyramid Polyhedron := P -> (
   -- Saving the vertices
   V := vertices P;
   n := numColumns V;
   if n == 0 then error("P must not be empty");
   -- Computing the barycenter of P
   -- FIXME: the two `<< "Compute barycenter..." <<` lines below are leftover
   -- debug output; a public constructor should not print to stdout on every
   -- call.  They should be removed.
   << "Compute barycenter." << endl;
   v := matrix toList(n:{1_QQ,1_QQ});
   v = (1/n)*V*v;
   << "Compute barycenter done." << endl;
   C := getProperty(P, underlyingCone);
   M := promote(rays C, QQ);
   LS := promote(linealitySpace C, QQ);
   r := ring M;
   -- Embedding into n+1 space and adding the two new vertices
   zerorow := map(r^1,source M,0);
   newvertices := makePrimitiveMatrix(matrix {{1,1}} || v || matrix {{1,-1}});
   M = (M || zerorow) | newvertices;
   LS = LS || map(r^1,source LS,0);
   newC := coneFromVData(M, LS);
   result := new HashTable from {
      underlyingCone => newC
   };
   internalPolyhedronConstructor result
)

ccRefinement Matrix := M -> (
     -- Checking for input errors
     M = chkZZQQ(M,"rays");
     -- Extracting data
     n := numRows M;
     m := numColumns M;
     -- Generating all cones generated by 'n' rays in 'M'
     nCones := apply(subsets(m,n), e -> coneFromVData M_e);
     -- Selecting those cones that are 'n' dimensional and do not contain any 
     -- of the others
     nConesfd := select(nCones, C -> dim C == n);
     nConesfd = inclMinCones nConesfd;
     refCones := {};
     while nConesfd != {} do (
	  newCones := {};
	  -- scan through the 'n' dimensional cones and check for each of the cones generated by
	  -- 'n' rays if their intersection is 'n' dimensional and if the first one is not contained 
	  -- in the latter. If true, then their intersection will be saved in the list 'newCones'.
	  -- If false for every cone generated by 'n' rays, then the 'n' dimensional cone will be 
	  -- appended to the list 'refCones'
	  refCones = refCones | (flatten apply(nConesfd, C1 -> (
			 toBeAdded := flatten apply(nCones, C2 -> (
				   C := intersection(C2,C1);
				   if dim C == n and (not contains(C2,C1)) then C
				   else {}));
			 if toBeAdded == {} then C1
			 else (
			      newCones = newCones | toBeAdded;
			      {}))));
	  -- now, the new intersections will be the 'n' dimensional cones and the same procedure 
	  -- starts over again if this list is not empty
	  nConesfd = unique newCones);
     -- Compute the fan generated by the 'refCones'
     fan refCones);

cellDecompose (Polyhedron,Matrix) := (P,w) -> (
   warning("regularSubdivision", "1.11");
   regularSubdivision (P,w))

centroid Polyhedron := Matrix => P -> (
    if not isCompact P then error "the polyhedron must be compact";
    totalVolume := volume P;
    sum(barycentricTriangulation P, delta -> (
            barycenter := (sum delta) / #delta;
            (volume convexHull delta / totalVolume) * barycenter
        )
    )
)

commonFace(Polyhedron,Polyhedron) := (P,Q) -> (
   CP := getProperty(P, underlyingCone);
   CQ := getProperty(Q, underlyingCone);
   commonFace(CP, CQ)
)

commonFace(Cone,Cone) := (C1,C2) -> (
   if ambDim(C1) == ambDim(C2) then (
      I := intersection(C1,C2);
      isFace(I,C1) and isFace(I,C2)
   ) else false
)

commonFace(Fan,Fan) := (F1,F2) -> all(values getProperty(F1, honestMaxObjects), 
   C -> commonFace(C,F2)
)

coneFromHData Matrix := ineq -> (
   coneFromHData(ineq, map(ZZ^0,ZZ^(numColumns ineq), 0))
)

coneFromHData(Matrix, Matrix) := (ineq, eq) -> (
   if numColumns ineq != numColumns eq then error("Column dimensions of inequalities and equations do not agree.");
   result := new HashTable from {
      inequalities => ineq,
      equations => eq
   };
   return internalConeConstructor result

)

coneFromVData(Matrix,Matrix) := (Mrays,LS) -> (
   if numRows Mrays =!= numRows LS then error("rays and linSpace generators must lie in the same space");
   result := new HashTable from {
      ambientDimension => numRows Mrays,
      inputRays => Mrays,
      inputLinealityGenerators => LS
   };
   internalConeConstructor result
)

coneFromVData Matrix := R -> (
   r := ring R;
   -- Generating the zero lineality space LS
   LS := map(target R, r^0,0);
   coneFromVData(R,LS)
)

coneFromVData(Cone,Cone) := (C1,C2) -> (
   local iRays;
   local linealityGens;
   if hasProperties(C1, {rays, computedLinealityBasis}) then (
      iRays = rays C1;
      linealityGens = linealitySpace C1;
   ) else if hasProperties(C1, {inputRays, inputLinealityGenerators}) then (
      iRays = getProperty(C1, inputRays);
      linealityGens = getProperty(C1, inputLinealityGenerators);
   ) else (
      iRays = rays C1;
      linealityGens = linealitySpace C1;
   );
   if hasProperties(C2, {rays, computedLinealityBasis}) then (
      iRays = iRays | rays C2;
      linealityGens = linealityGens | linealitySpace C2;
   ) else if hasProperties(C2, {inputRays, inputLinealityGenerators}) then (
      iRays = iRays | getProperty(C2, inputRays);
      linealityGens = linealityGens | getProperty(C2, inputLinealityGenerators);
   ) else (
      iRays = iRays | rays C2;
      linealityGens = linealityGens | linealitySpace C2;
   );
   coneFromVData(iRays, linealityGens)
)

coneFromVData List := L -> (
   -- Turn everything into cones.
   cones := apply(L, 
      l -> (
         if not instance(l, Cone) then coneFromVData l
         else l
      )
   );
   result := cones#0;
   cones = drop(cones, 1);
   -- Adding the cones is not expensive, since we will not do fourierMotzkin
   -- every time.
   for cone in cones do (
      result = coneFromVData(result, cone);
   );
   result
)

coneFromVData Polyhedron := P -> (
     Mrays := makePrimitiveMatrix vertices(P) | rays(P);
     Mlinspace := linSpace(P);
     coneFromVData(Mrays,Mlinspace)
)

cones(ZZ,Fan) := (k,F) -> (
   d := dim F;
   faces := getProperty(F, computedFacesThroughRays);
   faces#(d-k)
)

contains(Polyhedron,Polyhedron) := (P1,P2) -> (
   -- checking for input errors
   if ambDim(P1) =!= ambDim(P2) then error("Polyhedra must lie in the same ambient space");
   C1 := getProperty(P1, underlyingCone);
   C2 := getProperty(P2, underlyingCone);
   contains(C1, C2)
)

contains(Cone,Cone) := (C1,C2) -> (
   -- checking for input errors
   if ambDim(C1) =!= ambDim(C2) then error("Cones must lie in the same ambient space");
   -- Saving the equations of C1 and rays of C2
   local C1ineq;
   local C1eq;
   -- Extracting inequalities of C1
   if hasProperty(C1, facets) then C1ineq = facets C1
   else if hasProperty(C1, inequalities) then C1ineq = getProperty(C1, inequalities)
   else C1ineq = facets C1;
   -- Extracting equations of C1
   if hasProperty(C1, computedHyperplanes) then C1eq = hyperplanes C1
   else if hasProperty(C1, equations) then C1eq = getProperty(C1, equations)
   else C1eq = hyperplanes C1;
   local C2rays;
   local C2lineality;
   -- Extracting rays of C2
   if hasProperty(C2, rays) then C2rays = rays C2
   else if hasProperty(C2, inputRays) then C2rays = getProperty(C2, inputRays)
   else C2rays = rays C2;
   -- Extracting lineality of C2
   if hasProperty(C2, computedLinealityBasis) then C2lineality = linealitySpace C2
   else if hasProperty(C2, inputLinealityGenerators) then C2lineality = getProperty(C2, inputLinealityGenerators)
   else C2lineality = linealitySpace C2;
   gens := C2rays | C2lineality | (-C2lineality);
   positiveTest := flatten entries (C1ineq * gens);
   zeroTest := flatten entries (C1eq * gens);
   all(positiveTest, p -> p>=0) and all(zeroTest, p -> p==0)
)

contains(Cone,Polyhedron) := (C,P) -> (
      -- checking for input errors
      if ambDim(C) =!= ambDim(P) then error("Cone and Polyhedron must lie in the same ambient space");
      -- Saving the equations of C and vertices/rays of P
      M := makePrimitiveMatrix vertices(P) | rays(P);
      LS := linSpace(P);
      C1 := coneFromVData(M,LS);
      contains(C,C1))

contains(Polyhedron,Cone) := (P,C) -> (
      -- checking for input errors
      if ambDim(C) =!= ambDim(P) then error("Polyhedron and Cone must lie in the same ambient space");
      -- Saving the cone 'C' as a polyhedron and using the function on two polyhedra
      Q := polyhedron C;
      contains(P,Q))

contains(Polyhedron,Matrix) := (P,p) -> (
      -- checking for input errors
      if ambDim(P) =!= numRows p then error("Polyhedron and point must lie in the same ambient space");
      if numColumns p =!= 1 then error("The point must be given as a one row matrix");
      contains(P,convexHull p))

contains(Cone,Matrix) := (C,p) -> (
      -- checking for input errors
      if ambDim(C) =!= numRows p then error("Polyhedron and point must lie in the same ambient space");
      if numColumns p =!= 1 then error("The point must be given as a one row matrix");
      contains(C,convexHull p))

contains(Fan,Cone) := (F,C) -> (
      -- Checking for input errors
      if ambDim F != ambDim C then error("Fan and Cone must lie in the same ambient space");
      -- Making the list of cones of same dimension as 'C'
      L := cones(dim C,F);
      contains(L,C))

convexHull(Matrix, Matrix, Matrix) := (Mvert, Mrays, Mlineality) -> (
   if numgens target Mvert =!= numgens target Mrays then error ("points and rays must lie in the same space");
   if numgens target Mvert =!= numgens target Mlineality then error ("points and lineality generators must lie in the same space");
   result := new HashTable from {
      ambientDimension => numRows Mvert,
      points => Mvert,
      inputRays => Mrays,
      inputLinealityGenerators => Mlineality
   };
   internalPolyhedronConstructor result
)

convexHull(Matrix,Matrix) := (Mvert,Mrays) -> (
   r := ring Mvert;
	Mlineality := map(target Mvert,r^0,0);
   convexHull(Mvert, Mrays, Mlineality)
)

convexHull Matrix := Mvert -> (
   r := ring Mvert;
	Mrays := map(target Mvert,r^0,0);
	convexHull(Mvert, Mrays)
)

convexHull(Polyhedron,Polyhedron) := (P1,P2) -> (
	-- Checking for input errors
	if ambDim(P1) =!= ambDim(P2) then error("Polyhedra must lie in the same ambient space");
   C1 := getProperty(P1, underlyingCone);
   C2 := getProperty(P2, underlyingCone);
   result := new HashTable from {
      ambientDimension => ambDim P1,
      underlyingCone => coneFromVData(C1, C2)
   };
   internalPolyhedronConstructor result
)

convexHull List := L -> (
   polyhedra := apply(L,
      l -> (
         if not instance(l, Polyhedron) then convexHull l
         else l
      )
   );
   cones := apply(polyhedra, p -> getProperty(p, underlyingCone));
   underLyingResult := coneFromVData(cones);
   result := new HashTable from {
      underlyingCone => underLyingResult
   };
   internalPolyhedronConstructor result
)

crossPolytope(ZZ,QQ) := (d,s) -> (
   -- Checking for input errors
   if d < 1 then error("dimension must at least be 1");
   if s <= 0 then error("size of the crosspolytope must be positive");
   constructMatrix := (d,v) -> (
   if d != 0 then flatten {constructMatrix(d-1,v|{-1}),constructMatrix(d-1,v|{1})}
   else {v});
   homHalf := ( sort makePrimitiveMatrix transpose( matrix toList(2^d:{-s}) | promote(matrix constructMatrix(d,{}),QQ)),map(ZZ^(d+1),ZZ^0,0));
   homVert := (sort makePrimitiveMatrix (matrix {toList(2*d:1_QQ)} || (map(QQ^d,QQ^d,s) | map(QQ^d,QQ^d,-s))),map(ZZ^(d+1),ZZ^0,0));
   C := new HashTable from {
      rays => homVert#0,
      computedLinealityBasis => homVert#1,
      facets => transpose(-homHalf#0),
      computedHyperplanes => transpose(homHalf#1)
   };
   C = internalConeConstructor C;
   result := new HashTable from {
      underlyingCone => C
   };
   internalPolyhedronConstructor result
)

cyclicPolytope(ZZ,ZZ) := (d,n) -> (
     -- Checking for input errors
     if d < 1 then error("The dimension must be positive");
     if n < 1 then error("There must be a positive number of points");
     convexHull map(ZZ^d, ZZ^n, (i,j) -> j^(i+1)))

dualCone Cone := C -> (
   result := new CacheTable;
   if hasProperty(C, inequalities) then result#inputRays = transpose getProperty(C, inequalities);
   if hasProperty(C, equations) then result#inputLinealityGenerators = transpose getProperty(C, equations);
   if hasProperty(C, inputRays) then result#inequalities = transpose getProperty(C, inputRays);
   if hasProperty(C, inputLinealityGenerators) then result#equations = transpose getProperty(C, inputLinealityGenerators);
   if hasProperty(C, rays) then result#facets = transpose getProperty(C, rays);
   if hasProperty(C, computedLinealityBasis) then result#computedHyperplanes = transpose getProperty(C, computedLinealityBasis);
   if hasProperty(C, facets) then result#rays = transpose getProperty(C, facets);
   if hasProperty(C, computedHyperplanes) then result#computedLinealityBasis = transpose getProperty(C, computedHyperplanes);
   return new Cone from {ambientDimension => ambDim C, cache => result}
)

dualFaceRepresentationMap Cone := C -> (
   getProperty(C, facetRayDataConverter)
)

dualFaceRepresentationMap Polyhedron := P -> (
   if not isCompact P then error("Only works for bounded polyhedra for now.");
   C := getProperty(P, underlyingCone);
   getProperty(C, facetRayDataConverter)
)

emptyPolyhedron ZZ := n -> (
   -- Checking for input errors
   if n < 1 then error("The ambient dimension must be positive");
   C := coneFromVData map(ZZ^(n+1), ZZ^0,0);
   result := new HashTable from {
      underlyingCone => C
   };
   internalPolyhedronConstructor result
);

fVector SimplicialComplex := List => D -> (
    -- the `faces' methods creates the face ring as a quotient of the exterior algebra
    if not D.cache.?faces then faces(-1,D);
    d := dim D;
    -- the void complex is exceptional
    if d < -1 then return {0};
    apply(toList(0..1+dim D), i -> hilbertFunction(i, D.cache.faces.ring))
    )

faceFan Polyhedron := P -> (
   -- Checking for input errors
   if not inInterior(map(QQ^(ambDim P),QQ^1,0),P) then  error("The origin must be an interior point.");
   if not isCompact P then error("Polyhedron must be compact");
   resultRays := vertices P;
   resultCones := faces(1, P);
   resultCones = apply(resultCones, c -> c#0);
   fan(resultRays, resultCones)
)

faces(ZZ, PolyhedralObject) := (k,PO) -> (
   result := faces PO;
   if result#?k then result#k
   else {}
)

faces (ZZ, SimplicialComplex) := List => (i, D) -> (
    S := ring D;
    if not D.cache.?faces then (
	D.cache.faces = new MutableHashTable;
	E := (coefficientRing S)(monoid[gens S, SkewCommutative => true]);
	phi := map(E, S, gens E);
	J := phi(ideal D);
	D.cache.faces.ring = E/J;
	);
    if not D.cache.faces#?i then (
    	D.cache.faces#i = first entries( 
	    if dim D < -1 or i < -1 or i > dim D then 
	        matrix(S, {{}})
    	    else if i === -1 then matrix {{1_S}}
    	    else (
	    	R := D.cache.faces.ring;
	    	sub(matrix basis(i+1, R), vars S)
	    	)
	    )
	);
    D.cache.faces#i
    )

faces SimplicialComplex := HashTable => D -> (
    hashTable apply(toList(-1..dim D), i -> i => faces(i, D))
    )

facesAsCones(ZZ, Cone) := (d, C) -> (
   raysC := rays C;
   linC := linealitySpace C;
   result := faces(d, C);
   apply(result, f -> coneFromVData(raysC_f, linC))
)

facesAsCones(ZZ, Fan) := (d, F) -> (
   raysF := rays F;
   linF := linealitySpace F;
   result := faces(d, F);
   apply(result, f -> coneFromVData(raysF_f, linF))
)

facesAsPolyhedra(ZZ, Polyhedron) := (d, P) -> (
   vertP := vertices P;
   raysP := rays P;
   linP := linealitySpace P;
   result := faces(d, P);
   apply(result, f -> convexHull(vertP_(f#0), raysP_(f#1), linP))
)

facets(AbstractSimplicialComplex):=List => K ->(
    L := flatten(apply(spots K, i-> K_i));
    listFacets(L))

fan NormalToricVariety := Fan => X -> (
    rayMatrix := promote (matrix transpose rays X, QQ); 
    fan(rayMatrix, max X) 
    );

fan(Matrix, Matrix, List) := (irays, linealityGens, icones) -> (
   n := max flatten icones;
   if numColumns irays < n then error("The number of indices exceeds the number of vectors");
   if (numRows irays != numRows linealityGens) then error("Rays and lineality must have same ambient dimension.");
   lineality := makeRaysPrimitive(mingens image linealityGens);
   result := new HashTable from {
      inputRays => irays,
      computedLinealityBasis => lineality,
      inputCones => icones
   };
   internalFanConstructor result
)

fan(Matrix, Matrix, Sequence) := (irays, linealityGens, icones) -> (
   fan(irays, linealityGens, toList icones)
)

fan(Matrix, List) := (irays, icones) -> (
   r := ring irays;
   linealityGens := map(target irays, r^0, 0);
   fan(irays, linealityGens, icones)
)

fan(Matrix, Sequence) := (irays, icones) -> (
   fan(irays, toList icones)
)

fan Cone := C -> (
   raysC := rays C;
   linealityC := linealitySpace C;
   n := numColumns raysC;
   mc := {toList (0..(n-1))};
   result := fan(raysC, linealityC, mc);
   setProperty(result, honestMaxObjects, new HashTable from {mc#0 => C});
   result
)

fan List := inputCones -> (
   if instance(inputCones, Cone) then error("Why did I arrive here?");
   if not all(inputCones, c -> instance(c, Cone)) then error("This constructor needs a list of cones.");
   result := fan(inputCones#0);
   for i from 1 to #inputCones - 1 do (
      result = addCone(result, inputCones#i);
   );
   result
)

fanFromGfan List := gfanOutput -> (
-- 0 rays -> Matrix
-- 1 lineality -> Matrix
-- 2 cones -> List<List>
-- 3 dimension -> ZZ
-- 4 pure -> bool
-- 5 simplicial -> bool
-- 6 fVector -> List
   numberOfGfanOutputs := 7;
   if #gfanOutput != numberOfGfanOutputs then
      error("fanFromGfan was given a list with " | toString(#gfanOutput)
         | " inputs and " | toString(numberOfGfanOutputs) | " are required.");
   R := gfanOutput#0;
   L := gfanOutput#1;

   -- Perform some basic sanity checks on the fan. If the fan is empty (i.e.
   -- there are no rays and no lineality space), then all of the other values
   -- need to agree with that (there cannot be any cones, the dimension must
   -- be zero, and the f-vector must be empty).
   if ((numColumns R == 0) and (numColumns L == 0))
   and ((#(gfanOutput#2) != 0) or (gfanOutput#3 != 0) or (#(gfanOutput#6) != 0))
   then error("Inconsistent input into fanFromGfan");

   if (numColumns R == 0) then R = map(ZZ^(numRows L), ZZ^0, 0);
   if (numColumns L == 0) then L = map(ZZ^(numRows R), ZZ^0, 0);
   result := fan(R, L, gfanOutput#2);
   setProperty(result, computedFVector, gfanOutput#6);
   setProperty(result, pure, gfanOutput#4);
   setProperty(result, simplicial, gfanOutput#5);
   setProperty(result, computedDimension, gfanOutput#3);
   return result;
)

hirzebruch ZZ := r -> (
   -- Checking for input errors
   if r < 0 then error ("Input must be a positive integer");
   normalFan convexHull matrix {{0, 1, 0, r+1},{0, 0, 1, 1}}
)

hypercube(ZZ,QQ,QQ) := (d, lower, upper) -> (
     -- Checking for input errors
     if d < 1 then error("dimension must at least be 1");
     if lower >= upper then error("Lower vertex value cannot be bigger than upper.");
     -- Generating half-spaces matrix and vector
     A := map(QQ^d,QQ^d,1) || -map(QQ^d,QQ^d,1);
     b := (matrix toList(d:{upper})) || (matrix toList(d:{-lower}));
     polyhedronFromHData(A, b)
)

hyperplanes Matroid := List => M -> (
	if M.cache.?hyperplanes then M.cache.hyperplanes else M.cache.hyperplanes = (circuits dual M)/(c -> M.groundSet - c)
)

imageFan (Matrix,Cone) := (M,C) -> (
   M = chkZZQQ(M,"map");
   if numColumns M != ambDim C then error("The source space of the matrix must be the ambient space of the cone");
   -- Extracting data
   m := numRows M;
   n := dim C;
   raysC := rays C;
   lin := linealitySpace C;
   -- Compute the images of all 'm' dimensional faces and select those that are again 
   -- 'm' dimensional
   L := apply(faces(n-m,C), 
      e -> (
         Ce := coneFromVData(raysC_e, lin);
         affineImage(M,Ce)
      )
   );
   L = select(L, e -> dim e == m);
   -- Compute their common refinement
   refineCones L
)

inInterior (Matrix,Cone) := (p,C) -> (
     hyperplanesTmp := hyperplanes C;
     all(flatten entries(hyperplanesTmp*p), e -> e == 0) and (
	  HS := halfspaces C;
	  all(flatten entries(HS*p), e -> e > 0)))

inInterior (Matrix,Polyhedron) := (p,P) -> (
     hyperplanesTmp := hyperplanes P;
     hyperplanesTmp = (hyperplanesTmp#0 * p)-hyperplanesTmp#1;
     all(flatten entries hyperplanesTmp, e -> e == 0) and (
	  HS := halfspaces P;
	  HS = (HS#0 * p)-HS#1;
	  all(flatten entries HS, e -> e < 0)))

incompCones List := L -> (
     if any(L, l -> (not instance(l,Cone)) and (not instance(l,Fan))) then error("The list may only contain cones and fans");
     select(apply(subsets(L,2),toSequence), p -> not commonFace p))

incompCones(Fan,Fan) := (F1,F2) -> 
   flatten apply(values getProperty(F1, honestMaxObjects), 
      C1 -> flatten apply(values getProperty(F2, honestMaxObjects),
         C2 -> if not commonFace(C1,C2) then (C1,C2) else {}
      )
   )

incompPolyhedra List := L -> (
     if any(L, l -> (not instance(l,Polyhedron)) and (not instance(l,PolyhedralComplex))) then error("The list may only contain polyhedra and polyhedral complexes");
     select(apply(subsets(L,2),toSequence), p -> not commonFace p))

interiorPoint Polyhedron := P -> (
     -- Checking for input errors
     if isEmpty P then error("The polyhedron must not be empty");
     Vm := vertices P | promote(rays P,QQ);
     n := numColumns Vm;
     ones := matrix toList(n:{1/n});
     -- Take the '1/n' weighted sum of the vertices
     Vm * ones)

interiorVector Cone := C -> (
     Rm := rays C;
     if numColumns Rm == 0 then map(ZZ^(ambDim C),ZZ^1,0)
     else (
	  ones := matrix toList(numColumns Rm:{1});
	  -- Take the sum of the rays
	  iv := Rm * ones;
	  transpose matrix apply(entries transpose iv, w -> (g := abs gcd w; apply(w, e -> e//g)))));

isFace(Cone,Cone) := (C1,C2) -> (
   c := dim C2 - dim C1;
   -- Checking if the two cones lie in the same space and the dimension difference is positive
   if ambDim(C1) == ambDim(C2) and c >= 0 then (
      raysC2 := rays C2;
      linC2 := linealitySpace C2;
      raysC1 := rays C1;
      linC1 := linealitySpace C1;
      if not (image linC2 == image linC1) then return false;
      rcm := rayCorrespondenceMap(raysC1, linC1, raysC2);
      L := sort for k in keys rcm list (
         p := rcm#k;
         if p == -1 then return false;
         p
      );
      goodFaces := faces(c, C2);
      any(goodFaces, f -> sort f === L)
   )
   else false
)

isFace(Polyhedron,Polyhedron) := (P,Q) -> (
   -- Checking if the two polyhedra lie in the same space and computing the dimension difference
   if not isEmpty P then (
      CP := getProperty(P, underlyingCone);
      CQ := getProperty(Q, underlyingCone);
      isFace(CP, CQ)
   ) else return ambDim P == ambDim Q
)

isPointed Cone := C -> (
   getProperty(C, pointed)
)

isPure SimplicialComplex := Boolean => D -> (
     F := facets D;
     L := unique apply(F, m -> # support m);
     #L <= 1
     )

isSimplicial Poset := Boolean => P -> (

    -- Not sure if doing this correctly (did we ever write to the cache?)
    --if P.cache.?isSimplicial then return P.cache.isSimplicial;

    minP := minimalElements P;
    if (#minP) != 1 then return false;

    zeroP := minP#0;    

    -- Test that each interval is a boolean algebra.
    for x in vertices(P) do (
	interval := closedInterval(P, zeroP, x);
    	if not isBoolean(interval) then return false;
	);
    true
    );

latticePoints(FlagMatroid) := M -> (
    n := #M.groundSet;
    BL := M.constituents/bases/(B -> B/(b -> setIndicator(b,n)));
    k := #BL;
    unique apply((k:0)..toSequence(BL/(B -> #B-1)), i -> sum(k, j -> (BL_j)_(i_j)))
)

latticePoints ToricDivisor := Matrix => D -> (
    V := vertices D;
    if V === null then return null;
    c := matrix(vector \ latticePoints convexHull V);
    c_(sortColumns c) 
    );

latticePoints Polyhedron := P -> (
   getProperty(P, computedLatticePoints)
)

