maxCones ToricVectorBundle := T -> (
      TV := T#"ToricVariety";
      TR := rays TV;
      TL := linealitySpace TV;
      mC := maxCones TV;
      sort apply(mC, c -> posHull(TR_c, TL))
    -- sort maxCones T#"ToricVariety"
