   L := facesAsPolyhedra(codimensionfd, Pd);
   Pd = first select(1,L, l -> all(flatten entries(V*(vertices l)),e -> e == -1) and V*(rays l) == 0 and R*(vertices l | rays l) == 0);
   Pd
)

