   -- Checking for input errors
   if k < 0 or dim PC < k then error("k must be between 0 and the dimension of the fan.");
   L := getProperty(PC, computedFacesThroughRays);
   -- Collecting the 'k'-dim faces of all generating polyhedra of dimension greater than 'k'
   dk := dim(PC) - k;
   if L#?dk then return L#dk
   else return {}
)

polyhedralComplex(Matrix, Matrix, Matrix, List) := (V, R, lineality, mO) -> (
   if not all(mO, m -> #m == 2) then error("Expected pairs of lists.");
   shift := numColumns V;
   mO = apply(mO,
      m -> (
         flatten{m#0, apply(m#1, e->e+shift)}
      )
   );
   irays := prependOnes(V) | prependZeros(R);
   result := new HashTable from {
      underlyingFan => fan(irays, prependZeros(lineality), mO)
   };
   internalPolyhedralComplexConstructor result
)

polyhedralComplex(Matrix, Matrix, List) := (V, R, mO) -> (
   if not all(mO, m-> all(m, e->instance(e, List))) then (
      mO = apply(mO, m -> {m, {}})
   );
   RL := map(QQ^(numRows V), QQ^0, 0);
   polyhedralComplex(V, R, RL, mO)
)

polyhedralComplex(Matrix, List) := (V, mO) -> (
   if not all(mO, m-> all(m, e->instance(e, List))) then (
      mO = apply(mO, m -> {m, {}})
   );
   RL := map(QQ^(numRows V), QQ^0, 0);
   polyhedralComplex(V, RL, RL, mO)
)

polyhedralComplex Fan := F -> (
   n := ambDim F;
   vertex := map(ZZ^n, ZZ^1, 0);
   mO := maxCones F;
   mO = apply(mO, m -> {{0},m});
   polyhedralComplex(vertex, rays F, linealitySpace F, mO)
)

polyhedralComplex Polyhedron := P -> (
   C := getProperty(P, underlyingCone);
   result := new HashTable from {
      underlyingFan => fan C
   };
   internalPolyhedralComplexConstructor result
)

polyhedralComplex List := L -> (
   if not all(L, l->instance(l, Polyhedron) or instance(l, PolyhedralComplex)) then error("Expected list of polyhedra and polyhedral complices.");
   PCs := select(L, l->instance(l, PolyhedralComplex));
   Ps := select(L, l->instance(l, Polyhedron));
   PCs = flatten apply(PCs, l->getProperty(l, honestMaxObjects));
   MO := flatten {Ps, PCs};
   result := polyhedralComplex MO#0;
   addPolyhedron(MO, result)
)

polyhedron Cone := C -> (
   n := ambDim C;
   rayData := getSufficientRayData C;
   r := ring rayData#0;
   vertex := map(ZZ^n, ZZ^1, 0);
   convexHull(vertex, rayData#0, rayData#1)
)

polyhedronFromHData(Matrix, Matrix) := (M,v) -> (
   r := ring M;
   Nw := map(r^0, source M, 0);
   w := map(r^0, r^1, 0);
   polyhedronFromHData(M, v, Nw, w)
)

polyhedronFromHData(Matrix,Matrix,Matrix,Matrix) := (M,v,N,w) -> (
	-- checking for input errors
	if numColumns M =!= numColumns N then error("equations of half-spaces and hyperplanes must have the same dimension");
	if numRows M =!= numRows v or numColumns v =!= 1 then error("invalid condition vector for half-spaces");
	if numRows N =!= numRows w or numColumns w =!= 1 then error("invalid condition vector for hyperplanes");
	ineq := v | M;
   ezero := matrix {flatten {1 , toList ((numgens source M):0)}};
   ineq = ineq ||  ezero;
	eq := w | N;
   result := new HashTable from {
      inequalities => (M,v),
      equations => (N,w)
   };
   internalPolyhedronConstructor result
)

