     run ex
     )

runPolymake(PolymakeObject, String) := (P, propertyname) -> (
     filename := temporaryFileName();
     << "using temporary file " << filename << endl;
     filename << toPolymakeFormat(P) << endl << close;
     runPolymake(filename, propertyname)
     )

toPolymakeFormat(String, Matrix) := (propertyname, M) -> (
     if M === null then ""
     else(
     	  S := propertyname|"\n";
     	  if numRows M > 0 then
	     S = S|replace("\\|", "", toString net M);
     	  S
     )
)

toPolymakeFormat(String,Vector) := (propertyname,V) -> (
     if V === null then ""
     else(
          L := entries V;
     	  S := propertyname|"\n";
     	  if length L > 0 then
              S = S|replace("\\|", "", toString net matrix{L});     
     	  S
     )
)

toPolymakeFormat(PolymakeObject) := (P) -> (
     concatenate apply(pairs P, a -> toPolymakeFormat(a)|"\n\n")
     )

adjacent2MinorIdeal CollectionOfCells := opts -> Q ->(
R:=polyoRing(Q,Field=>opts.Field, TermOrder=>opts.TermOrder, RingChoice=> 1);
GensForIdeal := for cell in Q list (
        lowerLeftCorner  := toSequence(cell);
       	upperRightCorner := toSequence(cell + {1,1});
       	upperLeftCorner  := toSequence(cell + {0,1});
       	lowerRightCorner := toSequence(cell + {1,0});
	x_lowerLeftCorner_R*x_upperRightCorner_R - x_upperLeftCorner_R*x_lowerRightCorner_R
  	);
I:= ideal GensForIdeal;
I
);

