allNonAttackingRookConfigurations CollectionOfCells := opts -> L -> (

    Q := for i from 0 to #L-1 list L#i; 
    Q = sort Q;

    conf := apply(Q, i -> {i}); 
    AllConf:={conf};
    while true do (
        out :={};
        for N in conf do (
            for c in Q do (
                if all(N, n -> isNonAttackingRooks(c, n, L)) then (
                    FF := sort join(N, {c});
                    out = join(out, {FF});
                );
            );
        );
        out = toList set out; 
        if #out == 0 then return AllConf;
        AllConf = append(AllConf, out);
        conf = out;
    );
);
```

