isColumnConvex CollectionOfCells := opts -> Q -> (
    n := #Q;
    for i from 0 to n-2 do (
        for j from i+1 to n-1 do (
            A := Q#i;
            B := Q#j;
            if (A#0 == B#0) then (
		a := min {A#0, B#0};
    		b := min {A#1, B#1};
