	f1 := map(unQuotiented, ambient myRing1, firstVars);
	J1 := f1(ideal(myRing1));

	f2 := map(unQuotiented, ambient myRing2, secondVars);
	J2 := f2(ideal(myRing2));

	outputRing :=unQuotiented/(JObviousRelation + J1 + J2);

	{outputRing, e1}
