           Jq := ideal(Iq);
   ----------------------------------------------------------------------------
           Dq := qthConductor(Jq,depno);
	   Dq=Dq/leadCoefficient(Dq);
           print(q,Dq);
   --q is good if D%q matches Dq-----------------------------------------------   
      if Dq == sub(D0,Rq) then(
