	      oldrelsZ = for i to #relationsicRq-1 list sub(relationsicRq#i,icRZ);
              oldvarsQ = for i to #oldvarsZ-1 list polyrecon(oldvarsZ#i,q,R0);
	          icRQ = QQ(monoid icRZ);		 
	      oldrelsQ = for i to #oldrelsZ-1 list polyrecon(oldrelsZ#i,q,icRQ);
	        oldmod = q;
	       stable  = false;
	   firstPrime  = false;
         )
         else(
