	    if newvarsQ != oldvarsQ or newrelsQ != oldrelsQ  then(
	       oldvarsQ = newvarsQ;
	       oldrelsQ = newrelsQ;
	       oldvarsZ = newvarsZ;
	       oldrelsZ = newrelsZ;
