	             oldvarsZ = newvarsZ;
	             oldrelsZ = newrelsZ;
	             stable = false;
		     break;
		  );
	       );
	    );	     
         );
         q = q+1;
      )
      else(
         q = q+1;
         stable = false;  
      );
   );
