testWeightMatrix(Matrix,Ring,List) := (wtr,r,GB) ->(
   for i to #GB-1 list(
      pol:=GB#i;
      lp:=leadTerm(pol);
      lq:=leadTerm(pol-lp);
      mp:=transpose matrix{apply(#gens r,i->degree((gens r)#i,lp))};
      mq:=transpose matrix{apply(#gens r,i->degree((gens r)#i,lq))};
      wtr*mp==wtr*mq
      )	  
);

weightGrevlex(Matrix) := (matr)-> (
   grev := for i to numColumns(matr)-numRows(matr)-1 list (
              for j to numColumns(matr)-1 list(
	         if i+j < numColumns(matr)-numRows(matr) then 1 else 0
                 )
              );
              matr||matrix(grev)
          );

almostKoszul (Ring, ZZ) := Ring => (kk, a)-> (
   --A series of examples discovered by Jan-Erik Roos:
   --
   --If kk = QQ then the resolution of kk over the output
   --ring has linear resolution for a steps but 1 quadratic syzygy
   --at the a+1-st step. 
   --It also seems to have the first socle summand
   --at the a+1-st step!
   --These phenomena are also visible with kk = ZZ/32003, at
   --least for moderate size a.
   x := symbol x; 
   y := symbol y;
   z := symbol z; 
   u := symbol u; 
   v := symbol v; 
   w := symbol w;
   S := kk[x,y,z,u,v,w];
   I := ideal (x^2,x*y,y*z,z^2,z*u,u^2,u*v,v*w,w^2,
          x*z+a*z*w-u*w,z*w+x*u+(a-2)*u*w);
   S/I
      )

exceptionalSet(Matrix) := (A) -> (
    x := symbol x;
    R := makeGradedRing(A,x);
    I := toricIdeal(A,R);
    M := R^1/I;
    quasidegreesLocalCohomology M
    )

makeGradedRing(Matrix,Symbol) := (A,x) -> (
    degs := entries(transpose(A));
    QQ[x_0..x_(numgens(source(A))-1),Degrees=>degs]
    )

quasidegrees(Module) := (M) -> (
    R := ring M;
    P := presentation M;
    if not isMonomialMatrix P then error "expected module to be presented by a matrix with monomial entries";
    if not isPositivelyGraded M then error "module is not positively graded";
    if not isHomogeneous M then error "module is not homogeneous with respect to ambient grading";
    E := entries P;
    D := degrees target P;
--  We make the following list of pairs S.  
--  The first entry is a degree twist in the presentation of M.
--  The second entry are the standard pairs of the corresponding row.
    S := apply(#D, i -> (
	    {vector(D_i), standardPairs monomialIdeal E_i}
	    )
	);
--  Next we make a list T representing the quasidegree set of M as follows.
--  The variables in S get assigned their degrees and then
--  shifted by the corresponding degree twist in the
--  presentation of M.
    T := flatten(apply(S, s-> (
		apply((s_1), w -> (
			if w_0==1 then (
			    if w_1 =={} then (
				{s_0,{}}
				)
			    else {s_0, apply(w_1, x -> vector degree x)}
			    )
			else{s_0 + (vector(degree(w_0))), apply(w_1, x -> vector degree x)}
			)
		    )
		)
	    )
	);
    toList set T
    )

quasidegrees(Ideal) := (I) -> (
    R := ring I;
    M := R^1/I;
    quasidegrees M
    )

quasidegreesAsVariables(Module) := (M) -> (
    R := ring M;
    P := presentation M;
    if not isMonomialMatrix P then error "expected module to be presented by a matrix with monomial entries";
    if not isPositivelyGraded M then error "module is not positively graded";
    if not isHomogeneous M then error "module is not homogeneous with respect to ambient grading";
    S := entries P;
    stdPairs := {};
    for s to (#S-1) do stdPairs = stdPairs|standardPairs(monomialIdeal(S#s));
    stdPairs
    )

quasidegreesAsVariables(Ideal) := (I) -> (
    R := ring I;
    M := R^1/I;
    quasidegreesAsVariables M
    )

quasidegreesLocalCohomology(ZZ, Module) := (i,M) -> (
    R := ring M;
    n := numgens R;
    v := gens R;
    e := vector sum apply(v,x -> degree x);
--  use Local Duality
    N := Ext^(n-i)(M,R);
    P := presentation N;
    if not isMonomialMatrix P then error "expected module to be presented by a matrix with monomial entries";
    if not isPositivelyGraded N then error "module is not positively graded";
    if not isHomogeneous N then error "module is not homogeneous with respect to ambient grading";
    E := entries P;
    D := degrees target P;
--  We make the following list of pairs S.  
--  The first entry is a degree twist in the presentation of M.
--  The second entry is a list of the standard pairs of the monomial ideal
--  generated by the entries of the corresponding row.
    S := apply(#D, i -> (
	    {vector(-D_i), standardPairs monomialIdeal E_i}
	    )
	);
--  We next make a list T representing the quasidegree set of M.
--  The variables in S are assigned their degrees and then
--  shifted by the corresponding degree twist in the
--  presentation of M.
    T := flatten(apply(S, s-> (
		apply((s_1), w -> (
			if w_0==1 then (
			    if w_1 =={} then (
				{s_0,{}}
				)
			    else {s_0, apply(w_1, x -> vector degree x)}
			    )
			else{s_0 - (vector(degree(w_0))), apply(w_1, x -> vector degree x)}
			)
		    )
		)
	    )
	);
    Q := toList set T;
    apply( #Q, j -> {((Q_j)_0)-e,(Q_j)_1})
    )

quasidegreesLocalCohomology(ZZ, Ideal) := (i,I) -> (
    R := ring I;
    M := R^1/I;
    quasidegreesLocalCohomology(i,M)
    )

quasidegreesLocalCohomology(Module) := (M) ->( 
    Q := for i from 0 to (dim M)-1 list quasidegreesLocalCohomology(i,M);
    Q' := delete({}, Q);
    flatten Q'
    )

quasidegreesLocalCohomology(Ideal) := (I) -> (
    R := ring I;
    M := R^1/I;
    quasidegreesLocalCohomology M   
    )

removeRedundancy(List) := (L) -> (
    for i from 0 to #L-1 do(
	S := {};
	for j in i+1..#L-1 do(
	    if rank matrix(L_j)_1 == rank(matrix(L_j)_1|matrix(L_i)_0) then(
		for k from 0 to #((L_i)_1)-1 do(
		    if (rank matrix(L_j)_1 == rank((matrix(L_j)_1)|matrix((L_i)_1)_k)) then S=S|{1};
		    if S == toList(#((L_i)_1):1) then L = delete(L_i,L);
		    )
		)
	    )
	);
    L
    )

toGradedRing(Matrix,PolynomialRing) := (A,R) -> (
    if numgens R =!= rank source A then error "expected numgens R to equal number of columns of A";
    degs := entries transpose A;
    k := coefficientRing R;
    v := toSequence flatten entries vars R;
    k[v,Degrees=>degs]
    )

toricIdeal(Matrix,Ring) := (A,R) -> (
    m := product gens R;
    saturate(sub(toBinomial(transpose(syz(A)),R),R),m)
    )

doubling(ZZ, Ideal) := Ideal => opts -> (deg, I) -> (
    c := codim I;
    wR := Ext^c(comodule I, ring I);
    H := Hom(wR, comodule I);
    count := 0;
    while count < opts.Count do (
        f := randomHomomorphism(deg, comodule I, wR);
        if ker f == 0 then (
            if debugLevel > 0 then (
                if count == 1 then << "took 1 try" << endl;
                if count > 1 then << "took " << count << " tries" << endl;
                );
            return trim ideal presentation coker f;
            );
        count = count+1;
        );
    null
    );

nondegenerateBorels(ZZ, Ring) := List => opts -> (d, S) -> (
    Bs := stronglyStableIdeals(d, S);
    Bs = select(Bs, i -> all(i_*, f -> degree f =!= {1}));
    if opts.Sort then
      Bs = Bs/(i -> ideal sort(gens i, MonomialOrder => Descending, DegreeOrder => Ascending));
    Bs
    )

pointsIdeal Matrix := Ideal => (m) -> (
    intersect for i from 0 to numcols m - 1 list pointIdeal(m_{i})
    )

pointsIdeal(Ring, Matrix) := Ideal => (S, mkk) -> (
    m := mkk ** S;
    intersect for i from 0 to numcols m - 1 list pointIdeal(m_{i})
    )

quartic(Matrix, Ring) := RingElement => (pts, S) -> (
    if numgens S =!= numrows pts then error ("expected a matrix with "|toString numgens S|" rows");
    linforms := flatten entries((vars S) * pts);
    sum for ell in linforms list ell^4
    )

quarticType RingElement := String => F -> (
    -- returns either "[has linear form]", or one of the 19 strata that this quartic sits on
    R := ring F;
    if numgens R =!= 4 then error "expected a polynomial ring in 4 variables";
    if degree F =!= {4} then error "expected a quartic polynomial";
    I := trim inverseSystem F;
    if any(I_*, f -> degree f === {1}) then return "[has linear form]";
    Q := ideal select(I_*, f -> degree f === {2}); -- quadratic part
    CQ := res Q;
    twolinear := topRow betti CQ;
    if twolinear === {3,0,0} then (
        -- 3 possible types: abc.
        if codim Q === 2 then 
            "[300c]"
        else if codim Q === 3 then 
            "[300ab]" -- how to detect the difference?
        else
            error "internal error: should not reach this line"
        )
    else if twolinear === {4,4,1} then (
        syz2 := ideal CQ.dd_3_{0};
        if codim syz2 === 3 then 
            "[441a]"
        else if codim syz2 === 4 then 
            "[441b]"
        )
    else -- the easy case: the quadric strand determines the type
       "["|twolinear#0|twolinear#1|twolinear#2|"]"
    )

randomBlockMatrix(List, List, List) := (tar, src, mats) -> (
    if #tar == 0 or #src == 0 then error "expected lists of free modules";
    if not all(tar, x -> instance(x, Module))
      or
      not all(src, x -> instance(x, Module))
      then error "expected lists of free modules";
    R := ring tar_0;
    if not all(tar, x -> ring x === R)
      or
      not all(src, x -> ring x === R)
      then error "expected lists of free modules over a common ring";
    nrowblocks := #tar;
    ncolblocks := #src;
    if #mats != nrowblocks or not all(mats, r -> #r == ncolblocks)
    then error "wrong number of matrices given";
    matrix for i from 0 to nrowblocks-1 list
      for j from 0 to ncolblocks-1 list (
          if mats#i#j === random then random(tar#i, src#j)
          else map(tar#i, src#j, mats#i#j)
          -- else if mats#i#j === 0 then map(tar#i, src#j, 0)
          -- else if mats#i#j === 1 then map(tar#i, src#j, 1)
          )
    )

randomHomomorphism(ZZ, Module, Module) := Matrix => (deg, tar, src) -> (
    H := Hom(src, tar);
    B := basis(deg, H); -- map HomModule <--- graded free
    rand := random(source B, (ring B)^{-deg});
    homomorphism(B * rand)
    )

randomHomomorphism(ZZ, Module, Module) := Matrix => (deg, tar, src) -> (
    H := Hom(src, tar);
    B := basis(deg, H); -- map HomModule <--- graded free
    rand := random(source B, (ring B)^{-deg});
    homomorphism(B * rand)
    )

randomPoints(Ring, ZZ, ZZ) := Matrix => opts -> (kk, n, d) -> (
    -- n is the number of variables 
    -- d is the number of points
    -- returns a d by n matrix over kk.
    if not opts.Normalize then return random(kk^n, kk^d);
    I := id_(kk^n) | matrix apply(n, i -> {1});
    if d <= n+1 then return I_{0..d-1};
    rand := random(kk^n, kk^(d-n-1));
    I | rand
    )

smallerBettiTables BettiTally := (B) -> (
    -- first find the spots where there could be cancellation
    nonminimals := for k in keys B list (
        (i,d,j) := k;
        if B#?(i+1,d,j) then k else continue
        );
    Bs := {B};
    for k in nonminimals do (
        Bs = flatten for B in Bs list smallerTables1(B, k);
        );
    Bs
    )

