    Indices := edges Rn.ReactionGraph;
    N := matrix{for i from 1 to length(Rn.Complexes) list 0_ZZ};
    A := mutableMatrix (N**transpose N);
    for i from 0 to length(Indices)-1 do A_(toSequence(Indices_i)) = 1;
