    N := matrix{for i from 1 to length(Rn.Complexes) list 0_(Rn.ReactionRing)};
    A := mutableMatrix (N**transpose N);
    for i from 0 to length(Rn.ReactionRates)-1 do A_(toSequence(Indices_i)) = Rn.ReactionRing_(NumVars+i);
