      Rcox := ring Jcan;
      part1 := rank source basis({1,0},Rcox);
      part2 := rank source basis({1,1},Rcox)-2*part1;
      k := part1+part2+1;
      f := g-k+1;
    -- computation of the degreeLimit
      e := balancedPartition(k-1,g-k+1);
      degLimit := toList(coxDegrees({k,f-2},e));  
