                    cols := toList(0..rank source M0-1);
                    M = M0_(select(cols,j -> ((degrees source M0)_j)_0 == degsH_(i-1)));
		    if (rank source M < rkSyzModules(1+i,k) ) then error("DegreeLimit too low");
