    e := balancedPartition(k-1,g-k+1);
    degLimit := toList(coxDegrees({k,f-2},e));  
    degsH := toList(3..(k-2))|{k}; -- twists of H
    lengthRes := floor((k-4)/2); -- half of the resolution
    resX := for i from 0 to lengthRes list (
                    if i == 0 then M:= gens Jcan
		    else (
	            M0 := syz(M,DegreeLimit => degLimit);
                    cols := toList(0..rank source M0-1);
                    M = M0_(select(cols,j -> ((degrees source M0)_j)_0 == degsH_(i-1)));
		    if (rank source M < rkSyzModules(1+i,k) ) then error("DegreeLimit too low");
                    M));
