multTableOneOne(Ring) := opts -> A -> (
   if not (A.cache#?"l" and A.cache#?"m" and A.cache#?"n") then
      error "Expected an algebra created with a resLengthThree routine.";
   l := A.cache#"l";
   m := A.cache#"m";
   n := A.cache#"n";

   eVector := matrix {apply(m, i -> A_i)};
   oneTimesOneA := table(m,m, (i,j) -> if i <= j then (A_i)*(A_j) else if opts.Compact then "." else (A_i)*(A_j));
   topLine := {{" "} | flatten entries eVector};
   sideLine := entries transpose eVector;
   result := (topLine | apply(sideLine,oneTimesOneA, (i,j) -> i | j));

   if (opts.Labels) then result else oneTimesOneA

)

multTableOneTwo(Ring) := opts -> A -> (
   if not (A.cache#?"l" and A.cache#?"m" and A.cache#?"n") then
      error "Expected an algebra created with a resLengthThree routine.";
   l := A.cache#"l";
   m := A.cache#"m";
   n := A.cache#"n";
   eVector := matrix {apply(m, i -> A_i)};
   fVector := matrix {apply(l, i -> A_(m+i))};
   oneTimesTwoA := matrix table(m,l,(i,j) -> (A_i)*(A_(m+j)));
   -- put on the row and column labels for fun
   result := matrix entries ((matrix {{0}} | fVector) || ((transpose eVector) | oneTimesTwoA));
   if (opts.Labels) then entries result else entries oneTimesTwoA
)

resLengthThreeAlg(Complex, List) := (F, sym) -> (
   if F.cache#?"Algebra Structure" then return F.cache#"Algebra Structure";
   if length F != 3 then
     error "Expected a chain complex of length three which is free of rank one in degree zero.";
   if #sym != 3 or any(sym, s -> (class baseName s =!= Symbol))  then
     error "Expected a list of three symbols.";
   mult := multTables(F);
   Q := ring F;
   m := numcols F.dd_1;
   l := numcols F.dd_2;
   n := numcols F.dd_3;        
   degreesP := if isHomogeneous F then 
                  flatten apply(3, j -> apply(degrees source F.dd_(j+1), d -> {j+1} | d))
	       else
	          flatten apply(3, j -> apply(degrees source F.dd_(j+1), d -> {0} | d));
   skewList := toList((0..(m-1)) | ((m+l)..(m+l+n-1)));
   e := baseName (sym#0);
   f := baseName (sym#1);
   g := baseName (sym#2);
   -- use this line if you want to ensure that 'basis' works properly on the returned ring.
   --P := first flattenRing (Q[e_1..e_m,f_1..f_l,g_1..g_n,SkewCommutative=>skewList, Degrees => degreesP, Join => false]);
   P := Q[e_1..e_m,f_1..f_l,g_1..g_n,SkewCommutative=>skewList, Degrees => degreesP, Join => false];
   eVector := matrix {apply(m, i -> P_(i))};
   fVector := matrix {apply(l, i -> P_(m+i))};
   gVector := matrix {apply(n, i -> P_(m+l+i))};

   eeGens := flatten entries (matrix {flatten entries (-((transpose eVector) * eVector))} - fVector*(mult#0));
   efGens := flatten entries (matrix {flatten entries (((transpose eVector) * fVector))} - gVector*(mult#1));

   I := (ideal eeGens) +
        (ideal efGens) +
	(ideal apply(m..(m+l-1), i -> P_i))^2 +
	(ideal apply(0..(m-1), i -> P_i))*(ideal apply((m+l)..(m+l+n-1), i -> P_i)) + 
	(ideal apply(m..(m+l-1), i -> P_i))*(ideal apply((m+l)..(m+l+n-1), i -> P_i)) +
	(ideal apply((m+l)..(m+l+n-1), i -> P_i))^2;
   I = ideal mingens I;
   A := P/I;
   A.cache#"l" = l;
   A.cache#"m" = m;
   A.cache#"n" = n;
   F.cache#"Algebra Structure" = A;
   A
)

resLengthThreeAlg( Complex ) := (F) -> (
    resLengthThreeAlg(F, {getSymbol "e", getSymbol "f", getSymbol "g" })
    )

resLengthThreeTorAlg(Complex,List) := (F,sym) -> (
   if F.cache#?"Tor Algebra Structure" then return F.cache#"Tor Algebra Structure";
   A := resLengthThreeAlg(F,sym);
   P := ambient A;
   Q := ring F;
   kk := coefficientRing first flattenRing Q;
   PP := kk monoid P;
   I := ideal mingens sub(ideal A, PP);
   B := PP/I;
   B.cache#"l" = A.cache#"l";
   B.cache#"m" = A.cache#"m";
   B.cache#"n" = A.cache#"n";
   F.cache#"Tor Algebra Structure" = B;
   B
)

resLengthThreeTorAlg( Complex ) := (F) -> (
    resLengthThreeTorAlg(F, {getSymbol "e", getSymbol "f", getSymbol "g" })
    )

resLengthThreeTorAlgClass Complex := F -> (
  A := resLengthThreeTorAlg(F);
  p := rank multMap(A,1,1);
  q := rank multMap(A,1,2);
  r := rank homothetyMap(A,2,1);
  tau := first tauMaps(A,1,1,1);
  if (p >= 4 or p == 2) then
      return ("H(" | p | "," | q | ")")
  else if (p == 3) then
  (
      if (q > 1) then return ("H(" | p | "," | q | ")")
      else if (q == 1 and r != 1) then return "C(3)"
      else if (q == 0 and tau == 0) then return ("H(" | p | "," | q | ")")
      else return "T";
  )
  else if (p == 1) then
  (
      if (q != r) then return "B"
      else return ("H(" | p | "," | q | ")");
  )
  else if (p == 0) then
  (
      if (q != r) then return ("G(" | r | ")")
      else return ("H(" | p | "," | q | ")");
  );
)

resLengthThreeTorAlgClass Ideal := I -> (
   resLengthThreeTorAlgClass freeResolution I
)

depthsOfPowers(ZZ,ZZ,Ideal) := (s,c,I) ->(
    --c should be codim I
    S := ring I;
    apply(s-c+1, j->depth(S^1/I^(j+1)))
    )

genericArtinNagata(ZZ,Ideal) := (s,I) -> (
    needsPackage "MCMApproximations";
    S := ring I;
    K := genericResidual(s,I);
    s' := codim K;
    if s' === s then 
      codepth := (numgens (ring K) -s) - depth ((ring K)^1/K)
    else codepth = -1;
    {codepth,K}
    )

genericResidual(ZZ,Ideal):= (s,I) ->(
    --computes a generic residual 
    S := ring I;
    sgens := sort gens I;
    rgens := (sgens)*random(source sgens, S^{ -1}**source sgens);
    n := numcols rgens;
    if s <= n then return ((ideal (rgens_{n-s..n-1})):I);
    d :=  max flatten (degrees gens I)_1;
    rgens = (rgens | sgens *random(source sgens, S^{(s-n):-d-1}));
    (ideal rgens):I
    )

hasSlidingDepth(ZZ,Ideal) := (k,I) -> (
    d := dim I;
    s := numColumns(mingens I)-codim I;
    -- s = numgens(I) - codim(I) is the top index of nonvanishing Koszul
    -- homology, so the sliding depth condition saturates at k = s; clamp k
    -- there to keep the loop below from probing Koszul homology in negative
    -- degree (this line previously read "if k >= s then k;", a no-op)
    if k >= s then k = s;
    all(k, i -> (koszulDepth(s-i-1,I))>=d-i-1)
    )

isLicci(ZZ, ZZ, Ideal) := opts -> (b,c,I) -> (
    --I homogeneous ideal
    --b = linkageBound I
    --c = codim I
    --output is list of up to b integers, the numbers of generators of the
    --successive random links
    J := I;
    -- a complete intersection (numgens == codim) is licci; detect it up front,
    -- since randomLink would link it to the unit ideal and the test below
    -- would then wrongly report it as not licci
    if numgens J == c then return true;
    p := numgens J;
    count := 0;
--    <<p<<endl;flush;
    scan(b, i -> (count = i+1;
	    J = randomLink(c,J);
	    if numgens J == c then break;
	    if Verbose === true then <<numgens J<<endl<<flush;
	    ));
   if Verbose === true then <<" done in "<< count << " steps"<<endl;
   c == numgens J)

isLicci Ideal := opts -> I -> (
isLicci(linkageBound(I, UseNormalModule => opts.UseNormalModule), I, Verbose => opts.Verbose
    ))

isStronglyCM(Ideal) := I -> (
    J := trim I;
    c := codim J;
    d := dim J;
    m := numgens J;
    C := koszul gens J;
    result := true;
    scan(m-c, i-> if depth HH_i(C)<d then (result = false; break;)); 
    return result;
    )

koszulDepth Ideal := I -> (
    if I==0 then return {};
    J := trim I;
    m := numgens J;
    C := koszul gens J;
    c := codim J;
    for i in 0..m-c-1 list depth prune HH_i(C)
    )

koszulDepth(ZZ,Ideal) := (k,I) -> (
    if I==0 then return {};
    C := koszul mingens I;
    depth HH_k(C)
    )

linkageBound Ideal := opts -> I -> (
if opts.UseNormalModule == false then
    max(0, 2*(codim I)*(degree I -1) -6)
 else (
	N := prune Hom(I, (ring I)^1/I);
	max(0, 2*(numgens N - codim I)-6))
)

maxGs MonomialIdeal := J -> (
    for i from 1 to numgens ring J do if numgensByCodim(J,i) > i then return i;
    infinity
    )

numgensByCodim (MonomialIdeal,ZZ) := (J,k) -> (
    R := ring J;
    n := numgens R;
    max for A in subsets(n,k) list (
	M := new MutableList from (n:1_R);
	for a in A do M#a = R_a;
	M = map(R,R,matrix{toList M});
	numgens trim M J
	)
    )

numgensByCodim MonomialIdeal := J -> (
    n := numgens ring J;
    toList apply(n, i->numgensByCodim(J,i+1))
    )

residualCodims MonomialIdeal := J -> (
    toList select((codim J + 1..numgens ring J + 1), i->numgensByCodim(J,i-1) <= i)
    )

