modificationRule = (lambda, n, type) -> (
     if type == "C" then sswTypeC(lambda, n)
     else if type == "B" then sswTypeBD(lambda, 2*n+1)
     else if type == "D" then sswTypeBD(lambda, 2*n)
     else error("modificationRule: unknown type " | toString type)
     )

