connectedComponents HyperGraph := H -> (
     V := select(H#"vertices", v-> any(H#"edges", e -> member(v,e)));
     while #V > 0 list (
       C := {V#0};
       i := 0;
       while i < #C do (
         N := select(neighbors(H, C#i), v-> not member(v,C));
         C = join(C,N);
         i = i+1;
       );
       V = select(V, v -> not member(v,C));
       rsort C
       )
     )

connectedComponents Graph := List => G -> (
    V := vertexSet G;
    while #V != 0 list (
        C := {first V};
        i := 0;
        while i!= #C do (
            N := toList neighbors(G, C_i);
            C = unique(C | N);
            V = V - set C;
            i = i + 1;
            if #V == 0 then break;
            );
        C
        )
    )

connectedComponents Poset := List => P -> (
    if not P.cache.?connectedComponents then (
        C := new MutableList from apply(toList(0 ..< #P.GroundSet), i -> {i});
        Q := toList(0 ..< #P.GroundSet);
        if not P.cache.?coveringRelations then coveringRelations P;
        cr := P.cache.coveringRelations;
        while (#cr > 0 and #Q > 1) do (
            i := first first cr;
            j := last first cr;
            C#j = unique join(C#i, C#j);
            cr = apply(drop(cr, 1), c -> { if c_0 == i then j else c_0, if c_1 == i then j else c_1 });
            Q = unique replace(position(Q, k -> k == i), j, Q);
            );
        P.cache.connectedComponents = (toList C)_Q;
        );
    apply(P.cache.connectedComponents, r -> P.GroundSet_r)
    )

connectedComponents SimplicialComplex := D -> ( 
    if dim D < 0 then return {D};
    R := ring D;
    H := new MutableHashTable;
    for F in facets D do (
    	if all(keys H, h -> gcd(F, H#h) == 1_R) then H#F = F
    	else (
	    L := {};
	    for k in keys H do if not (gcd(F, H#k) == 1_R) then L = append(L, k);
	    m := lcm append(L, F);
	    for l in L do remove(H, l);
	    H#m = m;
	    )
	);
    for k in keys H list inducedSubcomplex(D, support H#k)
    )

dunceHatComplex PolynomialRing := SimplicialComplex => S -> (
