    MO := opts.MonomialOrder;
    R := QQ(monoid[vars(0..#L-1)]);
    if opts.MonomialOrder == {}
    then complex(lyubeznikSimplicialComplex(L,R),Labels=>L)
    else complex(lyubeznikSimplicialComplex(L,R),Labels=>L_MO)
