        X.cache#(surface X,"label") = 6;
        return X;
    );
    if str === "rho-plane" then (
        X = gushelMukaiFourfold(schubertCycle({2,2},G),InputCheck=>o.InputCheck,Verbose=>o.Verbose);
        X.cache#(surface X,"label") = 9;
        return X;
