beilinsonContraction(RingElement, List, List) := opts -> (e, rowdeg, coldeg) -> (
    if e != 0 and degree e + rowdeg != coldeg then error "degrees in 'beilinsonContraction' are incorrect";
    E := ring e;
    tD := tateData E;
    (t,v,n,varsList,irrList) := ringData E;
    S := first tD.Rings;
    edeg := coldeg - rowdeg;
    if opts.BundleType === PrunedQuotient then (
        (mc, mr, changemat) := contractionData(rowdeg, coldeg, ring e, opts);
        missing := for i from 0 to t-1 list if rowdeg#i == 0 and coldeg#i == 0 then 1 else 0;
        signchange1 := sum(0..t-2, i -> edeg#i * sum(i+1..t-1, j -> missing#j));
        signchange := if odd signchange1 then -1 else 1;
        if e == 0 then
            map(S^(numgensU(rowdeg,E,opts)), S^(numgensU(coldeg,E,opts)), 0)
        else
            changemat * signchange * substitute(contract(diff(e, mc), mr), S)
        )
    else if opts.BundleType === QuotientBundle or opts.BundleType === DummyQuotientBundle then (
        (mc, mr) = contractionData(rowdeg, coldeg, ring e, opts);
        if e == 0 then
            map(S^(numgensU(rowdeg,E,opts)), S^(numgensU(coldeg,E,opts)), 0)
        else
            substitute(contract(diff(e, mc), mr), S)
        )
    else if opts.BundleType === FreeBundle then (
       	(mc, mr) = contractionData(rowdeg, coldeg, ring e, opts);
        if e == 0 then
            map(S^(numgensU(rowdeg,E,opts)), S^(numgensU(coldeg,E,opts)), 0)
        else
	 --(
	      --print substitute(contract(diff(e, mc), mr), S);
--	   print endl;   
--	   print substitute(contract(mc,e*mr),S));
	  substitute(contract(diff(e, mc), mr), S) 
        )
    else if opts.BundleType === SubBundle then (
        -- implemented exactly same as Free bundle; CHECK later on extreme degrees
	(mc, mr) = contractionData(rowdeg, coldeg, ring e, opts);
        if e == 0 then
            map(S^(numgensU(rowdeg,E,opts)), S^(numgensU(coldeg,E,opts)), 0)
        else
            substitute(contract(diff(e, mc), mr), S)
        )
    else error "what?"
    )

beilinsonWindow Complex := (C)-> (
    tD := tateData ring C;
    (S,E) := tD.Rings;
    (minC, maxC) := concentration C;
    windows := for i from minC to maxC list (
        degs := degrees C_i;
        positions(degs, a -> inBeilinsonWindow(a,E))
        );
    maps := hashTable for i from minC + 1 to maxC list (
        rowPositions := windows_(i-minC-1);
        colPositions := windows_(i-minC);
        if #rowPositions === 0 then continue
        else
            i => submatrix(C.dd_i, rowPositions, colPositions)
        );

    complex maps
    )

bgg Module := Complex => o -> P -> (
    (S,E) := (tateData ring P)#Rings;
    D := null; 
    Ds := null;
    freeModuleDegs := null;
    tar := null;
    sour := null;
    utar := 0;
    usour := null;
    a := 0;
    a':= 0;
    u := null;
    modules := new MutableHashTable;
    maps := null;
    if ring P === E then (
        D = (degrees basis P)_1;
        Ds = sort apply(D, d->(sum d,d));
        minP := min(Ds/first);
        maxP := max(Ds/first);
        if o.LengthLimit =!= null then
            maxP = min(maxP,minP+1+o.LengthLimit);
        freeModuleDegs = hashTable apply(toList(minP..maxP), 
            i -> (-i => select(Ds, d-> d_0 == i)/last)
	    );
        --define the modules as direct sums, with one degree per summand
        for i from minP to maxP do
	    modules#(-i) = directSum apply(unique freeModuleDegs#(-i), 
                d -> S^(select(freeModuleDegs#(-i), k -> d == k))
                );
        if minP === maxP then return complex(modules#(-minP), Base => -minP);
        maps = hashTable for k from -maxP+1 to -minP list k => (
            tar = modules#(k-1);
            sour = modules#k;
            utar = unique degrees tar;
            usour = unique degrees sour;
	    sum(#utar, i->
                sum(#usour, j->(
                        a' = -utar_i;
                        a = -usour_j;
                        map(tar,sour,
                            tar_[i]*multMap(P,a',a)*(sour^[j])
                            )
                )))
            );
        return complex maps
        );
    if ring P =!= S then 
        error "expected ring created with 'productOfProjectiveSpaces'";

    -- at this point ring P is S.
    LengLim := if o.LengthLimit === null 
        then 1+numgens S 
        else o.LengthLimit;
    M := P/((ideal vars S)^(LengLim+1));
    D = (degrees basis M)_1;
    Ds = sort apply(D, d->(sum d,d));
    minM := min(Ds/first);
    maxM := max(Ds/first);
    freeModuleDegs = hashTable apply(toList(minM..maxM),
        i -> (-i => select(Ds, d-> d_0 == i)/last)
        );
    for i from minM to maxM do
        modules#(-i) = directSum apply(unique freeModuleDegs#(-i), 
            d -> E^(select(freeModuleDegs#(-i), k -> d == k))
            );
    if minM === maxM then return complex(modules#(-minM), Base => -minM);
    maps = hashTable for k from -maxM+1 to -minM list k => (
        tar = modules#(k-1);
        sour = modules#k;
        utar = unique degrees tar;
        usour = unique degrees sour;
        sum(#utar, i->
            sum(#usour, j->(
                    a' = -utar_i;
                    a = -usour_j;
                    map(tar,sour,
                        tar_[i]*multMapE(M,a',a)*(sour^[j])
                        )
                    )))
        );
    complex maps
    )

coarseMultigradedRegularity Complex := o-> F -> (
    --we assume F starts in homological degree 0.
    t := degreeLength ring F;
    range := toList(min F..max F-1);
    degsF := flatten apply(range,i -> degrees (F_i));
