lowerCorner(Complex,List) := (F,deg) ->(
     E:=ring F;
     degsE:= unique degrees E;
     n:=apply(degsE,dege->#select(degrees E,d->d==dege)-1);
     assert(
	  #(degrees E)_0 == # deg
	  );
     -- sign change for k
     k:= sum deg;
     degsa:=degrees F_(-k);
     -- sign change -deg_j three times and inequalities
     L1:=select(#degsa,i->#select(#deg,j->degsa_i_j==-deg_j)==#deg);
     degsb:=degrees F_(-k+1);
     L2:=select(#degsb,i->#select(#deg,j->degsb_i_j<=-(deg_j-n_j-1) and degsb_i_j>=-deg_j)==#deg);
     ((F.dd_(-k+1))^L1)_L2
     )

productOfProjectiveSpaces(List) := opts -> n -> (
     kk := opts.CoefficientField;
     x:= opts.Variables#0; -- symbol x;
     e:= opts.Variables#1; -- symbol e;
     h := opts.CohomologyVariables#0; -- symbol h
     k := opts.CohomologyVariables#1; -- symbol k
     t:= #n;
     xx:=flatten apply(t,i->apply(n_i+1,j->x_(i,j)));
     degs:=flatten apply(t,i->apply(n_i+1,k->apply(t,j->if i==j then 1 else 0)));
     S:=kk[xx,Degrees=>degs];
     ee:=flatten apply(t,i->apply(n_i+1,j->e_(i,j)));
     E:=kk[ee,Degrees=>degs,SkewCommutative=>true];
     CR := ZZ[h,k];
     tateData := new MutableHashTable;
     tateData#Rings = (S,E);
     tateData#CohomRing = CR;
     tateData#BeilinsonBundles = new MutableHashTable;
     S.TateData = tateData;
     E.TateData = tateData;
     (S,E))

regionComplex(Complex,List,Sequence) := (T,c,IJK) -> (
    T1:=trivialHomologicalTruncation(T,nonzeroMin T, nonzeroMax T);
    T2:=T1[min T1];
    Ls:=apply(toList(min T2..max T2),k->goodColumns(T2_k,c,IJK));
    rT:=complex apply(toList(min T2+1..max T2),k-> ((T2.dd_k))^(Ls_(k-1))_(Ls_(k)));
    rT[-min T1])

symExt(Matrix,Ring) := (m,E) -> (
     ev := map(E,ring m,vars E);
     mt := transpose jacobian m;
     jn := ev(syz mt);
     a:=(vars E**E^(rank target m));
--betti a,tally degrees source a, isHomogeneous a
--betti jn, tally degrees target jn, tally degrees source jn, isHomogeneous jn
--tally(     degrees target jn+degrees source a)
     b:=a*jn;
--betti b, tally degrees target b, tally degrees source b
     c:=map(target b,E^(degrees source jn),b);
     transpose c)

tateExtension(Complex) := W -> (
    -- input W : a Beilinson representative of an object in D^b(PP)
    -- output :  an Tate extension in a bounded range
    -- compute the TateExtension in a sloppy way: the Beilinson window of the extension is only
    -- isomorphic, bat not equal W.
    (t,v,n,irrList,idealList) := ringData ring W;
    if not inWindow W then error "expect a complex with terms only in the Beilinson window";
    W1 := removeZeroTrailingTerms W;
    -- W1:= W;
    TW1:=pushAboveWindow W1;
    ma:= nonzeroMax TW1; 
    mi:=nonzeroMin TW1;
    --betti W1,betti TW1
--Bbounds given for the length of the resolution have to be discussed
--They should come out of the proof of the theorem !!
    TW1e := freeResolution(coker TW1.dd_(ma),LengthLimit=>(3*sum v))[-ma];
    --betti TW1e
    --changed a sign here
    --TW1c := cornerComplex(TW1e,2*v);
    TW1c := cornerComplex(TW1e,-2*v); -- replace with upper quad cplx
--cohomologyMatrix(TW1c, -4*v,4*v)
    --betti TWc
    TW2 := dual freeResolution(coker transpose TW1c.dd_(ma+sum v),
	LengthLimit =>(ma+3*sum v -mi))[-ma-sum v+1];
--cohomologyMatrix(TW2, -4*v,4*v)
    --betti TW2
    TW2
    )

tateResolution(Matrix, List, List) := (A, low, high) -> (
    -- if we have a map A : M -> N between two modules, 
    -- then compute the induced map T(A) : T(M) -> T(N)
    M := source A;
    N := target A;
    (S,E) := (tateData ring M)#Rings;
    regM := coarseMultigradedRegularity M;
    regN := coarseMultigradedRegularity N;

    hi := apply (#high, i->max(regM_i, regN_i, high_i+1));
    linearPresentationM := presentation truncate(hi, M)**S^{hi};
    linearPresentationN := presentation truncate(hi, N)**S^{hi};
    truncatedMapMtoN := (truncate(hi, A)**S^{hi});

    QM := symExt(linearPresentationM,E);
    QN := symExt(linearPresentationN,E);
    CM := (freeResolution (coker QM,LengthLimit=>(sum hi-sum low)));
    CN := (freeResolution (coker QN,LengthLimit=>(sum hi-sum low)));

    extPos := extend(CN[1], CM[1], map(CN_1, CM_1, sub(matrix truncatedMapMtoN, E)));
    extNeg := dual extend(dual CM[-1], dual CN[-1], transpose sub(matrix truncatedMapMtoN,E));
    -- shift does not change the sign of map of complexes
    extAll := map(CN, CM, i->(if i<1 then extNeg_(i-1) else extPos_(i-1)));

    (extAll**E^{hi})[sum hi-#regM+2]
    )

trivialHomologicalTruncation(Complex,ZZ,ZZ) := (C,d,e) -> (
    F := C;
    -- given a chain complex
    -- ... <- C_{k-1} <- C_{k} <- C_{k+1} <- ...
    -- return the trivial truncation
    --   0 <- C_d <- C_{d+1} <- ... < C_e <- 0
    if d>e then error "expect d <= e";
    while min F > d do (F =prependZeroMap F);
    while max F < e do (F=appendZeroMap F);
    G := F[d];
    if d==e then (G= prependZeroMap complex G_0) else (
	G=prependZeroMap appendZeroMap complex apply(toList(1..e-d),k->G.dd_k));
    G[-d])

upperCorner(Complex,List) := (F,deg) ->(
     E:=ring F;
     degsE:= unique degrees E;
     n:=apply(degsE,dege->#select(degrees E,d->d==dege)-1);
     assert(
	  #(degrees E)_0 == # deg
	  );
     -- sign change for k
     k:=sum deg;
     degsa:=degrees F_(-k-1);
     -- sign change -deg_j three times and inequalities
     L1:=select(#degsa,i->#select(#deg,j->degsa_i_j <= -deg_j and degsa_i_j >= -(deg_j+n_j+1) )==#deg);
     degsb:=degrees F_(-k);
     L2:=select(#degsb,i->#select(#deg,j->degsb_i_j==-deg_j)==#deg);
     ((F.dd_(-k))^L1)_L2
     )

cauchyMap (ZZ, LabeledModule) := (b,E) -> (
  sour := exteriorPower(b,E);
  L := underlyingModules E;
  L10 := {exteriorPower(b,L#0)};
  L11 := apply(#L-1, j -> symmetricPower(b,L#(j+1)));
  L = L10 | L11;
  targ := tensorProduct L;
  M := mutableMatrix(ring E, rank targ, rank sour);
  local j;
  for i in basisList sour do (
    j = transpose i;
    if j#0 == unique j#0 then (
      j = apply(j, l -> sort l);
      M_(toOrdinal(j,targ), toOrdinal(i,sour)) = 1));
  map(targ, sour, matrix M))

flattenedESTensor (List, Ring) := LabeledModuleMap => o-> (L,kk)->(
  --make ring of generic tensor
  if #L === 0 then error "expected a nonempty list";
  if #L === 1 then error "expected a balanced tensor";
  n:=#L-1;
  x:=symbol x;
  S:=kk[x_0..x_(n-1), MonomialSize=>o.MonSize];
  Blist := apply(#L, i->labeledModule S^(L_i));
  --B = tensor product of all but Blist_0
  B := tensorProduct apply(#L-1, i -> Blist_(i+1));     
  map(B, Blist_0, 
      (i,j) -> if 0<=j-sum fromOrdinal(i,B) then if j-sum fromOrdinal(i,B)<n 
      then x_(j-sum fromOrdinal(i,B)) else 0 else 0)
 )

flattenedGenericTensor (List, Ring) := LabeledModuleMap => (L,kk)->(
  --make ring of generic tensor
  if #L === 0 then error "expected a nonempty list";
  inds := productList apply(#L, i -> toList(0..L#i-1));
  x := symbol x;
  vrbls := apply(inds,i -> x_(toSequence i));
  local S;
  if #L === 1 then S=kk[x_0..x_(L_0-1)] 
  else S = kk[vrbls];
  --make generic tensor (flattened)
  Blist := apply(#L, i->labeledModule S^(L_i));
  --B = tensor product of all but Blist_0
  if #L === 1 then map(labeledModule S,Blist_0, vars S)
  else(
    B := tensorProduct apply(#L-1, i -> Blist_(i+1));     
    map(B, Blist_0, 
      (i,j) -> x_(toSequence({fromOrdinal(j, Blist_0)}| fromOrdinal(i, B))))))

hyperdeterminant LabeledModuleMap := f -> (
     --hyperdeterminant of a boundaryformat tensor f
     --check boundary format
     b := apply(underlyingModules target f, M -> rank M);
     if not rank source f == 1 + sum b - #b then
     	  error"not boundary format!";
     w := {0,1}|apply(toList(2..#b), i-> sum(toList(0..i-2), j-> b_j)-(i-2));
     det matrix tensorComplex1 (f,w))

hyperdeterminantMatrix LabeledModuleMap := f -> (
     --check boundary format
     b := apply(underlyingModules target f, M -> rank M);
     if not rank source f == 1 + sum b - #b then
     	  error"not boundary format!";
     w := {0,1}|apply(toList(2..#b), i-> sum(toList(0..i-2), j-> b_j)-(i-2));
     matrix tensorComplex1 (f,w))

minorsMap(Matrix, LabeledModule):= LabeledModuleMap => (f,E) -> (
  --Assumes that E has the form 
  --E = wedge^b((source f)^*) ** wedge^b(target f)
  --where source f and target f are labeled free modules.
  S := ring f;
  b := #((basisList E)_0_0);
  if b != #((basisList E)_0_1) or #((basisList E)_0) != 2
  then error "E doesn't have the right format";
  J := basisList E;
  sour := (underlyingModules((underlyingModules E)_0))_0;
  tar := (underlyingModules((underlyingModules E)_1))_0;
  map(labeledModule S, E, (i,j)-> (
      p := J_j;
      det submatrix(f, apply(p_1, k-> toOrdinal(k, tar)),
	apply(p_0, k-> toOrdinal(k, sour))))))

pureResES (List,Ring):=Complex => (d,kk)->(
     res coker matrix pureResES1(d,kk)
     )

pureResES1 (List,Ring) := LabeledModuleMap => o -> (d,kk)->(
     b := apply(#d-1,i-> d_(i+1)-d_i);
     if min b<=0 then error"d is not strictly increasing";
     a := d_(#b) - d_0;
     f := flattenedESTensor({a}|b,kk,MonSize => o.MonSize);
     tensorComplex1(f)
     )

pureResTC (List,Ring):=Complex => (d,kk)->(
     res coker matrix pureResTC1(d,kk)
     )

pureResTC1 (List,Ring) := LabeledModuleMap =>(d,kk)->(
     b := apply(#d-1,i-> d_(i+1)-d_i);
     if min b<=0 then error"d is not strictly increasing";
     a := d_(#b) - d_0;
     f := flattenedGenericTensor({a}|b,kk);
     tensorComplex1(f)
     )

symmetricMultiplication (LabeledModule,ZZ,ZZ) := (F,d,e) -> (
  --make the map Sym^d(F)\otimes Sym^e F \to Sym^(d+e) F
  --Caveat: for large examples it would probably be better to make this as a sparse matrix!
  S := ring F;
  Sd := symmetricPower(d,F);
  Se := symmetricPower(e,F);
  Sde := symmetricPower(d+e,F);
  SdSe := tensorProduct {Sd,Se};
  map(Sde,SdSe, 
    (i,j) -> if fromOrdinal (i,Sde) == sort flatten fromOrdinal(j, SdSe) 
    then 1_S else 0_S))

tensorComplex1 (LabeledModuleMap,List) := LabeledModuleMap => (f,w) -> (
  -- NOTE: local variables names following the notation from the
  -- Berkesch-Erman-Kummini-Sam "Tensor Complexes" paper
  -- 
  -- f: A --> B1** B2** ... Bn
  -- makes the map F0 <- F1 as above.
  -- w = (0,w1,...).  w must satisfy some technical conditions that are checked below.
  -- These technical conditions also appear in the documentation node for this function.
  if not w_0 == 0 and w_1 >=0 and min apply(toList(2..#w), i-> w_i-w_(i-1)) > 0 then 
      error "w not of the form (0,non-neg,increasing)";

  S := ring f;  
  B := {S^0} | underlyingModules target f;
  A := source f;
  a := rank A;
  n := #B-1;
  if #w != n+1 then error"weight vector has wrong length";
  b := B / rank; -- {0, b1, b2,..,bn}

  d1 := if w_1>0 then 1 else b_1;
  r1 := # select(w, wj -> wj < d1);
  if r1>2 then error "r1>2 is a case we can't handle";
  if n === 0 or n===1 and r1 ===1 then return f;
  if n === 1 and r1 === 2
      then return map(exteriorPower(b_1,B_1),exteriorPower(b_1,A)**labeledModule(S^{ -d1}), gens minors(b_1,matrix f));

    F1 := tensorProduct({exteriorPower(d1,A)}|
	 apply(toList(1..r1-1),j-> exteriorPower(b_j,B_j)) | -- r1 = 1 or 2
      apply(toList(r1..n), j-> symmetricPower(w_j-d1,B_j)));
    F0 := tensorProduct apply(n, j-> symmetricPower(w_(j+1), B_(j+1)));
    --  F1 is the source of the output map, and F0 is the target.
    trMap := traceMap tensorProduct apply(toList(r1..n), 
      j -> symmetricPower(d1,B_j));
    G1 := tensorProduct(target trMap, F1);
    g0 := map(G1, F1, trMap ** id_F1);
    G1factors := flatten(
      ((underlyingModules target trMap) | {F1}) / underlyingModules );
    -- G2 and G1 are isomorphic as free modules with ordered basis but different
    -- as labeled modules.  G2 is obtained from G1 by dropping parentheses in 
    -- the tensor product.
    G2 := tensorProduct G1factors;
    -- g1 is the isomorphism induced by dropping all parentheses in the tensor product.
    -- Due to indexing conventions, matrix(g1) is just an identity matrix.
    g1 := map(G2, G1, id_(S^(rank G1)));
    perm := {};
    if r1==2 then perm = join({2*n-2, 2*n-1}, toList(0..n-2), 
      flatten apply(n-1, j -> {j+n-1, j+2*n}))
    else  perm ={2*n}|toList(0..n-1)|flatten apply(n, j -> {j+n, j+2*n+1});
    G3factors := G1factors_perm;
    G3 := tensorProduct G3factors;
    -- G3 is obtained from G2 by reordering the factors in the tensor product.
    -- g2 is the isomorphism induced by reordering the factors of the tensor product.
    -- The reordering is given by the permutation 'perm'.  
    permMatrix := mutableMatrix(S, rank G3, rank G2);
    for J in basisList G2 do permMatrix_(toOrdinal(J_perm,G3),toOrdinal(J,G2)) = 1;
    g2 := map(G3, G2, matrix permMatrix);
    --  G3=G3a**G3b**G3c. The map g3: G3->G4 is defined as the tensor product of 3 maps.
    G3a := G3factors_0;
    G3b := tensorProduct G3factors_(toList(1..n));
    G3c := tensorProduct G3factors_(toList(n+1..#G3factors-1));
    prodB := tensorProduct apply(n,i -> B_(i+1));  
    -- G4=G3a**G4b**G3c.
    G4b := exteriorPower(d1, prodB);
    G4 := tensorProduct({G3a,G4b,G3c});
    dualCauchyMap := map (G4b, G3b, transpose cauchyMap(d1, prodB));
    g3 := id_(G3a) ** dualCauchyMap ** id_(G3c); 
    -- G5 is obtained from G4 by adding parentheses in the tensor product.
    --  the map g4: G4->G5 is simply represented by an identity matrix.
    G5 := (G3a**G4b)**G3c;
    g4 := map(G5,G4,matrix id_(G4));
    symMultMap := map(F0, G3c, tensorProduct apply(toList(r1..n), 
      	j -> symmetricMultiplication(B_j,d1,w_j-d1)));
    minMap := minorsMap(f, tensorProduct(G3a, G4b));
    g5 := minMap ** symMultMap;
    --  the source of minMap is (G3a**G4b).  the source of symMultMap is G3c.
    map(F0, F1 ** labeledModule S^{ -d1}, g5 * g4 * g3 * g2 * g1 * g0))

tensorComplex1 LabeledModuleMap := LabeledModuleMap => f -> (
  -- The output is the first map F0 <- F1 of the balanced tensor complex.
  -- If f is not balanced this outputs an error.  
  -- If f is balanced, then this computes the appropriate weight w, and calls the other
  -- version of this method.
  if not isBalanced f then error "The map f is not a balanced tensor. Need to add a weight vector as a second input.";
  S := ring f;
  B := {S^0} | underlyingModules target f;
  n := #B-1;
  b := B/rank; --- {0,b1,b2,..,bn}
  w := {0}|accumulate(plus,{0}|b_(toList(0..#b-2)));  --{0,0,b1,b1+b2,...,b1+..+b(n-1)}
  tensorComplex1(f,w)
  )

tensorProduct Sequence := args -> (
  if #args === 0 then  error "expected more than 0 arguments"; -- note: can't return, since we don't know the ring!
  y := youngest args;
  key := (tensorProduct, args);
  if y =!= null and y#?key then y#key else (
    type := apply(args, class);
    if not same type then error "incompatible objects in tensor product";
    type = first type;
    meth := lookup(symbol tensorProduct, type);
    if meth === null then error "no method for tensor product";
    S := meth args;
    if y =!= null then y#key = S;
    S))

traceMap LabeledModule := LabeledModuleMap => E -> (
  S := ring E;
  T := E ** E;
  map(T, labeledModule S^1, (i,j) -> (
      I := fromOrdinal(i,T);
      if I_0 == I_1 then 1_S else 0_S)))

terraciniLocus(ZZ, Matrix, Ideal) := o -> (r, A, I) -> (
    if r < 1 then error "expected positive integer";
    if ring A =!= ring I then error "expected rings to agree";
    R := ring A;
    s := numRows A;
    t := numColumns A;
    rk := if zero I then rank A else codim I;
    n := numgens R - 1;
    Q := productOfProjectiveSpaces(toList(r : n),
	CoefficientField => coefficientRing R,
	VariableName => "z");
    if r == 1 then return ideal 1_Q;
    opts := apply(r, i -> apply(n + 1, j -> R_j => Q_((n + 1) * i + j)));
    Az := concatRows apply(r, i -> sub(A, opts#i));
    Ir := ideal apply(r, i -> sub(I, opts#i));
    result := trim(recursiveMinors(min(r * rk, t), Az, o) + Ir);
    Z := genericMatrix(Q, n + 1, r);
    duplicate := intersect apply(subsets(r, 2), ij ->
	recursiveMinors(2, Z_ij, o));
    result = saturate(result, duplicate);
    blocksingular := recursiveMinors(rk, A, o);
    singular := intersect apply(r, i -> sub(blocksingular, opts#i));
    radical result : radical singular)

testAudit Package := opts -> pkg -> (
    if opts.Experimental then return testAuditHashTable(pkg);
    -- Capture method-key info BEFORE calling `tests pkg`: `tests` reloads the
    -- package with documentation, which silently replaces the global Package
    -- and detaches methods registered on the original object.
    methodHeads := methodHeadFunctions pkg;
    inputs := tests pkg; -- returns the tests as a hashtable
    code := testCodeStringFromInputs inputs; -- concats all test code with newlines between
    sourceCode := packageSourceString pkg; -- returns string of all source code
    syms := exportedSymbols pkg; -- returns exported symbols using pkg#"exported symbols"

    funcs := select(syms, isExportedFunction); -- returns symbols with class "MethodFunc", "MethodFuncWithOptions", "FuncClosure", or "Func" (I've abbreviated the types)
    types := select(syms, isExportedType); -- returns symbols that satisfy 'class s === "Type"'
    others := select(syms, s -> not isExportedFunction s and not isExportedType s); -- is there a smarter way to do this?

    -- Methods added by this package to functions whose symbols this package
    -- does not export (e.g., a package can add (pullback, RingMap, RingMap)
    -- to the built-in `pullback` without exporting `pullback`). Restrict to
    -- identifier-style names so operator-valued method heads (++, **, _, ...)
    -- don't trip up wordMatch's `\b` regex.
    exportedFuncNames := apply(funcs, toString);
    isIdentifierName := name -> match("^[A-Za-z][A-Za-z0-9]*$", name);
    extraMethodFuncs := select(methodHeads, f -> (
        n := toString f;
        isIdentifierName n and not member(n, exportedFuncNames)
    ));
    extraMethodFuncNames := apply(extraMethodFuncs, toString);

    untestedExports := select(apply(syms, toString), name -> not wordMatch(name, code));
    untestedFunctions := select(exportedFuncNames | extraMethodFuncNames, name -> not wordMatch(name, code));

    optionPairs := flatten apply(funcs, f -> apply(optionNamesForSymbol f, opt -> {toString f, opt})) |
        flatten apply(extraMethodFuncs, f -> apply(optionNamesForFunction f, opt -> {toString f, opt}));
    untestedOptions := select(optionPairs, pair -> not wordMatch(pair#1, code));
    untestedOptionLabels := apply(untestedOptions, pair -> pair#0 | ": " | pair#1);

    silencedTests := silencedTestMatches pkg;
    fixmeTodos := taskMarkerMatches inputs;

    exportHeader := "exported: " | toString(#funcs) | " functions, " | toString(#types) | " types, " | toString(#others) | " other symbols";
    if #extraMethodFuncNames > 0 then
        exportHeader = exportHeader | "; " | toString(#extraMethodFuncNames) | " methods on external functions";

    reportLines := {
        exportHeader,
        "n_tests: " | toString(#inputs),
        "style: " | demark(", ", styleOfTests inputs),
        ""} |
        testSourceLines inputs |
        {"",
        "Report:",
        ""
        } |
        auditListLines("untested functions", untestedFunctions) |
        auditListLines("untested options", untestedOptionLabels) |
        auditListLines("silenced tests", silencedTests) |
        auditListLines("FIXME/TODO markers", fixmeTodos) |
        (if opts.ScoreReport then scoreReportLines(inputs, syms, funcs, types, others, extraMethodFuncNames, untestedExports, untestedFunctions, optionPairs, untestedOptions, silencedTests, fixmeTodos) else {}) |
        (if opts.SpeedReport then speedReportLines(pkg, inputs) else {}) |
        (if opts.CommentReport then commentReportLines inputs else {});

    report := demark(newline, reportLines);
    report
)

testScore Package := pkg -> (
    -- Capture method-keys before tests pkg reloads the package; see testAudit.
    methodHeads := methodHeadFunctions pkg;
    inputs := tests pkg;
    code := testCodeStringFromInputs inputs;
    syms := exportedSymbols pkg;
    funcs := select(syms, isExportedFunction);
    types := select(syms, isExportedType);
    others := select(syms, s -> not isExportedFunction s and not isExportedType s);

    exportedFuncNames := apply(funcs, toString);
    isIdentifierName := name -> match("^[A-Za-z][A-Za-z0-9]*$", name);
    extraMethodFuncs := select(methodHeads, f -> (
        n := toString f;
        isIdentifierName n and not member(n, exportedFuncNames)
    ));
    extraMethodFuncNames := apply(extraMethodFuncs, toString);

    untestedExports := select(apply(syms, toString), name -> not wordMatch(name, code));
    untestedFunctions := select(exportedFuncNames | extraMethodFuncNames, name -> not wordMatch(name, code));
    optionPairs := flatten apply(funcs, f -> apply(optionNamesForSymbol f, opt -> {toString f, opt})) |
        flatten apply(extraMethodFuncs, f -> apply(optionNamesForFunction f, opt -> {toString f, opt}));
    untestedOptions := select(optionPairs, pair -> not wordMatch(pair#1, code));

    silencedTests := silencedTestMatches pkg;
    fixmeTodos := taskMarkerMatches inputs;

    (scoreValues(syms, funcs, types, others, extraMethodFuncNames, untestedExports, untestedFunctions, optionPairs, untestedOptions, silencedTests, fixmeTodos))#0
)

o->() -> (
    curRing := o.CurrentRing;
    canIdeal := o.CanonicalIdeal;
    uList := o.GeneratorList;
    if ( (not (curRing === null)) and (canIdeal === null) ) then (--if no canonicalIdeal is chosen
        canIdeal = canonicalIdeal curRing;
    );
    if (canIdeal===null) then (error "HSGLModule: cannot compute the FPureModule with no arguments or optional arguments";)
    else (--if we have a canonical ideal (or built one)
        if (curRing === null) then curRing = ring canIdeal;
        if (uList === null) then ( --build the uList if needed
            S1 := ambient curRing;
            I1 := ideal curRing;
            J1 := sub(canIdeal, S1);
            uList = frobeniusTraceOnCanonicalModule(I1, J1);
        )
    );
    return internalFPureModule(curRing, canIdeal, uList, FrobeniusRootStrategy=>o.FrobeniusRootStrategy);
)

FPureModule( Ring ) := Sequence => opts -> (R1) -> (
    canIdeal := opts.CanonicalIdeal;
    uList := opts.GeneratorList;

    if (canIdeal === null) then canIdeal = trim canonicalIdeal R1;
    S1 := ambient R1;
    I1 := ideal R1;
    J1 := sub( canIdeal, S1 );
    if (uList === null) then uList = frobeniusTraceOnCanonicalModule( I1, J1 );

    return internalFPureModule(R1, canIdeal, uList, FrobeniusRootStrategy=>opts.FrobeniusRootStrategy);
);

FPureModule ( Number, RingElement ) := Sequence => opts -> ( tt, ff ) ->
(
    R1 := opts.CurrentRing;
    canIdeal := opts.CanonicalIdeal;
    uList := opts.GeneratorList;

    if (R1 === null ) then R1 = ring ff;
    if (canIdeal === null) then canIdeal = trim canonicalIdeal R1;
    S1 := ambient R1;
    I1 := ideal R1;
    J1 := sub( canIdeal, S1 );
    if (uList === null) then uList = frobeniusTraceOnCanonicalModule( I1, J1 );

    internalFPureModule( tt, ff, canIdeal, uList,FrobeniusRootStrategy=>opts.FrobeniusRootStrategy )
)

FPureModule ( List, List ) := Sequence => opts -> ( tList, fList ) ->
(
    if #tList != #fList then error "FPureModule: expected the lists to have the same lengths";
    if #fList == 0 then error "FPureModule: expected a nonempty list";

    R1 := opts.CurrentRing;
    canIdeal := opts.CanonicalIdeal;
    uList := opts.GeneratorList;

    if (R1 === null ) then R1 = ring( fList#0 );
    if (canIdeal === null) then canIdeal = trim canonicalIdeal R1;
    S1 := ambient R1;
    I1 := ideal R1;
    J1 := sub( canIdeal, S1 );
    if (uList === null) then uList = frobeniusTraceOnCanonicalModule( I1, J1 );

    internalFPureModule( tList, fList, canIdeal, uList,FrobeniusRootStrategy=>opts.FrobeniusRootStrategy )
)

QGorensteinGenerator ( ZZ, Ring ) := ( e, R ) ->
(
    S := ambient R; -- the ambient ring
    I := ideal R; -- the defining ideal
    gensList := I_*;
    p := char R;
    --principal ideals shouldn't have colons computed
    if #gensList == 1 then return (gensList#0)^(p^e - 1);
    Ie := frobenius( e, I );
    J := trim ( Ie : I ); --compute the colon
    J = trim sub( J, S/Ie ); -- extend colon ideal to S/Ie
    L := J_*; -- grab generators
    if #L != 1 then
        error "QGorensteinGenerator: this ring does not appear to be (Q-)Gorenstein, or you might need to work on a smaller chart. Or the index may not divide p^e-1 for the e you have selected.  Alternately it is possible that Macaulay2 failed to trim a principal ideal.";
    lift( L#0, S )
)

adicDigit ( ZZ, ZZ, QQ ) := ZZ => ( p, e, x ) ->
(
    if p <= 1 then error "adicDigit: Expected first argument to be greater than 1";
    if e <= 0 then error "adicDigit: Expected second argument to be positive";
    if x < 0 or x > 1 then error "adicDigit: Expected last argument to be in the interval [0,1]";
    if x == 0 then return 0;
    lift( ( adicTruncation( p, e, x ) - adicTruncation( p, e-1, x ) ) * p^e, ZZ )
)

adicExpansion( ZZ, ZZ ) := List => ( p, N ) ->
(
    if p <= 1 then error "adicExpansion: Expected first argument to be greater than 1";
    if N < 0 then error "adicExpansion: Expected second argument to be nonnegative";
    if N < p then { N } else prepend( N % p, adicExpansion( p, N // p ) )
    -- would this be faster if it were tail-recursive? we could do this w/ a helper function.
)

adicExpansion( ZZ, ZZ, QQ ) := List => ( p, e, x ) ->
(
    if p <= 1 then error "adicExpansion: Expected first argument to be greater than 1";
    if x < 0 or x > 1 then error "adicExpansion: Expected the last argument to be in the interval [0,1]";
    apply( e, i -> adicDigit( p, i+1, x ) )
)

adicTruncation ( ZZ, ZZ, QQ ) := QQ => ( p, e, x ) ->
(
    if p <= 1 then error "adicTruncation: Expected first argument to be greater than 1";
    if e < 0 then error "adicTruncation: Expected second argument to be nonnegative";
    if x < 0 then error "adicTruncation: Expected third argument to be nonnegative (or a list of nonegative numbers)";
    if x == 0 then 0 else ( ceiling( p^e*x ) - 1 ) / p^e
)

ascendIdeal ( ZZ, List, List, Ideal ) := o -> ( ek, akList,  hkList, Jk ) ->
(
    Rk := ring Jk;
    Ik := ideal Rk;
    Sk := ambient Rk;

    pp := char Sk;
    IN := sub(Jk, Sk);
    IP := ideal(0_Sk);
    i1 := 0;
     --we want to make the largest ideal that is phi-stable, following Moty Katzman's idea
     --we do the following
    while not isSubset(IN+Ik, IP+Ik) do
    (
        i1 = i1 + 1;
        --print "Step";
        IP = IN;
        IN = frobeniusRoot( ek, akList, hkList, IP, FrobeniusRootStrategy => o.FrobeniusRootStrategy) + IP
    );

    --trim the output
    if not o.AscentCount then trim (IP*Rk) else ( trim (IP*Rk), i1 )
)

ascendModule(ZZ, Module, Matrix) := (e, A, U) ->
(
    if (isFreeModule super A) then (
        return image ascendModule(e, generators A, U);
    ) else (
        error "ascendModule: Expected the second argument to be a submodule of a free module.";
    );
);

ascendModule ( ZZ, Matrix, Matrix ) := ( e, A, U ) ->
(
    R := ring A;
    p := char R;
    if A == 0 then A
    else
    (
	flag := true;
	Ne := sum( e, i -> p^i );
	lastA := A;
	while flag do
	(
	    flag = false;
	    A1 := matrix entries mEthRoot( e, mingens image( U^Ne * lastA ) );
	    A1 = A1 | lastA;
	    t1 := compress ( A1 % lastA );
	    if t1 != 0 then
	    (
	        flag = true;
		lastA = mingens image A1;
	    );
	 );
	 mingens image A1
    )
--    use R;
--    answer
)

canonicalIdeal Ring := o -> R1 ->
(
    S1 := ambient R1;
    I1 := ideal R1;
    dR := dim R1;
    dS := dim S1;
    varList := first entries vars S1;
    degList := {};
    if #varList > 0 then
    (
	if #(degree(varList#0)) == 1 then
	    degList = apply(varList, q -> (degree(q))#0)
    	else degList = apply(varList, q -> (degree(q)))
    );
    M1 := (Ext^(dS - dR)(S1^1/I1, S1^{-(sum degList)}))**R1;
    embedAsIdeal(M1, Attempts => o.Attempts)
)

compatibleIdeals RingElement := o -> u ->
(
    if not isPolynomialOverPrimeField( u ) then 
        error "compatibleIdeals: expected an element of a polynomial ring over a prime field ZZ/p";
    L := { }; 
    R := ring u; 
    P := ideal 0_R;
    J:=frobeniusRoot( 1, ideal u );
    t := 1_R % ( gens J );
    if t != 0_R then print "compatibleIdeals: *** WARNING *** Frobenius action has nilpotent elements";
    compatibleIdealsInnards ( u, L, P )
)

decomposeFraction ( ZZ, QQ ) := Sequence => o -> ( p, t ) ->
(
    if not isPrime p then error "decomposeFraction: first argument must be a prime number";
    a := numerator t; -- finding a is easy, for now
    den := denominator t;
    b := 1;
    while den % p^b == 0 do b = b+1;
    b = b-1;
    temp := denominator( t*p^b );
    local c;
    if temp == 1 then c = 0 else
    (
        c = multiplicativeOrder( p, temp );
        a = lift( a*(p^c-1)/temp, ZZ ) -- fix a
    );
    if o.NoZeroC and c == 0 then
    (
        a = a*(p-1);
        c = 1
    );
    (a,b,c)
)

descendIdeal (ZZ, List, List, Ideal) := Sequence => opts -> (e1, expList, fList, canIdeal ) ->
(
    if #expList != #fList then error "descendIdeal: expected the lists to have the same lengths";
    if #fList == 0 then error "descendIdeal: expected a nonempty list";

    R1 := ring( fList#0 );
    if (not (R1 === ring canIdeal)) then error "descendIdeal: Expected a common ideal for the currentRing, ring elements, and ideal";

    HSLList := internalFPureModule( e1, expList, fList, canIdeal,FrobeniusRootStrategy=>opts.FrobeniusRootStrategy );
    (HSLList#0, HSLList#3)
)

floorLog ( Number, Number ) := ZZ => ( b, x ) ->
(
    if b <= 1 then error "floorLog: expected the first argument to be greater than 1";
    if x <= 0 then error "floorLog: expected the second argument to be positive";
    if x < b then return 0;
    flog := floor( log_b x );
    while b^flog <= x do flog = flog + 1;
    flog - 1
)

frobeniusPower ( ZZ, Ideal ) := Ideal => o -> ( N, I ) -> 
(
    R := ring I;
    p := char R;
    if p == 0 then 
        error "frobeniusPower: expected an ideal in a ring of positive characteristic.";
    G := first entries mingens I;
    if #G == 0 then return ideal 0_R;
    if #G == 1 then return ideal (G#0)^N;
    E := adicExpansion( p, N );
    product( #E, m -> frobenius( m, I^( E#m ) ) )
)

frobeniusPower( QQ, Ideal ) := Ideal => o -> ( t, I ) ->
(
    if t < 0 then error "frobeniusPower: expected a nonnegative exponent.";
    p := char ring I;
    if p == 0 then 
        error "frobeniusPower: expected an ideal in a ring of positive characteristic.";
    ( a, b, c ) := decomposeFraction( p, t ); --write t = a/(p^b*(p^c-1))
    if c == 0 then frobeniusPowerHelper( b, a, I, o )  --if c = 0, call simpler function
        else 
	(
	    rem := a % ( p^c - 1 );      
	    quot := a // ( p^c - 1 );     
	    J := stableIdeal( c, frobeniusPower( rem, I ), I, FrobeniusRootStrategy => o.FrobeniusRootStrategy );
	    frobeniusRoot( b, frobeniusPower( quot, I ) * J, FrobeniusRootStrategy => o.FrobeniusRootStrategy )
        )
)

frobeniusPreimage(ZZ, Ideal) := Ideal => o -> (e1, J1) -> (
    R1 := ring J1;
    I1 := ideal R1;
    S1 := ambient R1;
    Ipe := frobenius(e1, I1 );
    Jpe := frobenius(e1, I1 + sub(J1, S1));
    fedderColon := Ipe : I1;
    return sub( Jpe : fedderColon , R1);
)

frobeniusRoot ( ZZ, Ideal ) := Ideal => opts -> ( e, I ) ->
(
    if e < 0 then error "frobeniusRoot: Expected first argument to be a nonnegative integer";
    R := ring I;
    if class R =!= PolynomialRing then error "frobeniusRoot: Expected an ideal in a PolynomialRing";
    p := char R;
    if not isPrime p then error "frobeniusRoot: Expected an ideal in a ring of prime characteristic";
    k := coefficientRing R;
    if k =!= ZZ/p and class k =!= GaloisField then error "frobeniusRoot: Expected the coefficient field to be a finite prime field or a GaloisField";

    q := k#order;
    --Gets the cardinality of the base field.
    G := I_*;
    --Produces a list of the generators of I.
    if #G == 0 then ideal 0_R
    else
        if opts.FrobeniusRootStrategy == MonomialBasis then
        (
	    L := sum apply( G, f -> frobeniusRootMonStrat(e,p,q,k,f,R) );
    	    L = first entries mingens L;
	    ideal L
	)
        else frobeniusRootSubStrat(e,p,q,k,I,R)
)

frobeniusRoot ( ZZ, MonomialIdeal ) := MonomialIdeal => opts -> ( e, I ) ->
(
    R := ring I;
    p := char R;
    G := I_*;
    if #G == 0 then ideal 0_R else monomialIdeal apply( G, f -> R_( (exponents f)#0 // p^e ))
)

frobeniusRoot ( ZZ, List, List ) := Ideal => opts -> ( e, exponentList, idealList ) ->
(
    --idealList is a list of ideals and/or ring elements.
    --exponentList is a list of exponents we're taking these ideals/elements to

    --include the following line to set a break point:
    --error "break here";
--    if (#idealList > 0) then (
--        if (instance(idealList#0, RingElement)) then (
--            return
--        );
--    );
    I := null;
    if e == 0 then
    (
        I = idealList#0^( exponentList#0 );
        apply( 1..(length(idealList) - 1), j-> I = I * ( idealList#j )^( exponentList#j ) );
        return I
    );

    R := ring idealList#0;
    p := char R;
    minGensList := apply( idealList, jj -> if class jj === Ideal then #(first entries mingens jj) else 1 );

    -- find max n such that a - (n-1)p > m*p. This is the number of copies of $I$ we can
    -- move outside the pth root.

    nsList := apply( exponentList, minGensList, ( aa, mm ) -> max( 0, floor( aa/p - mm + 1 ) ) );
    I = R;
    apply( length idealList, j -> I = I * ( idealList#j )^( exponentList#j - nsList#j * p ) );
    I = frobeniusRoot( 1, I, opts );
    frobeniusRoot( e - 1, append( nsList, 1 ), append( idealList, I ), opts )
)

frobeniusRoot ( ZZ, Module ) := Matrix => opts -> ( e, A ) ->
(
    if (isFreeModule super A) then (
        return image frobeniusRoot(e, generators A, opts);
    ) else (
        error "frobeniusRoot: Expected the second argument to be a submodule of a free module.";
    );
);

frobeniusRoot ( ZZ, Matrix ) := Matrix => opts -> ( e, A ) ->
(
    if e < 0 then error "frobeniusRoot: Expected first argument to be a nonnegative integer";
    R := ring A;
    if class R =!= PolynomialRing then error "frobeniusRoot: Expected a matrix with entries in a PolynomialRing";
    p := char R;
    if not isPrime p then error "frobeniusRoot: Expected a matrix with entries in a ring of prime characteristic";
    k := coefficientRing R;
    if k =!= ZZ/p and class k =!= GaloisField then error "frobeniusRoot: Expected the coefficient field to be a finite prime field or a GaloisField";
   mEthRoot( e, A )
)

frobeniusTraceOnCanonicalModule ( Ideal, Ideal ) := ( defIdeal, canIdeal ) ->
(
    canonical := canIdeal + defIdeal;
    Ip := frobenius defIdeal;
    tempIdeal := intersect( frobenius( canonical ) : canonical, Ip : defIdeal );
    M1 := compress( (gens tempIdeal) % (gens Ip) );
    first entries M1
)

isCohenMacaulay Ring := o -> R1 ->
(
    if o.AtOrigin then isCM R1
    else
    (
        S1 := ambient R1;
        I1 := ideal R1;
        M1 := S1^1/I1;
        dimS := dim S1;
        dimR := dim R1;
        flag := true;
        P1 := res M1;

        if (length P1 == dimS - dimR) then (
            true
        )
        else if (isHomogeneous(I1) == true) then (
            false
        )
        else (
            RHom := Hom(P1, S1^1);
            i := dimS - dimR + 1;
            while ((flag == true) and (i <= dimS))do (
                if (dim (HH^i(RHom)) > -1) then (
                    flag = false;
                );
                i = i+1;
            );
            flag
        )
    )
)

isFInjective Ring := Boolean => o-> R1 ->
(
    d := dim R1;
    S1 := ambient R1;
    I1 := ideal R1;
    FS := null; -- this is the pushFwd of (R-F_*R) to a map of (ambient R) modules. computationally expensive. Only computed if needed.
    F := map( R1, S1 );
    d1 := dim S1;
    i := d1 - d + 1;
    myMap := null; -- maps between ext groups used to test F-injectivity. Computationally expensive and computed where needed.
    flag := true;
    flagPushComputed := false;

    -- F-Injectivity fast to compute on dim(S)-dim(R), so we check there separately by default
    if o.CanonicalStrategy === Katzman then
    (
	-- if F-injectivity fails in top dimension, no need to try any others
         if not isFInjectiveCanonicalStrategy(R1, passOptions( o, { AtOrigin, FrobeniusRootStrategy } ) )  then return false
    )
    else i = i - 1;

    --if we assume Cohen-Macaulay, then we are already done
    if o.AssumeCM then return true;
    --otherwise we next construct G : R -> F_* R
    G := null;

    if o.AssumeNormal then d1 = d1 - 2 else if o.AssumeReduced then d1 = d1 - 1;

    while i <= d1 and flag do
    (
    	--if ambient pushforward is faster in the next line, use it instead
	    if Ext^i( S1^1/I1, S1^1 ) != 0 then
	    (
    	        if G === null then G = frobPFMap( 1, R1 );
	        --note we only compute the Frobenius pushforward if the ring is not CM
                if not flagPushComputed then
		(
		    FS = pushFwdToAmbient( R1, G );   --pushforward Frobenius
                    flagPushComputed = true
                );
	        myMap = Ext^i( FS, S1^1 ); --functorial Ext
	        if (dim coker myMap) != -1 then flag = false;
	    );
	    i = i + 1;
	);
	flag
)

isFPure Ideal := o -> I1 ->
(
    p1 := char ring I1;
    if o.AtOrigin then
    (
        maxideal := maxIdeal I1;
        if codim(I1) == numgens(I1) then
	(
	    L := flatten entries gens I1;
	    not isSubset(
		ideal( product( L, l -> l^(p1-1) ) ),
		frobenius maxideal
	    )
    	)
        else not isSubset( frobenius( I1 ) : I1, frobenius maxideal )
    )
    else (
        nonFPureLocus := frobeniusRoot( 1, frobenius( I1 ) : I1, FrobeniusRootStrategy => o.FrobeniusRootStrategy );
        nonFPureLocus == ideal( sub( 1, ring I1 ) )
    )
)

isFRational Ring := o -> R1 ->
(
    flag := true;
    --first verify if it is CM
    if not o.AssumeCM then
        if not isCohenMacaulay(R1, AtOrigin => o.AtOrigin) then flag = false;
    --next verify if it is Frational
    if flag then
    (
        --note we don't compute the test module if we know that the ring is not CM.
        MList := testModule(CurrentRing => R1, passOptions( o, { AssumeDomain, FrobeniusRootStrategy } ) );
        if o.AtOrigin then
	(
            paraTestIdeal := (MList#0):(MList#1);
            myMaxIdeal := sub(maxIdeal(ambient R1), R1);
            flag = not isSubset(paraTestIdeal, myMaxIdeal);
        )
        else (
            if not isSubset(MList#1, MList#0) then flag = false
        );
    );

    flag
)

isFRegular Ring := o -> R1 ->
(
    if o.QGorensteinIndex == infinity then
        return nonQGorensteinIsFregular( o.DepthOfSearch, {0}, {1_R1}, R1, passOptions( o, { AssumeDomain, FrobeniusRootStrategy } ) );
  --      return nonQGorensteinIsFregular( o.DepthOfSearch, {0}, {1_R1}, R1, AssumeDomain => o.AssumeDomain, FrobeniusRootStrategy => o.FrobeniusRootStrategy );
    tau := testIdeal( R1, passOptions( o, { AssumeDomain, MaxCartierIndex, FrobeniusRootStrategy, QGorensteinIndex } ) );
--    tau := testIdeal( R1, AssumeDomain => o.AssumeDomain, MaxCartierIndex => o.MaxCartierIndex, FrobeniusRootStrategy => o.FrobeniusRootStrategy, QGorensteinIndex => o.QGorensteinIndex);
    if o.AtOrigin then isSubset( ideal 1_R1, tau + maxIdeal R1 )
    else isSubset( ideal 1_R1, tau )
)

isFRegular ( Number, RingElement ) := o -> ( tt, ff ) ->
(
    tt = tt/1;
    if o.QGorensteinIndex == infinity then
        return nonQGorensteinIsFregular( o.DepthOfSearch, {tt}, {ff}, ring ff, passOptions( o, { AssumeDomain, FrobeniusRootStrategy } ) );
--        return nonQGorensteinIsFregular( o.DepthOfSearch, {tt}, {ff}, ring ff, AssumeDomain => o.AssumeDomain,  FrobeniusRootStrategy => o.FrobeniusRootStrategy );
    R1 := ring ff;
    tau := testIdeal( tt, ff, passOptions( o, { AssumeDomain, MaxCartierIndex, FrobeniusRootStrategy, QGorensteinIndex } ) );
--    tau := testIdeal( tt, ff, AssumeDomain => o.AssumeDomain, MaxCartierIndex => o.MaxCartierIndex, FrobeniusRootStrategy => o.FrobeniusRootStrategy, QGorensteinIndex => o.QGorensteinIndex );
    if o.AtOrigin then isSubset( ideal 1_R1, tau + maxIdeal R1 )
    else isSubset( ideal 1_R1, tau )
)

isFRegular ( List, List ) := o -> ( ttList, ffList ) ->
(
    if o.QGorensteinIndex == infinity then
        return nonQGorensteinIsFregular( o.DepthOfSearch, ttList, ffList, ring ffList#0, passOptions( o, { AssumeDomain, FrobeniusRootStrategy } ) );
--        return nonQGorensteinIsFregular( o.DepthOfSearch, ttList, ffList, ring ffList#0, AssumeDomain => o.AssumeDomain,  FrobeniusRootStrategy => o.FrobeniusRootStrategy );
    R1 := ring ffList#0;
    tau := testIdeal( ttList, ffList, passOptions( o, { AssumeDomain,, MaxCartierIndex, FrobeniusRootStrategy, QGorensteinIndex } ) );
--    tau := testIdeal( ttList, ffList, AssumeDomain => o.AssumeDomain, MaxCartierIndex => o.MaxCartierIndex, FrobeniusRootStrategy => o.FrobeniusRootStrategy, QGorensteinIndex => o.QGorensteinIndex);
    if o.AtOrigin then isSubset( ideal 1_R1, tau + maxIdeal R1 )
    else isSubset( ideal 1_R1, tau )
)

multiplicativeOrder ( ZZ, ZZ ) := ZZ => ( a, b ) ->
(
    if gcd( a, b ) != 1 then error "multiplicativeOrder: Expected numbers to be relatively prime";
    if b == 1 then return 1;
    maxOrder := lcm(apply(toList apply(factor b, i-> factor ((i#0-1)*((i#0)^(i#1-1)))), tt -> value tt));
    primeFactorList := sort unique apply( subsets( flatten apply(toList factor maxOrder, myPower -> apply(myPower#1, tt->myPower#0))), tt -> product tt);
--    potentialOrderList := sort unique flatten  apply(flatten apply(toList apply(toList factor b, tt -> cyclicOrdPGroup(tt#0, tt#1)), tt -> toList tt), myPower -> subsets apply(myPower#1, tt->myPower#0));
    i := 0;
    while i < #primeFactorList do 
    (
        if powermod(a, primeFactorList#i, b) == 1 then return primeFactorList#i;
        i = i + 1
    );
    error "multiplicativeOrder: Something went wrong; failed to find the multiplicative order";
)

parameterTestIdeal(Ring) := o-> (R1) -> (
    testMod := testModule(CurrentRing => R1,o);
    (testMod#0) : (testMod#1)
)

testElement Ring := o -> R1 ->
(
    -- Marcus I believe wrote this code to look at random minors instead of all
    -- minors. Note in the current version this will not terminate if the ring
    -- is not generically reduced.
    I1 := ideal R1;
    n1 := #(gens R1) - dim R1;
    M1 := jacobian I1;
    r1 := rank target M1;
    c1 := rank source M1;
    testEle := sub( 0, ambient R1 );
    primesList := {};
    primesList = if o.AssumeDomain then { I1 } else minimalPrimes I1;
    curMinor := ideal sub( 0, ambient R1 );
    while any( primesList, II -> isSubset( ideal testEle, II ) ) do
    (
	curMinor = ( minors( n1, M1, First => {randomSubset(r1,n1),randomSubset(c1,n1)}, Limit => 1 ) )_*;
	if #curMinor > 0 then
	    testEle = if o.AssumeDomain then first curMinor else
	        testEle + random( coefficientRing R1 )*( first curMinor );
    );
    testEle % I1
)

