equivariantCohomology(NormalToricVariety) := Module => (X) -> (
	r := dim X;
	t := vars r;
	R := QQ[t_1..t_r, Degrees=>{r:2}];
	S := (ring X)/(dual monomialIdeal X);
	m := length(rays(X));
	S = newRing(S, Degrees=>{m:2});
	A := transpose(matrix(rays(X)));
	v := vector(gens(S));
	imgGen := flatten(entries(A*v));
	f := map(S, R, imgGen);
	M := pushForward(f, S^1);
	M
)

