quasiToricManifold(SimplicialComplex,Matrix) := QuasiToricManifold => (sc,lambda) -> (
	if not isValidChar(sc,lambda) then error "expected characteristic matrix";
	new QuasiToricManifold from {
		QTMSimplicialComplex => sc,
