     n := type Lh;
     B := Lh#0; H := Lh#1; C := Lh#2;
     R := ZZ;
     nB := #B - 1;
     nH := #H - 1;
     nC := #C - 1;
     b := H_nH; 
     if not (b == C_nC) then error "homology and cohomology do not have same end";
     IntH := toList apply(H_0..H_nH, i -> i); 
     --print IntH;
     NdH := IntH - set(H);
     nNdH := #NdH-1;
     IntC := toList apply(C_0..C_nC, i -> i); 
     NdC := IntC - set(C);
