        then (A1mat := map(R^(nNdH+1), R^(nB+1), 
		  (i,j) -> binomial(NdH_i,B_j)))
        else (A1mat = map(R^0, R^(nB+1), (i,j) -> 1));         
     if nNdC >= 0
        then (A2mat := map(R^(nNdC+1), R^(nB+1), 
		  (i,j) -> binomial(NdC_i,n-B_j)))
        else (A2mat = map(R^0, R^(nB+1), (i,j) -> 1));   
