);

torusIntersection (NormalToricVariety,Ideal,Ring) := (X,I,TR) ->(
  G := new List;
  for g in flatten entries (gens I) do(
    G = append(G, torusIntersection(X,g,TR));
  );
  G = ideal G;
  --saturate the ideal with respect to the product of variables in TR
  for a in gens TR do(
    G = saturate(G,a);
  );
  return G
);

