     W:=rem//(sub(D#"Xperturb",QT)|sub(D#"Yperturb",QT)|sub(D#"O1",QT)); -- first deal with non-T2 bit
     remred:=rem%(sub(D#"Xperturb",QT)|sub(D#"Yperturb",QT)|sub(D#"O1",QT));
