makeWeylAlgebra(PolynomialRing, List) := opts -> (R, v) -> (
    n := numgens R;
    w := if #v == n   then toList(#v:0) | v
    else if #v == 2*n then v
    else error("expected a weight of length ", n, " or ", 2*n);
    coordVars := gens R;
    diffVars := apply(coordVars, i -> value("symbol d" | toString(i)) );
    allVars := join(coordVars, diffVars);
    W := (coefficientRing R)(monoid [allVars,
	    WeylAlgebra   => apply(coordVars, diffVars, (x,dx) -> x => dx),
	    MonomialOrder => WeightThenEliminationOrder w ]);
    if opts.SetVariables then use W;
    W)

makeWeylAlgebra(PolynomialRing) := opts -> R -> (
    n := length(gens R);
    v := (for i from 1 to n list 0);
    W := makeWeylAlgebra(R, v);
    W)

stafford Ideal := I -> (
     g := first entries gens I;
     while #g>2 do g = mainStep(g#0,g#1,g#2) | drop(g,3);
     ideal g
     )

aboveBruhat(WeylGroupElement) := (w) ->
	(
	w0:=longestWeylGroupElement w#0;
	apply(underBruhat(w0*w),x->{w0*x#0,x#1})
	)

aboveBruhat(BasicList):=(L)->
	(
	result:=new MutableHashTable from {};
	U:=local U;
	for i from 0 to #L-1 do
	  (
	  U=aboveBruhat(L#i); --find the elements above this one.
	  for j from 0 to #U-1 do
		if result#?(U#j#0) then result#(U#j#0)=append(result#(U#j#0),{i,U#j#1})
		else result#(U#j#0)={{i,U#j#1}};
	  );
	apply(pairs result,(x,y)->{x,y})
	)

addRoots(RootSystem,Root,Root) := (R,r,q) -> 
