				   -- <<"added Whit Strata X"<<endl;
			    	    if opts.Print then<<"X whit= "<<K<<endl;
				    --<<"X whit= "<<K<<endl;
		       	    	    Kpf=ideal mingens(sub(eliminate(elimIm,Gam+sub(K,graphR)),S)+Y);
		       	    	    for comp in decompose Kpf do(
