				    	if opts.Print then<<"X whit in Y "<<comp<<endl;
	       		 	    	if (any(toList(W#dimKinv),jj->comp==jj)==false) then(
					    (W#dimKinv)#(#(W#dimKinv))=comp;
					    if dimKinv>(dimY-aY) then aY=dimY-dimKinv;
					    );
     				    	);
			    	    );
			    	);

		    );
